-- =====================================================================
-- Medical Text Expander - Supabase Database Setup & Full Restore SQL
-- Version: v1.9.9
-- Target: Supabase PostgreSQL (Run in Supabase Dashboard > SQL Editor)
-- =====================================================================

-- 1. CREATE TABLE: bed_notes
CREATE TABLE IF NOT EXISTS public.bed_notes (
    bed_number BIGINT PRIMARY KEY,
    content TEXT DEFAULT '',
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_by TEXT DEFAULT ''
);

-- 2. CREATE TABLE: bed_history
CREATE TABLE IF NOT EXISTS public.bed_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    bed_number BIGINT NOT NULL,
    reason TEXT DEFAULT '',
    content TEXT DEFAULT '',
    char_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- 3. CONFIGURE ROW LEVEL SECURITY (RLS) & POLICIES
ALTER TABLE public.bed_notes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow anon all on bed_notes" ON public.bed_notes;
CREATE POLICY "Allow anon all on bed_notes" ON public.bed_notes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

ALTER TABLE public.bed_history ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow anon all on bed_history" ON public.bed_history;
CREATE POLICY "Allow anon all on bed_history" ON public.bed_history FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

GRANT ALL ON TABLE public.bed_notes TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.bed_history TO anon, authenticated, service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;

-- 4. RESTORE SEED DATA (BED NOTES 1-30, WARD DOCS, USERS, TEMPLATES)
INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (1, '', now(), 'Local Backup') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (2, '', now(), 'Local Backup') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (3, '', now(), 'Local Backup') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (4, '', now(), 'Local Backup') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (5, '', now(), 'Local Backup') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
