INSERT INTO public.bed_notes (bed_number, content, updated_at, updated_by) VALUES (102, '{"version":"1.9.9","categories":{"value":[{"category":"1. การดูแลก่อน-หลังผ่าตัดและหัตถการ","items":[{"shortcut":".preop","title":"เตรียมความพร้อมก่อนผ่าตัด (Pre-operative care)","content":"Focus: เตรียมความพร้อมผู้ป่วยก่อนส่งผ่าตัด\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจก่อนเข้าห้องผ่าตัด ปฏิบัติตัวตามแผน NPO ถูกต้อง เอกสารและผลตรวจครบถ้วน และไม่เกิดภาวะแทรกซ้อนก่อนผ่าตัด\nData: ผู้ป่วยมีแผนผ่าตัด... วันนี้ NPO ตั้งแต่... น., V/S: T... °C, BP.../... mmHg, PR... /min, RR... /min, SpO2... %\nAction:\n[☀️ เวรเช้า]\n- ตรวจสอบความถูกต้องของใบยินยอมผ่าตัด (Informed consent) เซ็นเรียบร้อย\n- ตรวจสอบผลตรวจทางห้องปฏิบัติการ (CBC, Coag, Electrolyte, Anti-HIV), ผล X-ray/EKG และ Chart ผู้ป่วย\n- อาบน้ำฟอกสบู่ฆ่าเชื้อ เปลี่ยนชุดผ่าตัด ถอดฟันปลอม แว่นตา คอนแทคเลนส์ และเครื่องประดับทุกชนิด\n- ตรวจสอบแถบข้อมือระบุตัวตน (Patient ID) และทำเครื่องหมายตำแหน่งผ่าตัด (Surgical Site Marking) ชัดเจน\n- ดูแลให้สารน้ำทางหลอดเลือดดำ และให้ยาปฏิชีวนะป้องกันล่วงหน้า (Prophylactic Antibiotic) ก่อนส่ง OR ตามแผน\n- สวมหมวกคลุมผม และนำส่งห้องผ่าตัดพร้อมเอกสารครบถ้วน\n[⛅ เวรบ่าย]\n- ตรวจเช็คตารางผ่าตัด (OR list) ของวันพรุ่งนี้ และประสานงานติดตามผลตรวจที่ยังค้าง (Pending labs/X-ray)\n- แนะนำและเตรียมความพร้อมทางจิตใจแก่ผู้ป่วยและญาติ อธิบายขั้นตอนการผ่าตัดและการปฏิบัติตัวหลังผ่าตัด\n- แนะนำการฝึกหายใจลึกๆ (Deep breathing exercise) และการฝึกไออย่างมีประสิทธิภาพ\n- ตรวจเช็คการจองโลหิต (Cross-match / PRC) พร้อมใช้ตามแผนการรักษา\n- ให้ยาระบายหรือสวนอุจจาระตามคำสั่งแพทย์เฉพาะราย\n[🌙 เวรดึก]\n- กำชับและดูแลการงดน้ำและอาหารทางปาก (Strict NPO) ตั้งแต่เวลา 24:00 น. เป็นต้นไป\n- ติดป้าย \"งดน้ำและอาหาร (NPO)\" ที่หัวเตียงและหน้าชาร์ต\n- ดูแลให้สารน้ำทางหลอดเลือดดำตามคำสั่งแพทย์\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจประเมินความพร้อมก่อนผ่าตัด (Pre-op checklist) ซ้ำอีกครั้ง\n- เตรียมแฟ้มประวัติ ยาประจำตัว และผลตรวจให้พร้อมส่งต่อเวรเช้า\nResponse: ส่งผู้ป่วยถึงห้องผ่าตัดเวลา... น. ปลอดภัยดี พยาบาลห้องผ่าตัดรับมอบผู้ป่วยและเอกสารเรียบร้อย"},{"shortcut":".postop","title":"การพยาบาลดูแลหลังผ่าตัด (Post-operative care)","content":"Focus: เสี่ยงต่อภาวะแทรกซ้อนจากการระงับความรู้สึกและการผ่าตัด\nGoal: สัญญาณชีพคงที่ ฟื้นตัวจากยาระงับความรู้สึกได้ดี แผลผ่าตัดไม่มี active bleeding และไม่เกิดภาวะแทรกซ้อนหลังผ่าตัด\nData: รับย้ายผู้ป่วยกลับจากห้องผ่าตัด/ห้องพักฟื้น หลังทำผ่าตัด... ระดับความรู้สึกตัว: ตื่นดี รู้เรื่อง (Alert), V/S แรกรับ: BP.../... mmHg, PR... /min, RR... /min, SpO2... %, แผลผ่าตัดปิด gauze แนบสนิท ไม่มีเลือดสดซึมเปื้อน, สายระบายออก... ml ลักษณะ serosanguinous\nAction:\n[☀️ เวรเช้า]\n- ประเมินสัญญาณชีพ และตรวจประเมินแผลผ่าตัด ทำแผล (Dressing) ด้วยเทคนิคปลอดเชื้อ\n- ตรวจสอบสายระบาย (Drain) และสายสวนปัสสาวะ บันทึกปริมาณและลักษณะสารคัดหลั่ง\n- ประเมินระดับความรู้สึกตัวและความปวด (Pain score) ให้ยาบรรเทาปวดและยาปฏิชีวนะตามแผน\n- ส่งเสริมการลุกขยับตัวเร็ว (Early ambulation) ช่วยเหลือผู้ป่วยฝึกนั่งข้างเตียงหรือยืนเดิน\n- ประเมินเสียงการเคลื่อนไหวของลำไส้ (Bowel sound) ก่อนเริ่มจิบน้ำหรืออาหารตามลำดับขั้น\n[⛅ เวรบ่าย]\n- รับย้ายผู้ป่วยกลับจากห้องผ่าตัด/ห้องพักฟื้น ตรวจวัด V/S ทุก 15 นาที x 4, 30 นาที x 2 และทุก 1 ชม. จนคงที่\n- จัดท่านอนราบหรือศีรษะสูงตามข้อกำหนดของการระงับความรู้สึก (Spinal block / GA)\n- ตรวจสอบผ้าปิดแผล สังเกต active bleeding และตรวจเช็คสายระบายสุญญากาศ\n- ประเมินและดูแลบรรเทาอาการคลื่นไส้อาเจียนหลังผ่าตัด (PONV)\n- ดูแลให้สารน้ำทางหลอดเลือดดำและยาแก้ปวดตามแผนการรักษา\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อความปลอดภัย\n[🌙 เวรดึก]\n- ตรวจวัดสัญญาณชีพและประเมินระดับความรู้สึกตัวระหว่างคืน\n- ประเมินระดับความปวด ให้ยาแก้ปวดก่อนนอนเพื่อส่งเสริมการนอนหลับพักผ่อน\n- จัดสิ่งแวดล้อมให้เงียบสงบ แสงไฟเหมาะสม และยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างตลอดเวลา\n- ตรวจเช็คสายระบายและถุงปัสสาวะไม่ให้หักพับงอ บันทึกและสรุปยอด Intake-Output สะสม 24 ชม.\n- ตรวจวัดสัญญาณชีพรอบ 06:00 น. เฝ้าระวังไข้และภาวะแทรกซ้อนก่อนส่งเวรเช้า\nResponse: สัญญาณชีพคงที่ รู้สึกตัวดี ไม่มีคลื่นไส้อาเจียน แผลผ่าตัดแห้งดี ไม่มี active bleeding"},{"shortcut":".drain","title":"การดูแลสายระบายและแผลผ่าตัด (Surgical Drain \u0026 Wound Care)","content":"Focus: เสี่ยงต่อการติดเชื้อและมีสารน้ำคั่งค้างบริเวณแผลผ่าตัด\nGoal: สารคัดหลั่งระบายได้สะดวก สายระบายทำงานมีประสิทธิภาพ แผลรอบสายระบายสะอาด แห้งดี และไม่พบสัญญาณการติดเชื้อ\nData: มีสายระบาย (Redivac / Hemovac / Jackson-Pratt / ICD) บริเวณแผลผ่าตัด มีสารคัดหลั่งออกสะสม... ml ลักษณะ serosanguinous ไม่มีเลือดสดออกเพิ่ม แผลผ่าตัดเย็บแนบสนิท\nAction:\n[☀️ เวรเช้า]\n- ตรวจเช็คตำแหน่งรอยเจาะสายระบาย ทำความสะอาดแผลรอบสายระบายด้วยเทคนิคปลอดเชื้อ\n- ตรวจสอบระบบสุญญากาศ (Vacuum) ของขวด/กระเปาะระบาย (Redivac / Hemovac / Jackson-Pratt)\n- เทสารคัดหลั่ง บันทึกปริมาณ สี และลักษณะ (Serous, Serosanguinous, Sanguinous)\n- ติดเข็มกลัดยึดสายระบายกับเสื้อผ้าผู้ป่วย ป้องกันการดึงรั้งขณะฝึกเดินหรือทำกายภาพ\n[⛅ เวรบ่าย]\n- ตรวจสอบการไหลของสายระบาย ไม่ให้สายหักพับงอหรือมีลิ่มเลือดอุดตัน\n- สังเกตปริมาณเลือดที่ออก หากออก \u003e 100 ml/hr ติดต่อกัน 2 ชม. ให้รายงานแพทย์ทันที\n- ตรวจสอบขวดสุญญากาศให้คงสภาพแรงดูดอย่างต่อเนื่อง\n[🌙 เวรดึก]\n- จัดวางขวดสายระบายให้อยู่ในระดับต่ำกว่าแผลผ่าตัดเสมอ และไม่ให้สายดึงรั้งขณะนอนหลับ\n- บันทึกและสรุปยอดปริมาณสารคัดหลั่งจากสายระบายสะสมรอบ 24 ชั่วโมงลงในชาร์ต\n- ส่งต่อข้อมูลยอดรวมเลือดจากสายระบายให้แพทย์ประเมินการถอดสายระบาย (Off drain) ในรอบเช้า\nResponse: สายระบายไม่หักพับงอ การระบายไหลสะดวก สารคัดหลั่งออกลดลง แผลรอบสายระบายไม่มีอาการบวมแดงหรือมีหนอง"},{"shortcut":".wound","title":"ตรวจประเมินแผลผ่าตัดแห้งดี (Wound Clean \u0026 Dry)","content":"Focus: แผลผ่าตัดสะอาด ไม่มีสัญญาณการติดเชื้อ\nGoal: แผลผ่าตัดสมานตัวดี ขอบแผลแนบสนิท แห้งสะอาด ไม่มีเลือดหรือหนองซึมเปื้อน และไม่เกิดการติดเชื้อที่แผลผ่าตัด (SSI)\nData: แผลผ่าตัดบริเวณ... ปิดแผลเรียบร้อย ขอบแผลเย็บแนบสนิทดี (Well-approximated)\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินแผลผ่าตัด: ขอบแผล รอยเย็บ อาการบวม แดง ร้อน\n- ทำแผล (Wound dressing) ด้วย Normal Saline และยึดหลัก Aseptic technique\n- ปิดแผลด้วยผ้าก๊อซสะอาดหรือพลาสเตอร์กันน้ำตามแผนการรักษา\n- ให้คำแนะนำผู้ป่วยระวังไม่ให้แผลเปียกน้ำหรือสัมผัสสิ่งสกปรก\n[⛅ เวรบ่าย]\n- ตรวจเช็คผ้าปิดแผล สังเกตมีเลือดหรือสารคัดหลั่งซึมเปื้อนผ้าก๊อซด้านนอก (Reinforce if needed)\n- ประเมินอาการปวดตึงหรือแสบร้อนบริเวณแผล\n- ดูแลความสะอาดของเสื้อผ้าและผ้าปูเตียงไม่ให้สัมผัสเสียดสีกับแผล\n[🌙 เวรดึก]\n- ตรวจสอบผ้าปิดแผลไม่ให้เลื่อนหลุดขณะผู้ป่วยพลิกตัวเวลานอน\n- เฝ้าระวังอาการไข้สูง หนาวสั่น ซึ่งอาจเป็นสัญญาณเริ่มต้นของการติดเชื้อที่แผล\n- สรุปและบันทึกลักษณะแผลเพื่อรายงานส่งต่อเวรเช้า\nResponse: แผลผ่าตัดแห้ง สะอาดดี ไม่มีเลือดหรือสิ่งคัดหลั่งซึมเปื้อน ไม่มีรอยบวมแดง (No signs of inflammation/infection)"}]},{"category":"2. การจัดการความปวด Pain Management (DAR)","items":[{"shortcut":".pain","title":"ปวดแผลผ่าตัดเฉียบพลัน (Acute Pain: DAR)","content":"Focus: ปวดแผลผ่าตัดเฉียบพลัน (Acute Post-Op Pain)\nGoal: ผู้ป่วยสุขสบายขึ้น ระดับความปวดลดลง Pain score ≤ 3/10 สามารถพักผ่อนได้ และไม่มีผลข้างเคียงจากยาบรรเทาปวด\nData: ผู้ป่วยบ่นปวดแผลผ่าตัด Pain score = .../10, หน้าตานิ่ว ร้องคราง ขยับตัวลำบาก, V/S: BP.../... mmHg, PR... /min\nAction:\n[☀️ เวรเช้า]\n- ประเมินตำแหน่ง ลักษณะ และระดับความปวด (Pain score 0-10) ก่อนและหลังทำกิจกรรม\n- ให้ยาแก้ปวดตามแผนการรักษาก่อนเริ่มทำกายภาพบำบัด/ทำแผล 30 นาที\n- สอนเทคนิคการหายใจช้าๆ ลึกๆ ผ่อนคลายกล้ามเนื้อ (Deep breathing) และการประคองแผลเวลาเคลื่อนไหว\n- จัดท่านอนและใช้อุปกรณ์หนุนรองเพื่อผ่อนคลายกล้ามเนื้อรอบแผล\n[⛅ เวรบ่าย]\n- ประเมินระดับความปวดซ้ำหลังเสร็จสิ้นกิจกรรมประจำวัน/กายภาพบำบัด\n- ดูแลให้ยาบรรเทาปวดชนิดฉีด/รับประทาน หรือปรับอัตราเครื่องให้ยาแก้ปวดทางหลอดเลือดดำ (PCA) ตามคำสั่งแพทย์\n- ใช้วิธีไม่ใช้ยาเสริม: ประคบเย็น/ประคบอุ่นตามข้อบ่งชี้ จัดท่าทางให้สุขสบาย\n- ประเมินอาการข้างเคียงของยาแก้ปวด (ง่วงซึม, คลื่นไส้, ความดันตก, ท้องอืด)\n[🌙 เวรดึก]\n- ประเมินความปวดช่วงกลางคืนเพื่อป้องกันการตื่นจากความเจ็บปวด\n- ดูแลให้ยาแก้ปวดก่อนนอน (Bedtime analgesics) ตามแผน เพื่อส่งเสริมการนอนหลับต่อเนื่อง\n- จัดสิ่งแวดล้อมให้เงียบสงบ ผ่อนคลาย ลดแสงไฟรบกวน\n- เฝ้าระวังภาวะกดการหายใจ (Respiratory depression) จากยากลุ่ม Opioids บันทึก RR สม่ำเสมอ\nResponse: หลังให้การพยาบาลและได้รับยา 30 นาที ผู้ป่วยบอกอาการปวดทุเลาลง Pain score ลดลงเหลือ.../10, สีหน้าผ่อนคลาย สามารถนอนหลับพักผ่อนได้"},{"shortcut":".painbreak","title":"ปวดรุนแรงแทรกซ้อนฉับพลัน (Breakthrough Pain: DAR)","content":"Focus: มีอาการปวดรุนแรงแทรกซ้อนขึ้นมาฉับพลัน (Breakthrough pain)\nGoal: ได้รับการบรรเทาความปวดอย่างรวดเร็ว อาการปวดกำเริบลดลงเหลือ Pain score ≤ 3/10 ภายใน 30 นาทีหลังได้ยาเสริม\nData: ผู้ป่วยมีอาการปวดกำเริบเฉียบพลัน Pain score พุ่งสูงขึ้นเป็น.../10 เหงื่อแตก กระสับกระส่าย ไม่สามารถทนต่อความปวดได้\nAction:\n- รายงานแพทย์เวรรับทราบอาการ\n- ดูแลให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough dose)... ทางหลอดเลือดดำตามคำสั่งแพทย์\n- เฝ้าระวังผลข้างเคียงของยา (ง่วงซึม, อัตราการหายใจ)\n- อยู่เป็นเพื่อนให้กำลังใจและช่วยนวดผ่อนคลาย\nResponse: หลังได้รับยาเสริม 15-20 นาที ระดับความปวดลดลงเหลือ.../10, V/S คงที่ ไม่มีภาวะกดการหายใจ (RR... /min)"},{"shortcut":".painchronic","title":"ปวดเรื้อรังจากพยาธิสภาพของโรค (Chronic Pain)","content":"Focus: ปวดเรื้อรังจากพยาธิสภาพของกระดูกและข้อ (Chronic Pain)\nGoal: ควบคุมระดับความปวดให้อยู่ในเกณฑ์ที่ผู้ป่วยทนได้ สามารถนอนหลับพักผ่อนและเคลื่อนไหวทำกิจวัตรประจำวันได้ดีขึ้น\nData: ผู้ป่วยบอกมีอาการปวดตื้อๆ บริเวณ... เป็นๆ หายๆ Pain score = .../10, รบกวนการทำกิจวัตรประจำวันและการนอนหลับ\nAction:\n- ประเมินปัจจัยที่กระตุ้นให้ปวดและปัจจัยที่ช่วยบรรเทา\n- ให้ยาตามเวลา (Around-the-clock) ตามแผนการรักษา\n- แนะนำการประคบอุ่น/เย็น\n- จัดสิ่งแวดล้อมให้เงียบสงบเอื้อต่อการพักผ่อน\nResponse: ผู้ป่วยปรับตัวต่อความปวดได้ดีขึ้น มีระดับความปวดอยู่ในเกณฑ์ที่ยอมรับได้ (Pain score \u003c 3/10) นอนหลับได้ต่อเนื่อง"}]},{"category":"3. ศัลยกรรมกระดูกและข้อ (Orthopedic Nursing)","items":[{"shortcut":".ortho","title":"ตรวจระบบประสาทและการไหลเวียนส่วนปลาย 5Ps (Neurovascular Check)","content":"Focus: เสี่ยงต่อภาวะการไหลเวียนโลหิตและระบบประสาทส่วนปลายบกพร่อง (Impaired Neurovascular Function)\nGoal: การไหลเวียนโลหิตและประสาทรับรู้ส่วนปลายปกติ ปลายเท้า/มืออุ่น สีชมพู CRT \u003c 2 วินาที คลำชีพจรได้ชัดเจน และไม่เกิดภาวะ Compartment syndrome\nData: ผู้ป่วยหลังผ่าตัด/มีกระดูกหักบริเวณ... ปลายรยางค์มีอาการตึงบวมเล็กน้อย\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมิน 5Ps และ CMS check (Color, Motion, Sensation, Pulse, Temp) ปลายมือ/เท้า\n- ตรวจ Capillary refill time (CRT \u003c 2 วินาที) และคลำชีพจรส่วนปลาย (Dorsalis pedis / Radial pulse)\n- กระตุ้นให้ผู้ป่วยบริหารกระดกข้อเท้าและขยับนิ้วมือ/นิ้วเท้า 20-30 ครั้ง/ชม.\n- จัดยกอวัยวะส่วนปลายให้สูงกว่าระดับหัวใจด้วยหมอนหนุนเพื่อลดบวม\n[⛅ เวรบ่าย]\n- ตรวจประเมิน CMS ซ้ำหลังผู้ป่วยเสร็จสิ้นการฝึกเดินหรือทำกายภาพบำบัด\n- สังเกตอาการบวมตึง ปวดรุนแรงผิดปกติ หรืออาการชา (Paresthesia) เฝ้าระวัง Compartment Syndrome\n- ตรวจสอบผ้าพันแผลหรือเฝือกไม่ให้รัดแน่นจนเกินไป\n[🌙 เวรดึก]\n- ตรวจเช็คตำแหน่งหมอนหนุนยกขาสูงไม่ให้เลื่อนหลุดขณะนอนหลับ\n- ตรวจประเมินความอุ่นและสีผิวปลายเท้า/ปลายมือรอบดึก\n- เฝ้าระวังอาการปวดตึงรุนแรงตอนดึกที่ปลุกให้ผู้ป่วยตื่น รายงานแพทย์ทันทีหากสงสัย Compartment syndrome\nResponse: ปลายรยางค์อุ่น สีชมพู ชีพจร 2+ คลำได้ชัดเจน, CRT \u003c 2 วินาที, การรับความรู้สึกปกติ ขยับนิ้วได้ดี ไม่มีอาการชาหรือปวดตึงผิดปกติ (No Compartment syndrome)"},{"shortcut":".cast","title":"การดูแลผู้ป่วยใส่เฝือก/ดามกระดูก (Cast \u0026 Splint Care)","content":"Focus: เสี่ยงต่อการเกิดแผลกดทับและเนื้อเยื่อขาดเลือดจากการใส่เฝือก\nGoal: เฝือกคงรูปดี ไม่แตกหัก ไม่กดทับเนื้อเยื่อ ไม่เกิดแผลกดทับใต้เฝือก การไหลเวียนโลหิตส่วนปลายปกติ และผู้ป่วยดูแลเฝือกได้ถูกต้อง\nData: ผู้ป่วยใส่เฝือก (Cast / Splint / Slab) บริเวณ...\nAction:\n[☀️ เวรเช้า]\n- ตรวจสอบสภาพเฝือก: แข็งแรง แห้งดี ไม่แตกหัก ไม่เปียกชื้น และไม่หลวมหรือรัดแน่นเกินไป\n- ตรวจขอบเฝือกไม่ให้เสียดสีหรือกดทับผิวหนัง (Pad ขอบเฝือกหากจำเป็น)\n- สอนและกระตุ้นการเกร็งกล้ามเนื้อใต้เฝือก (Isometric exercise) เพื่อคงสภาพกล้ามเนื้อ\n- แนะนำห้ามนำสิ่งแปลกปลอมแคะเกาในเฝือก ระวังไม่ให้เฝือกเปียกน้ำ\n[⛅ เวรบ่าย]\n- ตรวจประเมิน 5Ps และ CMS check ปลายรยางค์อย่างละเอียด (ปวด บวม ชา เย็น สีคล้ำ)\n- จัดยกอวัยวะส่วนที่ใส่เฝือกให้สูงกว่าระดับหัวใจด้วยหมอนหนุนเพื่อลดอาการบวมตึง\n- ประเมินระดับความปวด หากมีอาการปวดแสบร้อนใต้เฝือกหรือปวดตึงรุนแรงให้รายงานแพทย์\n[🌙 เวรดึก]\n- จัดตำแหน่งหมอนหนุนยกขาสูง/แขนสูงไม่ให้เลื่อนหลุดขณะนอนหลับ\n- ตรวจสอบการระบายอากาศและระวังขอบเฝือกกดทับผิวหนังเวลานอน\n- เฝ้าระวังอาการปวดตึงรุนแรงรอบดึก (Pain out of proportion) เฝ้าระวัง Compartment Syndrome\nResponse: เฝือกแห้งและอยู่ในสภาพดี ปลายรยางค์อุ่น ขยับนิ้วได้คล่อง ไม่บ่นชาหรือปวดแสบร้อนใต้เฝือก"},{"shortcut":".traction","title":"การดูแลผู้ป่วยดึงถ่วงน้ำหนัก (Traction Care)","content":"Focus: ดูแลประสิทธิภาพการดึงถ่วงน้ำหนักและป้องกันภาวะแทรกซ้อน\nGoal: กระดูกอยู่ในแนวแรงดึงที่ถูกต้อง (Alignment) สายดึงถ่วงทำงานมีประสิทธิภาพ ตำแหน่ง Pin site สะอาด ไม่ติดเชื้อ และไม่เกิดแผลกดทับ\nData: ผู้ป่วยได้รับการดึงถ่วงน้ำหนัก (Skin / Skeletal traction) บริเวณ... น้ำหนักถ่วง... กิโลกรัม\nAction:\n- ตรวจสอบเชือกดึงถ่วงน้ำหนักให้อยู่ในร่องรอก ไม่พันกัน, ลูกตุ้มน้ำหนักลอยแขวนอิสระไม่แตะพื้น\n- จัดท่าผู้ป่วยให้อยู่ในแนวตรงตามแนวแรงดึง (Body alignment)\n- ตรวจสอบผิวหนังและตำแหน่ง Pin site ทำความสะอาดด้วยเทคนิคปลอดเชื้อทุกวัน\nResponse: แนวการดึงถูกต้อง น้ำหนักถ่วงคงที่ Pin site แห้งสะอาด ไม่มีสิ่งคัดหลั่งซึมหรืออักเสบติดเชื้อ"},{"shortcut":".mobility","title":"บกพร่องในการเคลื่อนไหวร่างกาย (Impaired Physical Mobility)","content":"Focus: บกพร่องในการเคลื่อนไหวร่างกายเนื่องจากกระดูกหัก/มีข้อจำกัดการลงน้ำหนัก\nGoal: ผู้ป่วยสามารถเคลื่อนไหว พลิกตัว และใช้อุปกรณ์ช่วยเดินได้อย่างปลอดภัย ถูกต้องตามแผนการรักษา และไม่เกิดอุบัติเหตุหกล้ม\nData: ผู้ป่วยเคลื่อนไหวลำบาก ช่วยเหลือตนเองบนเตียงได้บางส่วน ต้องใช้ไม้ค้ำยัน/Walker\nAction:\n- ช่วยเหลือในการทำกิจวัตรประจำวัน, ช่วยพลิกตะแคงตัวสลับข้างทุก 2 ชั่วโมง\n- สอนการบริหารข้อต่อและกล้ามเนื้อส่วนที่ไม่ได้บาดเจ็บ\n- ฝึกสอนการใช้อุปกรณ์ช่วยเดิน (Walker / Crutches) ตามระดับการลงน้ำหนักที่แพทย์กำหนด (NWB / PWB)\n- ประเมินความปลอดภัยขณะเคลื่อนไหว\nResponse: ผู้ป่วยเข้าใจและปฏิบัติตามคำแนะนำในการฝึกเดินได้อย่างถูกต้อง ปลอดภัย ไม่เกิดอุบัติเหตุ"}]},{"category":"4. การพยาบาลอายุรกรรม (Internal Medicine Nursing)","items":[{"shortcut":".chf","title":"หัวใจล้มเหลวและน้ำท่วมปอด (Heart Failure / Pulmonary Edema)","content":"Focus: ภาวะน้ำเกินและเหนื่อยหอบจากหัวใจล้มเหลว (Fluid Overload / CHF)\nGoal: ภาวะน้ำคั่งลดลง อาการหอบเหนื่อยทุเลา หายใจสะดวกขึ้น SpO2 ≥ 95% ไม่มีอาการบวม และปริมาณน้ำเข้า-ออกสมดุล\nData: ผู้ป่วยบ่นหายใจเหนื่อยหอบ นอนราบไม่ได้ (Orthopnea), หายใจเร็ว RR... /min, SpO2... %, ฟังปอดได้ยินเสียง Crepitation ชายปอดทั้ง 2 ข้าง, ขาทั้ง 2 ข้างบวมกดบุ๋ม (Pitting edema 2+), เส้นเลือดดำที่คอโป่งพอง (JVD positive)\nAction:\n- จัดท่านอนศีรษะสูง (High-Fowler\u0027s position)\n- ให้ออกซิเจน Mask with bag / Cannula ตามแผนการรักษา\n- ให้ยาขับปัสสาวะ Lasix (Furosemide)... mg IV ตามคำสั่งแพทย์\n- จำกัดน้ำดื่ม... ml/วัน และจำกัดอาหารเค็ม (Low salt diet)\n- บันทึก Intake-Output อย่างเคร่งครัด\n- ชั่งน้ำหนักตัวทุกเช้า\nResponse: ปัสสาวะออกเพิ่มขึ้น... ml หลังได้ยาขับปัสสาวะ, ผู้ป่วยหายใจเหนื่อยลดลง RR... /min, SpO2 เพิ่มขึ้นเป็น... %, ฟังปอดเสียง Crepitation ลดลง นอนพักได้"},{"shortcut":".acs","title":"กล้ามเนื้อหัวใจขาดเลือดเฉียบพลัน แน่นหน้าอก (ACS / Myocardial Infarction)","content":"Focus: เจ็บแน่นหน้าอกเฉียบพลันจากกล้ามเนื้อหัวใจขาดเลือด (Acute Chest Pain / ACS)\nGoal: บรรเทาอาการเจ็บแน่นหน้าอก กล้ามเนื้อหัวใจได้รับออกซิเจนเพียงพอ สัญญาณชีพและคลื่นไฟฟ้าหัวใจคงที่ และไม่เกิดภาวะแทรกซ้อนรุนแรง\nData: ผู้ป่วยบอกเจ็บแน่นหน้าอกตรงกลางเหมือนมีของหนักทับ ร้าวไปกรามและแขนซ้าย Pain score = .../10, เหงื่อแตก ตัวเย็น กระสับกระส่าย, V/S: BP.../... mmHg, PR... /min\nAction:\n- ให้ผู้ป่วยนอนพักนิ่งบนเตียง (Absolute bed rest)\n- ให้ออกซิเจน Cannula 3-4 LPM\n- รายงานแพทย์ทันที\n- ทำ EKG 12 leads ส่งแพทย์อ่านผล\n- ดูแลให้ยา Isordil (Isosorbide dinitrate) 5 mg อมใต้ลิ้นทันที และให้ยาตามแผนการรักษา (Aspirin, Clopidogrel, Morphine)\n- เจาะเลือดส่งตรวจ Cardiac markers (Troponin-T/I, CK-MB)\nResponse: หลังได้รับยาและนอนพัก อาการแน่นหน้าอกทุเลาลง Pain score ลดลงเหลือ.../10, EKG ไม่พบ ST elevation เพิ่มขึ้น, สัญญาณชีพคงที่ เฝ้าระวังอาการต่อเนื่อง"},{"shortcut":".htn","title":"ความดันโลหิตสูงวิกฤต (Hypertensive Urgency / Crisis)","content":"Focus: ความดันโลหิตสูงรุนแรงเสี่ยงต่อภาวะแทรกซ้อนทางหลอดเลือดสมองและหัวใจ\nGoal: ควบคุมความดันโลหิตให้อยู่ในเกณฑ์เป้าหมายตามแผนการรักษา (\u003c 140/90 mmHg หรือตามแพทย์สั่ง) และไม่เกิดภาวะแทรกซ้อนทางสมองและหัวใจ\nData: วัดความดันโลหิตได้สูงมาก BP = .../... mmHg (SBP \u003e 180 หรือ DBP \u003e 110), บ่นปวดศีรษะตึงบริเวณท้ายทอย ตาพร่ามัว เวียนศีรษะ คลื่นไส้\nAction:\n- ให้ผู้ป่วยนอนพักผ่อนบนเตียงในสิ่งแวดล้อมที่เงียบสงบ\n- ดูแลให้ยาลดความดันโลหิต... ตามแผนการรักษาของแพทย์\n- ประเมินอาการทางระบบประสาท (Neuro sign) ตรวจเช็คการพูด แขนขาอ่อนแรง\n- วัดและบันทึกสัญญาณชีพซ้ำทุก 15-30 นาที\nResponse: ความดันโลหิตค่อยๆ ลดลงสู่ระดับเป้าหมาย BP = .../... mmHg, อาการปวดศีรษะและตาพร่ามัวทุเลาลง ไม่มีอาการแขนขาอ่อนแรง"},{"shortcut":".copd","title":"ปอดอุดกั้นเรื้อรัง/หอบหืดกำเริบเฉียบพลัน (COPD / Asthma Exacerbation)","content":"Focus: หายใจลำบากและแลกเปลี่ยนก๊าซบกพร่องจากหลอดลมตีบเกร็ง\nGoal: การระบายอากาศดีขึ้น อาการหอบเหนื่อยลดลง ขับเสมหะได้ SpO2 อยู่ในเกณฑ์ 88-92% และไม่มีภาวะคาร์บอนไดออกไซด์คั่ง\nData: ผู้ป่วยหายใจหอบเหนื่อย ใช้กล้ามเนื้อช่วยหายใจ (Accessory muscle use), อัตราการหายใจ RR... /min, SpO2... %, ฟังปอดได้ยินเสียง Wheezing ทั้งสองข้าง, ไอมีเสมหะเหนียว\nAction:\n- จัดท่านอนศีรษะสูงหรือนั่งโน้มตัวไปข้างหน้า (Tripod position)\n- ให้ออกซิเจน Low flow (Venturi mask หรือ Cannula 1-2 LPM ควบคุม SpO2 88-92%)\n- พ่นยาขยายหลอดลม (Berodual / Ventolin + Atrovent) ตามแผนการรักษา\n- ให้ยา Corticosteroid IV ตามคำสั่งแพทย์\n- สอนการหายใจแบบห่อปาก (Pursed-lip breathing)\nResponse: หายใจหอบเหนื่อยลดลง การใช้กล้ามเนื้อช่วยหายใจลดลง, SpO2 อยู่ในเกณฑ์เป้าหมาย... %, ฟังปอดเสียง Wheezing ทุเลาลง หายใจโล่งขึ้น"},{"shortcut":".pneumonia","title":"ปอดอักเสบติดเชื้อ (Pneumonia)","content":"Focus: ติดเชื้อในระบบทางเดินหายใจและมีเสมหะคั่งค้าง\nGoal: ทางเดินหายใจโล่ง ขับเสมหะได้ดี ไข้ลดลง อาการหอบเหนื่อยทุเลา SpO2 ≥ 95% และผลตรวจทางห้องปฏิบัติการ/ภาพรังสีปอดดีขึ้น\nData: มีไข้สูง T... °C, ไอมีเสมหะข้นเหนียวสีเขียว/เหลือง, หายใจเหนื่อย หายใจเร็ว, ฟังปอดได้ยินเสียง Crepitation ชายปอด, ผล CXR พบ Infiltration บริเวณ...\nAction:\n- จัดท่านอนศีรษะสูง, เคาะปอดระบายเสมหะและสอนการไอขับเสมหะอย่างมีประสิทธิภาพ\n- ให้ออกซิเจนตามแผนการรักษา\n- ดูแลให้ยาปฏิชีวนะ (Antibiotics)... ทางหลอดเลือดดำตรงเวลาสม่ำเสมอ\n- เช็ดตัวลดไข้เมื่ออุณหภูมิ \u003e 38.5 °C\n- กระตุ้นให้ดื่มน้ำอุ่นวันละ 2,000 ml\nResponse: ไข้ลดลง เสมหะขับออกได้ง่ายขึ้น สีจางลงและเหนียวน้อยลง, SpO2 = ... %, อาการเหนื่อยหอบลดลง"},{"shortcut":".dka","title":"ภาวะน้ำตาลในเลือดสูงวิกฤต (DKA / Hyperglycemia)","content":"Focus: ภาวะน้ำตาลในเลือดสูงรุนแรงและกรดคีโตนคั่งในร่างกาย (DKA / HHS)\nGoal: ระดับน้ำตาลในเลือดลดลงสู่เกณฑ์ปลอดภัย ภาวะกรดคีโตนในเลือดดีขึ้น สารน้ำและเกลือแร่กลับสู่สมดุล และผู้ป่วยรู้สึกตัวดี\nData: ผู้ป่วยซึมลง หายใจเร็วลึก (Kussmaul breathing) มีกลิ่นลมหายใจคล้ายผลไม้ (Fruity odor), ผิวหนังแห้ง ริมฝีปากแห้ง, ตรวจ DTX = ... mg/dL, Urine ketone/sugar positive, V/S: BP.../... mmHg, PR... /min\nAction:\n- รายงานแพทย์ทันที\n- เปิดเส้นเลือดดำให้สารน้ำ 0.9% NSS ในอัตราเร็วตามแผนการรักษาเพื่อแก้ไขภาวะขาดน้ำ\n- ให้ยาฉีดอินซูลิน Regular Insulin (RI) ทางหลอดเลือดดำตามแพทย์สั่ง\n- บันทึกสัญญาณชีพและเจาะตรวจ DTX ทุก 1 ชั่วโมง\n- ติดตามผลตรวจระดับเกลือแร่ (Electrolyte โดยเฉพาะ Potassium) และค่าก๊าซในเลือด (ABG)\n- บันทึก Intake-Output ทุกชั่วโมง\nResponse: ระดับน้ำตาลในเลือด DTX ค่อยๆ ลดลงสู่ระดับ... mg/dL, ภาวะขาดน้ำทุเลาลง ปัสสาวะออกดี (\u003e 0.5 ml/kg/hr), ผู้ป่วยรู้สึกตัวตื่นขึ้น หายใจเร็วลึกลดลง"},{"shortcut":".hypo","title":"ภาวะน้ำตาลในเลือดต่ำ (Hypoglycemia)","content":"Focus: ภาวะน้ำตาลในเลือดต่ำเสี่ยงต่อการหมดสติและสมองขาดพลังงาน\nGoal: ระดับน้ำตาลในเลือด DTX กลับสู่เกณฑ์ปกติ (≥ 100 mg/dL) อาการใจสั่น มือสั่น เหงื่อแตก ซึมทุเลาลง และผู้ป่วยปลอดภัย\nData: ผู้ป่วยรู้สึกใจสั่น มือสั่น เหงื่อแตกท่วมตัว หน้าซีด อ่อนเพลีย สับสน พูดไม่ชัด, ตรวจ DTX = ... mg/dL (ต่ำกว่า 70 mg/dL)\nAction: ให้การพยาบาลแก้ไขตามเกณฑ์ Rule of 15 ทันที:\n* กรณีรู้สึกตัวดี: ให้ดื่มน้ำหวาน/น้ำผลไม้ 1 แก้ว (150-200 ml) หรือน้ำหวานเข้มข้น 1 ช้อนโต๊ะ\n* กรณีซึม/ไม่รู้สึกตัว/NPO: รีบรายงานแพทย์และให้ 50% Glucose 50 ml ทางหลอดเลือดดำทันที\nตรวจวัดระดับน้ำตาล DTX ซ้ำหลังให้การดูแล 15 นาที, ประเมินอาการทางระบบประสาทอย่างใกล้ชิด\nResponse: ตรวจ DTX ซ้ำได้... mg/dL (\u003e 100 mg/dL), ผู้ป่วยรู้สึกตัวดี อาการใจสั่น มือสั่น เหงื่อแตกทุเลาลง ปลอดภัยดี"},{"shortcut":".ckd","title":"ไตวายเรื้อรัง/บวมน้ำและของเสียคั่ง (CKD / Uremia)","content":"Focus: ภาวะบวมน้ำและสารน้ำคั่งค้างเนื่องจากไตทำงานบกพร่อง (Fluid Retention in CKD)\nGoal: ปริมาณน้ำและของเสียในร่างกายสมดุล ไม่มีภาวะน้ำเกินหรือน้ำท่วมปอด เกลือแร่ในเลือดอยู่ในเกณฑ์ปลอดภัย และชะลอการเสื่อมของไต\nData: ผู้ป่วยมีประวัติโรคไตเรื้อรัง (CKD Stage...), ขาบวมกดบุ๋มทั้งสองข้าง Pitting edema 2+, ปัสสาวะออกน้อย... ml/วัน, ค่า eGFR... , Cr... , BUN... , K+...\nAction:\n- บันทึกปริมาณน้ำเข้า-ออก (Intake-Output) อย่างเข้มงวด\n- จำกัดปริมาณน้ำดื่มตามแพทย์สั่ง (... ml/วัน)\n- ให้สุขศึกษาจำกัดอาหารที่มีโพแทสเซียมสูง (กล้วย ส้ม มะเขือเทศ) โซเดียมสูง และฟอสฟอรัสสูง\n- ชั่งน้ำหนักตัวเวลาเดียวกันทุกเช้า\n- ดูแลให้ยาขับปัสสาวะ/ยาจับฟอสฟอรัสตามแผนการรักษา\nResponse: ผู้ป่วยและญาติปฏิบัติตามการจำกัดน้ำและอาหารได้ดี น้ำหนักตัวไม่เพิ่มขึ้น ไม่มีอาการเหนื่อยหอบ ปัสสาวะออกได้ต่อเนื่อง"},{"shortcut":".hd","title":"การพยาบาลผู้ป่วยฟอกเลือดด้วยเครื่องไตเทียม (Hemodialysis Care)","content":"Focus: การดูแลหลอดเลือดสำหรับฟอกเลือดและเฝ้าระวังภาวะแทรกซ้อนหลังฟอกเลือด\nGoal: การฟอกเลือดดำเนินไปด้วยความราบรื่นและปลอดภัย เส้นฟอกเลือด (AVF/AVG) ใช้งานได้ดี มี Thrill/Bruit ชัดเจน และไม่เกิดภาวะความดันตกหลังฟอกเลือด\nData: ผู้ป่วยได้รับการฟอกเลือดด้วยเครื่องไตเทียม (Hemodialysis) ผ่านเส้นฟอกเลือด (AVF / AVG / Double lumen catheter)\nAction:\n- ตรวจคลำการสั่นสะเทือน (Thrill) และฟังเสียงฟู่ (Bruit) บริเวณเส้นฟอกเลือดทุกเวร\n- ห้ามวัดความดันโลหิต ห้ามเจาะเลือด หรือให้สารน้ำบริเวณแขนข้างที่มีเส้นฟอกเลือด\n- สังเกตตำแหน่งเข็มฟอกเลือดไม่มีเลือดซึมหรือบวมช้ำ, หลังฟอกเลือดตรวจวัดสัญญาณชีพเฝ้าระวังความดันโลหิตต่ำ (Post-HD Hypotension)\nResponse: เส้นฟอกเลือด Thrill/Bruit ชัดเจนดี แผลฟอกเลือดไม่มีเลือดซึม สัญญาณชีพหลังฟอกเลือดคงที่ ไม่มีอาการเวียนศีรษะหรือตะคริว"},{"shortcut":".ugib","title":"เลือดออกในทางเดินอาหารส่วนบน (Upper GI Bleed)","content":"Focus: เสี่ยงต่อภาวะช็อกจากการสูญเสียเลือดในระบบทางเดินอาหาร\nGoal: ภาวะเลือดออกในทางเดินอาหารหยุด สัญญาณชีพคงที่ ไม่มีอาการอาเจียนเป็นเลือดหรือถ่ายดำเพิ่ม และระดับฮีโมโกลบินคงที่\nData: ผู้ป่วยถ่ายอุจจาระเป็นสีดำเหนียวคล้ายยางมะตอย (Melena) / อาเจียนเป็นเลือดสดหรือสีกาแฟ (Hematemesis), หน้าซีด เหงื่อแตก ตัวเย็น, V/S: BP.../... mmHg, PR... /min, ค่า Hb/Hct...\nAction:\n- ให้ผู้ป่วยนอนพักบนเตียง ยกปลายเท้าสูงเล็กน้อย\n- ให้ออกซิเจนตามแผนการรักษา\n- ใส่สายยางทางจมูกถึงกระเพาะอาหาร (NG tube) ดูแล Gastric lavage ด้วยน้ำเย็นตามคำสั่งแพทย์และบันทึกสี/ปริมาณ\n- เปิดเส้นเลือดดำขนาดใหญ่ให้สารน้ำและเตรียมจองเลือด (PRC)\n- ให้ยา Proton Pump Inhibitor (Omeprazole/Pantoprazole) IV ตามคำสั่ง\n- งดน้ำและอาหาร (NPO)\nResponse: เลือดสดจากการ Lavage จางลง, ได้รับสารน้ำและเลือดทดแทน สัญญาณชีพคงที่ BP.../... mmHg, PR... /min"},{"shortcut":".cirrhosis","title":"ตับแข็งและภาวะท้องมาน (Cirrhosis \u0026 Ascites)","content":"Focus: ภาวะท้องมานและเสี่ยงต่อการเกิดภาวะสมองทำงานบกพร่องจากตับวาย (Hepatic Encephalopathy)\nGoal: ลดการคั่งของน้ำในช่องท้อง (Ascites) ไม่มีภาวะเลือดออกในทางเดินอาหาร สติสัมปชัญญะคงที่ ไม่เกิดภาวะ Hepatic encephalopathy\nData: ท้องมานโต ตึง แน่นอึดอัดท้อง หายใจไม่สะดวก, ตาเหลือง ตัวเหลือง (Jaundice), ประเมินระดับความรู้สึกตัว (Orientation to time, place, person)\nAction:\n- วัดขนาดรอบเอว (Abdominal girth) และชั่งน้ำหนักทุกวัน\n- จัดท่านอนศีรษะสูงเพื่อช่วยให้กระบังลมขยายตัวหายใจสะดวกขึ้น\n- จำกัดโซเดียมและน้ำดื่มตามแผนการรักษา\n- ดูแลให้ยาขับปัสสาวะและยาระบาย Lactulose เพื่อขับสารแอมโมเนีย\n- ประเมินอาการสับสน มือสั่นกระตุก (Asterixis / Flapping tremor)\nResponse: ผู้ป่วยรู้สึกตัวดี สื่อสารตรงประเด็น ไม่มีอาการสับสน มือไม่สั่น, รอบเอวลดลงเหลือ... cm, หายใจเหนื่อยลดลง"},{"shortcut":".stroke","title":"โรคหลอดเลือดสมองเฉียบพลัน (Acute Stroke / CVA)","content":"Focus: การทำงานของระบบประสาทบกพร่องเนื่องจากสมองขาดเลือดหรือมีเลือดออกในสมอง\nGoal: ควบคุมความดันโลหิตและสัญญาณประสาทให้คงที่ ป้องกันเนื้อสมองขาดเลือดเพิ่ม ไม่เกิดภาวะสำลัก และฟื้นฟูสมรรถภาพการเคลื่อนไหว\nData: ผู้ป่วยมีอาการแขนขาข้าง... อ่อนแรง (Motor power grade...), ปากเบี้ยว พูดไม่ชัด กลืนลำบาก, ระดับความรู้สึกตัว GCS = ... คะแนน (E... V... M...)\nAction:\n- จัดท่านอนศีรษะสูง 30 องศา (Head up 30 degrees) แนวคอตรงไม่พับงอ\n- ตรวจประเมินสัญญาณทางระบบประสาท (Neuro sign) และ GCS ทุก... ชม.\n- เฝ้าระวังและควบคุมความดันโลหิตให้อยู่ในเกณฑ์ที่แพทย์กำหนด\n- ทดสอบการกลืน (Swallowing test) ก่อนให้อาหาร/น้ำเพื่อป้องกันการสำลักลงปอด (Aspiration)\n- พลิกตะแคงตัวและจัดวางแขนขาข้างที่อ่อนแรงในท่าที่ถูกต้อง (Functional position)\nResponse: สัญญาณทางระบบประสาทคงที่ GCS... คะแนน, ไม่มีอาการสำลัก, แขนขาข้างที่อ่อนแรงได้รับการจัดท่าถูกต้อง ไม่มีข้อติดแข็ง"},{"shortcut":".sepsis","title":"ภาวะติดเชื้อในกระแสเลือด (Sepsis Hour-1 Bundle)","content":"Focus: เสี่ยงต่อภาวะช็อกจากการติดเชื้อในกระแสเลือด (Septic Shock / Hypoperfusion)\nGoal: สัญญาณชีพคงที่ ค่า Serum Lactate ลดลงสู่เกณฑ์ปกติ ได้รับยาปฏิชีวนะและสารน้ำครบตาม Hour-1 Bundle และป้องกันภาวะ Septic shock\nData: มีไข้สูง T... °C (หรือตัวเย็น T \u003c 36 °C), หายใจเร็ว RR... /min, ชีพจรเต้นเร็ว PR... /min, ความดันโลหิตเริ่มลดลง SBP... mmHg, ผลตรวจเลือดพบ WBC... , Serum Lactate... mmol/L\nAction: ปฏิบัติตามแนวทางการดูแลผู้ป่วย Sepsis (Hour-1 Bundle) อย่างเร่งด่วน:\n1. เจาะเลือดส่งตรวจ Hemoculture 2 ตำแหน่งก่อนเริ่มยาปฏิชีวนะ\n2. ให้ยาปฏิชีวนะทางหลอดเลือดดำ (Broad-spectrum IV Antibiotics)... ทันทีภายใน 1 ชั่วโมง\n3. ให้สารน้ำอย่างรวดเร็ว (Fluid resuscitation) 0.9% NSS หรือ Acetar 30 ml/kg ภายใน 3 ชั่วโมง\n4. ติดตามค่า Serum Lactate ซ้ำตามแผนการรักษา\n5. บันทึกสัญญาณชีพทุก 15-30 นาที และใส่สายสวนปัสสาวะเพื่อติดตาม Urine output ทุก 1 ชั่วโมง (เป้าหมาย \u003e 0.5 ml/kg/hr)\nResponse: สัญญาณชีพเริ่มคงที่หลังได้รับสารน้ำ BP = .../... mmHg (MAP \u003e 65 mmHg), ปัสสาวะออกดี... ml/hr, ได้รับยาฆ่าเชื้อตรงตามเวลา"},{"shortcut":".tb","title":"วัณโรคปอดและการป้องกันการแพร่กระจายเชื้อ (Pulmonary TB)","content":"Focus: เสี่ยงต่อการแพร่กระจายเชื้อวัณโรคสู่ผู้อื่น (Airborne Infection)\nGoal: ผู้ป่วยได้รับยาต้านวัณโรคครบถ้วน อาการไอและไข้ลดลง ป้องกันการแพร่กระจายเชื้อสู่ผู้อื่น และไม่เกิดผลข้างเคียงจากยาต้านวัณโรค\nData: ผู้ป่วยได้รับการวินิจฉัย/สงสัยวัณโรคปอด (Pulmonary TB), ผล Sputum AFB positive, ไอเรื้อรัง มีไข้ต่ำๆ ตอนเย็น เหงื่อออกกลางคืน น้ำหนักลด\nAction:\n- จัดผู้ป่วยให้อยู่ในห้องแยกโรคความดันลบ (Negative pressure room) หรือห้องแยกเดี่ยวที่อากาศถ่ายเทสะดวก\n- ติดป้ายเตือนการป้องกันการติดเชื้อทางอากาศ (Airborne Precaution) หน้าห้อง\n- ให้ผู้ป่วยสวม Surgical mask ตลอดเวลาเมื่อต้องออกจากห้อง, บุคลากรทางการแพทย์สวมหน้ากาก N95 ทุกครั้งก่อนเข้าห้องผู้ป่วย\n- สอนสุขอนามัยการไอจาม (Cough etiquette) โดยใช้กระดาษชำระปิดปากและทิ้งลงในถังขยะติดเชื้อ\n- ดูแลให้ยารักษาวัณโรค (Anti-TB drugs) ตามแผนการรักษา\nResponse: ผู้ป่วยเข้าใจและปฏิบัติตามมาตรการป้องกันการแพร่เชื้อ สวมหน้ากากอนามัยถูกต้อง บุคลากรใช้อุปกรณ์ PPE ครบถ้วน"}]},{"category":"5. ความปลอดภัยและการป้องกันภาวะแทรกซ้อน","items":[{"shortcut":".fall","title":"เสี่ยงต่อการพลัดตกหกล้ม (High Risk for Falls)","content":"Focus: เสี่ยงต่อการพลัดตกหกล้ม (High Risk for Falls)\nGoal: ผู้ป่วยและญาติมีความตระหนักและปฏิบัติตามมาตรการป้องกันการพลัดตกหกล้ม ไม่เกิดอุบัติเหตุพลัดตกหกล้มตลอดการพักรักษาตัวในโรงพยาบาล\nData: ประเมิน Fall risk score = ... คะแนน (กลุ่มเสี่ยงสูง), ผู้ป่วยสูงอายุ / เคลื่อนไหวไม่คล่องตัว / ได้รับยาที่ทำให้ง่วงซึม\nAction:\n[☀️ เวรเช้า]\n- ประเมินความเสี่ยงต่อการพลัดตกหกล้ม (Morse Fall Scale) ติดป้ายเตือนเสี่ยงล้มที่ข้อมือและหัวเตียง\n- จัดสภาพแวดล้อมรอบเตียงให้แห้ง สะอาด แสงสว่างเพียงพอ ไม่มีสายไฟหรือสิ่งกีดขวางทางเดิน\n- วางกริ่งเรียกพยาบาลและของใช้จำเป็นในระยะที่ผู้ป่วยเอื้อมถึงได้สะดวก\n- แนะนำการใช้อุปกรณ์ช่วยเดิน (Walker / ไม้เท้า) และมีเจ้าหน้าที่ช่วยประคองทุกครั้งที่ลงจากเตียง\n[⛅ เวรบ่าย]\n- ตรวจเช็คไม้กั้นเตียงยกขึ้นทั้ง 2 ข้าง และปรับระดับเตียงให้อยู่ระดับต่ำสุดพร้อมล็อกล้อเตียง\n- กำชับผู้ป่วยและญาติให้กดกริ่งเรียกพยาบาลทุกครั้งที่ต้องการลุกจากเตียง โดยเฉพาะเวลาไปห้องน้ำ\n- ตรวจสอบผู้ป่วยที่ได้รับยานอนหลับหรือยาที่มีผลต่อความดันโลหิต ให้ระวังอาการหน้ามืดเวลาเปลี่ยนท่า\n[🌙 เวรดึก]\n- ตรวจสอบไม้กั้นเตียงยกขึ้นทั้ง 2 ข้างอย่างแน่นหนา และล็อกล้อเตียงเรียบร้อย\n- เปิดไฟส่องสว่างนำทาง (Night light) ในห้องและทางไปห้องน้ำ ป้องกันการสะดุดล้มในความมืด\n- ช่วยเหลือผู้ป่วยในการขับถ่ายข้างเตียงโดยใช้ Urinal หรือ Commode chair ไม่ให้เดินไปห้องน้ำลำพัง\n- เดินตรวจเวรทุก 1-2 ชั่วโมง สังเกตผู้ป่วยที่กระสับกระส่ายหรือพยายามปีนไม้กั้นเตียง\nResponse: ผู้ป่วยและญาติเข้าใจและให้ความร่วมมือ ไม้กั้นเตียงยกขึ้นตลอดเวลา ไม่พบอุบัติเหตุพลัดตกหกล้มในเวร"},{"shortcut":".pressure","title":"เสี่ยงต่อการเกิดแผลกดทับ (Risk for Pressure Injury)","content":"Focus: เสี่ยงต่อการเกิดแผลกดทับเนื่องจากการนอนนิ่งบนเตียงเป็นเวลานาน\nGoal: ผิวหนังบริเวณปุ่มกระดูกคงความสมบูรณ์ ไม่เกิดแผลกดทับรายใหม่ (Zero New Pressure Injury) และแผลเดิมได้รับการดูแลจนสมานดีขึ้น\nData: ประเมิน Braden Scale = ... คะแนน (กลุ่มเสี่ยงปานกลาง/สูง), ผู้ป่วยเคลื่อนไหวลำบาก นอนติดเตียง\nAction:\n- พลิกตะแคงตัวสลับซ้าย-หงาย-ขวา ทุก 2 ชั่วโมงตามตาราง\n- จัดหาที่นอนลมลดแรงกดทับ (Air mattress)\n- ดูแลผ้าปูเตียงให้สะอาด เรียบตึง และแห้งอยู่เสมอ\n- ใช้อุปกรณ์หนุนรองบริเวณปุ่มกระดูก (ส้นเท้า, ก้นกบ)\n- ทาโลชั่นบำรุงผิวหนังไม่ให้แห้งแตก\nResponse: ผิวหนังบริเวณก้นกบและปุ่มกระดูกต่างๆ ทั่วร่างกายเรียบเนียน ไม่มีรอยแดงหรือแผลกดทับ (Skin intact, Stage 0)"},{"shortcut":".infection","title":"เสี่ยงต่อการติดเชื้อในระบบต่างๆ (Risk for Infection)","content":"Focus: เสี่ยงต่อการติดเชื้อเนื่องจากมีแผลผ่าตัดและอุปกรณ์คาสายในร่างกาย\nGoal: แผลผ่าตัดและตำแหน่งสายสวนต่างๆ สะอาด ไม่เกิดการติดเชื้อในโรงพยาบาล (Healthcare-associated infection) และสัญญาณชีพปกติ\nData: ผู้ป่วยมีแผลผ่าตัด, สายน้ำเกลือ (IV line), สายสวนปัสสาวะ, V/S: T... °C, PR... /min, WBC...\nAction:\n- ปฏิบัติการพยาบาลโดยยึดหลัก Aseptic technique อย่างเคร่งครัด\n- ล้างมือตามหลัก 5 Moments\n- ดูแลความสะอาดของ IV site และแผลผ่าตัด\n- ดูแลสายสวนปัสสาวะเป็นระบบปิด\n- ติดตามสัญญาณชีพและสังเกตอาการไข้ หนาวสั่น บวมแดง\nResponse: อุณหภูมิร่างกายปกติ ไม่มีไข้, ตำแหน่งคาสายต่างๆ แห้งสะอาด ไม่มีอาการอักเสบติดเชื้อ"},{"shortcut":".dvt","title":"เสี่ยงต่อภาวะลิ่มเลือดอุดตันในหลอดเลือดดำส่วนลึก (Risk for DVT)","content":"Focus: เสี่ยงต่อภาวะหลอดเลือดดำส่วนลึกอุดตัน (Deep Vein Thrombosis)\nGoal: การไหลเวียนโลหิตในหลอดเลือดดำส่วนปลายดี ไม่มีอาการปวดบวมแดงร้อนที่น่อง และไม่เกิดภาวะลิ่มเลือดอุดตันในหลอดเลือดดำลึก (DVT / PE)\nData: ผู้ป่วยหลังผ่าตัดกระดูกสะโพก/ขา เคลื่อนไหวได้น้อย นอนบนเตียง\nAction:\n- สวมปลอกขาลดการคั่งของเลือด (TED stockings / IPC)\n- สอนและกระตุ้นให้บริหารข้อเท้า กระดกปลายเท้าขึ้น-ลง (Ankle pumping exercise) บ่อยๆ\n- ดูแลให้ยาป้องกันลิ่มเลือดอุดตัน (Anticoagulant) ตามคำสั่งแพทย์\n- สังเกตอาการปวด บวม แดง ร้อน บริเวณน่องและขา\nResponse: ขาทั้งสองข้างขนาดเท่ากัน ไม่มีอาการบวมแดงหรือกดเจ็บบริเวณน่อง (Homan\u0027s sign negative)"}]},{"category":"6. สารน้ำ สารอาหาร และการขับถ่าย","items":[{"shortcut":".iv","title":"การดูแลให้สารน้ำทางหลอดเลือดดำ (IV Infusion Care)","content":"Focus: ได้รับสารน้ำทางหลอดเลือดดำตามแผนการรักษา\nGoal: สารน้ำและยาหยดต่อเนื่องตามแผนการรักษา ตำแหน่งแทงเข็มน้ำเกลือปกติ ไม่มีอาการบวม แดง ปวด หรือรั่วซึม (Phlebitis Grade 0)\nData: ได้รับสารน้ำ... อัตราไหล... ml/hr ตำแหน่งเส้นเลือดดำบริเวณ...\nAction:\n- ตรวจสอบความถูกต้องของชนิดและอัตราการไหลของสารน้ำ\n- ตรวจประเมินตำแหน่งแทงเข็มน้ำเกลือ สังเกตอาการบวม แดง ปวด หรือน้ำเกลือซึมรั่ว (Phlebitis / Infiltration check)\n- บันทึก Intake-Output\nResponse: สารน้ำไหลสะดวกดี ไม่มีอาการปวด บวม แดง หรือเลื่อนหลุดรอบตำแหน่งแทงเข็ม"},{"shortcut":".foley","title":"ดูแลสายสวนปัสสาวะและป้องกัน CAUTI (Foley\u0027s Catheter Care)","content":"Focus: ดูแลสายสวนปัสสาวะและป้องกันการติดเชื้อในระบบทางเดินปัสสาวะ (CAUTI Prevention)\nGoal: ปัสสาวะระบายไหลสะดวก ถุงและสายสวนเป็นระบบปิดสะอาด ปัสสาวะสีเหลืองใส ปริมาณ ≥ 0.5 ml/kg/hr และไม่เกิดการติดเชื้อ CAUTI\nData: Retained Foley\u0027s catheter No. ... ต่อถุงปัสสาวะ (Urine bag)\nAction:\n- ทำความสะอาดอวัยวะสืบพันธุ์ภายนอกและสายสวนด้วยน้ำยาฆ่าเชื้อวันละ 2 ครั้งและหลังขับถ่าย\n- ดูแลสายสวนไม่ให้หักพับงอ\n- แขวนถุงปัสสาวะให้อยู่ต่ำกว่าระดับกระเพาะปัสสาวะเสมอ\n- เทปัสสาวะและบันทึกปริมาณ สี ความใสทุกเวร\nResponse: ปัสสาวะไหลสะดวก สีเหลืองใส ไม่มีตะกอนหรือกลิ่นเหม็นผิดปกติ ปริมาณ... ml/เวร"},{"shortcut":".constipation","title":"ภาวะท้องผูกจากการนอนนิ่งและยาแก้ปวด (Constipation)","content":"Focus: ภาวะท้องผูกเนื่องจากความพร่องในการเคลื่อนไหวและได้รับยาแก้ปวดกลุ่ม Opioids\nGoal: ระบบขับถ่ายทำงานมีประสิทธิภาพ ผู้ป่วยสามารถถ่ายอุจจาระได้นุ่ม ไม่ต้องออกแรงเบ่ง และไม่มีอาการแน่นอึดอัดท้อง\nData: ผู้ป่วยบอกไม่ได้ถ่ายอุจจาระมา... วัน, บ่นอึดอัดแน่นท้อง, ฟังเสียงลำไส้ Bowel sound... ครั้ง/นาที\nAction:\n- ประเมินแบบแผนการขับถ่าย\n- กระตุ้นให้ดื่มน้ำอุ่น 2,000-2,500 ml/วัน (หากไม่มีข้อห้าม)\n- แนะนำอาหารที่มีกากใยสูง ผัก ผลไม้, ช่วยนวดหน้าท้องตามแนวการเคลื่อนของลำไส้ใหญ่\n- ดูแลให้ยาระบายตามแผนการรักษาของแพทย์\nResponse: หลังให้การพยาบาล ผู้ป่วยสามารถถ่ายอุจจาระได้ อุจจาระนิ่ม ขับถ่ายสะดวก สบายท้องขึ้น"},{"shortcut":".nausea","title":"คลื่นไส้ อาเจียน (Nausea \u0026 Vomiting)","content":"Focus: มีอาการคลื่นไส้ อาเจียนจากผลข้างเคียงของยาดมสลบ/ยาแก้ปวด\nGoal: อาการคลื่นไส้อาเจียนทุเลาลง สามารถรับประทานอาหารและสารน้ำได้ ไม่เกิดภาวะขาดน้ำ และไม่เกิดการสำลักลงปอด\nData: ผู้ป่วยบ่นคลื่นไส้ พะอืดพะอม อาเจียน... ครั้ง เป็นเศษอาหาร/น้ำย่อยสีเหลือง\nAction:\n- จัดท่านอนศีรษะสูงหรือนอนตะแคงเพื่อป้องกันการสำลัก\n- ดูแลเช็ดปากและทำความสะอาดหลังอาเจียน\n- ให้บ้วนปากด้วยน้ำสะอาด\n- ดูแลให้ยาแก้อาเจียน... ตามคำสั่งแพทย์\n- งดอาหารและน้ำชั่วคราวจนกว่าอาการจะดีขึ้น\nResponse: อาการคลื่นไส้ทุเลาลง ไม่อาเจียนเพิ่ม สีหน้าสดชื่นขึ้น ไม่มีภาวะสำลัก"}]},{"category":"7. การรับใหม่ ส่งเวร และจำหน่าย (Admin/Shift/Discharge)","items":[{"shortcut":".nsadm","title":"บันทึกแรกรับผู้ป่วยใน (IPD Admission Note)","content":"Focus: รับใหม่ผู้ป่วยใน (Admission Note)\nGoal: ผู้ป่วยและญาติได้รับการปฐมนิเทศ คลายความวิตกกังวล ได้รับการประเมินแรกรับครบถ้วน และปลอดภัยตลอดการพักรักษาในหอผู้ป่วย\nData: รับใหม่ผู้ป่วยเพศ... อายุ... ปี มาจากห้องตรวจ/ER ด้วยอาการสำคัญ..., ระดับความรู้สึกตัว: ตื่นดี รู้เรื่อง (Alert), สัญญาณชีพแรกรับ: T... °C, BP.../... mmHg, PR... /min, RR... /min, SpO2... %\nAction:\n- ปฐมนิเทศผู้ป่วยและญาติ แนะนำสถานที่ กฎระเบียบ การใช้กริ่งเรียกพยาบาล สิทธิ์การรักษา\n- ประเมินความเสี่ยงล้ม/แผลกดทับ/ภาวะโภชนาการ\n- เจาะเลือดส่งตรวจ Lab และจัดยาตามคำสั่งแพทย์แรกรับ\n- รายงานแพทย์เวรรับทราบ\nResponse: ผู้ป่วยและญาติเข้าใจดี มีความร่วมมือ ไม่มีภาวะวิตกกังวล อยู่ในความดูแลของพยาบาลประจำหอผู้ป่วย"},{"shortcut":".shift","title":"บันทึกส่งเวรพยาบาลประจำผลัด (End of Shift Handover)","content":"Focus: สรุปรายงานอาการผู้ป่วยประจำผลัด (Shift Summary)\nGoal: ผู้ป่วยได้รับการดูแลพยาบาลต่อเนื่องตามแผนการรักษา สัญญาณชีพคงที่ ได้รับยาตรงเวลา และปลอดภัยในทุกเวร\nData: ผู้ป่วยรู้สึกตัวดี สัญญาณชีพคงที่ (V/S stable): T... °C, BP.../... mmHg, PR... /min, SpO2... %\nAction:\n- ดูแลให้ยาตามตารางการรักษา\n- ตรวจสอบแผลผ่าตัดแห้งดี, สายระบายทำงานปกติ ปริมาณ... ml, ปัสสาวะออก... ml สีเหลืองใส, รับประทานอาหารได้ ไม่มีอาการคลื่นไส้อาเจียน\n- ยกไม้กั้นเตียงและดูแลความปลอดภัยรอบเตียง\nResponse: อาการทั่วไปคงที่ ปวดแผลทุเลา พักผ่อนได้ ส่งมอบเวรให้ผลัดถัดไปรับทราบและดูแลต่อเนื่อง"},{"shortcut":".transfer","title":"บันทึกส่งต่อ/ย้ายหอผู้ป่วย (Patient Transfer Note)","content":"Focus: ส่งต่อผู้ป่วยไปรับการรักษาต่อที่... (Transfer Note)\nGoal: การส่งย้ายผู้ป่วยไปยังหอผู้ป่วยปลายทางเป็นไปด้วยความราบรื่น รวดเร็ว ปลอดภัย และส่งมอบข้อมูลการรักษาครบถ้วน\nData: ผู้ป่วยมีแผนย้ายไปรับการรักษาต่อที่..., ระดับความรู้สึกตัว..., V/S ก่อนย้าย: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\nAction:\n- ตรวจสอบความพร้อมของเอกสาร Chart, ฟิล์ม X-ray, ยาประจำตัว และผล Lab ล่าสุด\n- ประสานงานพยาบาลหอผู้ป่วยปลายทาง\n- ตรวจสอบสายน้ำเกลือและสายระบายต่างๆ ให้เรียบร้อย\n- นำส่งผู้ป่วยพร้อมรายงานสรุปอาการและการรักษา\nResponse: ส่งผู้ป่วยถึงหอผู้ป่วยปลายทางปลอดภัย เจ้าหน้าที่รับมอบผู้ป่วยและเอกสารครบถ้วนเรียบร้อย"},{"shortcut":".dc","title":"บันทึกจำหน่ายกลับบ้านตามหลัก D-METHOD (Discharge Planning D-METHOD)","content":"Focus: ให้สุขศึกษาและคำแนะนำก่อนจำหน่ายตามหลัก D-METHOD\nGoal: ผู้ป่วยและญาติมีความรู้ความเข้าใจเกี่ยวกับโรค การดูแลแผล การรับประทานยา และการมาตรวจตามนัดตามหลัก D-METHOD อย่างถูกต้อง\nData: แพทย์มีคำสั่งให้ผู้ป่วยจำหน่ายกลับบ้านได้ อาการทั่วไปคงที่ V/S stable แผลผ่าตัดแห้งดี\nAction: ให้คำแนะนำจำหน่ายตามหลัก D-METHOD:\n1. D (Disease): อธิบายพยาธิสภาพของโรคและการดำเนินโรคให้ผู้ป่วยและญาติเข้าใจ\n2. M (Medicine): แนะนำชื่อยา ขนาด วิธีรับประทาน และอาการข้างเคียงที่ต้องระวัง\n3. E (Environment): การจัดสภาพแวดล้อมที่บ้านให้ปลอดภัย ห้องน้ำมีราวจับ ป้องกันการลื่นล้ม\n4. T (Treatment): การดูแลรักษาแผลผ่าตัด ระวังอย่าให้เปียกน้ำ การบริหารร่างกาย และข้อจำกัดการลงน้ำหนัก\n5. H (Health): การดูแลสุขภาพ โภชนาการ การพักผ่อน การสังเกตอาการผิดปกติ\n6. O (Outpatient): มอบใบนัดตรวจติดตามอาการ วันที่... เวลา... น. ณ แผนก...\n7. D (Diet): อาหารที่ควรรับประทาน (โปรตีนสูงช่วยสมานแผล) และอาหารที่ควรงดเว้น\nResponse: ผู้ป่วยและญาติเข้าใจคำแนะนำทั้งหมด สามารถทวนซ้ำได้ถูกต้อง ได้รับยากลับบ้านและใบนัดครบถ้วน เดินทางกลับบ้านปลอดภัย"},{"shortcut":".dama","title":"ปฏิเสธการรักษาและขอกลับบ้าน (Discharge Against Medical Advice)","content":"Focus: ผู้ป่วย/ญาติปฏิเสธการรักษาและประสงค์ขอกลับบ้าน (DAMA)\nGoal: ผู้ป่วยและญาติรับทราบข้อมูลเกี่ยวกับพยาธิสภาพ ความเสี่ยง และอันตรายจากการปฏิเสธการรักษาครบถ้วน และยินยอมลงนามในเอกสารตามระเบียบ\nData: ผู้ป่วยและญาติแสดงความจำนงขอยุติการรักษาและขอกลับบ้านด้วยเหตุผล...\nAction:\n- แพทย์และพยาบาลได้อธิบายถึงพยาธิสภาพของโรค แผนการรักษา และผลเสีย/อันตรายที่อาจเกิดขึ้นถึงแก่ชีวิตหากไม่ได้รับการรักษาต่อเนื่อง แต่ผู้ป่วยและญาติยังคงยืนยันขอกลับบ้าน\n- ให้ผู้ป่วย/ญาติลงลายมือชื่อในเอกสารปฏิเสธการรักษา (DAMA form) ไว้เป็นหลักฐาน\n- ถอดสายน้ำเกลือและอุปกรณ์ทางการแพทย์\n- มอบยากลับบ้านและเอกสารที่เกี่ยวข้อง\nResponse: ผู้ป่วยและญาติลงนามรับทราบความเสี่ยงเรียบร้อย และเดินทางออกจากโรงพยาบาลด้วยความสมัครใจ"}]},{"category":"8. สัญลักษณ์และคีย์ลัดย่อด่วน","items":[{"shortcut":".vs","title":"สัญญาณชีพ (Vital Signs)","content":"T: ... °C, BP: .../... mmHg, PR: ... /min, RR: ... /min, SpO2: ... %"},{"shortcut":".order","title":"รับคำสั่งแพทย์ทางโทรศัพท์ (Telephone Order)","content":"รับคำสั่งการรักษาทางโทรศัพท์จาก นพ./พญ. ... เมื่อเวลา... น. \nคำสั่งการรักษา: ...\nพยาบาลได้ทำการทวนสอบซ้ำ (Read back) ครบถ้วนถูกต้อง แพทย์ยืนยันคำสั่งเรียบร้อย"},{"shortcut":".dt","title":"วันที่และเวลาปัจจุบัน","content":"{NOW}"},{"shortcut":".d","title":"วันที่ปัจจุบัน","content":"{DATE}"},{"shortcut":".t","title":"เวลาปัจจุบัน","content":"{TIME}"}]},{"category":"9. ศัลยกรรมข้อเข่าเสื่อม Knee Arthroplasty (TKA / UKA / Rehab)","items":[{"shortcut":".tka","title":"ผ่าตัดเปลี่ยนข้อเข่าเทียม (Total Knee Arthroplasty: TKA)","content":"Focus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อเข่าเทียม (Post-Op TKA)\nGoal: การไหลเวียนโลหิตและเส้นประสาทปลายเท้าปกติ (CMS Intact) ควบคุมความปวดได้ดี สายระบายทำงานมีประสิทธิภาพ และไม่เกิดภาวะข้อเข่างอติดหรือ DVT\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Total Knee Arthroplasty (TKA) เข่าข้าง... แผลผ่าตัดปิด pressure dressing แนบสนิทดี, มีสายระบาย (Redivac/Hemovac) ต่อลงขวดสุญญากาศ มีเลือดออกสะสม... ml ลักษณะ serosanguinous, CMS check ปลายเท้า: ปลายเท้าอุ่น capillary refill \u003c 2 วินาที, คลำชีพจร Dorsalis pedis pulse ได้ชัดเจน, กระดิกนิ้วเท้าและข้อเท้าได้ ไม่บวมตึง, Pain score = .../10\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินแผลผ่าตัด ทำแผล (Dressing) ด้วย Normal Saline และเทคนิคปลอดเชื้อ\n- จัดวางขาบนเครื่องช่วยงอเข่าอัตโนมัติ (CPM) มุมงอเริ่มต้น... องศา นาน 1 ชม. ตามคำสั่งแพทย์\n- ฝึกสอนและกระตุ้นการบริหารกล้ามเนื้อ Quadriceps setting และ Ankle pumping exercise\n- ช่วยเหลือและฝึกสอนผู้ป่วยลงจากเตียงและฝึกเดินด้วยอุปกรณ์ช่วยเดิน (Walker)\n- ให้ยาบรรเทาปวดและยาปฏิชีวนะมื้อเช้า-เที่ยงตามแผนการรักษา\n[⛅ เวรบ่าย]\n- ตรวจประเมินการไหลเวียนโลหิตและประสาทรับรู้ส่วนปลาย (CMS check) ปลายเท้าข้างที่ผ่าตัด\n- ประเมินระดับความปวดหลังการฝึกกายภาพ และดูแลให้ยาแก้ปวดตามคำสั่งการรักษา\n- ประคบเย็น (Cold pack) รอบข้อเข่า 20-30 นาที เพื่อลดอาการบวมและปวดตึง\n- ตรวจสอบสายระบายแผลผ่าตัด (Redivac drain) ให้คงสภาพสุญญากาศ บันทึกปริมาณและลักษณะเลือด\n- จัดท่านอนหงาย หนุนหมอนรองใต้ข้อเท้าให้เข่าเหยียดตรง (ห้ามหนุนใต้ข้อพับเข่า)\n[🌙 เวรดึก]\n- ตรวจเช็คการจัดท่านอน เหยียดข้อเข่าตรง ป้องกันภาวะข้อเข่างอติด (Knee flexion contracture)\n- จัดสิ่งแวดล้อมให้เงียบสงบ แสงสว่างเหมาะสม และยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อความปลอดภัย\n- ดูแลจัดสายระบายไม่ให้ดึงรั้งหรือหักพับงอ และสังเกตสารคัดหลั่งรอบแผล\n- บันทึกและสรุปยอด Intake-Output และปริมาณเลือดจากสายระบายสะสมรอบ 24 ชั่วโมง\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจประเมิน CMS ปลายเท้า และอาการปวดก่อนส่งต่อเวรเช้า\nResponse: สัญญาณชีพคงที่, CMS ปลายเท้าปกติ ปลายเท้าอุ่น ชีพจรเต้นชัดเจน ขยับนิ้วเท้าได้ดี, แผลผ่าตัดไม่มี active bleeding, สายระบายออกลดลง, ผู้ป่วยสามารถทำ Ankle pumping ได้ถูกต้อง, Pain score ลดลงเหลือ.../10"},{"shortcut":".uka","title":"ผ่าตัดเปลี่ยนข้อเข่าเทียมเฉพาะส่วน (Unicompartmental Knee Arthroplasty: UKA)","content":"Focus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อเข่าเทียมเฉพาะส่วน (Post-Op UKA)\nGoal: แผลผ่าตัดเรียบร้อยดี บวมตึงน้อย ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี ควบคุมความปวดได้ และเริ่มฝึกเดินลงน้ำหนักได้อย่างปลอดภัย\nData: รับย้ายหลังผ่าตัด UKA เข่าข้าง... แผลผ่าตัดขนาดเล็กปิดก๊อซแนบสนิท ไม่มีเลือดสดซึม, ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี, Pain score = .../10\nAction: \n1. ตรวจวัดสัญญาณชีพและประเมิน CMS check ปลายเท้าทุก 2 ชม.\n2. จัดท่าเหยียดข้อเข่าตรง หนุนหมอนใต้ข้อเท้า และประคบเย็นรอบข้อเข่าเพื่อลดบวม\n3. ดูแลให้ยาแก้ปวดและสารน้ำทางหลอดเลือดดำตามแผน\n4. กระตุ้นให้ทำ Ankle pumping และ Straight leg raising exercise\n5. วางแผนร่วมกับนักกายภาพบำบัดในการฝึกยืนและลงน้ำหนัก (Weight bearing) ด้วย Walker ตามคำสั่งแพทย์\nResponse: แผลผ่าตัดแห้งดี บวมช้ำน้อย, CMS check ปกติ, ผู้ป่วยสามารถงอและเหยียดเข่าได้ตามเกณฑ์, ปวดลดลง ลุกยืนลงน้ำหนักได้มั่นคง"},{"shortcut":".tkarehab","title":"การฟื้นฟูสภาพและกายภาพบำบัดข้อเข่า (TKA Rehabilitation \u0026 CPM)","content":"Focus: ฟื้นฟูสมรรถภาพกล้ามเนื้อและการเคลื่อนไหวข้อเข่า (Impaired Physical Mobility / Knee Rehabilitation)\nGoal: ผู้ป่วยสามารถงอและเหยียดข้อเข่าได้ตามเป้าหมาย (Extension 0°, Flexion ≥ 90°) กล้ามเนื้อต้นขาแข็งแรงขึ้น และใช้อุปกรณ์ช่วยเดินได้ถูกต้อง\nData: ผู้ป่วยหลังผ่าตัด TKA วันที่... ข้อเข่ายังมีอาการตึงตัว งอเข่าได้... องศา กล้ามเนื้อต้นขายังล้า\nAction:\n[☀️ เวรเช้า]\n- ดูแลให้ยาแก้ปวดก่อนเริ่มฝึกกายภาพ 30 นาทีเพื่อให้บริหารข้อเข่าได้อย่างเต็มที่\n- จัดผู้ป่วยลงเครื่องช่วยงอเข่าอัตโนมัติ (CPM) มุมงอเริ่มต้น... องศา นาน 1-2 ชม. ตามคำสั่งแพทย์\n- ฝึกสอนและกระตุ้นการบริหารกล้ามเนื้อ: Quad setting, Terminal knee extension, และ Heel slide\n- ฝึกสอนการเดินโดยใช้อุปกรณ์ช่วยเดิน (Walker) และการก้าวเดินที่ถูกต้อง\n- ประคบเย็นรอบข้อเข่า 20-30 นาทีทันทีหลังฝึกเสร็จ\n[⛅ เวรบ่าย]\n- ประเมินอาการบวม แดง ร้อน และระดับความปวดรอบข้อเข่าหลังการฝึกช่วงเช้า\n- จัดผู้ป่วยฝึก CPM รอบบ่ายตามคำสั่งแพทย์ (กรณีมีคำสั่งวันละ 2 ครั้ง)\n- กระตุ้นให้ทำ Ankle pumping exercise บ่อยๆ เพื่อป้องกัน DVT\n- จัดท่านอนเหยียดเข่าตรง หนุนหมอนใต้ข้อเท้า (ห้ามหนุนใต้ข้อพับเข่า)\n[🌙 เวรดึก]\n- ตรวจเช็คท่านอนให้ข้อเข่าเหยียดตรง ป้องกันการงอข้อเข่าค้างขณะหลับ (Knee flexion contracture)\n- ประคบเย็นเสริมกรณีข้อเข่ายังมีอาการบวมตึง\n- จัดสิ่งแวดล้อมให้ผู้ป่วยได้นอนหลับพักผ่อนเต็มที่เพื่อฟื้นฟูกล้ามเนื้อ\nResponse: ผู้ป่วยสามารถงอข้อเข่าได้เพิ่มขึ้นเป็น... องศา, ทนต่อการทำกายภาพได้ดี ไม่มีอาการเจ็บปวดรุนแรง, กล้ามเนื้อต้นขามีกำลังดีขึ้น สามารถใช้ Walker เดินได้อย่างปลอดภัย"},{"shortcut":".arthro","title":"ส่องกล้องตรวจและผ่าตัดข้อเข่า (Knee Arthroscopy / Meniscectomy / ACL)","content":"Focus: การพยาบาลหลังผ่าตัดส่องกล้องข้อเข่า (Post-Op Knee Arthroscopy)\nGoal: อาการบวมและปวดในข้อเข่าลดลง แผลส่องกล้องแห้งสะอาด ไม่มีการติดเชื้อในข้อ และฟื้นฟูการเคลื่อนไหวข้อเข่าได้เร็ว\nData: รับย้ายผู้ป่วยหลังทำ Knee Arthroscopy เข่าข้าง... แผลรอยเจาะส่องกล้องปิดก๊อซและพันผ้ายืด (Elastic bandage) แนบกระชับดี\nAction: \n1. ประเมิน CMS check ปลายเท้า (สีผิว ความอุ่น การเคลื่อนไหวนิ้วเท้า ชีพจรส่วนปลาย)\n2. หนุนขาสูงกว่าระดับหัวใจ และประคบเย็นรอบข้อเข่า 24-48 ชม. แรก เพื่อลดอาการบวม\n3. ตรวจสอบผ้าพันแผลไม่ให้รัดแน่นหรือหลวมจนเกินไป\n4. สอนการบริหาร Ankle pump และ Quad setting\n5. แนะนำการลงน้ำหนักตามคำสั่งแพทย์ (PWB / FWB / NWB)\nResponse: ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี ไม่มีอาการชาหรือบวมคล้ำ, แผลไม่มี bleeding ซึมทะลุผ้าพันแผล, ปวดทุเลาลง"}]},{"category":"10. ศัลยกรรมข้อสะโพก Hip Arthroplasty (THA / BHA / Bipolar)","items":[{"shortcut":".tha","title":"ผ่าตัดเปลี่ยนข้อสะโพกเทียม (Total Hip Arthroplasty: THA)","content":"Focus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อสะโพกเทียม และป้องกันข้อสะโพกหลุด (Post-Op THA \u0026 Dislocation Prevention)\nGoal: ข้อสะโพกเทียมอยู่ในตำแหน่งที่ถูกต้อง ไม่เกิดภาวะข้อสะโพกหลุด (No Dislocation) CMS ปลายเท้าปกติ และฟื้นฟูการเดินได้อย่างปลอดภัย\nData: รับย้ายผู้ป่วยหลังผ่าตัด Total Hip Arthroplasty (THA) สะโพกข้าง... แผลผ่าตัดด้านข้างสะโพกปิดแน่นสนิท, สายระบาย Redivac มีเลือดออกสะสม... ml, ปลายเท้าอุ่น เคลื่อนไหวและรับความรู้สึกได้ปกติ\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินแผลผ่าตัด ทำแผลด้านข้างสะโพกด้วยเทคนิคปลอดเชื้อ\n- ตรวจสอบการวางหมอนสามเหลี่ยม (Abduction pillow) ระหว่างขาทั้งสองข้างให้ถูกต้อง\n- ช่วยเหลือผู้ป่วยฝึกยืนและลงน้ำหนักเดินด้วย Walker ตามคำสั่งแพทย์ (PWB / FWB)\n- กระตุ้นให้ทำ Ankle pumping exercise อย่างต่อเนื่องเพื่อส่งเสริมการไหลเวียนเลือดดำ\n- เน้นย้ำข้อห้าม: ห้ามงอสะโพกเกิน 90 องศา, ห้ามไขว่ห้างหรือหนีบขา, ห้ามบิดปลายเท้าเข้าใน\n[⛅ เวรบ่าย]\n- ตรวจประเมิน CMS check ปลายเท้า และเฝ้าระวังภาวะข้อสะโพกหลุด (ขาไม่สั้นเต่อ ไม่บิดหมุน)\n- ดูแลให้ยาแก้ปวดและยาป้องกันลิ่มเลือดอุดตัน (Anticoagulant) ตามแผนการรักษา\n- ตรวจสอบสายระบายสุญญากาศ บันทึกปริมาณเลือด ระวังสายดึงรั้ง\n- แนะนำการใช้เบาะเสริมความสูงบนชักโครก (Raised toilet seat) เวลาขับถ่าย\n[🌙 เวรดึก]\n- จัดท่านอนหงายและตรวจเช็คหมอน Abduction pillow อยู่ในตำแหน่งถูกต้องตลอดเวลาที่นอนหลับ\n- กำชับการพลิกตัวตะแคงต้องพลิกแบบ Log-roll โดยมีหมอนหนุนคั่นระหว่างขาทั้งสองข้างเสมอ\n- สรุปยอด Intake-Output และปริมาณเลือดจากสายระบายสะสม 24 ชม.\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจเช็คแนวข้อสะโพกและ CMS ปลายเท้าก่อนส่งเวรเช้า\nResponse: ขาสองข้างกางในแนวตรงด้วย Abduction pillow ไม่มีข้อสะโพกบิดหมุนผิดรูป, สัญญาณชีพคงที่, CMS check ปกติ ขยับนิ้วเท้าได้ดี, ปริมาณเลือดจากสายระบายค่อยๆ ลดลง, Pain score.../10"},{"shortcut":".bha","title":"ผ่าตัดเปลี่ยนข้อสะโพกเทียมสองแกน (Bipolar Hemiarthroplasty: BHA)","content":"Focus: การพยาบาลผู้สูงอายุหลังผ่าตัด Bipolar Hemiarthroplasty จากกระดูกสะโพกหัก\nGoal: ป้องกันภาวะแทรกซ้อนจากการผ่าตัดข้อสะโพก ป้องกันข้อหลุด ควบคุมความปวดได้ดี และเริ่มฝึกยืนเดินด้วย Walker ได้อย่างมั่นคง\nData: ผู้ป่วยสูงอายุ รับย้ายหลังผ่าตัด Bipolar Hemiarthroplasty สะโพกข้าง... (Dx: Fracture Neck of Femur), รู้สึกตัวดี ถามตอบรู้เรื่อง แผลผ่าตัดปิด gauze แนบสนิท มี Redivac drain... ml\nAction: \n1. จัดท่านอนกางขาสะโพกด้วยหมอน Abduction pillow ป้องกันข้อสะโพกเทียมหลุด\n2. ประเมินภาวะสับสนเฉียบพลันในผู้สูงอายุ (Delirium assessment) จัดสภาพแวดล้อมให้เงียบสงบ มีแสงสว่างเพียงพอ\n3. ป้องกันภาวะแทรกซ้อนจากการนอนติดเตียง:\n   - พลิกตัวตะแคงตัวประคองทุก 2 ชม. พร้อมหนุนหมอนรองข้อเข่าและส้นเท้า ป้องกันแผลกดทับ\n   - กระตุ้นการหายใจลึกๆ และไออย่างมีประสิทธิภาพ (Deep breathing \u0026 Coughing) หรือเป่า Incentive spirometer ทุกชั่วโมง ป้องกันภาวะปอดแฟบ (Atelectasis)\n4. ตรวจสอบแผลผ่าตัด สายระบาย และ CMS check ปลายเท้า\n5. ดูแลให้สารน้ำ ยาแก้ปวด และยากระตุ้นการขับถ่ายเพื่อป้องกันท้องผูก\nResponse: รู้สึกตัวตื่นดี ไม่มีอาการสับสนเพ้อ, ข้อสะโพกอยู่ในแนวตรง ไม่บิดหมุน, แผลแห้งดี ไม่มีเลือดสดซึม, ปอดเสียงใส ไม่มีเสมหะคั่งค้าง"},{"shortcut":".hipcare","title":"ข้อควรระวังและป้องกันข้อสะโพกเทียมเคลื่อนหลุด (Hip Dislocation Prevention Precautions)","content":"Focus: ให้สุขศึกษาและแนวทางปฏิบัติเพื่อป้องกันข้อสะโพกเทียมหลุด (Post-Hip Surgery Precautions)\nGoal: ผู้ป่วยและญาติเข้าใจและปฏิบัติตามข้อห้ามเพื่อป้องกันข้อสะโพกหลุด (Hip Precautions) ได้ถูกต้อง 100% ตลอดเวลา\nData: ผู้ป่วยหลังผ่าตัดเปลี่ยนข้อสะโพกเทียม (THA/BHA) อยู่ในระยะฟื้นฟูสภาพ เตรียมพร้อมกลับบ้าน\nAction: \n1. เน้นย้ำกฎเหล็ก 3 ข้อ: 1) ห้ามงอสะโพกเกิน 90 องศา 2) ห้ามไขว่ห้างหรือหนีบขา 3) ห้ามบิดปลายเท้าเข้าด้านใน\n2. ท่านอน: นอนหงายหนุนหมอนข้างคั่นระหว่างขาเสมอ หากนอนตะแคงให้ตะแคงข้างปกติและหนุนหมอนหนาคั่นระหว่างขาทั้งสองข้าง\n3. ท่านั่ง: นั่งเก้าอี้ที่มีพนักพิงสูงและมีที่วางแขน ไม่นั่งเก้าอี้เตี้ย โซฟานุ่มจมตัว หรือนั่งยองๆ บนพื้น\n4. การขับถ่าย: ใช้ชักโครกที่มีเบาะเสริมความสูง ไม่นั่งส้วมซึม\n5. การหยิบของ: ใช้ไม้ยาวหนีบของ (Reacher) ห้ามก้มตัวลงเก็บของที่พื้น\n6. การสวมใส่เสื้อผ้า: ให้ญาติช่วยสวมกางเกงและถุงเท้า หรือใช้อุปกรณ์ช่วยสวม\n7. การสังเกตอาการผิดปกติ: ปวดสะโพกรุนแรงฉับพลัน ขาสั้นลงกว่าอีกข้าง หรือปลายเท้าบิดออกนอก ให้รีบมาโรงพยาบาลทันที\nResponse: ผู้ป่วยและญาติเข้าใจข้อห้ามและแนวทางปฏิบัติ สามารถสาธิตวิธีการลุก-นั่งและการนอนที่ถูกต้องได้ ปลอดภัยจากภาวะข้อสะโพกหลุด"}]},{"category":"11. ศัลยกรรมกระดูกสันหลัง Spine Surgery Nursing (DAR)","items":[{"shortcut":".laminectomy","title":"ผ่าตัดกระดูกสันหลังตัดกระดูกลามินา (Laminectomy / Decompression)","content":"Focus: การพยาบาลหลังผ่าตัดกระดูกสันหลัง (Post-Op Laminectomy)\nGoal: การทำงานของเส้นประสาทและไขสันหลังปกติ (Motor \u0026 Sensory Intact) อาการชาและปวดร้าวลดลง แผลผ่าตัดแห้งดี และไม่มี CSF leak\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Laminectomy ระดับ... แผลผ่าตัดกลางหลังปิดแน่นสนิท, มีสายระบายเลือด (Hemovac/Redivac) ออก... ml, Motor power ขาสองข้าง: ขวา grade... ซ้าย grade..., Sensation: รับความรู้สึกได้ดี ไม่มีอาการชาเพิ่มขึ้น\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินระบบประสาทส่วนล่าง (Motor power \u0026 Sensation ขาทั้ง 2 ข้าง)\n- ทำแผลผ่าตัดกลางหลังด้วยเทคนิคปลอดเชื้อ ตรวจสอบไม่มีน้ำใส CSF leakage\n- ฝึกสอนการพลิกตัวแบบท่อนซุง (Log-rolling technique) โดยเจ้าหน้าที่ 2-3 คน\n- ดูแลสวมเสื้อพยุงหลัง (TLSO / L-S support) ให้กระชับก่อนเริ่มฝึกนั่งและยืน\n[⛅ เวรบ่าย]\n- ตรวจเช็คสายระบายแผลผ่าตัด สังเกตสีและปริมาณ หากมีน้ำใสสีเหลืองฟางข้าวให้สงสัย CSF leak\n- ประเมินระดับความรู้สึกตัว อาการปวดศีรษะ และอาการปวดแผลผ่าตัด ให้ยาแก้ปวดตามแผน\n- ประเมินการขับถ่ายปัสสาวะ เฝ้าระวังภาวะปัสสาวะคั่งค้าง (Urinary retention)\n- แนะนำข้อห้าม BLT: ห้ามก้มตัว (No Bending), ห้ามยกของหนัก (No Lifting), ห้ามบิดเอี้ยวตัว (No Twisting)\n[🌙 เวรดึก]\n- จัดท่านอนหงายราบหรือศีรษะสูงไม่เกิน 30 องศา หนุนหมอนใต้ข้อพับเข่าเล็กน้อยเพื่อผ่อนคลายกล้ามเนื้อหลัง\n- ช่วยพลิกตัวแบบ Log-rolling ทุก 2 ชั่วโมงเพื่อป้องกันแผลกดทับ\n- จัดสิ่งแวดล้อมให้เงียบสงบ ยกไม้กั้นเตียงขึ้น 2 ข้างเพื่อความปลอดภัย\n- สรุปยอด Intake-Output และยอดเลือดจากสายระบายสะสมรอบ 24 ชั่วโมง\nResponse: Motor power ขาทั้งสองข้างคงที่ ขยับข้อเท้าและนิ้วเท้าได้ดี, พลิกตัวแบบ Log-roll ลำตัวตรงดี, แผลผ่าตัดไม่มี CSF leakage, ปัสสาวะออกสะดวก ไม่คั่งค้าง, Pain score ลดลง"},{"shortcut":".discectomy","title":"ผ่าตัดหมอนรองกระดูกทับเส้นประสาท (Microdiscectomy)","content":"Focus: การพยาบาลหลังผ่าตัดหมอนรองกระดูกสันหลัง (Post-Op Microdiscectomy)\nGoal: ลดการกดทับของเส้นประสาท อาการปวดหลังและปวดร้าวลงขาบรรเทาลง ควบคุมการขับถ่ายได้ปกติ และเคลื่อนไหวร่างกายได้ถูกสุขลักษณะ\nData: รับย้ายผู้ป่วยหลังผ่าตัด Microdiscectomy ระดับ L...-L... แผลผ่าตัดขนาดเล็กปิดก๊อซแน่นสนิท, อาการปวดร้าวชาลงขาเดิมทุเลาลง\nAction: \n1. ประเมิน Neuro signs ขาสองข้าง: Straight leg raising, ขยับนิ้วเท้า และกำลังกล้ามเนื้อ EHL/Gastroc\n2. พลิกตัวตะแคงด้วยเทคนิค Log-rolling\n3. แนะนำการลุกจากเตียง: ตะแคงตัวทั้งตัว ห้อยขาสองข้างลงข้างเตียงพร้อมใช้แขนสองข้างยันตัวลุกขึ้นนั่งตรงๆ ห้ามบิดเอี้ยวหลัง\n4. แนะนำข้อควรระวัง: หลีกเลี่ยงการนั่งนานเกิน 30-45 นาที ไม่ยกของหนัก\nResponse: ผู้ป่วยลุกนั่งและยืนเดินได้ตามขั้นตอน ลำตัวตรง ไม่บิดเอี้ยว, อาการปวดร้าวลงขาเดิมลดลงชัดเจน ขยับนิ้วเท้าได้แรงดี"},{"shortcut":".plif","title":"ผ่าตัดเชื่อมข้อกระดูกสันหลังและใส่เหล็กดาม (PLIF / TLIF Spinal Fusion)","content":"Focus: การพยาบาลหลังผ่าตัดเชื่อมข้อกระดูกสันหลังและดามเหล็ก (Post-Op PLIF / TLIF)\nGoal: แนวกระดูกสันหลังมั่นคง การยึดตรึงข้อกระดูกอยู่ในตำแหน่งที่ถูกต้อง ระบบประสาทส่วนปลายปกติ และสามารถพลิกตัวแบบ Log rolling ได้ดี\nData: รับย้ายหลังผ่าตัด Posterior Lumbar Interbody Fusion (PLIF/TLIF) ระดับ... แผลผ่าตัดปิด gauze แนบสนิท, สายระบาย... ml, ขาสองข้างขยับได้ Motor grade...\nAction: \n1. ประเมินสัญญาณชีพ และ Neuro signs ขาทั้งสองข้างอย่างใกล้ชิด\n2. พลิกตัวแบบ Log-rolling ทุก 2 ชม. ป้องกันแผลกดทับและลดการดึงรั้งของแนวกระดูกสันหลังที่เชื่อมข้อ\n3. ดูแลสายระบายสุญญากาศให้อยู่ในระบบปิด\n4. แนะนำข้อห้ามการเคลื่อนไหว: **ห้ามก้มตัว ห้ามยกของหนัก ห้ามบิดเอี้ยวตัว (No Bending, No Lifting, No Twisting: BLT restrictions)**\n5. เมื่อเริ่มฝึกนั่งหรือยืนเดิน: ดูแลสวมเสื้อพยุงหลังชนิดแข็ง (TLSO หรือ L-S Support) ให้กระชับพอดีตัวก่อนลุกขึ้นนั่งทุกครั้ง\n6. ดูแลให้ยาแก้ปวดและยาลดการเกร็งกล้ามเนื้อ (Muscle relaxant) ตามแผนการรักษา\nResponse: กระดูกสันหลังอยู่ในแนวตรงมั่นคงดี, สวมเสื้อพยุงหลังได้ถูกต้องก่อนเคลื่อนไหว, Neurovascular ขาปกติ ไม่มีอาการกล้ามเนื้ออ่อนแรงเฉียบพลัน, แผลแห้งดี"},{"shortcut":".acdf","title":"ผ่าตัดกระดูกสันหลังส่วนคอทางด้านหน้า (Anterior Cervical Discectomy \u0026 Fusion: ACDF)","content":"Focus: การพยาบาลหลังผ่าตัดกระดูกคอ และเฝ้าระวังทางเดินหายใจอุดกั้น (Post-Op ACDF)\nGoal: ทางเดินหายใจโล่ง ไม่มีอาการแน่นคอหรือหายใจลำบากจาก Hematoma กลืนอาหารได้สะดวก ระบบประสาทแขนขาทั้ง 4 ข้างปกติ\nData: รับย้ายหลังผ่าตัด ACDF ระดับ C...-C... แผลผ่าตัดบริเวณลำคอด้านหน้าปิดเรียบร้อย, หายใจสม่ำเสมอ ไม่มีเสียง Stridor, พูดมีเสียง ไม่มีเสียงแหบ, กลืนน้ำลายได้\nAction: \n1. **เฝ้าระวังภาวะทางเดินหายใจอุดกั้นจากก้อนเลือดคั่งที่คอ (Neck Hematoma \u0026 Airway Obstruction)**:\n   - ตรวจประเมินอัตราและลักษณะการหายใจอย่างใกล้ชิด สังเกตอาการหายใจเหนื่อย หายใจมีเสียงฮึด (Stridor)\n   - สังเกตและคลำบริเวณลำคอด้านหน้ารอบแผลผ่าตัด เฝ้าระวังอาการบวมตึง คอหนาขึ้น หรือหลอดลมถูกดันเบี้ยว (Tracheal deviation)\n   - เตรียมชุด Emergency Tracheostomy set และอุปกรณ์กู้ชีพไว้ข้างเตียงเสมอ\n2. สังเกตอาการกลืนลำบาก (Dysphagia) และอาการเสียงแหบ (Hoarseness) จากการบาดเจ็บของ Recurrent laryngeal nerve\n3. จัดท่านอนศีรษะสูง 30-45 องศา (Semi-Fowler\u0027s position) เพื่อลดอาการบวมบริเวณคอ\n4. ดูแลให้ผู้ป่วยสวมปลอกคอพยุง (Philadelphia collar / Hard collar) ตลอดเวลาตามคำสั่งแพทย์ ห้ามก้มหรือหงายคอ\n5. ประเมินกำลังกล้ามเนื้อแขนและมือ (Grip strength, Motor power แขนทั้งสองข้าง)\nResponse: ทางเดินหายใจโล่ง หายใจสะดวก ไม่มีเสียง Stridor, ลำคอไม่บวมตึง หลอดลมอยู่ตรงกึ่งกลาง, พูดชัดเจนไม่มีเสียงแหบ, กลืนน้ำได้ไม่สำลัก, กำลังกล้ามเนื้อแขนและมือแข็งแรงปกติ"},{"shortcut":".csfleak","title":"เฝ้าระวังและดูแลภาวะน้ำหล่อเลี้ยงสมองและไขสันหลังรั่ว (CSF Leakage)","content":"Focus: มีภาวะน้ำไขสันหลังรั่วซึมจากแผลผ่าตัดกระดูกสันหลัง (Cerebrospinal Fluid Leakage)\nGoal: ปริมาณน้ำไขสันหลังรั่วหยุด แผลผ่าตัดแห้งสนิท อาการปวดศีรษะทุเลาลง และไม่เกิดภาวะเยื่อหุ้มสมองอักเสบ (Meningitis)\nData: ผู้ป่วยบ่นปวดศีรษะตุ๊บๆ รุนแรงเวลาลุกนั่ง แต่อาการทุเลาลงเมื่อนอนราบ (Spinal headache), บริเวณแผลผ่าตัดมีน้ำเหลืองใส (Clear watery/yellowish discharge) ซึมเปื้อนผ้าปิดแผล\nAction: \n1. รายงานแพทย์เจ้าของไข้ทันทีที่พบอาการสงสัย CSF leak\n2. จัดให้ผู้ป่วย **นอนราบไม่หนุนหมอน (Flat bed rest)** ตลอด 24-48 ชม. เพื่อลดแรงดันน้ำไขสันหลังและเปิดโอกาสให้เยื่อหุ้มดูราประสานตัว\n3. สังเกตลักษณะและปริมาณน้ำที่ซึมจากแผล (Halo sign / Ring test), เปลี่ยนผ้าก๊อซด้านนอกด้วยเทคนิคปลอดเชื้อ\n4. เฝ้าระวังอาการแสดงของการติดเชื้อเยื่อหุ้มสมอง (Meningitis): ไข้สูง คอแข็ง (Stiff neck), สับสน, กลัวแสง (Photophobia)\n5. ดูแลให้สารน้ำทางหลอดเลือดดำและยาแก้ปวดตามคำสั่งแพทย์อย่างเคร่งครัด\nResponse: ผู้ป่วยให้ความร่วมมือนอนราบบนเตียง, อาการปวดศีรษะทุเลาลง, น้ำไขสันหลังที่ซึมแผลลดลง, ไม่มีไข้ ไม่มีอาการคอแข็ง"},{"shortcut":".spinerehab","title":"การฟื้นฟูสภาพกระดูกสันหลังและการสวมเสื้อพยุง (TLSO / L-S Support \u0026 BLT)","content":"Focus: ฝึกทักษะการเคลื่อนไหวร่างกายอย่างปลอดภัยหลังผ่าตัดกระดูกสันหลัง\nGoal: ผู้ป่วยสามารถทรงตัว ใส่กายอุปกรณ์เสริมพยุงหลัง (LS support / TLSO) และฝึกยืนเดินได้อย่างถูกต้อง ปลอดภัย ไม่ปวดหลังเพิ่ม\nData: ผู้ป่วยหลังผ่าตัดกระดูกสันหลัง แพทย์มีคำสั่งให้เริ่มลุกนั่งและเดินโดยใช้อุปกรณ์พยุงหลัง\nAction: \n1. แนะนำการสวมเสื้อเกราะพยุงหลัง (TLSO / L-S Support): สวมขณะนอนราบบนเตียง โดยการกลิ้งตัวตะแคงสวมเสื้อพยุงและดึงแถบตีนตุ๊กแกให้กระชับพอดีตัวก่อนลุกขึ้นนั่งทุกครั้ง\n2. ฝึกทักษะการลุกนั่งข้างเตียง: ตะแคงตัวแบบท่อนซุง หย่อนขาสองข้างลงพร้อมใช้มือยันตัวลุกขึ้นพร้อมกัน\n3. ย้ำเตือนข้อจำกัด BLT: ห้ามก้มตัว (No Bending), ห้ามยกของหนักเกิน 2-3 กก. (No Lifting), ห้ามเอี้ยวหรือบิดลำตัว (No Twisting) อย่างน้อย 6-12 สัปดาห์\n4. ส่งเสริมการเดินออกกำลังกายสม่ำเสมอ หลีกเลี่ยงการนั่งเก้าอี้นานเกิน 30-45 นาที\nResponse: ผู้ป่วยสามารถสวมเสื้อพยุงหลังได้ถูกต้อง ลุกนั่งและยืนเดินได้ทรงตัวมั่นคง ปฏิบัติตามหลัก BLT ได้ถูกต้อง"}]},{"category":"12. การพยาบาลกระดูกหักและการบาดเจ็บ Trauma \u0026 Fracture Care","items":[{"shortcut":".orif","title":"ผ่าตัดจัดกระดูกและยึดตรึงด้วยโลหะภายใน (ORIF: Fractures)","content":"Focus: การพยาบาลหลังผ่าตัดดามกระดูกหัก (Post-Op ORIF)\nGoal: กระดูกที่ยึดตรึงอยู่ในแนวที่ถูกต้อง แผลผ่าตัดสะอาด แห้งดี ปลายรยางค์อุ่น CMS ปกติ และไม่เกิดภาวะแทรกซ้อนจากการผ่าตัด\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Open Reduction and Internal Fixation (ORIF) บริเวณ... ขอบแผลผ่าตัดปิดเรียบร้อย ดามเฝือกชั่วคราว (Slab) ไว้, มีอาการปวดและบวมตึงบริเวณที่ผ่าตัด Pain score = .../10\nAction: \n1. **เฝ้าระวังภาวะความดันในช่องกล้ามเนื้อสูง (Compartment Syndrome Monitoring 5 Ps)**:\n   - ตรวจประเมิน Pain (ปวดรุนแรงไม่สัมพันธ์กับแผล), Pallor (ผิวซีดเย็น), Pulselessness (ชีพจรส่วนปลายเบา/คลำไม่ได้), Paresthesia (มีอาการชา/เหน็บ), Paralysis (ขยับนิ้วไม่ได้) ทุก 1-2 ชม.\n2. จัดวางอวัยวะที่ผ่าตัดให้อยู่ในระดับสูงกว่าหัวใจ (Elevation) โดยใช้หมอนรองรับ เพื่อช่วยลดอาการบวมคั่งของหลอดเลือดดำ\n3. ประคบเย็นบริเวณรอบๆ แผลผ่าตัด ครั้งละ 20 นาที\n4. ตรวจสอบความแน่นตึงของผ้าพันแผล (Elastic bandage) หากตึงแน่นเกินไปจนกดการไหลเวียนเลือด ให้คลายออกและพันใหม่พอดี\n5. ดูแลให้ยาแก้ปวดและยาปฏิชีวนะตามแผนการรักษา\nResponse: ไม่พบอาการแสดงของ Compartment syndrome, ปลายแขน/ปลายเท้าอุ่นดี ชีพจรส่วนปลายเต้นสม่ำเสมอ, ขยับนิ้วได้ ไม่ชา, อาการบวมลดลง, Pain score ลดลงเหลือ.../10"},{"shortcut":".exfix","title":"การพยาบาลผู้ป่วยใส่โครงยึดกระดูกภายนอก (External Fixation \u0026 Pin Site Care)","content":"Focus: การดูแลผู้ป่วยใส่โครงดามกระดูกภายนอกและป้องกันการติดเชื้อ (External Fixation Care)\nGoal: อุปกรณ์ตรึงกระดูกภายนอกมั่นคงแข็งแรง ตำแหน่ง Pin site สะอาด ไม่มีการติดเชื้อ CMS ส่วนปลายปกติ และบริหารกล้ามเนื้อได้ถูกต้อง\nData: ผู้ป่วยได้รับการผ่าตัดใส่เครื่องดามกระดูกภายนอก (External Fixator) บริเวณ... มีเหล็กแทงผ่านผิวหนังยึดกับกระดูก แผล Pin site ปิดก๊อซสะอาด\nAction: \n1. ตรวจประเมิน CMS check ปลายรยางค์ส่วนที่ใส่เครื่องมือดามกระดูก\n2. ทำความสะอาดบริเวณรอบเหล็กด้ามดึง (Pin site care) วันละ 1-2 ครั้ง โดยใช้ไม้พันสำลีชุบ Normal Saline เช็ดวนออกจากโคนเหล็ก ห้ามเช็ดย้อนกลับไปมา\n3. สังเกตอาการแสดงของการติดเชื้อ: ผิวหนังรอบเหล็กบวมแดง ร้อน กดเจ็บ หรือมีหนอง/discharge ไหลซึม\n4. ตรวจสอบความมั่นคงของน็อตและโครงยึด ห้ามหมุนหรือปรับแต่งน็อตเอง\n5. ยกอวัยวะสูงเพื่อลดอาการบวม และระวังไม่ให้โครงเหล็กกระแทกกับสิ่งกีดขวาง\nResponse: แผล Pin sites สะอาด แห้งดี ไม่พบอาการอักเสบติดเชื้อ, โครงยึดตรึงแน่นหนา, CMS check ส่วนปลายปกติ ไม่บวมตึง"},{"shortcut":".amputation","title":"การดูแลผู้ป่วยผ่าตัดตัดแขน/ขา (Amputation \u0026 Phantom Limb Pain)","content":"Focus: การพยาบาลหลังผ่าตัดตัดรยางค์และจัดการอาการปวดแขนขาเทียม (Post-Amputation Care)\nGoal: แผลตอกลับสมานตัวดี ควบคุมความปวด Phantom limb pain ได้ ป้องกันภาวะข้อพับติด (Contracture) และพร้อมสำหรับการใส่ขาเทียม\nData: รับย้ายผู้ป่วยหลังผ่าตัด Amputation (AKA / BKA) ข้าง... ตอขา (Stump) ปิด elastic bandage แนบสนิท, ผู้ป่วยบ่นปวดแปลบเหมือนยังมีขาอยู่ (Phantom limb sensation / pain)\nAction: \n1. เฝ้าระวังภาวะเลือดออกเฉียบพลัน: วางสายยางรัดห้ามเลือด (Tourniquet) ไว้ที่หัวเตียงตลอดเวลา สังเกตเลือดซึมที่ผ้าปิดแผล\n2. จัดท่าตอขา: ช่วง 24 ชม. แรก หนุนหมอนยกตอขาสูงเพื่อลดบวม หลังจาก 24 ชม. ให้นอนราบและกระตุ้นให้นอนคว่ำ (Prone position) วันละ 2-3 ครั้ง ครั้งละ 20-30 นาที เพื่อป้องกันข้อสะโพกงอติด (Hip flexion contracture)\n3. อธิบายให้เข้าใจว่าอาการปวดแปลบ Phantom limb pain เป็นปฏิกิริยาปกติของเส้นประสาทที่ถูกตัด และจะค่อยๆ ลดลง\n4. ดูแลให้ยาแก้ปวดกลุ่มประสาท (Gabapentin / Pregabalin) ตามคำสั่งแพทย์\n5. สอนการพันผ้ายืดตอขาแบบรูปเลข 8 (Figure of 8 bandaging) เพื่อเตรียมตอขาให้เรียวพร้อมใส่ขาเทียมในอนาคต\nResponse: แผลตอขาไม่มี active bleeding, ผู้ป่วยคลายความวิตกกังวลเรื่อง Phantom sensation, เข้าใจและให้ความร่วมมือในการนอนคว่ำ, ปวดลดลง"}]},{"category":"13. ศัลยกรรมและหัตถการเฉพาะทาง Specialized Surgery","items":[{"shortcut":".appendectomy","title":"ผ่าตัดไส้ติ่งอักเสบ (Post-Op Appendectomy)","content":"Focus: การพยาบาลหลังผ่าตัดไส้ติ่งอักเสบ (Post-Op Appendectomy)\nGoal: ฟื้นตัวหลังผ่าตัดไส้ติ่งได้ดี แผลผ่าตัดสะอาด ลำไส้เริ่มกลับมาทำงาน (Bowel sound ปกติ) ผายลมได้ และไม่มีภาวะเยื่อบุช่องท้องอักเสบ\nData: รับย้ายผู้ป่วยหลังผ่าตัด Appendectomy (Open / Laparoscopic), แผลผ่าตัดปิดก๊อซแนบสนิท, ท้องนุ่ม ฟังเสียงลำไส้เคลื่อนไหว (Bowel sounds) ได้... ครั้ง/นาที, Pain score = .../10\nAction: \n1. ประเมินสัญญาณชีพ อาการปวดแผล และอาการแน่นตึงท้อง\n2. จัดท่านอนศีรษะสูงเล็กน้อย (Low Fowler\u0027s) งอเข่าเล็กน้อยเพื่อผ่อนคลายกล้ามเนื้อหน้าท้องและลดการตึงของแผล\n3. ประเมินการกลับมาทำงานของลำไส้ (Bowel sound, การผายลม)\n4. เมื่อผายลมแล้ว เริ่มให้จิบน้ำ และเริ่มอาหารเหลว/อาหารอ่อนตามลำดับคำสั่งแพทย์\n5. กระตุ้นให้ลุกขยับตัวและเดินเร็วหลังผ่าตัด (Early ambulation) เพื่อป้องกันลำไส้ติดกันและกระตุ้นการเคลื่อนไหวของทางเดินอาหาร\nResponse: สัญญาณชีพคงที่, ผู้ป่วยผายลมได้ ท้องไม่อืด, เริ่มจิบน้ำได้ไม่คลื่นไส้อาเจียน, สามารถลุกเดินข้างเตียงได้, แผลผ่าตัดแห้งดี"},{"shortcut":".lapchole","title":"ผ่าตัดถุงน้ำดีส่องกล้อง (Post-Op Laparoscopic Cholecystectomy)","content":"Focus: การพยาบาลหลังผ่าตัดถุงน้ำดีผ่านกล้อง (Post-Op Lap Chole)\nGoal: แผลเจาะส่องกล้องแห้งสะอาด ไม่มีอาการแน่นอึดอัดท้องจากก๊าซ CO2 ไม่มีภาวะน้ำดีรั่ว และสามารถเริ่มรับประทานอาหารไขมันต่ำได้ดี\nData: รับย้ายหลังทำ Laparoscopic Cholecystectomy, มีแผลส่องกล้อง 3-4 รอยบริเวณหน้าท้อง ปิดแผลกันน้ำเรียบร้อย, ผู้ป่วยบ่นแน่นท้องและมีอาการปวดร้าวไปที่สะบักไหล่ขวา (Referred shoulder pain from CO2 gas)\nAction: \n1. ประเมินสัญญาณชีพ และแผลผ่าตัดหน้าท้อง\n2. อธิบายให้ผู้ป่วยเข้าใจว่าอาการปวดไหล่เกิดจากก๊าซคาร์บอนไดออกไซด์ที่ใช้ขยายช่องท้องระหว่างผ่าตัดระคายเคืองกะบังลม ซึ่งจะค่อยๆ สลายตัวไปเองใน 24-48 ชม.\n3. จัดท่านอนศีรษะสูงและแนะนำให้เปลี่ยนอิริยาบถบ่อยๆ, ช่วยพยุงลุกเดินเพื่อช่วยให้ก๊าซดูดซึมและระบายออกได้เร็วขึ้น\n4. ดูแลให้ยาแก้ปวดและยาขับลมตามแผน\n5. สังเกตอาการแทรกซ้อน: ตัวเหลือง ตาเหลือง (Jaundice) หรือปวดท้องรุนแรงผิดปกติ (Bile leak)\nResponse: ผู้ป่วยคลายความกังวล, ลุกเดินได้ดีขึ้น อาการปวดสะบักไหล่ทุเลาลง, ท้องไม่อืด แผลผ่าตัดแห้งดี ไม่มีเลือดหรือน้ำดีซึม"},{"shortcut":".mastectomy","title":"ผ่าตัดเต้านม (Post-Op Modified Radical Mastectomy: MRM)","content":"Focus: การพยาบาลหลังผ่าตัดเต้านมและป้องกันภาวะบวมน้ำเหลือง (Post-Op MRM \u0026 Lymphedema Prevention)\nGoal: แผลผ่าตัดและแผ่นผิวหนังแนบสนิทดี สายระบายทำงานมีประสิทธิภาพ แขนข้างที่ผ่าตัดไม่บวม (No Lymphedema) และบริหารข้อไหล่ได้ตามแผน\nData: รับย้ายหลังผ่าตัด MRM เต้านมข้าง... แผลผ่าตัดยาวที่ทรวงอกปิดแนบสนิท, มีสายระบาย JP drain ต่อขวดสุญญากาศ ออก... ml\nAction: \n1. **ป้องกันภาวะแขนบวมน้ำเหลือง (Lymphedema Prevention) ข้างที่ผ่าตัด**:\n   - แขวนป้ายเตือน \"ห้ามวัดความดันโลหิต ห้ามเจาะเลือด ห้ามฉีดยา และห้ามให้น้ำเกลือที่แขนข้างผ่าตัดเด็ดขาด\"\n   - จัดวางแขนข้างผ่าตัดหนุนบนหมอนให้อยู่ในระดับสูงกว่าหัวใจเล็กน้อยขณะนอน\n2. ดูแลสายระบายแผลให้อยู่ในภาวะสุญญากาศ บันทึกปริมาณและสีของสารคัดหลั่ง\n3. เริ่มบริหารแขนและมือแบบเบาๆ: กำมือคลายมือ (Ball squeezing), งอและเหยียดข้อศอก ใน 24 ชม. แรก\n4. ให้กำลังใจและประเมินความพร้อมทางด้านจิตใจในการปรับตัวต่อภาพลักษณ์ที่เปลี่ยนไป\nResponse: แขนข้างผ่าตัดไม่บวม, แผลไม่มีเลือดออกผิดปกติ, สายระบายคงสภาพสุญญากาศ, ผู้ป่วยสามารถบริหารมืองอศอกได้ดี"}]},{"category":"14. ภาวะเกลือแร่ในเลือดผิดปกติ (Electrolyte Imbalances)","items":[{"shortcut":".hypok","title":"ภาวะโพแทสเซียมในเลือดต่ำ (Hypokalemia, K \u003c 3.5 mEq/L)","content":"Focus: ภาวะโพแทสเซียมในเลือดต่ำ (Hypokalemia, K \u003c 3.5 mEq/L)\nGoal: ระดับ Serum K+ กลับสู่เกณฑ์ปกติ (3.5 - 5.0 mEq/L) คลื่นไฟฟ้าหัวใจปกติ กล้ามเนื้อมีแรงดีขึ้น และไม่เกิดภาวะหัวใจเต้นผิดจังหวะ\nData:\n- ผล Serum K+ ล่าสุด ... mEq/L (ค่าปกติ 3.5 - 5.0 mEq/L)\n- ผู้ป่วยมีอาการอ่อนแรง กล้ามเนื้อแขนขาไม่มีแรง ตะคริว ชาปลายมือปลายเท้า ท้องอืด แน่นท้อง ท้องผูก (Paralytic ileus)\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเต้นเบาหรือไม่สม่ำเสมอ)\n- EKG Monitor: พบ Flat/Inverted T wave, ST depression, Prominent U wave, เฝ้าระวัง Ventricular Arrhythmias\nAction:\n- รายงานแพทย์ทราบผลแล็บวิกฤต (Critical Lab Value) K+ ... mEq/L ทันที\n- ให้การรักษาตามแผน:\n  * กรณีรับประทานได้: ให้ KCl Elixir ... ml หรือ Kalimate / Add-K ตามแผนการรักษา แนะนำรับประทานหลังอาหารทันที\n  * กรณีให้ทางหลอดเลือดดำ: ให้ KCl ... mEq in IV fluid ... ml drip ใน ... ชม. (ใช้อัตราไม่เกิน 10 - 20 mEq/hr ผ่าน Infusion pump เสมอ ห้าม IV Push หรือ Bolus เด็ดขาด!)\n- ติดตาม EKG Monitor ต่อเนื่อง สังเกตอาการทางระบบประสาทและกล้ามเนื้อ\n- ตรวจสอบบริเวณแทงสายน้ำเกลือ เฝ้าระวังอาการปวดแสบร้อนตามแนวหลอดเลือด (Phlebitis / Vein irritation)\n- ชะลอหรือหลีกเลี่ยงยาขับปัสสาวะกลุ่มขับโพแทสเซียม (เช่น Furosemide) ชั่วคราวตามดุลยพินิจแพทย์\nResponse:\n- ผู้ป่วยไม่มีอาการชาหรือกล้ามเนื้อกระตุก แรงกล้ามเนื้อดีขึ้น ชีพจรเต้นสม่ำเสมอ\n- ไม่มีภาวะหัวใจเต้นผิดจังหวะ ไม่มีอาการปวดแสบบริเวณให้สายน้ำเกลือ\n- เจาะเลือดตรวจซ้ำ Serum K+ หลังให้ยาครบตามแผน ผล K+ ซ้ำได้ ... mEq/L"},{"shortcut":".hyperk","title":"ภาวะโพแทสเซียมในเลือดสูง (Hyperkalemia, K \u003e 5.0 - 5.5 mEq/L)","content":"Focus: ภาวะโพแทสเซียมในเลือดสูงวิกฤต (Hyperkalemia, K \u003e 5.0 - 5.5 mEq/L)\nGoal: ระดับ Serum K+ ลดลงสู่เกณฑ์ปลอดภัย (\u003c 5.0 mEq/L) ป้องกันภาวะหัวใจเต้นผิดจังหวะที่อันตรายถึงชีวิต และ EKG กลับสู่ภาวะปกติ\nData:\n- ผล Serum K+ ล่าสุด ... mEq/L (ค่าวิกฤต \u003e 5.5 - 6.0 mEq/L)\n- ผู้ป่วยมีอาการกล้ามเนื้ออ่อนแรง ชาตามปลายมือปลายเท้า คลื่นไส้ ใจสั่น ชีพจรเต้นช้าหรือไม่สม่ำเสมอ\n- EKG Monitor: พบ Tall peaked T wave, Prolonged PR interval, Flattened P wave, Widened QRS complex, เสี่ยงต่อ Sinus arrest หรือ Ventricular Fibrillation (VF)\nAction:\n- รายงานแพทย์ทันที และเตรียมอุปกรณ์ช่วยชีวิต / รถ Emergency Cart พร้อม Defibrillator\n- ให้การรักษาฉุกเฉินตามแผนแพทย์:\n  * ป้องกันกล้ามเนื้อหัวใจ: 10% Calcium Gluconate 10 ml IV push ช้าๆ ใน 3-5 นาที (EKG monitor ขณะให้)\n  * ดึงโพแทสเซียมเข้าสู่เซลล์: Regular Insulin (RI) 10 units + 50% Glucose 50 ml IV push หรือ 10% D/W 500 ml + RI ... units IV drip ใน ... ชม.\n  * ยาพ่นขยายหลอดลม: Salbutamol (Ventolin) 10-20 mg nebulizer\n  * ขับโพแทสเซียมออกจากร่างกาย: Sodium Polystyrene Sulfonate (Kalimate / Kayexalate) 15-30 g Oral / Retention enema หรือ Furosemide (Lasix) ... mg IV\n  * เตรียมการฟอกเลือดฉุกเฉิน (Hemodialysis) หากค่า K+ สูงรุนแรงและดื้อต่อยา\n- งดอาหารและผลไม้ที่มีโพแทสเซียมสูง (กล้วย ส้ม มะเขือเทศ ฝรั่ง น้ำมะพร้าว)\n- บันทึกสัญญาณชีพและ EKG Monitor ทุก 15-30 นาที จนกว่าจะพ้นภาวะวิกฤต\nResponse:\n- คลื่นไฟฟ้าหัวใจ Tall peaked T wave ลดลง ไม่พบ Widened QRS complex หรือหัวใจเต้นผิดจังหวะ\n- ผู้ป่วยรู้สึกตัวดี อาการชาและอ่อนแรงทุเลาลง สัญญาณชีพคงที่\n- ติดตามเจาะเลือดตรวจซ้ำ Serum K+ หลังการรักษา ผล K+ ลดลงเหลือ ... mEq/L"},{"shortcut":".hypona","title":"ภาวะโซเดียมในเลือดต่ำ (Hyponatremia, Na \u003c 135 mEq/L)","content":"Focus: ภาวะโซเดียมในเลือดต่ำ (Hyponatremia, Na \u003c 135 mEq/L)\nGoal: ระดับ Serum Na+ ค่อยๆ เพิ่มขึ้นสู่เกณฑ์ปลอดภัยอย่างระมัดระวัง สติสัมปชัญญะดีขึ้น ไม่มีอาการชักหรือสมองบวม\nData:\n- ผล Serum Na+ ล่าสุด ... mEq/L (ระดับต่ำปานกลาง 125-130 mEq/L, ต่ำรุนแรง \u003c 120 mEq/L)\n- ผู้ป่วยมีอาการปวดศีรษะ สับสน ซึม อ่อนเพลีย คลื่นไส้อาเจียน กล้ามเนื้อกระตุก (Cerebral edema)\n- ประเมิน Glasgow Coma Scale (GCS): E... V... M... คะแนนรวม ... คะแนน\n- ประเมินภาวะสารน้ำในร่างกาย (Hypovolemic / Euvolemic / Hypervolemic)\nAction:\n- รายงานแพทย์ทราบผลแล็บวิกฤต Na+ ... mEq/L ทันที\n- ปฏิบัติตามแผนการรักษาอย่างเคร่งครัด:\n  * กรณีมีอาการทางระบบประสาทรุนแรง (ชัก/ซึม): ให้ 3% NaCl ... ml IV drip ผ่าน Infusion pump ตามอัตราที่แพทย์สั่งอย่างเคร่งครัด\n  * กรณี SIADH / Euvolemic: จำกัดน้ำดื่ม (Fluid restriction) 800 - 1,000 ml/วัน\n  * กรณี Hypovolemic: ให้ 0.9% NSS IV drip ทดแทน\n- **ข้อควรระวังสำคัญ:** ควบคุมอัตราการเพิ่มของ Na+ ไม่เกิน 8 - 10 mEq/L ใน 24 ชม. เพื่อป้องกันภาวะก้านสมองเสื่อมถาวร (Osmotic Demyelination Syndrome: ODS)\n- เฝ้าระวังภาวะชัก: ยกไม้กั้นเตียงทั้งสองข้าง เตรียมออกซิเจนและอุปกรณ์ดูดเสมหะพร้อมข้างเตียง\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) ทุก 8 ชม. ชั่งน้ำหนักตัวทุกวัน\nResponse:\n- ผู้ป่วยรู้สึกตัวดีขึ้น ถามตอบรู้เรื่อง สับสนลดลง ไม่มีอาการชักเกร็งหรือคลื่นไส้\n- สัญญาณชีพคงที่ ไม่มีภาวะสารน้ำเกิน ปัสสาวะออก \u003e 0.5 ml/kg/hr\n- ติดตามระดับ Serum Electrolytes ตามแผนแพทย์ ระดับ Na+ ค่อยๆ ปรับขึ้นสู่เกณฑ์ปลอดภัย"},{"shortcut":".hyperna","title":"ภาวะโซเดียมในเลือดสูง (Hypernatremia, Na \u003e 145 mEq/L)","content":"Focus: ภาวะโซเดียมในเลือดสูง (Hypernatremia, Na \u003e 145 mEq/L)\nGoal: ระดับ Serum Na+ ค่อยๆ ลดลงสู่เกณฑ์ปกติ ภาวะขาดน้ำในเซลล์สมองได้รับการแก้ไข ผู้ป่วยรู้สึกตัวดี และสารน้ำในร่างกายสมดุล\nData:\n- ผล Serum Na+ ล่าสุด ... mEq/L (ค่าปกติ 135 - 145 mEq/L)\n- ผู้ป่วยมีอาการกระหายน้ำอย่างรุนแรง ริมฝีปากแห้ง ผิวหนังแห้ง ยืดหยุ่นลดลง (Poor skin turgor)\n- อาการทางระบบประสาท: กระสับกระส่าย สับสน ซึม กล้ามเนื้อกระตุก หรือชัก\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm, หายใจเร็ว, ปัสสาวะเข้มปริมาณลดลง\nAction:\n- รายงานแพทย์ทราบค่าระดับโซเดียมสูงผิดปกติ\n- คำนวณ Free Water Deficit ร่วมกับแพทย์ และให้น้ำทดแทนอย่างระมัดระวัง:\n  * ให้ดื่มน้ำสะอาดบ่อยๆ กรณีผู้ป่วยกลืนได้ปกติ\n  * ให้น้ำทางสายยาง NG tube ... ml ทุก ... ชม.\n  * กรณีให้ทางหลอดเลือดดำ: ให้สารน้ำไฮโปโทนิก (เช่น 0.45% NaCl หรือ 5% D/W) ทางหลอดเลือดดำตามอัตราที่แพทย์กำหนด\n- **ข้อควรระวังสำคัญ:** อัตราการลดลงของ Na+ ต้องไม่เกิน 10 - 12 mEq/L ใน 24 ชม. (ลดไม่เกิน 0.5 mEq/L/hr) เพื่อป้องกันภาวะสมองบวมน้ำเฉียบพลัน (Cerebral edema)\n- บันทึกสัญญาณชีพและประเมินระดับความรู้สึกตัว (Neuro signs) ทุก 2-4 ชม.\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) อย่างเคร่งครัด\nResponse:\n- ผู้ป่วยรู้สึกตัวดีขึ้น ความกระหายน้ำลดลง เยื่อบุช่องปากชุ่มชื้นขึ้น\n- ไม่มีอาการกระตุกหรือชัก สัญญาณชีพคงที่ ปัสสาวะออกเพียงพอ\n- ผล Serum Na+ ตรวจติดตามค่อยๆ ลดลงอย่างปลอดภัยตามเป้าหมายการรักษา"},{"shortcut":".hypoca","title":"ภาวะแคลเซียมในเลือดต่ำ (Hypocalcemia, Ca \u003c 8.5 mg/dL)","content":"Focus: ภาวะแคลเซียมในเลือดต่ำ (Hypocalcemia, Total Ca \u003c 8.5 mg/dL)\nGoal: ระดับ Serum Ca2+ กลับสู่เกณฑ์ปกติ อาการชา มือจีบเกร็ง กล้ามเนื้อกระตุก (Tetany) ทุเลาลง และคลื่นไฟฟ้าหัวใจปกติ\nData:\n- ผล Total Calcium ... mg/dL (หรือ Ionized Ca ... mmol/L, ค่าปกติ 1.15 - 1.30 mmol/L)\n- ผู้ป่วยมีอาการชาและเหน็บเสียวรอบปาก ปลายมือ ปลายเท้า กล้ามเนื้อกระตุก ปวดเกร็งกล้ามเนื้อ (Cramps)\n- ตรวจพบ Chvostek\u0027s sign ให้ผลบวก (เคาะหน้าหูมุมขากรรไกรแล้วมุมปากกระตุก)\n- ตรวจพบ Trousseau\u0027s sign ให้ผลบวก (วัดความดันโลหิตค้างไว้แล้วมือหงิกเกร็ง Carpopedal spasm)\n- EKG Monitor: พบ Prolonged QT interval, เสี่ยงต่อ Torsades de Pointes\nAction:\n- รายงานแพทย์ทันที และเตรียม 10% Calcium Gluconate 10 ml\n- ให้การรักษาตามแผน:\n  * กรณีฉุกเฉิน/มีอาการเกร็ง: ให้ 10% Calcium Gluconate 10 ml IV push ช้าๆ นานอย่างน้อย 10 นาที (หรือผสมใน 5% D/W 100 ml drip ใน 20-30 นาที)\n  * เฝ้าระวังอัตราการเต้นของหัวใจอย่างใกล้ชิดขณะฉีด (เสี่ยงต่อ Bradycardia / Arrhythmia)\n  * กรณีให้ต่อเนื่อง: ให้ Calcium Gluconate ... amp in IV fluid drip ผ่าน Infusion pump\n  * ยารับประทาน: ให้ Calcium carbonate ... mg + Vitamin D (Calcitriol) ตามแผนการรักษา\n- ตรวจสอบระดับ Serum Albumin และ Magnesium (หาก Mg ต่ำต้องแก้ไขควบคู่กันจึงจะหาย)\n- ดูแลความปลอดภัย ป้องกันอุบัติเหตุจากการหงิกเกร็งหรือชัก\nResponse:\n- อาการชาและหงิกเกร็งมือเท้าทุเลาลง Chvostek\u0027s sign และ Trousseau\u0027s sign ให้ผลลบ\n- คลื่นไฟฟ้าหัวใจ QT interval ปกติ ไม่มีภาวะหัวใจเต้นช้าหรือผิดจังหวะ\n- ผลตรวจติดตามระดับแคลเซียมในเลือดกลับสู่เกณฑ์ปกติ"},{"shortcut":".hyperca","title":"ภาวะแคลเซียมในเลือดสูง (Hypercalcemia, Ca \u003e 10.5 mg/dL)","content":"Focus: ภาวะแคลเซียมในเลือดสูง (Hypercalcemia, Total Ca \u003e 10.5 mg/dL)\nGoal: ระดับ Serum Ca2+ ลดลงสู่เกณฑ์ปลอดภัย ผู้ป่วยได้รับสารน้ำเพียงพอ ขับแคลเซียมออกทางปัสสาวะได้ดี และไม่มีอาการซึมหรือหัวใจเต้นผิดจังหวะ\nData:\n- ผล Total Calcium ... mg/dL (ระดับวิกฤต \u003e 12 - 14 mg/dL)\n- ผู้ป่วยมีอาการอ่อนเพลีย เบื่ออาหาร คลื่นไส้ อาเจียน ท้องผูก ปวดท้อง ปัสสาวะบ่อย กระหายน้ำมาก\n- อาการทางระบบประสาท: สับสน ซึม ตอบสนองช้า หลงลืม Reflex ลดลง\n- EKG Monitor: พบ Shortened QT interval, Widened T wave, Bradycardia หรือ Heart block\nAction:\n- รายงานแพทย์ทราบผลแล็บวิกฤตทันที\n- ให้การพยาบาลตามแผนการรักษา:\n  * ขยายปริมาตรสารน้ำในหลอดเลือด: ให้ 0.9% NSS IV drip ในอัตรา 200 - 300 ml/hr ตามสภาพหัวใจและไต เพื่อเร่งการขับแคลเซียมออกทางไต\n  * ยาขับปัสสาวะ: ให้ Furosemide (Lasix) ... mg IV ตามแผน (ให้หลังจากได้รับสารน้ำอย่างเพียงพอแล้วเท่านั้น ห้ามใช้ Thiazide เด็ดขาด)\n  * ยาลดการสลายกระดูก: ให้ Calcitonin / Bisphosphonates (Zoledronic acid / Pamidronate) ตามแผนแพทย์\n- บันทึกสัญญาณชีพ ระดับความรู้สึกตัว และ EKG Monitor อย่างใกล้ชิด\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) ทุก 2-4 ชม. ป้องกันภาวะขาดน้ำหรือสารน้ำเกิน\n- แนะนำการเคลื่อนไหวร่างกายเท่าที่ทำได้ (Mobilization) เพื่อลดการสลายแคลเซียมออกจากกระดูก\nResponse:\n- ผู้ป่วยรู้สึกตัวตื่นดีขึ้น อาการคลื่นไส้และท้องผูกทุเลาลง\n- ปัสสาวะออกดี (\u003e 100-150 ml/hr) ไม่มีอาการหอบเหนื่อยหรือบวมจากสารน้ำเกิน\n- คลื่นไฟฟ้าหัวใจ QT interval ปกติ ระดับแคลเซียมตรวจซ้ำลดลงสู่เกณฑ์ปลอดภัย"},{"shortcut":".hypomg","title":"ภาวะแมกนีเซียมในเลือดต่ำ (Hypomagnesemia, Mg \u003c 1.7 mg/dL)","content":"Focus: ภาวะแมกนีเซียมในเลือดต่ำ (Hypomagnesemia, Mg \u003c 1.7 mg/dL)\nGoal: ระดับ Serum Mg2+ กลับสู่เกณฑ์ปกติ (1.8 - 2.4 mg/dL) อาการกล้ามเนื้อกระตุกและใจสั่นทุเลาลง การตอบสนอง Reflex ปกติ\nData:\n- ผล Serum Mg2+ ล่าสุด ... mg/dL (ค่าปกติ 1.7 - 2.2 mg/dL)\n- ผู้ป่วยมีอาการกล้ามเนื้อกระตุก สั่น (Tremor) กล้ามเนื้อเกร็ง ไวต่อสิ่งกระตุ้น รีเฟล็กซ์ไวเกิน (Hyperreflexia, DTRs 3-4+)\n- มักพบร่วมกับภาวะ Hypokalemia และ Hypocalcemia ที่ดื้อต่อการรักษา\n- EKG Monitor: พบ Prolonged QT, Prolonged PR, ST depression, T wave inversion, เสี่ยงต่อ Torsades de Pointes และ VT/VF\nAction:\n- รายงานแพทย์ทราบผลตรวจแมกนีเซียมต่ำ\n- ให้การรักษาตามแผน:\n  * ภาวะวิกฤต/หัวใจเต้นผิดจังหวะ: ให้ 50% Magnesium sulfate (MgSO4) 2 g (4 ml) ผสมใน 5% D/W 100 ml IV drip ใน 15-30 นาที ผ่าน Infusion pump\n  * ภาวะไม่เร่งด่วน: ให้ 50% MgSO4 ... g ผสมใน IV fluid 1,000 ml drip ใน 8-12 ชม.\n  * ยารับประทาน: ให้ Magnesium oxide / Mag-F tab ตามแผน\n- ติดตาม EKG Monitor ต่อเนื่องขณะให้ยา\n- ตรวจ Deep Tendon Reflexes (DTRs), อัตราการหายใจ (RR) และปริมาณปัสสาวะก่อนและระหว่างให้ MgSO4 เสมอ (ป้องกันภาวะ Hypermagnesemia เป็นพิษ)\n- จัดสภาพแวดล้อมให้เงียบสงบ ลดสิ่งกระตุ้นเพื่อป้องกันอาการชักเกร็ง\nResponse:\n- กล้ามเนื้อไม่อ่อนแรงหรือกระตุกสั่น รีเฟล็กซ์ DTRs ปกติ (2+)\n- คลื่นไฟฟ้าหัวใจปกติ ไม่มี Ventricular Arrhythmia หรือ Torsades de Pointes\n- ผลตรวจติดตาม Serum Mg2+ กลับสู่ระดับปกติ"},{"shortcut":".hypermg","title":"ภาวะแมกนีเซียมในเลือดสูง (Hypermagnesemia, Mg \u003e 2.5 mg/dL)","content":"Focus: ภาวะแมกนีเซียมในเลือดสูง (Hypermagnesemia, Mg \u003e 2.5 mg/dL)\nGoal: ระดับ Serum Mg2+ ลดลงสู่เกณฑ์ปกติ การหายใจและสัญญาณชีพคงที่ Reflex กลับมาปกติ และขับแมกนีเซียมออกได้ดี\nData:\n- ผล Serum Mg2+ ล่าสุด ... mg/dL (ระดับวิกฤต \u003e 4.0 - 5.0 mg/dL)\n- ผู้ป่วยมีอาการหน้าแดง ร้อนวูบวาบ คลื่นไส้ อาเจียน กล้ามเนื้ออ่อนแรง ง่วงซึม ตอบสนองช้า\n- ตรวจ Deep Tendon Reflexes (DTRs): ลดลงหรือไม่พบ (Hyporeflexia / Absent DTRs, 0 - 1+)\n- สัญญาณชีพ: BP ตก (Hypotension), ชีพจรเต้นช้า (Bradycardia), อัตราการหายใจช้า (\u003c 10-12 ครั้ง/นาที)\n- EKG Monitor: Prolonged PR, Widened QRS, Tall T wave, เสี่ยงต่อ Complete Heart Block หรือ Cardiac arrest\nAction:\n- รายงานแพทย์ทันที และหยุดยาทุกชนิดที่มีส่วนผสมของแมกนีเซียม (ยาลดกรด, ยาระบาย M.O.M., ยาบำรุง)\n- ให้ยาต้านฤทธิ์ฉุกเฉินตามแผน: ให้ 10% Calcium Gluconate 10 ml IV push ช้าๆ ใน 5-10 นาที เพื่อต้านพิษของแมกนีเซียมต่อกล้ามเนื้อหัวใจ\n- ส่งเสริมการขับถ่ายแมกนีเซียม: ให้ 0.9% NSS IV drip ร่วมกับ Furosemide (Lasix) ... mg IV ตามแผน\n- ให้ออกซิเจนและเตรียมเครื่องช่วยหายใจ / รถกู้ชีพฉุกเฉินให้พร้อม\n- เตรียมผู้ป่วยเพื่อฟอกเลือดฉุกเฉิน (Hemodialysis) กรณีผู้ป่วยไตวายหรือระดับ Mg สูงวิกฤตรุนแรง\n- ประเมิน DTRs, อัตราการหายใจ และระดับความรู้สึกตัวทุก 15-30 นาที\nResponse:\n- ผู้ป่วยรู้สึกตัวดีขึ้น รีเฟล็กซ์ DTRs กลับมาปกติ (2+)\n- หายใจสม่ำเสมอ อัตราการหายใจ \u003e 16 ครั้ง/นาที ความดันโลหิตและชีพจรคงที่\n- ผลตรวจ Serum Mg2+ ลดลงสู่เกณฑ์ปลอดภัย"},{"shortcut":".hypop","title":"ภาวะฟอสเฟตในเลือดต่ำ (Hypophosphatemia, PO4 \u003c 2.5 mg/dL)","content":"Focus: ภาวะฟอสเฟตในเลือดต่ำ (Hypophosphatemia, Serum Phosphate \u003c 2.5 mg/dL)\nGoal: ระดับ Serum Phosphate กลับสู่เกณฑ์ปกติ (2.5 - 4.5 mg/dL) กล้ามเนื้อหายใจและกล้ามเนื้อลายมีแรงดีขึ้น ไม่อ่อนเพลีย\nData:\n- ผล Serum Phosphorus/Phosphate ล่าสุด ... mg/dL (ค่าวิกฤต \u003c 1.0 - 1.5 mg/dL)\n- ผู้ป่วยมีอาการกล้ามเนื้ออ่อนแรง หายใจเหนื่อย หย่าเครื่องช่วยหายใจไม่สำเร็จ (Difficulty weaning from ventilator)\n- มีอาการสับสน อ่อนเพลียอย่างมาก ชัก อาการกล้ามเนื้อสลาย (Rhabdomyolysis) ปวดกล้ามเนื้อ ปัสสาวะสีโค้ก\n- มักพบในผู้ป่วยทุพโภชนาการที่ได้รับสารอาหารเร็วเกินไป (Refeeding Syndrome), ผู้ป่วย DKA หลังได้ Insulin, หรือพิษสุราเรื้อรัง\nAction:\n- รายงานแพทย์ทราบค่าฟอสเฟตในเลือดต่ำ\n- ให้การพยาบาลตามแผนการรักษา:\n  * กรณีให้ทางหลอดเลือดดำ: ให้ Sodium Phosphate หรือ Potassium Phosphate ... mmol in IV fluid ... ml drip ช้าๆ ใน 4-6 ชม. (ใช้อัตราไม่เกิน 7-10 mmol/hr เฝ้าระวังระดับแคลเซียมในเลือดลดต่ำลง)\n  * กรณีรับประทานได้: เสริมฟอสเฟตทางปาก เช่น นม ไข่แดง ถั่ว ปลา หรือยาฟอสเฟตตามแพทย์สั่ง\n- ประเมินกำลังกล้ามเนื้อ อัตราและลักษณะการหายใจอย่างใกล้ชิด\n- ติดตามระดับ Serum Phosphate, Calcium, Potassium และ Magnesium ควบคู่กันเสมอ\n- เฝ้าระวังสีและปริมาณปัสสาวะ ตรวจติดตามค่า CK หากสงสัยภาวะกล้ามเนื้อสลาย\nResponse:\n- กำลังกล้ามเนื้อดีขึ้น หายใจสม่ำเสมอ หายใจด้วยตนเองได้ดีขึ้น\n- ปัสสาวะออกปกติ ไม่มีสีเข้มผิดปกติ\n- ผลตรวจติดตาม Serum Phosphate เพิ่มขึ้นสู่ระดับปกติอย่างปลอดภัย"},{"shortcut":".hyperp","title":"ภาวะฟอสเฟตในเลือดสูง (Hyperphosphatemia, PO4 \u003e 4.5 mg/dL)","content":"Focus: ภาวะฟอสเฟตในเลือดสูง (Hyperphosphatemia, Serum Phosphate \u003e 4.5 mg/dL)\nGoal: ระดับ Serum Phosphate ลดลงสู่เกณฑ์ปลอดภัย ป้องกันการจับตัวของผลึกแคลเซียมฟอสเฟตในเนื้อเยื่อ และไตขับฟอสเฟตได้ดีขึ้น\nData:\n- ผล Serum Phosphorus/Phosphate ล่าสุด ... mg/dL (ค่าปกติ 2.5 - 4.5 mg/dL)\n- ผู้ป่วยมีอาการคันตามผิวหนัง มีอาการของภาวะแคลเซียมต่ำร่วมด้วย (กล้ามเนื้อกระตุก มือหงิกเกร็ง ชารอบปาก)\n- มีประวัติโรคไตเรื้อรัง (CKD/ESRD), ภาวะเนื้อเยื่อสลาย (Tumor Lysis Syndrome / Rhabdomyolysis)\n- เสี่ยงต่อการเกิดผลึกแคลเซียมฟอสเฟตตกตะกอนตามเนื้อเยื่อ หลอดเลือด และไต (Metastatic Calcification)\nAction:\n- รายงานแพทย์ทราบผลแล็บ\n- ให้การรักษาและการพยาบาลตามแผน:\n  * ให้ยาจับฟอสเฟตในทางเดินอาหาร (Phosphate Binders) เช่น Calcium carbonate, Calcium acetate หรือ Sevelamer ตามแผนการรักษา (แนะนำผู้ป่วยรับประทานพร้อมอาหารหรือเคี้ยวพร้อมมื้ออาหารทันทีเพื่อให้ยาจับกับฟอสเฟตในอาหาร)\n  * งดอาหารที่มีฟอสเฟตสูง: ผลิตภัณฑ์จากนม เนย ชีส ถั่ว ข้าวโอ๊ต ช็อกโกแลต น้ำอัดลมสีเข้ม\n  * ให้น้ำเกลือ 0.9% NSS IV drip และยาขับปัสสาวะเพื่อเร่งการขับถ่ายทางไต (ในผู้ป่วยที่การทำงานของไตยังดี)\n  * เตรียมการฟอกเลือด (Hemodialysis) ตามแผนการรักษาในผู้ป่วยไตวายเรื้อรัง\n- ดูแลผิวหนัง ทาโลชั่นบรรเทาอาการคัน และตัดเล็บให้สั้นเพื่อป้องกันแผลติดเชื้อจากการเกา\nResponse:\n- ผู้ป่วยไม่มีอาการชาเกร็ง อาการคันตามผิวหนังลดลง\n- ปฏิบัติตัวและควบคุมอาหารที่มีฟอสเฟตสูงได้อย่างถูกต้อง รับประทานยาพร้อมมื้ออาหารตามคำแนะนำ\n- ผลตรวจ Serum Phosphate และ Calcium ค่อยๆ ลดลงสู่ระดับเป้าหมาย"}]},{"category":"15. ผลแล็บและค่าเลือดผิดปกติ (Critical Labs \u0026 Abnormal Blood Values)","items":[{"shortcut":".anemia","title":"ภาวะโลหิตจางรุนแรง / ซีดวิกฤต (Severe Anemia, Hb \u003c 7-8 g/dL)","content":"Focus: ภาวะโลหิตจางรุนแรง / ภาวะซีดวิกฤต (Severe Anemia, Hb \u003c 7-8 g/dL)\nGoal: ระดับ Hb/Hct เพิ่มขึ้นสู่เกณฑ์เป้าหมาย อาการซีด เหนื่อย เพลีย วิงเวียนศีรษะทุเลาลง เนื้อเยื่อได้รับออกซิเจนเพียงพอ และสัญญาณชีพคงที่\nData:\n- ผล CBC: Hb ... g/dL, Hct ... %, RBC indices ปกติ/ผิดปกติ\n- ผู้ป่วยมีอาการหน้ามืด วิงเวียนศีรษะ เหนื่อยง่าย อ่อนเพลีย ใจสั่นเวลาขยับตัว ตาพร่ามัว ซีดตามเยื่อบุตา ริมฝีปาก และฝ่ามือ\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเร็ว Tachycardia), SpO2 ... %\n- ประเมินแหล่งเลือดออก: แผลผ่าตัด, เลือดออกในทางเดินอาหาร (Melena / Hematemesis), หรือปัสสาวะปนเลือด\nAction:\n- รายงานแพทย์ทราบผลค่าเลือดวิกฤตทันที\n- ดูแลให้นอนพักบนเตียง (Bed rest) ช่วยเหลือการทำกิจวัตรประจำวัน ยกไม้กั้นเตียงป้องกันพลัดตกหกล้ม\n- ให้ออกซิเจนแคนนูลา 3-5 LPM ตามแผนการรักษาเพื่อเพิ่มการนำส่งออกซิเจนสู่เนื้อเยื่อ\n- เตรียมการให้เลือดตามแผนแพทย์:\n  * เจาะเลือดส่งตรวจ Blood Grouping, Rh และ Crossmatch ทันที\n  * ตรวจสอบเลือด Packed Red Cells (PRC) ... unit ร่วมกับพยาบาล 2 ท่าน (ตรวจสอบชื่อ-สกุล, HN, Unit no., Blood group, วันหมดอายุ)\n  * วัดสัญญาณชีพก่อนให้เลือด, ที่ 15 นาทีแรก, และทุก 1 ชม. จนให้เสร็จ\n  * ให้เลือดผ่านสาย Transfusion set ที่มีตัวกรอง เฝ้าระวังปฏิกิริยาแพ้เลือด (ไข้ หนาวสั่น แน่นหน้าอก ผื่นขึ้น BP ตก)\n- ติดตามบันทึกสัญญาณชีพและอาการเหนื่อยอย่างใกล้ชิด\nResponse:\n- ผู้ป่วยไม่มีอาการหน้ามืด เหนื่อยเพลียลดลง ริมฝีปากและเล็บมีสีชมพูขึ้น\n- ไม่มีภาวะแทรกซ้อนจากการให้เลือด สัญญาณชีพคงที่ ไม่มีไข้หรือผื่น\n- ตรวจติดตามค่า Hct ซ้ำหลังให้เลือด 4-6 ชม. ค่า Hct เพิ่มขึ้นเป็น ... %"},{"shortcut":".thrombocyto","title":"ภาวะเกล็ดเลือดต่ำวิกฤต (Severe Thrombocytopenia, Plt \u003c 20,000 - 50,000 /uL)","content":"Focus: ภาวะเกล็ดเลือดต่ำวิกฤต เสี่ยงต่อภาวะเลือดออกรุนแรง (Severe Thrombocytopenia)\nGoal: ระดับเกล็ดเลือดอยู่ในเกณฑ์ปลอดภัย ไม่เกิดภาวะเลือดออกผิดปกติในอวัยวะสำคัญ (Zero Major Bleeding) และไม่มีจุดเลือดออกเพิ่ม\nData:\n- ผล Platelet Count ล่าสุด ... /uL (ค่าวิกฤต \u003c 20,000 - 50,000 /uL)\n- สำรวจร่างกายพบ: จุดเลือดออกใต้ผิวหนัง (Petechiae), จ้ำเลือด (Purpura/Ecchymosis), เลือดออกตามไรฟัน, เลือดกำเดาไหล\n- เฝ้าระวังเลือดออกในอวัยวะสำคัญ: ปวดศีรษะรุนแรง อาเจียนพุ่ง (Intracranial hemorrhage), ถ่ายดำ ถ่ายเป็นเลือด ปัสสาวะเป็นเลือด\nAction:\n- รายงานแพทย์ทราบผลเกล็ดเลือดต่ำวิกฤต\n- ปฏิบัติตามมาตรการป้องกันเลือดออก (Bleeding Precautions) อย่างเคร่งครัด:\n  * **ห้ามฉีดยาเข้ากล้ามเนื้อ (No IM Injection)** เด็ดขาด และหลีกเลี่ยงการเจาะเลือดซ้ำซ้อน\n  * หากจำเป็นต้องเจาะเลือด ให้กดแผลห้ามเลือดแน่นๆ นานอย่างน้อย 5-10 นาที\n  * แนะนำผู้ป่วยใช้แปรงสีฟันขนอ่อนนุ่ม ห้ามแคะจมูก ห้ามเบ่งถ่ายอุจจาระแรงๆ\n  * ยกไม้กั้นเตียงทั้งสองข้าง ระวังการกระแทกหรือพลัดตกหกล้ม\n  * หลีกเลี่ยงยาที่มีผลต่อการทำงานของเกล็ดเลือด เช่น Aspirin, NSAIDs, Anticoagulants\n- ให้สารประกอบเกล็ดเลือด (Platelet Concentrate / Single Donor Platelet) ... units ตามแผนแพทย์ โดยให้ทันทีผ่านสายให้เลือดด้วยความนุ่มนวล\n- บันทึกสัญญาณชีพและตรวจระบบประสาท (Pupils, GCS) ทุก 2-4 ชม.\nResponse:\n- ไม่มีจุดเลือดออกใหม่ตามผิวหนัง ไม่มีเลือดออกตามไรฟันหรือเลือดกำเดา\n- รู้สึกตัวดี สัญญาณชีพคงที่ ไม่มีอาการปวดศีรษะหรือความดันในกะโหลกศีรษะสูง\n- ผลตรวจ Platelet count หลังให้เกล็ดเลือดเพิ่มขึ้นเป็น ... /uL"},{"shortcut":".pancytopenia","title":"ภาวะเม็ดเลือดต่ำทุกชนิด (Pancytopenia: Anemia + Leukopenia + Thrombocytopenia)","content":"Focus: ภาวะเม็ดเลือดต่ำทุกชนิด (Pancytopenia: เม็ดเลือดแดง เม็ดเลือดขาว และเกล็ดเลือดต่ำพร้อมกัน)\nGoal: ป้องกันการติดเชื้อในกระแสเลือด ป้องกันภาวะเลือดออกง่าย และแก้ไขภาวะซีดอย่างมีประสิทธิภาพ\nData:\n- ผล CBC: Hb ... g/dL, WBC ... /uL, ANC ... /uL, Platelet ... /uL\n- มีอาการอ่อนเพลีย เหนื่อย ซีด (Anemia) เสี่ยงต่อการติดเชื้อง่าย (Neutropenia) และมีจ้ำเลือด/เลือดออกง่าย (Thrombocytopenia)\n- ประเมินสัญญาณชีพ: T ... °C, BP ... mmHg, PR ... bpm, RR ... /min\nAction:\n- รายงานแพทย์และเฝ้าระวัง 3 ภาวะหลักพร้อมกัน:\n  1. **ด้านการติดเชื้อ (Infection Protection):** แนะนำผู้ป่วยสวมหน้ากากอนามัย ล้างมือบ่อยๆ แยกห้องพัก ดูแลความสะอาดของร่างกายและสิ่งแวดล้อม รับประทานอาหารปรุงสุกสะอาด\n  2. **ด้านภาวะซีด (Anemia Care):** ดูแลให้นอนพักบนเตียง ลดกิจกรรมที่เหนื่อยล้า ให้ออกซิเจนตามแผนการรักษา\n  3. **ด้านการป้องกันเลือดออก (Bleeding Precautions):** หลีกเลี่ยงการฉีดยาเข้ากล้าม ใช้แปรงสีฟันขนนุ่ม ระวังอุบัติเหตุหกล้ม\n- ให้ยาปฏิชีวนะ ยาเพิ่มเม็ดเลือดขาว (G-CSF) เลือด PRC หรือเกล็ดเลือดตามแผนแพทย์อย่างเคร่งครัด\n- วัดสัญญาณชีพและอุณหภูมิกายทุก 4 ชม. หากมีไข้ (T ≥ 38.0 °C) ให้รายงานแพทย์และส่ง Hemoculture ทันที\nResponse:\n- ผู้ป่วยไม่มีไข้ ไม่มีจุดเลือดออกใหม่ ปากและเยื่อบุสะอาด\n- รู้สึกตัวดี อาการอ่อนเพลียลดลง สัญญาณชีพคงที่\n- ปฏิบัติตัวตามมาตรการป้องกันการติดเชื้อและเลือดออกได้อย่างถูกต้อง"},{"shortcut":".leukocytosis","title":"ภาวะเม็ดเลือดขาวสูงผิดปกติ / ติดเชื้อรุนแรง (Leukocytosis, WBC \u003e 15,000 /uL)","content":"Focus: ภาวะเม็ดเลือดขาวสูงผิดปกติ บ่งชี้การติดเชื้อรุนแรงในร่างกาย (Leukocytosis / Severe Infection)\nGoal: ค้นหาและกำจัดแหล่งติดเชื้อ ระดับเม็ดเลือดขาวลดลงสู่เกณฑ์ปกติ สัญญาณชีพคงที่ และไข้ลดลง\nData:\n- ผล CBC: WBC ... /uL (ค่าปกติ 4,000 - 10,000 /uL), Neutrophil ... %, Band form ... % (Shift to the left)\n- อาการแสดง: มีไข้ หนาวสั่น เหงื่อออก ชีพจรเต้นเร็ว หายใจเร็ว ปวดเมื่อยตามตัว\n- ค้นหาจุดติดเชื้อ: แผลผ่าตัดมีอาการปวด บวม แดง ร้อน มีหนอง, ไอมีเสมหะสีเหลืองเขียว, ปัสสาวะแสบขัดขุ่น, หรือสายสวนต่างๆ\n- สัญญาณชีพ: T ... °C, PR ... bpm, RR ... /min, BP ... mmHg\nAction:\n- รายงานแพทย์ทราบผลค่าเม็ดเลือดขาวสูงและอาการแสดงของการติดเชื้อ\n- ปฏิบัติตาม Sepsis Protocol:\n  * ส่งตรวจเพาะเชื้อ (Hemoculture 2 ข้าง, Sputum, Urine culture) ก่อนเริ่มยาปฏิชีวนะ\n  * ให้ยาปฏิชีวนะทางหลอดเลือดดำ (IV Antibiotics) ภายใน 1 ชม. แรกตามแผนการรักษาอย่างเคร่งครัด\n  * ให้ยาลดไข้ Paracetamol ... mg ทางปาก/IV และเช็ดตัวลดไข้ (Tepid sponge)\n- ดูแลทำความสะอาดแผลผ่าตัดด้วยเทคนิคปลอดเชื้อ (Aseptic technique)\n- ติดตามอุณหภูมิกายและสัญญาณชีพทุก 2-4 ชม. ประเมินภาวะช็อกจากการติดเชื้อ (Septic Shock)\nResponse:\n- ไข้ลดลง อุณหภูมิกาย \u003c 37.5 °C ชีพจรและการหายใจช้าลงสู่เกณฑ์ปกติ\n- แผลผ่าตัดแห้งดี ไม่มีหนองซึม\n- ผลตรวจติดตาม WBC ตรวจซ้ำลดลงสู่ระดับปกติ"},{"shortcut":".neutropenia","title":"ภาวะเม็ดเลือดขาวต่ำวิกฤต / เสี่ยงติดเชื้อรุนแรง (Febrile / Severe Neutropenia, ANC \u003c 500-1,000)","content":"Focus: ภาวะเม็ดเลือดขาวต่ำวิกฤต เสี่ยงต่อการติดเชื้อรุนแรงถึงแก่ชีวิต (Severe Neutropenia, ANC \u003c 500-1,000)\nGoal: ป้องกันการติดเชื้อแบคทีเรียและเชื้อราอย่างเข้มงวด (Infection-free) เม็ดเลือดขาวชนิด Neutrophil ฟื้นตัว และไม่เกิดภาวะ Sepsis\nData:\n- ผล Absolute Neutrophil Count (ANC) ล่าสุด ... /uL (ภาวะวิกฤต ANC \u003c 500 /uL เสี่ยงติดเชื้อขั้นรุนแรง)\n- อุณหภูมิกาย: T ... °C (หาก T ≥ 38.0°C หรือ ≥ 38.3°C ถือเป็นภาวะฉุกเฉิน Febrile Neutropenia)\n- สังเกตอาการติดเชื้อที่อาจไม่มีหนองชัดเจน: เจ็บคอ แผลในปาก ปวดทวารหนัก เจ็บบริเวณสายสวนหลอดเลือด หนาวสั่น ซึม\nAction:\n- ดำเนินการตามมาตรการป้องกันการติดเชื้อเข้มงวด (Neutropenic Precautions):\n  * จัดให้อยู่ในห้องแยกเดี่ยว (Private Room) แนะนำผู้เข้าพบสวมหน้ากากอนามัยและล้างมือทุกครั้ง\n  * หลีกเลี่ยงอาหารดิบ ผักสด ผลไม้เปลือกบาง รับประทานเฉพาะอาหารปรุงสุกใหม่ สะอาด\n  * แนะนำบ้วนปากด้วยน้ำเกลือ 0.9% NSS ทุกครั้งหลังอาหาร หลีกเลี่ยงน้ำยาบ้วนปากที่มีแอลกอฮอล์\n  * **ห้ามวัดอุณหภูมิทางทวารหนัก และห้ามเหน็บยา/สวนอุจจาระ (No per rectum)** เพื่อป้องกันเยื่อบุฉีกขาด\n- กรณีมีไข้ (Febrile Neutropenia): ส่งเพาะเชื้อ Hemoculture 2 จุดทันที และให้ยาปฏิชีวนะ Broad-spectrum IV Antibiotics ภายใน 1 ชม.\n- ให้ยาเพิ่มเม็ดเลือดขาว Granulocyte Colony-Stimulating Factor (G-CSF / Filgrastim) ฉีดใต้ผิวหนังตามแผนแพทย์\n- วัดสัญญาณชีพและประเมินอาการติดเชื้อทุก 2-4 ชม.\nResponse:\n- ผู้ป่วยไม่มีไข้ ไม่มีอาการหนาวสั่น เยื่อบุช่องปากสะอาด ไม่มีแผลอักเสบ\n- สัญญาณชีพคงที่ ไม่มีอาการติดเชื้อในกระแสเลือด\n- ผลตรวจติดตาม ANC ค่อยๆ เพิ่มขึ้นสูงกว่า 1,000 /uL"},{"shortcut":".coagulopathy","title":"ภาวะการแข็งตัวของเลือดผิดปกติ (Coagulopathy, Prolonged PT/INR, PTT)","content":"Focus: ภาวะการแข็งตัวของเลือดผิดปกติ เสี่ยงต่อภาวะเลือดออกไม่หยุด (Coagulopathy)\nGoal: การแข็งตัวของเลือดกลับสู่เกณฑ์ปลอดภัย ค่า PT/INR/PTT ดีขึ้น ไม่มีเลือดออกในอวัยวะสำคัญ และหยุดเลือดได้อย่างรวดเร็ว\nData:\n- ผล Coagulogram ล่าสุด: PT ... sec, INR ... (ปกติ 0.8-1.2, วิกฤต \u003e 2.5-3.0), aPTT ... sec (ปกติ 25-35 sec)\n- ผู้ป่วยมีประวัติใช้ยาต้านการแข็งตัวของเลือด (Warfarin / Heparin / DOACs), โรคตับแข็ง, หรือภาวะ DIC\n- สำรวจร่างกาย: เลือดออกตามแผลผ่าตัดไม่ยอมหยุด, เลือดออกตามรอยเจาะเข็ม, จ้ำเลือดขนาดใหญ่, เลือดออกในทางเดินอาหาร\nAction:\n- รายงานแพทย์ทราบผลค่าการแข็งตัวของเลือดที่ผิดปกติทันที\n- ปฏิบัติตามแผนการรักษาเพื่อแก้ไขการแข็งตัวของเลือด:\n  * กรณีได้รับ Warfarin เกินขนาด: ให้ Vitamin K1 (Phytomenadione) ... mg IV slow push หรือ Oral ตามแผน\n  * กรณีได้รับ Heparin เกินขนาด: ให้ Protamine sulfate ตามสัดส่วนขนาดยาและเวลาที่แพทย์กำหนด\n  * กรณีเลือดออกเฉียบพลัน: ให้ Fresh Frozen Plasma (FFP) ... units IV drip เพื่อทดแทน Clotting factors\n  * หยุดยาต้านการแข็งตัวของเลือดทุกชนิดชั่วคราวตามคำสั่งแพทย์\n- ใช้สำลีหรือผ้าก๊อซกดแผลห้ามเลือดนานกว่าปกติ (อย่างน้อย 10-15 นาที)\n- เฝ้าระวังเลือดออกในอวัยวะสำคัญ: บันทึกระดับความรู้สึกตัว (Neuro signs), สัญญาณชีพ และตรวจสีปัสสาวะ/อุจจาระ\nResponse:\n- เลือดบริเวณแผลผ่าตัดและรอยเข็มหยุดสนิท ไม่มีจ้ำเลือดหรือเลือดออกเพิ่ม\n- ผู้ป่วยรู้สึกตัวดี สัญญาณชีพคงที่ Hct ไม่ลดลง\n- ผลตรวจซ้ำ PT/INR และ aPTT ลดลงสู่เกณฑ์ที่ปลอดภัยตามเป้าหมาย"},{"shortcut":".metacid","title":"ภาวะเลือดเป็นกรดเมแทบอลิก (Metabolic Acidosis, pH \u003c 7.35, HCO3 \u003c 22)","content":"Focus: ภาวะเลือดเป็นกรดเมแทบอลิก (Metabolic Acidosis, pH \u003c 7.35, HCO3 \u003c 22 mEq/L)\nGoal: ภาวะกรดเมตาบอลิกได้รับการแก้ไข ค่า pH และ HCO3- ในเลือดกลับสู่เกณฑ์ปกติ การหายใจลึกเหนื่อยลดลง และสัญญาณชีพคงที่\nData:\n- ผล Arterial Blood Gas (ABG): pH ... (ปกติ 7.35-7.45), HCO3 ... mEq/L (ปกติ 22-26), PaCO2 ... mmHg, Base Excess ...\n- อาการแสดง: หายใจลึกเร็ว (Kussmaul breathing เพื่อขับ CO2 ชดเชย), อ่อนเพลีย สับสน ซึม คลื่นไส้\n- สัญญาณชีพ: BP ตก (Hypotension), ชีพจรเร็ว, ปลายมือปลายเท้าเย็น\n- สาเหตุที่พบบ่อย: DKA (น้ำตาลสูง), Lactic Acidosis (Sepsis/Shock), ไตวายรุนแรง (Uremia), หรือท้องเสียรุนแรง\nAction:\n- รายงานแพทย์ทราบผลตรวจก๊าซในเลือดทันที\n- ดูแลรักษาตามสาเหตุของภาวะกรดเกิน:\n  * กรณีติดเชื้อ/ช็อก (Lactic acidosis): ให้สารน้ำ 0.9% NSS / Acetar IV resuscitation อย่างเต็มที่ ร่วมกับยาปฏิชีวนะ\n  * กรณี DKA: ให้ Regular Insulin IV drip ร่วมกับสารน้ำทดแทนตาม DKA Protocol\n  * กรณีเป็นกรดรุนแรง (pH \u003c 7.1-7.2 หรือ HCO3 \u003c 10): ให้ 7.5% Sodium Bicarbonate ... ml ผสมในสารน้ำ IV drip ตามแผนแพทย์อย่างระมัดระวัง\n- ให้ออกซิเจนแคนนูลาหรือ Mask with bag ตามความเหมาะสม\n- ติดตามเฝ้าระวังระดับ Serum K+ (ภาวะเลือดเป็นกรดทำให้ K+ ออกนอกเซลล์ เมื่อกรดลดลง K+ จะลดลงตาม)\n- ตรวจบันทึกสัญญาณชีพ, สภาพการหายใจ และประเมินระดับความรู้สึกตัวทุก 1-2 ชม.\nResponse:\n- การหายใจลึกเร็วลดลง สภาพการหายใจสม่ำเสมอขึ้น\n- ผู้ป่วยรู้สึกตัวดีขึ้น ความดันโลหิตและสัญญาณชีพกลับสู่เกณฑ์ปกติ\n- ผลตรวจติดตาม ABG: ค่า pH และ HCO3 ปรับตัวดีขึ้นสู่ระดับปลอดภัย"},{"shortcut":".metalk","title":"ภาวะเลือดเป็นด่างเมแทบอลิก (Metabolic Alkalosis, pH \u003e 7.45, HCO3 \u003e 26)","content":"Focus: ภาวะเลือดเป็นด่างเมแทบอลิก (Metabolic Alkalosis, pH \u003e 7.45, HCO3 \u003e 26 mEq/L)\nGoal: ภาวะด่างเมตาบอลิกดีขึ้น การหายใจและเกลือแร่กลับสู่สมดุล อาการชาและกล้ามเนื้อกระตุกเกร็งทุเลาลง\nData:\n- ผล Arterial Blood Gas (ABG): pH ... (ค่าปกติ 7.35 - 7.45), HCO3 ... mEq/L (ค่าปกติ 22 - 26 mEq/L)\n- อาการแสดง: การหายใจช้าและตื้น (Hypoventilation เพื่อกัก CO2 ชดเชย), ชาปลายมือปลายเท้า, กล้ามเนื้อกระตุกเกร็ง (Tetany)\n- มักพบร่วมกับภาวะ Hypokalemia และ Hypochloremia จากการอาเจียนรุนแรง, การดูดระบายน้ำย่อยทาง NG tube มากเกินไป, หรือการได้ยาขับปัสสาวะ\nAction:\n- รายงานแพทย์ทราบผลค่าเลือด\n- ให้การพยาบาลตามแผนการรักษา:\n  * ให้สารน้ำ 0.9% NSS IV drip เพื่อชดเชยปริมาตรและคลอไรด์ (Chloride-responsive alkalosis)\n  * ตรวจและแก้ไขภาวะโพแทสเซียมต่ำ: เสริม Potassium Chloride (KCl) ตามแผนการรักษา\n  * กรณีคาสาย NG tube ดูดน้ำย่อย: ปรับลดความถี่หรือหยุดการดูดระบายชั่วคราวตามคำสั่งแพทย์\n- สังเกตลักษณะการหายใจและตรวจวัดความอิ่มตัวของออกซิเจน (SpO2) อย่างใกล้ชิด (ป้องกันภาวะ Hypoxemia จากการหายใจช้า)\n- บันทึกสัญญาณชีพ ปริมาณน้ำเข้า-ออก (I/O) และอาการทางระบบประสาทกล้ามเนื้อ\nResponse:\n- อาการชาและกล้ามเนื้อกระตุกทุเลาลง การหายใจสม่ำเสมอ SpO2 \u003e 95%\n- สัญญาณชีพคงที่ ระดับเกลือแร่ K+ และ Cl- ตรวจซ้ำกลับสู่เกณฑ์ปกติ\n- ผล ABG ค่าความเป็นกรดด่าง (pH) กลับคืนสู่สภาวะสมดุล"},{"shortcut":".respacid","title":"ภาวะเลือดเป็นกรดจากการหายใจล้มเหลว (Respiratory Acidosis / CO2 Retention)","content":"Focus: ภาวะเลือดเป็นกรดจากการหายใจ ระบายคาร์บอนไดออกไซด์ไม่เพียงพอ (Respiratory Acidosis, PaCO2 \u003e 45 mmHg)\nGoal: ปรับปรุงการระบายอากาศให้มีประสิทธิภาพ ขจัดก๊าซคาร์บอนไดออกไซด์ส่วนเกิน ระดับ PaCO2 และ pH ในเลือดกลับสู่เกณฑ์ปกติ\nData:\n- ผล Arterial Blood Gas (ABG): pH ... (\u003c 7.35), PaCO2 ... mmHg (ปกติ 35-45 mmHg), HCO3 ... mEq/L\n- ผู้ป่วยมีอาการหายใจตื้น หายใจลำบาก หอบเหนื่อย อกบุ๋ม หรือกดการหายใจ ซึม ง่วงหลับ ปวดศีรษะ สับสน (CO2 Narcosis)\n- ตรวจพบ Asterixis (มือสั่นกระตุกเมื่อเหยียดแขนกระดกข้อมือ)\n- ประวัติโรคปอดอุดกั้นเรื้อรัง (COPD), หอบหืดรุนแรง (Severe Asthma), ได้รับยากดประสาท/มอร์ฟีน, หรือกล้ามเนื้อหายใจอ่อนแรง\nAction:\n- รายงานแพทย์ทันที และจัดท่านอนศีรษะสูง 45 - 90 องศา (High Fowler\u0027s position) เพื่อขยายทรวงอก\n- เคลียร์ทางเดินหายใจให้โล่ง ดูดเสมหะ (Suction) หากมีเสมหะคั่งค้าง\n- ให้การรักษาด้านระบบหายใจตามแผนแพทย์:\n  * ผู้ป่วย COPD: ให้ออกซิเจนความเข้มข้นต่ำอย่างระมัดระวัง (Venturi mask หรือ Low-flow nasal cannula 1-2 LPM) เป้าหมาย SpO2 88-92%\n  * พ่นยาขยายหลอดลม (Bronchodilator nebulizer) ตามคำสั่งแพทย์\n  * กรณีได้รับยาแก้ปวดกลุ่ม Opioids เกินขนาด: เตรียมยาต้าน Naloxone (Narcan) ... mg IV ตามแผน\n  * เตรียมอุปกรณ์ช่วยหายใจแรงดันบวก (BiPAP) หรือเตรียมท่อช่วยหายใจ (Endotracheal tube) หากผู้ป่วยซึมลงหรือไม่สามารถหายใจเองได้\n- บันทึกสัญญาณชีพ ความลึก-อัตราการหายใจ และ SpO2 อย่างต่อเนื่อง\nResponse:\n- ผู้ป่วยรู้สึกตัวตื่นดีขึ้น หายใจเหนื่อยลดลง ไม่มีอาการง่วงซึมหรือสับสน\n- อัตราการหายใจสม่ำเสมอ SpO2 อยู่ในเกณฑ์เป้าหมาย\n- ผลตรวจซ้ำ ABG ค่า PaCO2 ลดลง และค่า pH ปรับตัวดีขึ้น"},{"shortcut":".aki","title":"ภาวะไตวายเฉียบพลัน (Acute Kidney Injury: Cr สูง / ปัสสาวะออกน้อย Oliguria)","content":"Focus: ภาวะไตวายเฉียบพลัน (Acute Kidney Injury: AKI)\nGoal: ชะลอและฟื้นฟูการทำงานของไต ค่า BUN/Cr ลดลง ปริมาณปัสสาวะออกอย่างน้อย 0.5 ml/kg/hr และเกลือแร่ในเลือดสมดุล\nData:\n- ผลการทำงานของไต: Serum Creatinine (Cr) เพิ่มขึ้นเป็น ... mg/dL (เดิม ... mg/dL), BUN ... mg/dL, eGFR ... ml/min\n- ปริมาณปัสสาวะ: ปัสสาวะออกน้อย (Oliguria \u003c 0.5 ml/kg/hr ต่อเนื่อง 6 ชม.) ปริมาณปัสสาวะรวมใน 24 ชม. ได้ ... ml\n- อาการแสดง: มีอาการบวมตามหนังตา ขาและข้อเท้าบวมทั้งสองข้าง น้ำหนักตัวเพิ่มขึ้น อ่อนเพลีย คลื่นไส้ เบื่ออาหาร หายใจหอบเหนื่อย\n- ฟังปอดได้ยินเสียง Crepitation หรือ Wheezing (สงสัยภาวะน้ำท่วมปอด / Pulmonary edema)\nAction:\n- รายงานแพทย์ทราบค่าไตที่เพิ่มขึ้นและปริมาณปัสสาวะออกน้อย\n- หาสาเหตุและให้การพยาบาลตามแผน:\n  * กรณี Pre-renal (ขาดน้ำ/ความดันตก): ให้สารน้ำ IV resuscitation ตามแผน และติดตาม CVP หรือความดันโลหิต\n  * กรณี Post-renal (อุดกั้นทางเดินปัสสาวะ): ตรวจสอบสายสวนปัสสาวะว่าพับหักงอหรือตันหรือไม่ ล้างสายสวนหรือรายงานแพทย์พิจารณาใส่สายสวนใหม่\n  * กรณีได้รับยาที่มีพิษต่อไต (Nephrotoxic drugs): แจ้งแพทย์และเภสัชกรเพื่อชะลอหรือปรับขนาดยา (เช่น NSAIDs, Aminoglycosides, Vancomycin, Colistin)\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) อย่างเคร่งครัดทุก 1-2 ชม.\n- ชั่งน้ำหนักตัวทุกเช้าก่อนอาหาร\n- ติดตามระดับเกลือแร่ในเลือดอย่างใกล้ชิด โดยเฉพาะภาวะโพแทสเซียมสูง (Hyperkalemia) และเลือดเป็นกรด\nResponse:\n- ปริมาณปัสสาวะออกเพิ่มขึ้น (\u003e 0.5 ml/kg/hr) อาการบวมลดลง\n- ผู้ป่วยไม่มีอาการหอบเหนื่อย ไม่มีเสียงผิดปกติในปอด สัญญาณชีพคงที่\n- ผลตรวจติดตามค่า BUN และ Creatinine ทรงตัวและค่อยๆ ลดลงสู่เกณฑ์ปกติ"},{"shortcut":".hyperbili","title":"ภาวะบิลิรูบินในเลือดสูง / ดีซ่าน (Hyperbilirubinemia / Jaundice)","content":"Focus: ภาวะบิลิรูบินในเลือดสูงและภาวะดีซ่าน (Hyperbilirubinemia / Clinical Jaundice)\nGoal: ภาวะตัวเหลืองตาเหลืองลดลง ระดับบิลิรูบินในเลือดลดลง ขจัดสารพิษได้ดี และไม่เกิดภาวะแทรกซ้อนทางระบบประสาท\nData:\n- ผล LFTs: Total Bilirubin ... mg/dL (ปกติ 0.2 - 1.2 mg/dL), Direct Bilirubin ... mg/dL\n- สภาพร่างกาย: ตัวเหลือง ตาเหลือง (Icteric sclerae), ปัสสาวะสีเข้มเหมือนน้ำชา, อุจจาระสีซีด (Clay-colored stool)\n- มีอาการคันตามผิวหนัง (Pruritus), แน่นอึดอัดใต้ชายโครงขวา, เบื่ออาหาร, คลื่นไส้\n- สาเหตุ: นิ่วอุดกั้นท่อน้ำดี (Choledocholithiasis), ตับอักเสบ, เม็ดเลือดแดงแตก (Hemolysis), หรือเนื้องอกทางเดินน้ำดี\nAction:\n- รายงานแพทย์ทราบค่าผลแล็บและประเมินภาวะการติดเชื้อในท่อน้ำดี (Cholangitis: ไข้ หนาวสั่น ปวดท้อง ดีซ่าน)\n- ให้การพยาบาลตามแผนการรักษา:\n  * กรณีสงสัยท่อน้ำดีอุดกั้น: งดน้ำงดอาหาร (NPO) ส่งตรวจ Ultrasound หรือเตรียมตรวจส่องกล้อง ERCP\n  * ให้สารน้ำทางหลอดเลือดดำและยาปฏิชีวนะตามแผนการรักษา\n  * ให้ยาแก้คัน (Antihistamines / Cholestyramine) ตามคำสั่งแพทย์\n- ดูแลสุขอนามัยของผิวหนัง: เช็ดตัวด้วยน้ำสะอาด หลีกเลี่ยงน้ำอุ่นจัด ทาโลชั่นให้ความชุ่มชื้น ตัดเล็บสั้นเพื่อป้องกันแผลติดเชื้อจากการเกา\n- สังเกตและบันทึกสีของอุจจาระและปัสสาวะทุกครั้ง\nResponse:\n- ผู้ป่วยมีอาการคันผิวหนังลดลง ไม่มีไข้หนาวสั่นหรือปวดท้องรุนแรง\n- ตัวเหลืองตาเหลืองค่อยๆ จางลง สีปัสสาวะจางลง\n- ผลตรวจติดตามระดับ Bilirubin ในเลือดลดลงอย่างต่อเนื่อง"},{"shortcut":".hepatitis","title":"ภาวะตับอักเสบเฉียบพลัน / เอนไซม์ตับสูงรุนแรง (Acute Liver Injury / Transaminitis)","content":"Focus: ภาวะตับอักเสบเฉียบพลันและเอนไซม์ตับสูงรุนแรง (Acute Liver Injury / Transaminitis)\nGoal: ระดับเอนไซม์ตับ (AST/ALT) ลดลง เซลล์ตับได้รับการฟื้นฟู ไม่มีภาวะเลือดออกผิดปกติ และไม่มีภาวะตับวายเฉียบพลัน\nData:\n- ผลเอนไซม์ตับ: AST (SGOT) ... U/L, ALT (SGPT) ... U/L (สูงกว่าค่าปกติหลายเท่าตัว หรือ \u003e 500 - 1,000 U/L), ALP ... U/L\n- ผู้ป่วยมีอาการอ่อนเพลียอย่างมาก เบื่ออาหาร คลื่นไส้ อาเจียน แน่นอึดอัดบริเวณใต้ชายโครงขวา ปัสสาวะสีเข้ม\n- ประเมินประวัติการใช้ยา สมุนไพร แอลกอฮอล์ หรือการติดเชื้อไวรัสตับอักเสบ\n- เฝ้าระวังภาวะตับวายเฉียบพลัน (Hepatic Failure): สับสน ซึม พูดจาวกวน มือสั่น Flapping tremor (Asterixis)\nAction:\n- รายงานแพทย์ทันที และหยุดยาทุกชนิดที่มีผลต่อตับ (Hepatotoxic drugs เช่น Paracetamol, ยาต้านวัณโรค, ยากันชัก)\n- ให้การรักษาตามแผน:\n  * กรณีได้รับ Paracetamol เกินขนาด: ให้ N-acetylcysteine (NAC) ทางหลอดเลือดดำตาม Protocol\n  * ให้น้ำเกลือสารน้ำทดแทนทางหลอดเลือดดำอย่างเพียงพอ\n  * แนะนำผู้ป่วยนอนพักผ่อนอย่างเต็มที่ (Bed rest) เพื่อเพิ่มเลือดไปเลี้ยงตับ\n- ตรวจสอบค่าการแข็งตัวของเลือด (PT/INR) เสมอ (PT เป็นตัวบ่งชี้การสังเคราะห์โปรตีนของตับที่สำคัญที่สุด)\n- บันทึกสัญญาณชีพและตรวจประเมินระดับความรู้สึกตัว (Neuro signs / GCS) ทุก 4 ชม. เฝ้าระวัง Hepatic Encephalopathy\n- แนะนำอาหารคาร์โบไฮเดรตสูง ย่อยง่าย ลดอาหารไขมันสูง\nResponse:\n- ผู้ป่วยรู้สึกตัวดี ไม่มีอาการสับสน มือไม่สั่น (No flapping tremor)\n- อาการคลื่นไส้ แน่นชายโครงขวาลดลง รับประทานอาหารได้ดีขึ้น\n- ผลตรวจติดตามค่า AST, ALT และ PT/INR มีแนวโน้มลดลงสู่เกณฑ์ปลอดภัย"},{"shortcut":".hypogly","title":"ภาวะน้ำตาลในเลือดต่ำวิกฤต (Severe Hypoglycemia, DTX \u003c 70 mg/dL)","content":"Focus: ภาวะน้ำตาลในเลือดต่ำวิกฤต (Severe Hypoglycemia, DTX/Blood Glucose \u003c 70 mg/dL)\nGoal: ระดับน้ำตาลในเลือด DTX กลับสู่เกณฑ์ปกติ (≥ 100 mg/dL) อาการใจสั่น มือสั่น เหงื่อแตก ซึมทุเลาลง และผู้ป่วยปลอดภัย\nData:\n- ผลตรวจระดับน้ำตาลปลายนิ้ว (DTX) ล่าสุด ... mg/dL (ค่าวิกฤต \u003c 50-70 mg/dL)\n- อาการแสดงจากระบบประสาทอัตโนมัติ: ใจสั่น เหงื่อแตก ตัวเย็น มือสั่น กระสับกระส่าย รู้สึกหิวมาก หน้าซีด ชีพจรเต้นเร็ว\n- อาการแสดงจากสมองขาดน้ำตาล (Neuroglycopenic): ปวดศีรษะ เวียนศีรษะ มึนงง สับสน เดินเซ พูดไม่ชัด ซึมลง ชักเกร็ง หรือหมดสติ\nAction:\n- ให้การช่วยเหลือทันทีตาม Rule of 15 / Hypoglycemia Protocol:\n  * **กรณีผู้ป่วยรู้สึกตัวดีและกลืนได้:** ให้รับประทานคาร์โบไฮเดรตเชิงเดี่ยว 15 กรัมทันที (เช่น น้ำส้ม 1 กล่อง / น้ำหวาน 1 แก้ว หรือลูกอม 3-4 เม็ด)\n  * **กรณีผู้ป่วยซึม หมดสติ ชัก หรือ NPO:** ให้ 50% Glucose 25 - 50 ml (1-2 หลอด) ทางหลอดเลือดดำทันที (IV Push ช้าๆ)\n  * หากไม่มีเส้นเลือดดำ ให้ฉีด Glucagon 1 mg เข้ากล้ามเนื้อ (IM) ตามแผนแพทย์\n- ตรวจวัดระดับน้ำตาลในเลือดซ้ำ (Re-check DTX) หลังให้การรักษาครบ 15 นาที\n  * หาก DTX ยัง \u003c 70 mg/dL ให้ซ้ำตามขั้นตอนเดิมอีกครั้ง\n  * หาก DTX ≥ 70 mg/dL ให้ผู้ป่วยรับประทานอาหารมื้อหลักหรืออาหารว่าง (เช่น ขนมปัง นม) เพื่อรักษาระดับน้ำตาลให้คงที่\n- หาสาเหตุ: รับประทานอาหารน้อยกว่าปกติ ออกกำลังกายหักโหม หรือได้รับยาเบาหวาน/อินซูลินเกินขนาด\nResponse:\n- ผู้ป่วยรู้สึกตัวตื่นดี อาการใจสั่น เหงื่อแตก และมือสั่นหายไป\n- สัญญาณชีพคงที่ ไม่มีอาการชักเกร็ง\n- ผลตรวจ DTX ซ้ำหลังการรักษา 15 นาที ได้ ... mg/dL (เป้าหมาย \u003e 80-100 mg/dL)"},{"shortcut":".hypergly","title":"ภาวะน้ำตาลในเลือดสูงวิกฤต (Severe Hyperglycemia / DKA / HHS, DTX \u003e 300 - 500 mg/dL)","content":"Focus: ภาวะน้ำตาลในเลือดสูงวิกฤต (Severe Hyperglycemia / DKA / HHS, DTX \u003e 300 - 500 mg/dL)\nGoal: ระดับน้ำตาลในเลือด DTX ค่อยๆ ลดลงสู่เกณฑ์เป้าหมาย ป้องกันภาวะเลือดเป็นกรด DKA / HHS และภาวะขาดน้ำได้รับการแก้ไข\nData:\n- ผลตรวจระดับน้ำตาลในเลือด: DTX ... mg/dL (ค่าสูงเกินเกณฑ์หรืออ่านค่า Hi \u003e 500 mg/dL)\n- อาการแสดง: กระหายน้ำมาก ปัสสาวะบ่อย ปริมาณมาก ผิวหนังและเยื่อบุแห้ง ตาโหล อ่อนเพลีย น้ำหนักลด\n- อาการภาวะ DKA: หายใจหอบลึกเร็ว (Kussmaul breathing) ลมหายใจมีกลิ่นผลไม้ (Fruity breath / Acetone odor) ปวดท้อง คลื่นไส้อาเจียน ซึมลง\n- ผลตรวจปัสสาวะ: ตรวจพบ Urine Ketone และ Urine Sugar ให้ผลบวก\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเร็ว), หายใจเร็ว, อุณหภูมิกาย ... °C\nAction:\n- รายงานแพทย์ทันที และปฏิบัติตาม DKA/HHS Protocol:\n  * ให้สารน้ำชดเชยภาวะขาดน้ำ: ให้ 0.9% NSS 1,000 ml IV drip ใน 1 ชม. แรก และปรับอัตราตามแผนการรักษาอย่างเคร่งครัด\n  * ให้ยาอินซูลินลดน้ำตาล: Regular Insulin (RI) 100 units in 0.9% NSS 100 ml (1:1) IV drip ผ่าน Infusion pump ตามอัตราที่แพทย์สั่ง (เป้าหมายลดน้ำตาล 50-75 mg/dL/hr)\n  * ตรวจติดตาม DTX ทุก 1 ชม. เพื่อปรับขนาดยาอินซูลิน\n  * ส่งตรวจเลือดประเมิน Electrolytes, ABG, BUN, Cr และ Serum Ketone\n  * **ข้อควรระวังสำคัญ:** ตรวจระดับ Serum K+ เสมอ หาก K \u003c 3.3 mEq/L ให้ระงับอินซูลินชั่วคราวและเติม K+ ก่อน เพื่อป้องกัน Hypokalemic cardiac arrest\n- บันทึกสัญญาณชีพและปริมาณน้ำเข้า-ออก (I/O) ทุก 1-2 ชม.\nResponse:\n- ระดับน้ำตาลในเลือดค่อยๆ ลดลงอย่างคงที่ตามเป้าหมาย (ลดลง 50-75 mg/dL/hr) ไม่เกิดภาวะน้ำตาลตกเฉียบพลัน\n- ผู้ป่วยรู้สึกตัวดีขึ้น ริมฝีปากชุ่มชื้นขึ้น อาการหายใจหอบเหนื่อยลดลง\n- สัญญาณชีพคงที่ ปัสสาวะออกดี (\u003e 0.5-1 ml/kg/hr) ผลตรวจกรดด่างและเกลือแร่ปรับตัวดีขึ้น"}]},{"category":"16. การพยาบาลผู้ป่วยระยะสุดท้ายและการดูแลแบบประคับประคอง (Palliative \u0026 End-of-Life Care)","items":[{"shortcut":".palliative","title":"การดูแลแบบประคับประคองระยะสุดท้าย (Palliative \u0026 Comfort Care)","content":"Focus: การดูแลแบบประคับประคองเพื่อความสุขสบายและลดความทุกข์ทรมาน (Palliative Comfort Care)\nGoal: ผู้ป่วยได้รับการดูแลเพื่อความสุขสบายสูงสุด (Maximum Comfort) บรรเทาอาการทุกข์ทรมานทั้งทางกาย จิตใจ สังคม และจิตวิญญาณ\nData: ผู้ป่วยระยะท้าย (Terminal stage/End-stage disease), อ่อนเพลียมาก รับประทานอาหารและยาทางปากได้ลดลง/ไม่ได้, มีอาการไม่สุขสบาย/หายใจเหนื่อย/ปวด, ผู้ป่วยและครอบครัวมีความวิตกกังวล, สัญญาณชีพ: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\nAction:\n- ให้การพยาบาลโดยยึดหลักความสุขสบายของผู้ป่วยเป็นศูนย์กลาง (Comfort-oriented care)\n- จัดท่านอนศีรษะสูง 30-45 องศา หรือนอนตะแคงเพื่อช่วยให้หายใจโล่งขึ้น\n- ดูแลสุขอนามัยในช่องปาก (Oral care) ใช้สำลีชุบน้ำสะอาดแตะริมฝีปากและทาลิปมันบำรุงริมฝีปากไม่ให้แห้งแตก\n- ดูแลให้ยาบรรเทาปวดและยาระงับอาการไม่สุขสบายตามแผนการรักษาแบบประคับประคอง\n- สื่อสารด้วยความเคารพ อ่อนโยน และเปิดโอกาสให้สมาชิกในครอบครัวได้อยู่เคียงข้าง ได้พูดคุย สัมผัส และมีส่วนร่วมในการดูแล\n- ประสานงานทีมประคับประคอง (Palliative Care Team) และอำนวยความสะดวกในการประกอบพิธีกรรมทางศาสนาตามความเชื่อของผู้ป่วย\nResponse: ผู้ป่วยนอนหลับพักได้ สีหน้าผ่อนคลาย ไม่มีอาการทุรนทุรายหรือกระสับกระส่าย, ครอบครัวเข้าใจแนวทางการดูแล มีความสงบทางจิตใจและมีความพึงพอใจต่อการดูแล"},{"shortcut":".terminalpain","title":"การจัดการความปวดระยะสุดท้าย (Terminal Pain Management)","content":"Focus: จัดการความปวดรุนแรงในผู้ป่วยระยะสุดท้าย (Terminal Pain / Palliative Pain)\nGoal: ผู้ป่วยได้รับการระงับความปวดอย่างมีประสิทธิภาพและต่อเนื่อง สีหน้าผ่อนคลาย พักผ่อนได้สงบ และไม่มีอาการทุรนทุราย\nData: ผู้ป่วยบ่นปวด/แสดงสีหน้าเจ็บปวด คิ้วขมวด ร้องคราง หายใจเกร็ง ดิ้นกระสับกระส่าย, ประเมินระดับความปวด Pain score = .../10 (หรือ PAINAD / BPS = ... คะแนน), สัญญาณชีพ: BP.../... mmHg, PR... /min\nAction:\n- ประเมินอาการปวดอย่างสม่ำเสมอทั้งทางภาษาพูดและภาษากาย\n- ดูแลให้ยาแก้ปวดกลุ่ม Opioids (Morphine / Fentanyl) ทางหลอดเลือดดำ/แผ่นแปะ/ใต้ลิ้น ตามแผนการรักษาของแพทย์อย่างตรงเวลาสม่ำเสมอ (Around-the-clock)\n- ให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough pain dose) ทันทีเมื่อมีอาการปวดกำเริบ\n- เฝ้าระวังผลข้างเคียงของยา (อาการง่วงซึม คลื่นไส้ ท้องผูก)\n- จัดท่านอนในท่าที่ผ่อนคลาย หนุนหมอนรองรับบริเวณที่ปวด\n- ดูแลสิ่งแวดล้อมให้เงียบสงบ เปิดเพลงเบาๆ ช่วยผ่อนคลาย\nResponse: อาการปวดทุเลาลง ระดับความปวดลดลงเหลือ \u003c 3/10 (PAINAD/BPS ลดลง), สีหน้าผ่อนคลาย คลายเกร็ง สามารถนอนหลับพักผ่อนได้อย่างสงบ"},{"shortcut":".deathrattle","title":"ภาวะหายใจมีเสียงครืดคราดระยะใกล้เสียชีวิต (Death Rattle / Terminal Secretions)","content":"Focus: หายใจมีเสียงครืดคราดจากเสมหะคั่งค้างในทางเดินหายใจส่วนบน (Death Rattle)\nGoal: เสียงครืดคราดในลำคอลดลง ทางเดินหายใจส่วนบนโล่งขึ้น ผู้ป่วยหายใจได้อย่างสงบ และครอบครัวคลายความตื่นตระหนก\nData: ผู้ป่วยระยะใกล้เสียชีวิต (Actively dying) หายใจมีเสียงดังครืดคราดในลำคอ (Terminal respiratory secretions) จากกล้ามเนื้อกลืนและไออ่อนแรง, ญาติแสดงความตกใจและกังวลว่าผู้ป่วยจะสำลักหรือทรมาน\nAction:\n- จัดท่านอนตะแคงกึ่งคว่ำหรือยกศีรษะสูงเล็กน้อย เพื่อให้สารคัดหลั่งและน้ำลายไหลระบายออกทางมุมปากได้ตามแรงโน้มถ่วง\n- หลีกเลี่ยงการดูดเสมหะลึกเพราะจะกระตุ้นให้ผู้ป่วยระคายเคือง ไอกระสับกระส่าย และทรมานยิ่งขึ้น ใช้ผ้าสะอาดชุบน้ำเช็ดทำความสะอาดช่องปากและมุมปากอย่างนุ่มนวล\n- ดูแลให้ยาต้านสารคัดหลั่ง (Anticholinergics เช่น Buscopan / Atropine / Scopolamine) ตามแผนการรักษาของแพทย์เพื่อลดการสร้างสารคัดหลั่งใหม่\n- อธิบายให้ครอบครัวเข้าใจด้วยความนุ่มนวลว่าเสียงนี้เกิดจากการระบายน้ำลายตามธรรมชาติและผู้ป่วยไม่ได้รู้สึกเจ็บปวดหรือทรมาน\nResponse: เสียงหายใจครืดคราดลดลง ไม่มีสารคัดหลั่งไหลย้อนสำลัก, ญาติคลายความวิตกกังวลและเข้าใจสภาวะตามธรรมชาติของผู้ป่วย"},{"shortcut":".terminaldyspnea","title":"ภาวะหายใจลำบากและหิวอากาศระยะสุดท้าย (Terminal Dyspnea \u0026 Air Hunger)","content":"Focus: ภาวะหายใจลำบากและหิวอากาศในผู้ป่วยระยะสุดท้าย (Terminal Dyspnea \u0026 Air Hunger)\nGoal: อาการหอบเหนื่อยและหิวอากาศทุเลาลง ผู้ป่วยหายใจผ่อนคลายและสุขสบายขึ้น ไม่ทุรนทุราย\nData: ผู้ป่วยมีอาการหายใจหอบเหนื่อย อ้าปากหายใจ ใช้กล้ามเนื้อหน้าอกและคอช่วยหายใจ (Accessory muscle use), มีอาการหิวอากาศ (Air hunger), หายใจเร็ว RR... /min, SpO2... %\nAction:\n- จัดท่านอนศีรษะสูง 45-60 องศา (High-Fowler\u0027s position) เพื่อให้กระบังลมหย่อนตัวขยายปอดได้ดีขึ้น\n- ใช้พัดลมตั้งโต๊ะเปิดเป่าลมเย็นเบาๆ ผ่านบริเวณใบหน้าและจมูกผู้ป่วย (Facial cooling fan) เพื่อกระตุ้น Trigeminal nerve ช่วยลดความรู้สึกหอบเหนื่อย\n- ให้ออกซิเจน Cannula อัตราต่ำ 2-3 LPM เพื่อเพิ่มความสุขสบาย\n- ดูแลให้ยา Morphine ขนาดต่ำทางหลอดเลือดดำ/ใต้ลิ้นตามคำสั่งแพทย์ เพื่อลดความไวของศูนย์ควบคุมการหายใจและคลายความวิตกกังวล\n- พูดคุยปลอบประโลม จับมือให้ความมั่นใจแก่ผู้ป่วย\nResponse: ผู้ป่วยหายใจช้าลงและลึกขึ้น อาการหอบเกร็งและหิวอากาศทุเลาลง, อัตราการหายใจลดลงเหลือ RR... /min, สีหน้าสงบขึ้น สามารถนอนพักได้"},{"shortcut":".deliriumpalliative","title":"ภาวะเพ้อสับสนกระสับกระส่ายระยะสุดท้าย (Terminal Agitation \u0026 Delirium)","content":"Focus: ภาวะกระสับกระส่าย สับสน และเพ้อในผู้ป่วยระยะสุดท้าย (Terminal Restlessness \u0026 Delirium)\nGoal: ผู้ป่วยสงบลง อาการกระสับกระส่ายและสับสนลดลง ปลอดภัยจากอุบัติเหตุ และครอบครัวได้รับการประคับประคองจิตใจ\nData: ผู้ป่วยมีอาการกระสับกระส่าย ดึงสายน้ำเกลือ/อุปกรณ์ พยายามลุกจากเตียง พูดจาเพ้อสับสน ไม่รับรู้วันเวลาสถานที่ (Disoriented), สีหน้าหวาดกลัวหรือวิตกกังวล\nAction:\n- ตรวจประเมินค้นหาสาเหตุทางกายที่แก้ไขได้ (เช่น ภาวะปัสสาวะคั่ง, ท้องผูกแน่นท้อง, ปวดรุนแรง, หรือขาดออกซิเจน)\n- ปรับสิ่งแวดล้อมให้เงียบสงบ ลดแสงไฟจ้าและเสียงดังรบกวน\n- ให้ญาติที่คุ้นเคยคอยอยู่ดูแลเคียงข้างและพูดคุยบอกความจริงอย่างนุ่มนวล\n- ดูแลให้ยา Haloperidol หรือ Midazolam ตามแผนการรักษาของแพทย์เพื่อระงับความทรมาน (Palliative sedation for refractory distress)\n- ป้องกันอุบัติเหตุตกเตียงโดยยกไม้กั้นเตียงและบุผ้านวมกันกระแทก หลีกเลี่ยงการผูกมัดร่างกาย\nResponse: ผู้ป่วยสงบลง หายตื่นกลัว สามารถนอนหลับพักผ่อนได้อย่างปลอดภัย ไม่เกิดอุบัติเหตุพลัดตกหกล้ม"},{"shortcut":".postmortem","title":"การดูแลผู้ป่วยและครอบครัวหลังเสียชีวิต (Post-Mortem Care \u0026 Bereavement)","content":"Focus: การพยาบาลดูแลร่างผู้เสียชีวิตและการประคับประคองจิตใจครอบครัว (Post-Mortem Care)\nGoal: การดูแลร่างผู้เสียชีวิตเป็นไปด้วยความเคารพ สมเกียรติ ปฏิบัติถูกต้องตามแนวทาง และครอบครัวได้รับการดูแลด้านจิตใจอย่างอบอุ่น\nData: แพทย์ตรวจวินิจฉัยและลงบันทึกผู้ป่วยถึงแก่กรรมเวลา... น., สัญญาณชีพหยุดเต้น ไม่มีชีพจร ไม่มีเสียงหายใจ ม่านตาขยายทั้งสองข้างไม่ตอบสนองต่อแสง\nAction:\n- ปิดม่านรอบเตียงเพื่อความเป็นส่วนตัว\n- ปลดอุปกรณ์การแพทย์และสายระบายต่างๆ ออกอย่างนุ่มนวล (ยกเว้นกรณีชันสูตรพลิกศพ)\n- ทำความสะอาดร่างกายผู้เสียชีวิต จัดท่านอนหงาย หนุนหมอน 1 ใบใต้ศีรษะเพื่อป้องกันเลือดคั่งที่ใบหน้า\n- ปิดตาและหุบปาก\n- สวมเสื้อผ้าสะอาดและห่อร่างตามแนวปฏิบัติของโรงพยาบาล\n- ผูกป้ายระบุตัวตน (Mortuary tag) ที่ข้อมือและข้อเท้า\n- ให้เวลาครอบครัวได้อยู่ร่วมอำลาและประกอบพิธีกรรมทางศาสนา\n- กล่าวแสดงความเสียใจและประคับประคองด้านจิตใจ\n- แนะนำขั้นตอนการติดต่อรับศพและเอกสารใบมรณบัตร\nResponse: การทำความสะอาดและจัดเตรียมร่างผู้เสียชีวิตเรียบร้อย สมเกียรติ, ญาติได้รับข้อมูลขั้นตอนการติดต่อและเอกสารครบถ้วน ครอบครัวมีความซาบซึ้งต่อการดูแล"}]},{"category":"17. การพยาบาลระบบประสาทและสมอง (Neurological \u0026 Neurosurgical Nursing)","items":[{"shortcut":".icp","title":"ภาวะความดันในกะโหลกศีรษะสูง (Increased Intracranial Pressure - IICP)","content":"Focus: เสี่ยงต่อภาวะความดันในกะโหลกศีรษะสูงและสมองเคลื่อน (Increased ICP / Brain Herniation)\nGoal: ป้องกันและลดความดันในกะโหลกศีรษะ ระดับความรู้สึกตัวคงที่ สัญญาณชีพคงที่ รูม่านตาตอบสนองต่อแสงดี และไม่เกิดภาวะสมองเคลื่อน (Herniation)\nData: ผู้ป่วยมีอาการปวดศีรษะรุนแรง อาเจียนพุ่ง (Projectile vomiting), ซึมลง GCS ลดลง... คะแนน, รูม่านตาขยายไม่เท่ากัน (Pupils unequal / sluggish), สัญญาณชีพพบ Cushing\u0027s triad (ความดันโลหิตสูงขึ้นโดยเฉพาะ Systolic, ชีพจรเต้นช้า Bradycardia, หายใจผิดปกติ)\nAction:\n- จัดท่านอนศีรษะสูง 30 องศา คอตรงในแนวระนาบ (Neutral alignment) ห้ามพับงอคอหรือบิดเอียงเพื่อช่วยการระบายเลือดดำจากสมอง\n- ดูแลให้ยาลดบวมสมอง (Mannitol 20% หรือ 3% NaCl) หยดทางหลอดเลือดดำตามแผนการรักษาอย่างเคร่งครัด\n- หลีกเลี่ยงกิจกรรมที่เพิ่มความดันในกะโหลกศีรษะ (ห้ามดูดเสมหะนานเกิน 10-15 วินาที, ระวังอย่าให้ผู้ป่วยไอ จาม หรือเบ่งอุจจาระ)\n- ให้ออกซิเจนควบคุม PaCO2 35-40 mmHg\n- ตรวจประเมิน Neuro sign และ GCS ทุก 1 ชั่วโมง\n- รายงานแพทย์ทันทีเมื่อพบความผิดปกติ\nResponse: ระดับความรู้สึกตัวคงที่ GCS... คะแนน, รูม่านตาขนาด... mm ตอบสนองต่อแสงดีทั้ง 2 ข้าง, ไม่มีอาการอาเจียนพุ่ง สัญญาณชีพคงที่"},{"shortcut":".seizure","title":"การพยาบาลขณะชักและหลังชัก (Seizure Care \u0026 Status Epilepticus)","content":"Focus: ป้องกันอันตรายและภาวะขาดออกซิเจนขณะและหลังมีอาการชักเกร็ง (Active Seizure Management)\nGoal: ผู้ป่วยปลอดภัยขณะชัก ทางเดินหายใจโล่ง ไม่เกิดการสำลักหรือบาดเจ็บ อาการชักสงบลง และฟื้นตัวหลังชักได้ดี\nData: ผู้ป่วยมีอาการชักเกร็ง/กระตุก (Tonic-clonic seizure), กัดฟัน ตาค้าง น้ำลายฟูมปาก, ไม่รู้สึกตัว, ระยะเวลาชักนาน... นาที\nAction: \n- ขณะชัก: ป้องกันอันตรายโดยเคลียร์สิ่งของรอบตัว จัดท่านอนตะแคงหน้าเพื่อป้องกันการสำลักน้ำลาย ห้ามผูกมัดผู้ป่วย และห้ามนำสิ่งของใดๆ งัดหรือใส่ในปากเด็ดขาด, ให้ออกซิเจน Mask with bag / Cannula, ดูแลให้ยากันชักฉุกเฉิน (Diazepam / Midazolam / Keppra / Dilantin) ทางหลอดเลือดดำตามคำสั่งแพทย์, สังเกตและจับเวลาลักษณะการชัก\n- หลังชัก (Post-ictal): ดูดเสมหะในช่องปากอย่างนุ่มนวล, ตรวจวัดสัญญาณชีพ, เจาะ DTX ตรวจหาน้ำตาลต่ำ, ประเมิน GCS และ Neuro sign\nResponse: อาการชักหยุดลงเวลา... น. รวมเวลาชัก... นาที, ทางเดินหายใจโล่ง SpO2 = ... %, หลังชักผู้ป่วยค่อยๆ รู้สึกตัวตื่น ไม่พบการบาดเจ็บของร่างกาย"},{"shortcut":".gcsdrop","title":"ภาวะการเปลี่ยนแปลงระดับความรู้สึกตัว (Altered Level of Consciousness / GCS Drop)","content":"Focus: ระดับความรู้สึกตัวลดลงเฉียบพลัน เสี่ยงต่อภาวะสมองขาดเลือดหรือมีพยาธิสภาพลุกลาม\nGoal: ตรวจพบและรายงานสาเหตุของการเปลี่ยนแปลงระดับความรู้สึกตัวได้อย่างรวดเร็ว ได้รับการแก้ไขทันท่วงที และป้องกันเนื้อสมองขาดออกซิเจน\nData: ผู้ป่วยมีอาการซึมลง ไม่ตอบสนองต่อเสียงเรียกเหมือนเดิม, ค่า GCS ลดลงจากเดิม \u003e 2 คะแนน (E... V... M...), รูม่านตา...\nAction:\n- รายงานแพทย์ทันที\n- ตรวจวัดสัญญาณชีพฉุกเฉินและเจาะตรวจ DTX ทันทีเพื่อแยกภาวะ Hypoglycemia\n- จัดท่านอนศีรษะสูง 30 องศา\n- ดูแลทางเดินหายใจให้โล่ง ให้ออกซิเจนเสริม\n- ตรวจประเมิน Motor power แขนขาทั้ง 4 ข้าง\n- เตรียมความพร้อมส่งตรวจเอกซเรย์คอมพิวเตอร์สมอง (CT Brain Urgent) ตามคำสั่งแพทย์\nResponse: แพทย์ตรวจประเมินผู้ป่วย, DTX = ... mg/dL, ส่งทำ CT Brain เวลา... น. ปลอดภัยดี ไม่เกิดภาวะทางเดินหายใจอุดกั้น"},{"shortcut":".tbi","title":"การบาดเจ็บที่ศีรษะและสมอง (Traumatic Brain Injury / Head Injury)","content":"Focus: เสี่ยงต่อภาวะแทรกซ้อนจากการบาดเจ็บที่กะโหลกศีรษะและเนื้อสมอง (Traumatic Brain Injury Care)\nGoal: สัญญาณทางระบบประสาทคงที่หรือดีขึ้น ป้องกันการบาดเจ็บซ้ำของเนื้อสมอง (Secondary Brain Injury) และไม่พบสัญญาณ CSF leak\nData: ผู้ป่วยได้รับอุบัติเหตุกระทบกระแทกที่ศีรษะ, มีแผลแตก/บวมโนบริเวณ..., มีอาการปวดศีรษะ คลื่นไส้ จำเหตุการณ์ไม่ได้ (Amnesia), GCS = ... คะแนน\nAction:\n- ตรวจประเมินและบันทึก Neuro sign, GCS, และ Pupil ทุก 1 ชั่วโมง\n- สังเกตสัญญาณน้ำไขสันหลังรั่ว (CSF Leakage) เช่น มีน้ำใสหรือเลือดปนน้ำใสออกจากจมูก (Rhinorrhea) หรือหู (Otorrhea) ตรวจ Halo sign\n- สังเกต Battle\u0027s sign (รอยช้ำหลังหู) และ Raccoon eyes\n- จัดท่านอนศีรษะสูง 30 องศา\n- ดูแลให้ยาแก้ปวดที่ไม่มีผลกดประสาทตามคำสั่งแพทย์\nResponse: GCS คงที่... คะแนน, รูม่านตาตอบสนองต่อแสงดี, ไม่พบ CSF leakage หรืออาการชักเกร็ง"},{"shortcut":".sci","title":"การบาดเจ็บกระดูกสันหลังและไขสันหลัง (Spinal Cord Injury / Neuro Care)","content":"Focus: ป้องกันการบาดเจ็บของไขสันหลังเพิ่มขึ้นและเฝ้าระวัง Neurogenic / Spinal Shock\nGoal: ป้องกันการบาดเจ็บของไขสันหลังเพิ่มขึ้น สัญญาณชีพคงที่ ป้องกันภาวะช็อกทางระบบประสาท และป้องกันแผลกดทับ\nData: ผู้ป่วยมีภาวะกระดูกสันหลังหัก/บาดเจ็บไขสันหลัง (Spinal cord injury ระดับ...), แขนขาอ่อนแรง ขยับไม่ได้ ชาตั้งแต่ระดับ... ลงไป (Sensory level), ปัสสาวะ/อุจจาระไม่ออก\nAction:\n- ดามคอด้วย Hard collar ตลอดเวลา\n- จัดท่าและพลิกตัวแบบท่อนซุง (Log rolling) โดยมีผู้ช่วยอย่างน้อย 3-4 คน เพื่อให้แนวกระดูกสันหลังตรงตลอดเวลา\n- ตรวจวัดสัญญาณชีพเฝ้าระวังภาวะ Neurogenic shock (BP ต่ำร่วมกับชีพจรช้า)\n- สังเกตอาการ Autonomic dysreflexia (เหงื่อแตก ความดันสูง ปวดศีรษะรุนแรง)\n- ใส่สายสวนปัสสาวะและดูแลการขับถ่าย\n- ดูแลใส่ถุงน่องลมหรือ TED hose ป้องกัน DVT\nResponse: ผู้ป่วยได้รับการพลิกตัวแบบ Log roll ถูกต้อง, สัญญาณชีพคงที่ BP.../... mmHg, PR... /min, Sensory level คงที่ ไม่พบลำดับการบาดเจ็บเลื่อนสูงขึ้น"},{"shortcut":".delirium","title":"ภาวะสับสนเฉียบพลันในหอผู้ป่วย (Hospital / Ward Delirium Management)","content":"Focus: ภาวะสับสนเฉียบพลัน ขาดสมาธิ และอารมณ์แปรปรวน (Acute Delirium in Ward)\nGoal: ผู้ป่วยกลับมารู้จักบุคคล เวลา สถานที่ (Reoriented) อาการสับสนกระสับกระส่ายลดลง วงจรการหลับ-ตื่นปกติ และปลอดภัย\nData: ผู้ป่วยมีอาการสับสนเฉียบพลัน (CAM positive), หวาดระแวง เอะอะโวยวาย เห็นภาพหลอน (Hallucination), ดึงสายน้ำเกลือและพยายามก้าวลงจากเตียง, สมาธิสั้น พฤติกรรมแปรปรวนสลับไปมาระหว่างวัน\nAction:\n- ประเมินค้นหาสาเหตุทางกาย (Infection, Hypoxia, Electrolyte imbalance, Urinary retention, Pain)\n- จัดสิ่งแวดล้อมให้ปลอดภัย มีนาฬิกาและปฏิทินในห้อง เปิดม่านให้แสงสว่างเวลากลางวันและปิดไฟหรี่เวลากลางคืนเพื่อคงวงจรหลับ-ตื่น (Circadian rhythm)\n- พูดคุยบอกวัน เวลา สถานที่ซ้ำๆ (Reorientation)\n- กระตุ้นให้ญาติที่คุ้นเคยอยู่ดูแล\n- หลีกเลี่ยงการผูกมัดผู้ป่วย (Physical restraint) โดยไม่จำเป็น\n- จัดยาตามแผนการรักษา\nResponse: ผู้ป่วยสงบลง สามารถนอนหลับพักผ่อนได้เวลากลางคืน, ไม่เกิดอุบัติเหตุพลัดตกหกล้ม สายน้ำเกลือไม่เลื่อนหลุด"}]},{"category":"18. การพยาบาลผู้ป่วยใส่เครื่องช่วยหายใจและดูแลทางเดินหายใจ (Ventilator \u0026 Airway Care)","items":[{"shortcut":".vent","title":"การพยาบาลผู้ป่วยใช้เครื่องช่วยหายใจ (Mechanical Ventilator \u0026 VAP Bundle)","content":"Focus: ดูแลประสิทธิภาพการระบายอากาศและป้องกันปอดอักเสบจากการใช้เครื่องช่วยหายใจ (VAP Prevention Bundle)\nGoal: ผู้ป่วยหายใจสัมพันธ์กับเครื่องช่วยหายใจ การแลกเปลี่ยนก๊าซมีประสิทธิภาพ SpO2 ≥ 95% และไม่เกิดปอดอักเสบจากการใช้เครื่องช่วยหายใจ (Zero VAP)\nData: ผู้ป่วยใส่ท่อช่วยหายใจ (ETT No... ลึก... cm ที่มุมปาก) ต่อเครื่องช่วยหายใจ Mode... , FiO2... , TV... , RR... , PEEP... , V/S: BP.../... mmHg, SpO2... %\nAction: ปฏิบัติตามแนวทาง VAP Prevention Bundle อย่างเคร่งครัด:\n1. จัดท่านอนศีรษะสูง 30-45 องศา (Semi-Fowler\u0027s position) ตลอดเวลา\n2. ทำความสะอาดช่องปากและฟัน (Oral care) ด้วย 0.12% Chlorhexidine วันละ 2-4 ครั้ง\n3. ตรวจวัดความดันลมในกระเปาะท่อช่วยหายใจ (Cuff pressure) ให้อยู่ระหว่าง 20-30 cmH2O ทุกเวรเพื่อป้องกันลมรั่วและเนื้อเยื่อขาดเลือด\n4. เทน้ำขังในสายเครื่องช่วยหายใจ (Ventilator circuit condensate) ทิ้งลงภาชนะรองรับ ห้ามเทไหลย้อนกลับ\n5. ประเมินความพร้อมในการหย่าเครื่องช่วยหายใจ (Daily sedation vacation \u0026 weaning assessment)\nResponse: ผู้ป่วยหายใจสัมพันธ์กับเครื่องช่วยหายใจดี ไม่ต้านเครื่อง (Synchronized), SpO2 = ... %, ปอดขยายตัวเท่ากันทั้ง 2 ข้าง, ไม่มีสัญญาณการติดเชื้อ VAP"},{"shortcut":".suction","title":"การดูดเสมหะผ่านท่อช่วยหายใจ (Endotracheal Suctioning Care)","content":"Focus: กำจัดเสมหะและดูแลทางเดินหายใจให้โล่ง (Ineffective Airway Clearance)\nGoal: ทางเดินหายใจโล่ง เสียงเสมหะในปอดลดลง การระบายอากาศดีขึ้น และไม่เกิดภาวะพร่องออกซิเจนขณะดูดเสมหะ\nData: ผู้ป่วยหายใจเสียงเสมหะครืดคราดในท่อช่วยหายใจ, กราฟเครื่องช่วยหายใจพบรอยหยัก (Sawtooth pattern) หรือ Peak airway pressure สูงขึ้น, SpO2 ลดลงเหลือ... %\nAction:\n- ให้ออกซิเจนเข้มข้น 100% (Hyperoxygenation) นาน 30-60 วินาทีก่อนดูดเสมหะ\n- ใช้สายดูดเสมหะขนาดเหมาะสม (ไม่เกิน 1/2 ของขนาด ETT) ด้วยเทคนิคปลอดเชื้อ (Aseptic technique / Closed suction system), สอดสายดูดเสมหะลึกพอดี ดูดเสมหะพร้อมหมุนสายขึ้นมาภายในเวลาไม่เกิน 10-15 วินาที\n- สังเกตสี ปริมาณ และลักษณะของเสมหะ\n- ให้ออกซิเจน 100% ซ้ำหลังดูดเสมหะจนค่า SpO2 กลับสู่เกณฑ์ปกติ\nResponse: ดูดเสมหะได้... ml ลักษณะเหนียว สีขาวขุ่น/เหลือง, ทางเดินหายใจโล่งขึ้น หายใจสัมพันธ์กับเครื่อง, Peak pressure ลดลงสู่เกณฑ์ปกติ, SpO2 เพิ่มขึ้นเป็น... %"},{"shortcut":".ettcare","title":"การดูแลท่อช่วยหายใจและเปลี่ยนพลาสเตอร์ (ETT Care \u0026 Tape Repositioning)","content":"Focus: ป้องกันท่อช่วยหายใจเลื่อนหลุดและป้องกันแผลกดทับที่ริมฝีปาก (ETT Dislodgement \u0026 Pressure Injury)\nGoal: ท่อช่วยหายใจอยู่ในตำแหน่งที่ถูกต้อง ไม่เลื่อนหลุด ผิวหนังรอบปากและริมฝีปากปกติ ไม่เกิดแผลกดทับ\nData: ผู้ป่วยใส่ท่อช่วยหายใจ Endotracheal tube เบอร์... ตำแหน่งเดิมอยู่ที่ขีด... cm ที่มุมปาก... , พลาสเตอร์ยึดท่อเริ่มเปียกชื้น/หลุดลอก\nAction:\n- ตรวจวัดระดับความลึกของท่อช่วยหายใจที่ขีดมุมปากก่อนทำหัตถการ\n- จับยึดท่อช่วยหายใจให้แน่นตลอดเวลาขณะแกะพลาสเตอร์เดิมออก\n- ทำความสะอาดผิวหนังรอบปากและเช็ดคราบกาว\n- ตรวจสอบสภาพผิวหนังและริมฝีปาก\n- ย้ายตำแหน่งท่อช่วยหายใจสลับไปมุมปากอีกข้างเพื่อป้องกันแผลกดทับ\n- ติดพลาสเตอร์ยึดท่อ (ETT Taping) ให้แน่นหนาและมั่นคง\n- ฟังเสียงลมเข้าปอดซ้ำทั้ง 2 ข้างว่าเท่ากัน (Equal breath sounds)\nResponse: ท่อช่วยหายใจยึดติดแน่นที่มุมปากข้าง... ขีดความลึก... cm เท่าเดิม, ฟังปอดลมเข้าเท่ากันทั้งสองข้าง ไม่มีลมรั่วรอบ Cuff"},{"shortcut":".tracheo","title":"การดูแลท่อเจาะคอและแผลเจาะคอ (Tracheostomy Tube \u0026 Stoma Care)","content":"Focus: ป้องกันการอุดกั้นของท่อเจาะคอและป้องกันการติดเชื้อรอบแผลเจาะคอ (Tracheostomy Care)\nGoal: ทางเดินหายใจโล่ง ท่อเจาะคอไม่อุดกั้น แผลรอบ Stoma สะอาด แห้งดี และไม่เกิดการติดเชื้อ\nData: ผู้ป่วยมีท่อหลอดลมคอ (Tracheostomy tube No... มี Cuff / ไม่มี Cuff), แผลรอบท่อเจาะคอมีเสมหะและสิ่งคัดหลั่งซึมเปื้อนผ้าก๊อซรองแผล\nAction:\n- ประเมินทางเดินหายใจและดูดเสมหะในท่อเจาะคอให้โล่ง\n- ถอด Inner cannula ออกมาล้างทำความสะอาดด้วย Normal Saline และต้มฆ่าเชื้อ/เปลี่ยนอันใหม่ (กรณีเป็นท่อโลหะหรือท่อถอดล้างได้)\n- ทำความสะอาดผิวหนังรอบ Stoma ด้วยเทคนิคปลอดเชื้อ\n- ปิดแผลด้วยผ้าก๊อซผ่ากึ่งกลาง (Tracheostomy gauze)\n- เปลี่ยนเชือกผูกท่อเจาะคอให้กระชับพอสอดนิ้วมือได้ 1-2 นิ้วเพื่อป้องกันการรัดแน่นหรือหลุด\nResponse: ท่อเจาะคอสะอาด ทางเดินหายใจโล่ง หายใจสะดวก, แผลรอบท่อเจาะคอแห้งสะอาด ไม่มีรอยแดงหรือหนอง, เชือกผูกท่อแน่นหนาพอดี"},{"shortcut":".wean","title":"การฝึกหย่าเครื่องช่วยหายใจ (Ventilator Weaning \u0026 Spontaneous Breathing Trial)","content":"Focus: ประเมินความพร้อมและฝึกหย่าเครื่องช่วยหายใจ (Ventilator Weaning \u0026 SBT)\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจ ทนต่อการทดสอบหายใจด้วยตนเอง (SBT) ได้สำเร็จ สัญญาณชีพคงที่ และพร้อมถอดท่อช่วยหายใจ\nData: ผู้ป่วยรู้สึกตัวดี พยาธิสภาพของปอดดีขึ้น, ค่าก๊าซในเลือด (ABG) ปกติ, ตั้งเครื่องช่วยหายใจ Mode Weaning (PSV / CPAP / T-Piece) FiO2 \u003c 0.4, PEEP \u003c 5 cmH2O\nAction:\n- อธิบายขั้นตอนการฝึกหายใจให้ผู้ป่วยเข้าใจและคลายความวิตกกังวล\n- จัดท่านอนศีรษะสูง 45-60 องศา\n- เริ่มทดสอบการหายใจด้วยตนเอง (Spontaneous Breathing Trial: SBT) เป็นเวลา 30-120 นาที\n- เฝ้าสังเกตสัญญาณเตือนที่ต้องหยุด Weaning: อัตราการหายใจ RR \u003e 35 หรือ \u003c 8 ครั้ง/นาที, SpO2 \u003c 90%, HR \u003e 140 หรือเปลี่ยนแปลง \u003e 20%, BP \u003e 180 หรือ \u003c 90 mmHg, กระสับกระส่าย เหงื่อแตก ใช้กล้ามเนื้อช่วยหายใจ\nResponse: ผู้ป่วยทนต่อการฝึกหายใจได้ดี (Tolerated SBT) นาน... นาที, อัตราการหายใจคงที่ RR... /min, SpO2... %, สัญญาณชีพคงที่ สีหน้าผ่อนคลาย พร้อมสำหรับการพิจารณาถอดท่อช่วยหายใจ"},{"shortcut":".extubate","title":"การพยาบาลหลังถอดท่อช่วยหายใจ (Post-Extubation Care \u0026 Stridor Monitoring)","content":"Focus: เฝ้าระวังภาวะทางเดินหายใจอุดกั้นและทางเดินหายใจบวมหลังถอดท่อช่วยหายใจ (Post-Extubation Stridor)\nGoal: ถอดท่อช่วยหายใจสำเร็จอย่างปลอดภัย ทางเดินหายใจเปิดโล่ง ไม่มีเสียง Stridor หายใจสะดวก และไม่ต้องใส่ท่อช่วยหายใจซ้ำ (Re-intubation)\nData: แพทย์ทำการถอดท่อช่วยหายใจ (Extubation) หลังผ่านการประเมิน Cuff leak test, ผู้ป่วยตื่นดี สามารถไอขับเสมหะได้เอง\nAction:\n- ดูดเสมหะในช่องปากและท่อช่วยหายใจให้สะอาดก่อนถอดท่อ\n- ปลดลมออกจาก Cuff และถอดท่อออกอย่างนุ่มนวลขณะผู้ป่วยหายใจเข้าลึก\n- ให้ออกซิเจน Mask with bag / Cannula ทันทีหลังถอดท่อ\n- จัดท่านอนศีรษะสูง\n- ตรวจประเมินเสียงหายใจเฝ้าระวังภาวะกล่องเสียงบวม (Laryngeal edema / Stridor)\n- สังเกตการหายใจเข้ามีเสียงหวีด (Inspiratory stridor) หรือการดึงรั้งของทรวงอก\n- แนะนำงดน้ำและอาหาร (NPO) อย่างน้อย 2-4 ชั่วโมงเพื่อประเมินความปลอดภัย\nResponse: ผู้ป่วยหายใจด้วยตนเองได้ดี ไม่มีเสียง Stridor หรือเสียงแหบ, SpO2 = ... %, ไอขับเสมหะได้ดี ไม่มีอาการเหนื่อยหอบ"}]},{"category":"19. การช่วยชีวิตและการพยาบาลผู้ป่วยวิกฤต (Critical Care \u0026 Life Support)","items":[{"shortcut":".cpr","title":"การช่วยฟื้นคืนชีพขั้นสูงและการดูแลหลังฟื้นคืนชีพ (CPR \u0026 Post-Cardiac Arrest Care / ROSC)","content":"Focus: การช่วยฟื้นคืนชีพขั้นสูงและการดูแลเพื่อฟื้นฟูหลังหัวใจกลับมาเต้น (Cardiopulmonary Resuscitation \u0026 ROSC)\nGoal: ได้รับการกู้ชีพขั้นสูงอย่างรวดเร็วและมีประสิทธิภาพ หัวใจกลับมาเต้น (ROSC) สัญญาณชีพและการไหลเวียนโลหิตฟื้นตัว และสมองได้รับออกซิเจนเพียงพอ\nData: ผู้ป่วยหมดสติ คลำชีพจร Carotid ไม่ได้ ไม่หายใจ (Cardiac Arrest) เวลา... น., EKG Monitor พบ Rhythm: ... (VF / pVT / Asystole / PEA)\nAction:\n- กดปุ่มเรียก Code Blue ฉุกเฉินทันที\n- เริ่มกดหน้าอกทันที (Quality CPR: อัตราเร็ว 100-120 ครั้ง/นาที, ลึก 5-6 ซม., ปล่อยคืนสุด ไม่หยุดกดเกิน 10 วินาที)\n- เปิดทางเดินหายใจและช่วยหายใจด้วย Ambu bag with O2 100%\n- นำ Defibrillator มาติดขั้ว Pad\n- ให้การกระตุกหัวใจด้วยไฟฟ้า (Defibrillation) ... Joules (กรณี Shockable rhythm)\n- ให้ยาช่วยชีวิตฉุกเฉิน (Adrenaline 1 mg IV ทุก 3-5 นาที, Cordarone/Amiodarone) ตาม ACLS Guidelines\n- ใส่ท่อช่วยหายใจสำเร็จ ETT No... ลึก... cm\n- คลำพบชีพจรกลับมาเต้น (ROSC) เวลา... น. รวมเวลากดหน้าอก... นาที\nResponse: ได้รับการกู้ชีพสำเร็จ (ROSC), สัญญาณชีพหลัง ROSC: BP.../... mmHg, PR... /min, SpO2... %, ดูแลให้ยา Vasoactive inotropes ทางหลอดเลือดดำเพื่อควบคุมความดันโลหิต, ติดตามผล ABG และ EKG 12 leads, เตรียมส่งต่อหอผู้ป่วยวิกฤต (ICU)"},{"shortcut":".transfusion","title":"การให้เลือดและส่วนประกอบของเลือด (Blood Transfusion \u0026 Reaction Monitoring)","content":"Focus: ป้องกันภาวะแทรกซ้อนและเฝ้าระวังปฏิกิริยาจากการได้รับเลือด (Blood Transfusion Safety)\nGoal: ได้รับเลือดและส่วนประกอบของเลือดอย่างปลอดภัย ถูกต้องตามหลัก Double Check สัญญาณชีพคงที่ และไม่เกิดปฏิกิริยาจากการให้เลือด\nData: มีแผนการรักษาให้เลือด (PRC / FFP / Platelets / Cryoprecipitate) จำนวน... ยูนิต, ค่า Hb/Hct ก่อนให้เลือด...\nAction: ปฏิบัติตามแนวทางการให้เลือดปลอดภัย (Double Check Verification):\n1. ตรวจสอบชื่อ-นามสกุล, HN, หมายเลขยูนิตเลือด, หมู่เลือด (ABO \u0026 Rh), และวันหมดอายุ ร่วมกับพยาบาลวิชาชีพคนที่สองอย่างละเอียด\n2. ตรวจวัดสัญญาณชีพก่อนเริ่มให้เลือด (Baseline V/S)\n3. ให้เลือดผ่านชุดให้เลือดที่มีตัวกรอง (Blood administration set) ด้วยอัตราช้า 2 ml/min ในช่วง 15 นาทีแรก\n4. ตรวจวัดสัญญาณชีพที่ 15 นาทีหลังเริ่มให้เลือด และทุก 30-60 นาทีจนให้เลือดหมด\n5. เฝ้าระวังอาการแพ้เลือด (Transfusion reaction): ไข้ หนาวสั่น แน่นหน้าอก หายใจลำบาก ผื่นคัน ลมพิษ ความดันโลหิตตก ปวดหลัง หากพบอาการให้หยุดให้เลือดทันทีและรายงานแพทย์\n6. ให้เลือดหมดภายในเวลาไม่เกิน 4 ชั่วโมงต่อ 1 ยูนิต\nResponse: ให้เลือดหมดเวลา... น. รวมเวลาให้... ชม., สัญญาณชีพคงที่ ไม่มีไข้ ไม่มีอาการหนาวสั่นหรือผื่นคัน ปลอดภัยดี"},{"shortcut":".cvcline","title":"การดูแลสายสวนหลอดเลือดดำส่วนกลาง (Central Venous Catheter - CVC / CLABSI Bundle)","content":"Focus: ป้องกันการติดเชื้อในกระแสเลือดจากการคาสายสวนหลอดเลือดดำส่วนกลาง (CLABSI Prevention Bundle)\nGoal: สายสวนหลอดเลือดดำส่วนกลางทำงานมีประสิทธิภาพ ให้ยาและสารน้ำได้ต่อเนื่อง แผลแห้งสะอาด และไม่เกิดการติดเชื้อ CLABSI\nData: ผู้ป่วยคาสายสวนหลอดเลือดดำส่วนกลาง (CVC / PICC / Perm cath) บริเวณ (Subclavian / Internal Jugular / Femoral) ข้าง...\nAction:\n- ตรวจประเมินตำแหน่งรอยเจาะและสภาพแผล CVC ทุกเวร\n- ทำความสะอาดผิวหนังรอบรอยเจาะด้วย 2% Chlorhexidine in 70% Alcohol ด้วยเทคนิคปลอดเชื้อ (Aseptic technique)\n- ปิดแผลด้วยแผ่นฟิล์มใสปลอดเชื้อ (Transparent dressing)\n- ขัดถูทำความสะอาดจุกเกลียว (Hub scrubbing) ด้วยแอลกอฮอล์นานอย่างน้อย 15 วินาทีก่อนให้ยาหรือต่อสายน้ำเกลือ\n- ตรวจสอบการไหลย้อนของเลือด (Blood return) และล้างสาย (Flush) ด้วย Normal Saline หลังให้ยาทุกครั้ง\n- ประเมินความจำเป็นในการคาสายทุกวันเพื่อพิจารณาถอดออกโดยเร็ว\nResponse: แผลรอบรอยเจาะสาย CVC สะอาด แห้งดี ไม่มีอาการบวมแดง ร้อน หรือมีหนอง, สายระบายเปิดโล่งดี ไม่มีเลือดคั่งค้าง"},{"shortcut":".aline","title":"การดูแลสายวัดความดันในหลอดเลือดแดง (Arterial Line \u0026 Continuous ABP Care)","content":"Focus: เฝ้าระวังการไหลเวียนโลหิตส่วนปลายและป้องกันการติดเชื้อจากการคาสายหลอดเลือดแดง (Arterial Line Care)\nGoal: คลื่นความดันโลหิตคมชัด วัดค่าต่อเนื่องได้แม่นยำ การไหลเวียนโลหิตส่วนปลายมือ/เท้าปกติ และไม่มีภาวะเลือดออกหรือการติดเชื้อ\nData: มีการคาสายสวนหลอดเลือดแดง (Arterial line) บริเวณ Radial / Femoral artery ข้าง... เพื่อติดตามความดันโลหิตแบบต่อเนื่อง (Continuous ABP Monitoring) และเจาะตรวจก๊าซในเลือด\nAction:\n- ตรวจสอบระดับตัวแปลงสัญญาณ (Transducer) ให้อยู่ระดับหัวใจ (Phlebostatic axis) และทำการ Zero calibration ทุกเวร\n- ตรวจสอบระบบ Flush bag ความดัน 300 mmHg\n- ตรวจประเมินการไหลเวียนโลหิตส่วนปลายมือ/เท้า (Capillary refill, สีผิว, ความอุ่น, ชีพจร) ทุก 1-2 ชั่วโมง\n- ตรวจสอบข้อต่อทุกจุดให้แน่นหนาป้องกันการหลุดและตกเลือดรวดเร็ว\n- เจาะเก็บเลือดตรวจ ABG ด้วยเทคนิคปลอดเชื้อ\nResponse: คลื่นสัญญาณความดัน (Arterial waveform) คมชัดดี วัดค่า BP/MAP ได้แม่นยำ, ปลายมือข้างที่ใส่สายอุ่น สีชมพู CRT \u003c 2 วินาที ไม่พบภาวะแทรกซ้อน"},{"shortcut":".chesttube","title":"การดูแลท่อระบายทรวงอก (Chest Tube \u0026 Underwater Seal Drainage Care)","content":"Focus: ดูแลประสิทธิภาพการระบายลมและของเหลวจากช่องเยื่อหุ้มปอดและเฝ้าระวังลมรั่ว (Chest Tube / ICD Care)\nGoal: ปอดขยายตัวเต็มที่ สารคัดหลั่งและลมในช่องเยื่อหุ้มปอดระบายได้มีประสิทธิภาพ ระบบขวดระบายน้ำทำงานสมบูรณ์ และไม่มีลมรั่ว\nData: ผู้ป่วยใส่ท่อระบายทรวงอก (Intercostal Drainage: ICD) ข้าง... ต่อเข้าขวดระบายน้ำระบบ Water-seal / Suction... cmH2O, มีสารคัดหลั่ง/ลมระบายออก\nAction:\n- ตรวจสอบระดับน้ำในขวด Water-seal ให้ท่วมปลายหลอดแก้ว 2 ซม.\n- สังเกตการกระเพื่อมของน้ำในหลอดแก้วสัมพันธ์กับการหายใจ (Fluctuation / Tidaling)\n- สังเกตฟองอากาศปุดในขวด (Air leak)\n- วางขวดระบายให้อยู่ต่ำกว่าระดับทรวงอกผู้ป่วยเสมอ (อย่างน้อย 2-3 ฟุต) และตั้งตรงไม่ล้ม\n- ตรวจสอบสายยางไม่หักพับงอ ไม่ดึงรั้ง และห้ามบีบรูดสาย (Stripping) โดยไม่จำเป็น\n- ตรวจสอบรอยต่อทุกจุดให้แนบสนิท\n- ทำแผลรอบท่อระบายด้วยเทคนิคปลอดเชื้อ\nResponse: ระดับน้ำในขวดระบายกระเพื่อมตามการหายใจดี, สารคัดหลั่งระบายได้... ml สี serosanguinous, ปอดขยายตัวดีขึ้น เสียงหายใจเข้าเท่ากันทั้งสองข้าง"},{"shortcut":".hadrug","title":"การบริหารยาความเสี่ยงสูงทางหลอดเลือดดำ (High Alert Drug \u0026 Vasoactive Inotropes)","content":"Focus: ความปลอดภัยในการบริหารยากลุ่มความเสี่ยงสูงและยากระตุ้นความดันโลหิต (High Alert Drugs: HAD)\nGoal: ผู้ป่วยได้รับยาความเสี่ยงสูงอย่างถูกต้อง ปลอดภัย ผ่านเครื่อง Infusion pump สัญญาณชีพและค่า MAP อยู่ในเกณฑ์เป้าหมาย และไม่เกิดภาวะเนื้อเยื่อตาย\nData: ผู้ป่วยได้รับยาที่มีความเสี่ยงสูง / ยากระตุ้นหัวใจและความดันโลหิต (Norepinephrine / Dopamine / Nicardipine / Amiodarone / Insulin drip / Heparin) อัตราเร็ว... ml/hr (Dose... mcg/kg/min)\nAction: ปฏิบัติตามแนวทางการใช้ยาความเสี่ยงสูง (High Alert Drug Safety):\n1. ตรวจสอบความถูกต้องแบบ Double Check (ตัวยา ขนาดยา ความเข้มข้น อัตราหยด และชื่อผู้ป่วย)\n2. ให้ยาผ่านเครื่องควบคุมสารน้ำ (Infusion pump) เสมอ และติดป้ายเตือนยาความเสี่ยงสูงชัดเจนที่ขวดและสายน้ำเกลือ\n3. ให้ยาผ่านเส้นเลือดดำขนาดใหญ่หรือสาย CVC เพื่อป้องกันการรั่วออกนอกหลอดเลือด (Extravasation) ซึ่งทำให้เนื้อเยื่อตาย\n4. ตรวจวัดสัญญาณชีพและประเมินระดับความดันโลหิต/ชีพจรทุก 15-30 นาทีขณะปรับขนาดยา (Titration) เพื่อให้ได้ค่า MAP ตามเป้าหมาย (\u003e 65 mmHg)\n5. สังเกตอาการข้างเคียง เช่น หัวใจเต้นผิดจังหวะ ปลายมือปลายเท้าเขียวคล้ำ\nResponse: ยาหยดสม่ำเสมอผ่านเครื่อง Infusion pump, ความดันโลหิตอยู่ในเกณฑ์เป้าหมาย MAP = ... mmHg, บริเวณรอยแทงเข็มไม่มีอาการบวมแดงหรือยารั่วซึม"}]},{"category":"20. การพยาบาลผู้ป่วยมะเร็งกระดูกและรังสีรักษา (Bone Cancer \u0026 Radiotherapy)","items":[{"shortcut":".boneca","title":"การพยาบาลผู้ป่วยมะเร็งกระดูกและการแพร่กระจายมายังกระดูก (Bone Cancer \u0026 Bone Metastasis Care)","content":"Focus: การพยาบาลผู้ป่วยมะเร็งกระดูกและการแพร่กระจายมายังกระดูก\nGoal: ผู้ป่วยได้รับการดูแลแบบองค์รวม ควบคุมอาการปวดได้ดี ป้องกันภาวะแทรกซ้อนจากการทำลายกระดูก เสริมสร้างความปลอดภัย และได้รับการประคับประคองจิตใจ\nData: ผู้ป่วยได้รับการวินิจฉัยว่าเป็นมะเร็งกระดูก (Primary bone tumor / Metastatic bone disease จาก...), บ่นปวดตื้อลึกในกระดูกบริเวณ... ปวดมากขึ้นเวลากลางคืนหรือเมื่อลงน้ำหนัก, มีก้อนบวม/กดเจ็บ, เคลื่อนไหวร่างกายลำบาก\nAction:\n[☀️ เวรเช้า]\n- ประเมินอาการปวด อาการบวม และความสามารถในการทำกิจวัตรประจำวัน\n- ช่วยเหลือในการทำความสะอาดร่างกายและเปลี่ยนท่านอนอย่างนุ่มนวล หลีกเลี่ยงการดึงรั้งรยางค์ที่มีรอยโรค\n- ส่งเสริมการรับประทานอาหารที่มีโปรตีนสูงและแคลอรี่เพียงพอ\n- ติดตามผลภาพถ่ายทางรังสี (X-ray / Bone scan / CT / MRI) และผลตรวจเลือด\n[⛅ เวรบ่าย]\n- ดูแลให้ยาบรรเทาปวดตามแผนการรักษาอย่างตรงเวลา ประเมินระดับความปวดทั้งขณะพักและเคลื่อนไหว\n- สังเกตอาการข้างเคียงของยาแก้ปวดกลุ่ม Opioids (คลื่นไส้ อาเจียน ท้องผูก ง่วงซึม)\n- จัดท่าทางให้อยู่ในท่าที่สุขสบายและใช้อุปกรณ์หนุนรองรับน้ำหนักกระดูก\n- ให้กำลังใจและเปิดโอกาสให้ผู้ป่วยและครอบครัวระบายความกังวล\n[🌙 เวรดึก]\n- ดูแลสิ่งแวดล้อมให้เงียบสงบ เอื้อต่อการนอนหลับพักผ่อน\n- ให้ยาแก้ปวดก่อนนอนเพื่อป้องกันอาการปวดกระดูกรบกวนการนอนหลับ\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อป้องกันการพลัดตกหกล้ม\n- เฝ้าระวังอาการปวดรุนแรงเฉียบพลันหรืออาการผิดปกติทางระบบประสาทรอบดึก\nResponse: ผู้ป่วยสุขสบายขึ้น บ่นปวดกระดูกลดลง Pain score ≤ 3/10 เคลื่อนไหวเปลี่ยนท่าได้อย่างปลอดภัย ไม่มีอุบัติเหตุพลัดตกหกล้ม สีหน้าผ่อนคลายและนอนหลับพักผ่อนได้"},{"shortcut":".pathofx","title":"เสี่ยงต่อภาวะกระดูกหักจากพยาธิสภาพของโรค (Risk for Pathological Fracture)","content":"Focus: เสี่ยงต่อภาวะกระดูกหักจากพยาธิสภาพของมะเร็งทำลายเนื้อกระดูก (Risk for Pathological Fracture)\nGoal: ผู้ป่วยไม่เกิดภาวะกระดูกหักจากพยาธิสภาพ (Pathological fracture) ไม่มีอุบัติเหตุพลัดตกหกล้ม เคลื่อนย้ายตัวถูกต้อง และใช้อุปกรณ์พยุงกายอย่างปลอดภัย\nData: ภาพถ่ายรังสีพบรอยโรคกระดูกถูกทำลายแบบ Lytic lesion / Blastic lesion บริเวณ... เสี่ยงต่อกระดูกหักง่ายแม้รับแรงกระแทกเพียงเล็กน้อย (Pathological fracture risk), ผู้ป่วยรู้สึกเสียวแปลบและปวดเสียวเมื่อลงน้ำหนัก\nAction:\n[☀️ เวรเช้า]\n- ติดป้ายเตือน \"ระวังกระดูกหักง่าย (Fall \u0026 Fracture Precaution)\" ที่หัวเตียงและหน้าชาร์ต\n- แนะนำและดูแลการจำกัดการลงน้ำหนัก (Non-weight bearing / Partial weight bearing) ตามแผนการรักษาของแพทย์ออร์โธปิดิกส์\n- สอนและดูแลการใช้อุปกรณ์ช่วยเดิน (Walker / Crutches) หรืออุปกรณ์ประคองกระดูก (Brace / Splint)\n- แนะนำผู้ป่วยหลีกเลี่ยงการบิดหมุนตัว การก้มยกของหนัก หรือการออกแรงกระแทกกระดูก\n[⛅ เวรบ่าย]\n- ช่วยเหลือในการเคลื่อนย้ายตัวและเปลี่ยนท่าอย่างถูกวิธีโดยมีผู้ช่วยเหลืออย่างน้อย 1-2 คน (Log-roll technique เมื่อมีรอยโรคที่กระดูกสันหลัง)\n- จัดวางของใช้จำเป็นให้อยู่ใกล้มือผู้ป่วยเพื่อป้องกันการเอื้อมหรือก้มตัว\n- ดูแลทางเดินในห้องให้โล่ง ไม่มีสิ่งกีดขวาง และพื้นแห้งสนิท\n- สังเกตอาการปวดเฉียบพลัน ผิดรูป หรือได้ยินเสียงกรอบแกรบ (Crepitus)\n[🌙 เวรดึก]\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้าง ล็อกล้อเตียงให้แน่นสนิทตลอดเวลา\n- จัดวางกระโถนปัสสาวะไว้ข้างเตียงและกำชับให้กดกริ่งเรียกพยาบาลทุกครั้งที่ต้องการลุกจากเตียง\n- ตรวจตราความปลอดภัยรอบดึกอย่างสม่ำเสมอ\n- เฝ้าระวังไม่ให้ผู้ป่วยลุกเดินเองตามลำพัง\nResponse: ไม่เกิดอุบัติเหตุพลัดตกหกล้ม ไม่เกิดภาวะกระดูกหักจากพยาธิสภาพ เคลื่อนย้ายตัวได้อย่างนุ่มนวลและปลอดภัย ใช้อุปกรณ์ช่วยพยุงได้ถูกต้อง"},{"shortcut":".hypercamal","title":"ภาวะแคลเซียมในเลือดสูงฉุกเฉินจากมะเร็งกระดูก (Hypercalcemia of Malignancy: HCM)","content":"Focus: ภาวะระดับแคลเซียมในเลือดสูงฉุกเฉินจากการแพร่กระจายของมะเร็งทำลายกระดูก (Hypercalcemia of Malignancy: HCM)\nGoal: ระดับซีรั่มแคลเซียมลดลงสู่เกณฑ์ปกติ (Total Ca 8.5-10.5 mg/dL, Corrected Ca ปกติ) ได้รับสารน้ำและยาอย่างปลอดภัย สัญญาณชีพคงที่ รู้สึกตัวดี และไม่เกิดภาวะหัวใจเต้นผิดจังหวะ\nData: ผลตรวจ Total Calcium = ... mg/dL, Corrected Calcium = ... mg/dL (สูงกว่า 10.5 mg/dL), ผู้ป่วยมีอาการอ่อนเพลีย ซึม สับสน เบื่ออาหาร คลื่นไส้อาเจียน ท้องผูก ดื่มน้ำบ่อย ปัสสาวะมาก (Polyuria) หรือปัสสาวะออกน้อย กล้ามเนื้ออ่อนแรง\nAction:\n[☀️ เวรเช้า]\n- ประเมินระดับความรู้สึกตัว (GCS), สัญญาณชีพ และอาการแสดงของภาวะแคลเซียมสูง (คลื่นไส้ ท้องผูก สับสน กล้ามเนื้ออ่อนแรง)\n- ดูแลให้สารน้ำ 0.9% NSS ทางหลอดเลือดดำในอัตราเร็วตามแผนการรักษา (Vigorous hydration 200-300 ml/hr) เพื่อขับแคลเซียมออกทางไต\n- ตรวจสอบผลตรวจเลือดระดับ Electrolyte, BUN, Cr และ Corrected Calcium\n- บันทึกปริมาณน้ำเข้า-ออก (Intake/Output) อย่างเคร่งครัด\n[⛅ เวรบ่าย]\n- ดูแลให้ยาขับปัสสาวะ Furosemide (Lasix) ทางหลอดเลือดดำตามแผน เพื่อช่วยขับแคลเซียมหลังให้สารน้ำเพียงพอ (หลีกเลี่ยง Thiazide diuretics)\n- ดูแลให้ยากลุ่มยับยั้งการทำลายกระดูก (Bisphosphonates เช่น Zoledronic acid หรือ Pamidronate) ทางหลอดเลือดดำตามแผนการรักษา โดยผสมสารน้ำและหยดช้าๆ ไม่น้อยกว่า 15-30 นาที\n- ตรวจติดตามคลื่นไฟฟ้าหัวใจ (EKG) เฝ้าระวัง QT interval สั้นลง หรือ Bradycardia\n[🌙 เวรดึก]\n- ตรวจวัดสัญญาณชีพและประเมินภาวะน้ำเกิน (Fluid overload: หายใจหอบเหนื่อย, ฟังปอดพบ Crepitation, SpO2 ลดลง) จากการได้รับสารน้ำปริมาณมาก\n- สรุปยอดปัสสาวะสะสม หากออก \u003c 0.5 ml/kg/hr ให้รายงานแพทย์\n- เฝ้าระวังอาการชักหรือสับสนเพ้อ (Delirium) รอบดึก และยกไม้กั้นเตียงขึ้นเพื่อความปลอดภัย\nResponse: ปัสสาวะออกดีสะสม... ml/เวร ไม่มีภาวะน้ำคั่งหรือหอบเหนื่อย, ผล Corrected Calcium ลดลงเหลือ... mg/dL, ผู้ป่วยรู้สึกตัวดีขึ้น อาการคลื่นไส้อ่อนเพลียทุเลาลง สัญญาณชีพและคลื่นไฟฟ้าหัวใจปกติ"},{"shortcut":".radiotherapy","title":"การดูแลผู้ป่วยก่อน-ระหว่าง-หลังส่งฉายแสง (Radiation Therapy Management \u0026 Transport Care)","content":"Focus: การเตรียมความพร้อมและดูแลผู้ป่วยระหว่างเข้ารับการฉายรังสีรักษา (Radiation Therapy Nursing Care)\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจ ได้รับการฉายรังสีครบถ้วนตามแผนการรักษา ปลอดภัยระหว่างการเคลื่อนย้ายส่งต่อ และไม่เกิดภาวะแทรกซ้อนเฉียบพลัน\nData: ผู้ป่วยมีแผนเข้ารับการฉายรังสีรักษา (External Beam Radiation Therapy: EBRT) บริเวณ... ครั้งที่... จากแผนทั้งหมด... ครั้ง, V/S ก่อนไป: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\nAction:\n[☀️ เวรเช้า]\n- ตรวจสอบใบนัดและแผนการฉายรังสีรักษา (RT appointment \u0026 treatment sheet)\n- ประเมินความพร้อมของผู้ป่วย สัญญาณชีพ และระดับความรู้สึกตัว\n- จัดเตรียมยาแก้ปวดให้ผู้ป่วยรับประทานก่อนไปฉายแสง 30-45 นาที เพื่อให้ผู้ป่วยสามารถนอนราบนิ่งบนเตียงฉายแสงได้อย่างสุขสบาย\n- ตรวจสอบรอยมาร์กหมึกตำแหน่งฉายรังสี ห้ามขัดถูหรือลบเลือน\n- ประสานงานศูนย์รังสีรักษาและเวรเปลเพื่อนำส่งด้วยเตียงนอนหรือรถนั่งอย่างปลอดภัย\n[⛅ เวรบ่าย]\n- รับย้ายผู้ป่วยกลับจากห้องฉายรังสีรักษา ตรวจวัดสัญญาณชีพทันทีแรกรับกลับ\n- ประเมินอาการเหนื่อย อ่อนเพลีย วิงเวียน หรือคลื่นไส้หลังฉายแสง\n- จัดท่านอนพักผ่อนในสิ่งแวดล้อมที่เงียบสงบ\n- ดูแลให้จิบน้ำอุ่นหรือรับประทานอาหารว่างเบาๆ หากไม่มีอาการคลื่นไส้อาเจียน\n- บันทึกผลการฉายแสงและอาการตอบสนองลงในเวชระเบียน\n[🌙 เวรดึก]\n- ตรวจประเมินสัญญาณชีพรอบดึกและติดตามอาการข้างเคียงสะสม\n- ส่งเสริมการนอนหลับพักผ่อนเพื่อฟื้นฟูร่างกายจากการได้รับรังสี\n- ให้คำแนะนำผู้ป่วยและญาติเกี่ยวกับการปฏิบัติตัวและแผนการฉายแสงในวันถัดไป\n- เตรียมเอกสารส่งต่อเวรเช้าให้พร้อม\nResponse: ผู้ป่วยได้รับการฉายรังสีรักษาตามแผนเรียบร้อยดี การส่งต่อปลอดภัย สัญญาณชีพคงที่ ไม่มีอาการวิงเวียนหรือคลื่นไส้อาเจียนรุนแรง สามารถนอนพักผ่อนได้ดี"},{"shortcut":".radskin","title":"การดูแลผิวหนังบริเวณฉายแสงและป้องกันรังสีอักเสบ (Radiation Dermatitis \u0026 Skin Care)","content":"Focus: ป้องกันและดูแลภาวะผิวหนังอักเสบ บวมแดง และลอกหลุดจากรังสีรักษา (Radiation Dermatitis Care)\nGoal: ผิวหนังบริเวณที่ฉายรังสีสะอาด ชุ่มชื้น ไม่เกิดแผลฉีกขาด ลอกหลุดเป็นแผลเปียก (Moist desquamation) หรือติดเชื้อแทรกซ้อน เส้นมาร์กตำแหน่งฉายรังสีคมชัด\nData: ผิวหนังบริเวณที่ฉายรังสี (Radiation field) มีอาการแห้ง แดง คัน (Erythema) คล้ำขึ้น หรือมีสะเก็ดแห้งลอก (Dry desquamation), ผู้ป่วยบ่นแสบร้อนคันบริเวณรอยฉายแสง\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินสภาพผิวหนังบริเวณที่ฉายรังสี: สีผิว ความยืดหยุ่น รอยแดง อาการบวม หรือตุ่มน้ำพอง ตามเกณฑ์ RTOG/CTCAE\n- ทำความสะอาดผิวหนังด้วยน้ำเปล่าหรือสบู่อ่อนโยน (pH balance) ซับเบาๆ ด้วยผ้าขนหนูนุ่ม ห้ามถูแรง\n- ระมัดระวังไม่ให้รอยเส้นหมึกระบุพิกัดฉายรังสีลบเลือน หากเส้นจางให้แจ้งนักรังสีการแพทย์แต้มใหม่ ห้ามเขียนทับเอง\n[⛅ เวรบ่าย]\n- ทาโลชั่นหรือครีมบำรุงผิวที่ไม่มีน้ำหอม/โลหะผสม (เช่น Urea cream, Aloe vera gel) ตามที่แพทย์รังสีรักษาแนะนำ หลังการฉายแสงเสร็จสิ้น (ห้ามทาก่อนเข้าห้องฉายรังสีภายใน 2-4 ชม.)\n- แนะนำผู้ป่วยสวมใส่เสื้อผ้าเนื้อนุ่ม หลวมสบาย ไม่รัดแน่นหรือเสียดสีผิวหนัง\n- กำชับห้ามเกา ห้ามแกะสะเก็ด ห้ามประคบร้อนหรือเย็น และห้ามติดพลาสเตอร์เหนียวบริเวณรอยฉายรังสีเด็ดขาด\n- แนะนำหลีกเลี่ยงการถูกแสงแดดโดยตรง\n[🌙 เวรดึก]\n- ตรวจสอบผิวหนังก่อนนอนและจัดเสื้อผ้าผ้าปูที่นอนให้เรียบตึงไม่ระคายเคือง\n- ดูแลให้ยาแก้แพ้หรือยาแก้คันตามแผนการรักษาหากมีอาการคันรบกวนการนอนหลับ\n- สังเกตสัญญาณการติดเชื้อแทรกซ้อน (บวม ร้อน เจ็บ หรือมีน้ำเหลืองซึมเปื้อน) เพื่อรายงานแพทย์\nResponse: ผิวหนังบริเวณฉายแสงสะอาด ไม่มีรอยถลอกลอกเปียกหรือแผลติดเชื้อ เส้นมาร์กตำแหน่งรังสีชัดเจน อาการแสบคันลดลง ผู้ป่วยเข้าใจและปฏิบัติตามคำแนะนำในการดูแลผิวหนังได้ถูกต้อง"},{"shortcut":".painflare","title":"การจัดการอาการปวดกระดูกจากมะเร็งและปวดกำเริบหลังฉายแสง (Bone Cancer Pain \u0026 Radiation Pain Flare)","content":"Focus: การจัดการอาการปวดกระดูกจากมะเร็งและอาการปวดกำเริบชั่วคราวหลังฉายรังสี (Bone Cancer Pain \u0026 Radiation Pain Flare)\nGoal: ระดับความปวดลดลงอยู่ในเกณฑ์ที่ทนได้ Pain score ≤ 3/10 ควบคุมอาการปวดกำเริบฉับพลัน (Breakthrough pain / Pain flare) ได้รวดเร็ว และไม่มีภาวะกดการหายใจจากยากลุ่มอนุพันธ์ฝิ่น\nData: ผู้ป่วยบ่นปวดกระดูกบริเวณที่ฉายแสงเพิ่มขึ้นอย่างเฉียบพลันหลังการฉายรังสี 1-3 วันแรก (Radiation pain flare) Pain score = .../10, หน้าตานิ่ว กระสับกระส่าย ขยับตัวลำบาก, V/S: BP.../... mmHg, PR... /min\nAction:\n[☀️ เวรเช้า]\n- ประเมินลักษณะ ตำแหน่ง ความถี่ และระดับความปวดกระดูก (Pain score 0-10) แยกแยะระหว่างปวดเดิมกับปวดกำเริบจากรังสี (Pain flare)\n- ดูแลให้ยาแก้ปวดตามรอบเวลา (Around-the-clock analgesics) เช่น ยากลุ่มสเตียรอยด์ (Dexamethasone) เพื่อลดอาการบวมอักเสบ และยาแก้ปวดกลุ่ม Opioids ร่วมกับ Paracetamol ตามแผน\n- ประเมินความปวดซ้ำหลังให้ยา 30-60 นาที\n[⛅ เวรบ่าย]\n- ดูแลให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough dose / Rescue dose) ทันทีเมื่อผู้ป่วยมีอาการปวดกำเริบฉับพลัน\n- จัดท่านอนประคองส่วนที่ปวดด้วยหมอนนุ่ม ผ่อนคลายกล้ามเนื้อ หลีกเลี่ยงการเคลื่อนไหวที่ทำให้กระดูกรับแรงบิดเค้น\n- สังเกตอาการข้างเคียงของยากลุ่ม Opioids (อัตราการหายใจ, ระดับความง่วงซึม Sedation score, อาการคลื่นไส้)\n[🌙 เวรดึก]\n- ดูแลให้ยาแก้ปวดก่อนนอนเพื่อส่งเสริมการนอนหลับพักผ่อนต่อเนื่องตลอดคืน\n- เฝ้าระวังภาวะกดการหายใจ (Respiratory depression: RR \u003c 10 ครั้ง/นาที) ตรวจวัด RR สม่ำเสมอ\n- จัดสิ่งแวดล้อมห้องพักให้เงียบสงบลดสิ่งเร้า\n- เตรียมพร้อมยาแก้พิษ Naloxone ไว้กรณีเกิด Opioid toxicity\nResponse: อาการปวดกระดูกกำเริบทุเลาลง Pain score ลดลงเหลือ.../10, ผู้ป่วยสีหน้าผ่อนคลาย ขยับตัวได้ดีขึ้น อัตราการหายใจปกติ (RR... /min) ไม่มีง่วงซึมผิดปกติ สามารถนอนหลับพักผ่อนได้"},{"shortcut":".mscc","title":"ภาวะกดทับไขสันหลังจากมะเร็งกระดูกลุกลามฉุกเฉิน (Malignant Spinal Cord Compression: MSCC)","content":"Focus: ภาวะฉุกเฉินทางมะเร็งวิทยา: มะเร็งกระดูกสันหลังลุกลามกดทับไขสันหลัง (Malignant Spinal Cord Compression: MSCC)\nGoal: ตรวจพบสัญญาณเตือนทางระบบประสาทได้รวดเร็ว ได้รับการรักษาฉุกเฉินทันท่วงที (High-dose Dexamethasone \u0026 Emergency Radiotherapy/Surgery) ป้องกันความพิการอัมพาตถาวร และการทำงานของระบบประสาทฟื้นตัว\nData: ผู้ป่วยมะเร็งกระดูกสันหลังมีอาการปวดหลังรุนแรงร้าวไปตามรากประสาท (Radicular pain) ร่วมกับมีอาการขาอ่อนแรง ขยับขาได้ลดลง (Motor weakness Grade.../5), มีอาการชาหรือสูญเสียความรู้สึกตั้งแต่ระดับ... ลงไป (Sensory level loss), หรือมีปัญหาการกลั้นปัสสาวะ/อุจจาระไม่ได้ (Autonomic dysfunction / Urinary retention)\nAction:\n[☀️ เวรเช้า]\n- ตรวจประเมินระบบประสาทอย่างละเอียดทุก 2-4 ชั่วโมง: กำลังกล้ามเนื้อขา (Motor power), การรับความรู้สึก (Sensory level), และอาการชา\n- รายงานแพทย์ทันทีเมื่อพบสัญญาณเตือนของ MSCC เพื่อส่งตรวจ MRI Spine ฉุกเฉิน\n- ดูแลให้ยา Dexamethasone ขนาดสูง (High-dose IV Dexamethasone 10-16 mg IV stat then 4 mg IV q 6 hr) ตามคำสั่งแพทย์เพื่อลดอาการบวมกดทับไขสันหลัง\n- ป้องกันภาวะแทรกซ้อนของสเตียรอยด์ (ให้ยาป้องกันแผลในกระเพาะอาหาร PPI, ติดตามค่าน้ำตาลในเลือด DTX)\n[⛅ เวรบ่าย]\n- จัดท่าผู้ป่วยนอนราบบนที่นอนแข็ง ไม่งอพับหลัง ใช้เทคนิคการพลิกตัวแบบท่อนซุง (Log-roll turning technique) โดยมีเจ้าหน้าที่อย่างน้อย 3 คน\n- ตรวจสอบการคาสายสวนปัสสาวะ (Foley catheter) บันทึกปริมาณปัสสาวะเพื่อเฝ้าระวังกระเพาะปัสสาวะคั่งค้าง\n- ประสานงานเตรียมส่งผู้ป่วยเข้ารับการฉายรังสีรักษาฉุกเฉิน (Emergency Radiotherapy) หรือห้องผ่าตัดกระดูกสันหลัง (Emergency Decompression)\n[🌙 เวรดึก]\n- ตรวจประเมินกำลังกล้ามเนื้อขาและระดับความรู้สึกซ้ำรอบดึก หากอาการอ่อนแรงแย่ลงให้รายงานแพทย์เวรทันที\n- พลิกตัวเปลี่ยนท่านอนอย่างนุ่มนวลทุก 2 ชั่วโมงเพื่อป้องกันแผลกดทับ\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างและดูแลความปลอดภัยรอบด้าน\n- ให้กำลังใจผู้ป่วยและครอบครัวเพื่อลดความวิตกกังวล\nResponse: ได้รับยา High-dose Dexamethasone และประสานงานส่งฉายรังสีรักษาฉุกเฉินเรียบร้อย, กำลังกล้ามเนื้อขาคงที่ Motor power Grade.../5 ไม่พบการลุกลามเพิ่มขึ้น, อาการปวดหลังทุเลาลง และคาสายสวนปัสสาวะระบายได้สะดวก"},{"shortcut":".radfatigue","title":"ภาวะอ่อนเพลีย เบื่ออาหาร และไขกระดูกกดจากการฉายแสง (Radiation-Induced Fatigue, Anorexia \u0026 Myelosuppression)","content":"Focus: ภาวะอ่อนเพลียสะสม เบื่ออาหาร และไขกระดูกถูกกดจากการฉายรังสีรักษา (Radiation Fatigue \u0026 Bone Marrow Suppression)\nGoal: ผู้ป่วยมีระดับพลังงานเพิ่มขึ้น ทำกิจวัตรประจำวันได้ตามความสามารถ ได้รับสารอาหารและน้ำเพียงพอ น้ำหนักตัวคงที่ และไม่เกิดการติดเชื้อหรือภาวะเลือดออกจากเม็ดเลือดต่ำ\nData: ผู้ป่วยมีอาการอ่อนเพลีย เหนื่อยล้าสะสม (Fatigue score.../10), เบื่ออาหาร ทานได้น้อย คลื่นไส้ น้ำหนักตัวลดลง, ผลตรวจ CBC: Hb... g/dL, Hct... %, WBC... /uL, ANC... /uL, Platelet... /uL\nAction:\n[☀️ เวรเช้า]\n- ประเมินระดับความเหนื่อยล้าอ่อนเพลีย (Fatigue score 0-10) และวางแผนจัดตารางกิจกรรมให้สอดคล้องกับช่วงเวลาที่มีพลังงาน\n- จัดอาหารมื้อเล็กๆ แต่บ่อยครั้ง (Small frequent meals) เน้นโปรตีนสูงและพลังงานสูง\n- ตรวจสอบผลตรวจความสมบูรณ์ของเม็ดเลือด (CBC) สังเกตภาวะซีด (Anemia), เม็ดเลือดขาวต่ำ (Neutropenia), และเกล็ดเลือดต่ำ (Thrombocytopenia)\n- ดูแลความสะอาดของร่างกายและช่องปากด้วยแปรงขนนุ่ม\n[⛅ เวรบ่าย]\n- ส่งเสริมให้ผู้ป่วยได้งีบหลับพักผ่อนระหว่างวัน (ไม่เกิน 30-45 นาที เพื่อไม่ให้รบกวนการนอนกลางคืน)\n- แนะนำการออกกำลังกายเบาๆ เช่น การยืดเหยียดกล้ามเนื้อบนเตียง หรือนั่งเก้าอี้ขยับเท้า เพื่อลดความเมื่อยล้าสะสม\n- ดูแลให้สารน้ำ วิตามิน หรืออาหารเสริมทางการแพทย์ตามแผนการรักษา\n- สังเกตจุดจ้ำเลือด (Petechiae) หรือเลือดออกตามไรฟัน\n[🌙 เวรดึก]\n- เฝ้าระวังอาการไข้สูง หนาวสั่น (Neutropenic fever: T ≥ 38.0 °C) หากพบให้รายงานแพทย์และปฏิบัติตามแนวทางการดูแลผู้ป่วยติดเชื้อทันที\n- จัดสิ่งแวดล้อมห้องพักให้เงียบสงบ มืดพอเหมาะ ส่งเสริมการนอนหลับพักผ่อนเต็มที่ในเวลากลางคืน\n- ดูแลความปลอดภัยรอบเตียง ป้องกันการพลัดตกหกล้มจากความอ่อนเพลีย\nResponse: ผู้ป่วยรับประทานอาหารได้มากขึ้น... มื้อ, รู้สึกสดชื่นขึ้น Fatigue score ลดลงเหลือ.../10, สัญญาณชีพคงที่ ไม่มีไข้ (T... °C) ไม่มีจุดเลือดออกผิดปกติ สามารถนอนหลับพักผ่อนได้เต็มที่"}]}],"Count":20},"raw_text":"# ==============================================================================\r\n# e-PHIS Medical \u0026 Nursing Text Expander - คลังเทมเพลตบันทึกทางการพยาบาล\r\n# โรงพยาบาลธรรมศาสตร์เฉลิมพระเกียรติ\r\n# วิธีใช้: \r\n#   1) พิมพ์คีย์ลัด (เช่น .chf, .stroke, .pain, .preop) แล้วกด Spacebar หรือ Tab\r\n#   2) หรือกดปุ่ม F8 (หรือ Ctrl+Shift+M) เพื่อเปิดหน้าต่างค้นหาและคลิกเลือกวาง\r\n# ==============================================================================\r\n\r\n[1. การดูแลก่อน-หลังผ่าตัดและหัตถการ]\r\n.preop = เตรียมความพร้อมก่อนผ่าตัด (Pre-operative care)\r\nFocus: เตรียมความพร้อมผู้ป่วยก่อนส่งผ่าตัด\r\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจก่อนเข้าห้องผ่าตัด ปฏิบัติตัวตามแผน NPO ถูกต้อง เอกสารและผลตรวจครบถ้วน และไม่เกิดภาวะแทรกซ้อนก่อนผ่าตัด\r\nData: ผู้ป่วยมีแผนผ่าตัด... วันนี้ NPO ตั้งแต่... น., V/S: T... °C, BP.../... mmHg, PR... /min, RR... /min, SpO2... %\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจสอบความถูกต้องของใบยินยอมผ่าตัด (Informed consent) เซ็นเรียบร้อย\r\n- ตรวจสอบผลตรวจทางห้องปฏิบัติการ (CBC, Coag, Electrolyte, Anti-HIV), ผล X-ray/EKG และ Chart ผู้ป่วย\r\n- อาบน้ำฟอกสบู่ฆ่าเชื้อ เปลี่ยนชุดผ่าตัด ถอดฟันปลอม แว่นตา คอนแทคเลนส์ และเครื่องประดับทุกชนิด\r\n- ตรวจสอบแถบข้อมือระบุตัวตน (Patient ID) และทำเครื่องหมายตำแหน่งผ่าตัด (Surgical Site Marking) ชัดเจน\r\n- ดูแลให้สารน้ำทางหลอดเลือดดำ และให้ยาปฏิชีวนะป้องกันล่วงหน้า (Prophylactic Antibiotic) ก่อนส่ง OR ตามแผน\r\n- สวมหมวกคลุมผม และนำส่งห้องผ่าตัดพร้อมเอกสารครบถ้วน\r\n[⛅ เวรบ่าย]\r\n- ตรวจเช็คตารางผ่าตัด (OR list) ของวันพรุ่งนี้ และประสานงานติดตามผลตรวจที่ยังค้าง (Pending labs/X-ray)\r\n- แนะนำและเตรียมความพร้อมทางจิตใจแก่ผู้ป่วยและญาติ อธิบายขั้นตอนการผ่าตัดและการปฏิบัติตัวหลังผ่าตัด\r\n- แนะนำการฝึกหายใจลึกๆ (Deep breathing exercise) และการฝึกไออย่างมีประสิทธิภาพ\r\n- ตรวจเช็คการจองโลหิต (Cross-match / PRC) พร้อมใช้ตามแผนการรักษา\r\n- ให้ยาระบายหรือสวนอุจจาระตามคำสั่งแพทย์เฉพาะราย\r\n[🌙 เวรดึก]\r\n- กำชับและดูแลการงดน้ำและอาหารทางปาก (Strict NPO) ตั้งแต่เวลา 24:00 น. เป็นต้นไป\r\n- ติดป้าย \"งดน้ำและอาหาร (NPO)\" ที่หัวเตียงและหน้าชาร์ต\r\n- ดูแลให้สารน้ำทางหลอดเลือดดำตามคำสั่งแพทย์\r\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจประเมินความพร้อมก่อนผ่าตัด (Pre-op checklist) ซ้ำอีกครั้ง\r\n- เตรียมแฟ้มประวัติ ยาประจำตัว และผลตรวจให้พร้อมส่งต่อเวรเช้า\r\nResponse: ส่งผู้ป่วยถึงห้องผ่าตัดเวลา... น. ปลอดภัยดี พยาบาลห้องผ่าตัดรับมอบผู้ป่วยและเอกสารเรียบร้อย\r\n---\r\n.postop = การพยาบาลดูแลหลังผ่าตัด (Post-operative care)\r\nFocus: เสี่ยงต่อภาวะแทรกซ้อนจากการระงับความรู้สึกและการผ่าตัด\r\nGoal: สัญญาณชีพคงที่ ฟื้นตัวจากยาระงับความรู้สึกได้ดี แผลผ่าตัดไม่มี active bleeding และไม่เกิดภาวะแทรกซ้อนหลังผ่าตัด\r\nData: รับย้ายผู้ป่วยกลับจากห้องผ่าตัด/ห้องพักฟื้น หลังทำผ่าตัด... ระดับความรู้สึกตัว: ตื่นดี รู้เรื่อง (Alert), V/S แรกรับ: BP.../... mmHg, PR... /min, RR... /min, SpO2... %, แผลผ่าตัดปิด gauze แนบสนิท ไม่มีเลือดสดซึมเปื้อน, สายระบายออก... ml ลักษณะ serosanguinous\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินสัญญาณชีพ และตรวจประเมินแผลผ่าตัด ทำแผล (Dressing) ด้วยเทคนิคปลอดเชื้อ\r\n- ตรวจสอบสายระบาย (Drain) และสายสวนปัสสาวะ บันทึกปริมาณและลักษณะสารคัดหลั่ง\r\n- ประเมินระดับความรู้สึกตัวและความปวด (Pain score) ให้ยาบรรเทาปวดและยาปฏิชีวนะตามแผน\r\n- ส่งเสริมการลุกขยับตัวเร็ว (Early ambulation) ช่วยเหลือผู้ป่วยฝึกนั่งข้างเตียงหรือยืนเดิน\r\n- ประเมินเสียงการเคลื่อนไหวของลำไส้ (Bowel sound) ก่อนเริ่มจิบน้ำหรืออาหารตามลำดับขั้น\r\n[⛅ เวรบ่าย]\r\n- รับย้ายผู้ป่วยกลับจากห้องผ่าตัด/ห้องพักฟื้น ตรวจวัด V/S ทุก 15 นาที x 4, 30 นาที x 2 และทุก 1 ชม. จนคงที่\r\n- จัดท่านอนราบหรือศีรษะสูงตามข้อกำหนดของการระงับความรู้สึก (Spinal block / GA)\r\n- ตรวจสอบผ้าปิดแผล สังเกต active bleeding และตรวจเช็คสายระบายสุญญากาศ\r\n- ประเมินและดูแลบรรเทาอาการคลื่นไส้อาเจียนหลังผ่าตัด (PONV)\r\n- ดูแลให้สารน้ำทางหลอดเลือดดำและยาแก้ปวดตามแผนการรักษา\r\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อความปลอดภัย\r\n[🌙 เวรดึก]\r\n- ตรวจวัดสัญญาณชีพและประเมินระดับความรู้สึกตัวระหว่างคืน\r\n- ประเมินระดับความปวด ให้ยาแก้ปวดก่อนนอนเพื่อส่งเสริมการนอนหลับพักผ่อน\r\n- จัดสิ่งแวดล้อมให้เงียบสงบ แสงไฟเหมาะสม และยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างตลอดเวลา\r\n- ตรวจเช็คสายระบายและถุงปัสสาวะไม่ให้หักพับงอ บันทึกและสรุปยอด Intake-Output สะสม 24 ชม.\r\n- ตรวจวัดสัญญาณชีพรอบ 06:00 น. เฝ้าระวังไข้และภาวะแทรกซ้อนก่อนส่งเวรเช้า\r\nResponse: สัญญาณชีพคงที่ รู้สึกตัวดี ไม่มีคลื่นไส้อาเจียน แผลผ่าตัดแห้งดี ไม่มี active bleeding\r\n---\r\n.drain = การดูแลสายระบายและแผลผ่าตัด (Surgical Drain \u0026 Wound Care)\r\nFocus: เสี่ยงต่อการติดเชื้อและมีสารน้ำคั่งค้างบริเวณแผลผ่าตัด\r\nGoal: สารคัดหลั่งระบายได้สะดวก สายระบายทำงานมีประสิทธิภาพ แผลรอบสายระบายสะอาด แห้งดี และไม่พบสัญญาณการติดเชื้อ\r\nData: มีสายระบาย (Redivac / Hemovac / Jackson-Pratt / ICD) บริเวณแผลผ่าตัด มีสารคัดหลั่งออกสะสม... ml ลักษณะ serosanguinous ไม่มีเลือดสดออกเพิ่ม แผลผ่าตัดเย็บแนบสนิท\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจเช็คตำแหน่งรอยเจาะสายระบาย ทำความสะอาดแผลรอบสายระบายด้วยเทคนิคปลอดเชื้อ\r\n- ตรวจสอบระบบสุญญากาศ (Vacuum) ของขวด/กระเปาะระบาย (Redivac / Hemovac / Jackson-Pratt)\r\n- เทสารคัดหลั่ง บันทึกปริมาณ สี และลักษณะ (Serous, Serosanguinous, Sanguinous)\r\n- ติดเข็มกลัดยึดสายระบายกับเสื้อผ้าผู้ป่วย ป้องกันการดึงรั้งขณะฝึกเดินหรือทำกายภาพ\r\n[⛅ เวรบ่าย]\r\n- ตรวจสอบการไหลของสายระบาย ไม่ให้สายหักพับงอหรือมีลิ่มเลือดอุดตัน\r\n- สังเกตปริมาณเลือดที่ออก หากออก \u003e 100 ml/hr ติดต่อกัน 2 ชม. ให้รายงานแพทย์ทันที\r\n- ตรวจสอบขวดสุญญากาศให้คงสภาพแรงดูดอย่างต่อเนื่อง\r\n[🌙 เวรดึก]\r\n- จัดวางขวดสายระบายให้อยู่ในระดับต่ำกว่าแผลผ่าตัดเสมอ และไม่ให้สายดึงรั้งขณะนอนหลับ\r\n- บันทึกและสรุปยอดปริมาณสารคัดหลั่งจากสายระบายสะสมรอบ 24 ชั่วโมงลงในชาร์ต\r\n- ส่งต่อข้อมูลยอดรวมเลือดจากสายระบายให้แพทย์ประเมินการถอดสายระบาย (Off drain) ในรอบเช้า\r\nResponse: สายระบายไม่หักพับงอ การระบายไหลสะดวก สารคัดหลั่งออกลดลง แผลรอบสายระบายไม่มีอาการบวมแดงหรือมีหนอง\r\n---\r\n.wound = ตรวจประเมินแผลผ่าตัดแห้งดี (Wound Clean \u0026 Dry)\r\nFocus: แผลผ่าตัดสะอาด ไม่มีสัญญาณการติดเชื้อ\r\nGoal: แผลผ่าตัดสมานตัวดี ขอบแผลแนบสนิท แห้งสะอาด ไม่มีเลือดหรือหนองซึมเปื้อน และไม่เกิดการติดเชื้อที่แผลผ่าตัด (SSI)\r\nData: แผลผ่าตัดบริเวณ... ปิดแผลเรียบร้อย ขอบแผลเย็บแนบสนิทดี (Well-approximated)\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินแผลผ่าตัด: ขอบแผล รอยเย็บ อาการบวม แดง ร้อน\r\n- ทำแผล (Wound dressing) ด้วย Normal Saline และยึดหลัก Aseptic technique\r\n- ปิดแผลด้วยผ้าก๊อซสะอาดหรือพลาสเตอร์กันน้ำตามแผนการรักษา\r\n- ให้คำแนะนำผู้ป่วยระวังไม่ให้แผลเปียกน้ำหรือสัมผัสสิ่งสกปรก\r\n[⛅ เวรบ่าย]\r\n- ตรวจเช็คผ้าปิดแผล สังเกตมีเลือดหรือสารคัดหลั่งซึมเปื้อนผ้าก๊อซด้านนอก (Reinforce if needed)\r\n- ประเมินอาการปวดตึงหรือแสบร้อนบริเวณแผล\r\n- ดูแลความสะอาดของเสื้อผ้าและผ้าปูเตียงไม่ให้สัมผัสเสียดสีกับแผล\r\n[🌙 เวรดึก]\r\n- ตรวจสอบผ้าปิดแผลไม่ให้เลื่อนหลุดขณะผู้ป่วยพลิกตัวเวลานอน\r\n- เฝ้าระวังอาการไข้สูง หนาวสั่น ซึ่งอาจเป็นสัญญาณเริ่มต้นของการติดเชื้อที่แผล\r\n- สรุปและบันทึกลักษณะแผลเพื่อรายงานส่งต่อเวรเช้า\r\nResponse: แผลผ่าตัดแห้ง สะอาดดี ไม่มีเลือดหรือสิ่งคัดหลั่งซึมเปื้อน ไม่มีรอยบวมแดง (No signs of inflammation/infection)\r\n---\r\n\r\n[2. การจัดการความปวด Pain Management (DAR)]\r\n.pain = ปวดแผลผ่าตัดเฉียบพลัน (Acute Pain: DAR)\r\nFocus: ปวดแผลผ่าตัดเฉียบพลัน (Acute Post-Op Pain)\r\nGoal: ผู้ป่วยสุขสบายขึ้น ระดับความปวดลดลง Pain score ≤ 3/10 สามารถพักผ่อนได้ และไม่มีผลข้างเคียงจากยาบรรเทาปวด\r\nData: ผู้ป่วยบ่นปวดแผลผ่าตัด Pain score = .../10, หน้าตานิ่ว ร้องคราง ขยับตัวลำบาก, V/S: BP.../... mmHg, PR... /min\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินตำแหน่ง ลักษณะ และระดับความปวด (Pain score 0-10) ก่อนและหลังทำกิจกรรม\r\n- ให้ยาแก้ปวดตามแผนการรักษาก่อนเริ่มทำกายภาพบำบัด/ทำแผล 30 นาที\r\n- สอนเทคนิคการหายใจช้าๆ ลึกๆ ผ่อนคลายกล้ามเนื้อ (Deep breathing) และการประคองแผลเวลาเคลื่อนไหว\r\n- จัดท่านอนและใช้อุปกรณ์หนุนรองเพื่อผ่อนคลายกล้ามเนื้อรอบแผล\r\n[⛅ เวรบ่าย]\r\n- ประเมินระดับความปวดซ้ำหลังเสร็จสิ้นกิจกรรมประจำวัน/กายภาพบำบัด\r\n- ดูแลให้ยาบรรเทาปวดชนิดฉีด/รับประทาน หรือปรับอัตราเครื่องให้ยาแก้ปวดทางหลอดเลือดดำ (PCA) ตามคำสั่งแพทย์\r\n- ใช้วิธีไม่ใช้ยาเสริม: ประคบเย็น/ประคบอุ่นตามข้อบ่งชี้ จัดท่าทางให้สุขสบาย\r\n- ประเมินอาการข้างเคียงของยาแก้ปวด (ง่วงซึม, คลื่นไส้, ความดันตก, ท้องอืด)\r\n[🌙 เวรดึก]\r\n- ประเมินความปวดช่วงกลางคืนเพื่อป้องกันการตื่นจากความเจ็บปวด\r\n- ดูแลให้ยาแก้ปวดก่อนนอน (Bedtime analgesics) ตามแผน เพื่อส่งเสริมการนอนหลับต่อเนื่อง\r\n- จัดสิ่งแวดล้อมให้เงียบสงบ ผ่อนคลาย ลดแสงไฟรบกวน\r\n- เฝ้าระวังภาวะกดการหายใจ (Respiratory depression) จากยากลุ่ม Opioids บันทึก RR สม่ำเสมอ\r\nResponse: หลังให้การพยาบาลและได้รับยา 30 นาที ผู้ป่วยบอกอาการปวดทุเลาลง Pain score ลดลงเหลือ.../10, สีหน้าผ่อนคลาย สามารถนอนหลับพักผ่อนได้\r\n---\r\n.painbreak = ปวดรุนแรงแทรกซ้อนฉับพลัน (Breakthrough Pain: DAR)\r\nFocus: มีอาการปวดรุนแรงแทรกซ้อนขึ้นมาฉับพลัน (Breakthrough pain)\r\nGoal: ได้รับการบรรเทาความปวดอย่างรวดเร็ว อาการปวดกำเริบลดลงเหลือ Pain score ≤ 3/10 ภายใน 30 นาทีหลังได้ยาเสริม\r\nData: ผู้ป่วยมีอาการปวดกำเริบเฉียบพลัน Pain score พุ่งสูงขึ้นเป็น.../10 เหงื่อแตก กระสับกระส่าย ไม่สามารถทนต่อความปวดได้\r\nAction:\r\n- รายงานแพทย์เวรรับทราบอาการ\r\n- ดูแลให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough dose)... ทางหลอดเลือดดำตามคำสั่งแพทย์\r\n- เฝ้าระวังผลข้างเคียงของยา (ง่วงซึม, อัตราการหายใจ)\r\n- อยู่เป็นเพื่อนให้กำลังใจและช่วยนวดผ่อนคลาย\r\nResponse: หลังได้รับยาเสริม 15-20 นาที ระดับความปวดลดลงเหลือ.../10, V/S คงที่ ไม่มีภาวะกดการหายใจ (RR... /min)\r\n---\r\n.painchronic = ปวดเรื้อรังจากพยาธิสภาพของโรค (Chronic Pain)\r\nFocus: ปวดเรื้อรังจากพยาธิสภาพของกระดูกและข้อ (Chronic Pain)\r\nGoal: ควบคุมระดับความปวดให้อยู่ในเกณฑ์ที่ผู้ป่วยทนได้ สามารถนอนหลับพักผ่อนและเคลื่อนไหวทำกิจวัตรประจำวันได้ดีขึ้น\r\nData: ผู้ป่วยบอกมีอาการปวดตื้อๆ บริเวณ... เป็นๆ หายๆ Pain score = .../10, รบกวนการทำกิจวัตรประจำวันและการนอนหลับ\r\nAction:\r\n- ประเมินปัจจัยที่กระตุ้นให้ปวดและปัจจัยที่ช่วยบรรเทา\r\n- ให้ยาตามเวลา (Around-the-clock) ตามแผนการรักษา\r\n- แนะนำการประคบอุ่น/เย็น\r\n- จัดสิ่งแวดล้อมให้เงียบสงบเอื้อต่อการพักผ่อน\r\nResponse: ผู้ป่วยปรับตัวต่อความปวดได้ดีขึ้น มีระดับความปวดอยู่ในเกณฑ์ที่ยอมรับได้ (Pain score \u003c 3/10) นอนหลับได้ต่อเนื่อง\r\n---\r\n\r\n[3. ศัลยกรรมกระดูกและข้อ (Orthopedic Nursing)]\r\n.ortho = ตรวจระบบประสาทและการไหลเวียนส่วนปลาย 5Ps (Neurovascular Check)\r\nFocus: เสี่ยงต่อภาวะการไหลเวียนโลหิตและระบบประสาทส่วนปลายบกพร่อง (Impaired Neurovascular Function)\r\nGoal: การไหลเวียนโลหิตและประสาทรับรู้ส่วนปลายปกติ ปลายเท้า/มืออุ่น สีชมพู CRT \u003c 2 วินาที คลำชีพจรได้ชัดเจน และไม่เกิดภาวะ Compartment syndrome\r\nData: ผู้ป่วยหลังผ่าตัด/มีกระดูกหักบริเวณ... ปลายรยางค์มีอาการตึงบวมเล็กน้อย\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมิน 5Ps และ CMS check (Color, Motion, Sensation, Pulse, Temp) ปลายมือ/เท้า\r\n- ตรวจ Capillary refill time (CRT \u003c 2 วินาที) และคลำชีพจรส่วนปลาย (Dorsalis pedis / Radial pulse)\r\n- กระตุ้นให้ผู้ป่วยบริหารกระดกข้อเท้าและขยับนิ้วมือ/นิ้วเท้า 20-30 ครั้ง/ชม.\r\n- จัดยกอวัยวะส่วนปลายให้สูงกว่าระดับหัวใจด้วยหมอนหนุนเพื่อลดบวม\r\n[⛅ เวรบ่าย]\r\n- ตรวจประเมิน CMS ซ้ำหลังผู้ป่วยเสร็จสิ้นการฝึกเดินหรือทำกายภาพบำบัด\r\n- สังเกตอาการบวมตึง ปวดรุนแรงผิดปกติ หรืออาการชา (Paresthesia) เฝ้าระวัง Compartment Syndrome\r\n- ตรวจสอบผ้าพันแผลหรือเฝือกไม่ให้รัดแน่นจนเกินไป\r\n[🌙 เวรดึก]\r\n- ตรวจเช็คตำแหน่งหมอนหนุนยกขาสูงไม่ให้เลื่อนหลุดขณะนอนหลับ\r\n- ตรวจประเมินความอุ่นและสีผิวปลายเท้า/ปลายมือรอบดึก\r\n- เฝ้าระวังอาการปวดตึงรุนแรงตอนดึกที่ปลุกให้ผู้ป่วยตื่น รายงานแพทย์ทันทีหากสงสัย Compartment syndrome\r\nResponse: ปลายรยางค์อุ่น สีชมพู ชีพจร 2+ คลำได้ชัดเจน, CRT \u003c 2 วินาที, การรับความรู้สึกปกติ ขยับนิ้วได้ดี ไม่มีอาการชาหรือปวดตึงผิดปกติ (No Compartment syndrome)\r\n---\r\n.cast = การดูแลผู้ป่วยใส่เฝือก/ดามกระดูก (Cast \u0026 Splint Care)\r\nFocus: เสี่ยงต่อการเกิดแผลกดทับและเนื้อเยื่อขาดเลือดจากการใส่เฝือก\r\nGoal: เฝือกคงรูปดี ไม่แตกหัก ไม่กดทับเนื้อเยื่อ ไม่เกิดแผลกดทับใต้เฝือก การไหลเวียนโลหิตส่วนปลายปกติ และผู้ป่วยดูแลเฝือกได้ถูกต้อง\r\nData: ผู้ป่วยใส่เฝือก (Cast / Splint / Slab) บริเวณ...\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจสอบสภาพเฝือก: แข็งแรง แห้งดี ไม่แตกหัก ไม่เปียกชื้น และไม่หลวมหรือรัดแน่นเกินไป\r\n- ตรวจขอบเฝือกไม่ให้เสียดสีหรือกดทับผิวหนัง (Pad ขอบเฝือกหากจำเป็น)\r\n- สอนและกระตุ้นการเกร็งกล้ามเนื้อใต้เฝือก (Isometric exercise) เพื่อคงสภาพกล้ามเนื้อ\r\n- แนะนำห้ามนำสิ่งแปลกปลอมแคะเกาในเฝือก ระวังไม่ให้เฝือกเปียกน้ำ\r\n[⛅ เวรบ่าย]\r\n- ตรวจประเมิน 5Ps และ CMS check ปลายรยางค์อย่างละเอียด (ปวด บวม ชา เย็น สีคล้ำ)\r\n- จัดยกอวัยวะส่วนที่ใส่เฝือกให้สูงกว่าระดับหัวใจด้วยหมอนหนุนเพื่อลดอาการบวมตึง\r\n- ประเมินระดับความปวด หากมีอาการปวดแสบร้อนใต้เฝือกหรือปวดตึงรุนแรงให้รายงานแพทย์\r\n[🌙 เวรดึก]\r\n- จัดตำแหน่งหมอนหนุนยกขาสูง/แขนสูงไม่ให้เลื่อนหลุดขณะนอนหลับ\r\n- ตรวจสอบการระบายอากาศและระวังขอบเฝือกกดทับผิวหนังเวลานอน\r\n- เฝ้าระวังอาการปวดตึงรุนแรงรอบดึก (Pain out of proportion) เฝ้าระวัง Compartment Syndrome\r\nResponse: เฝือกแห้งและอยู่ในสภาพดี ปลายรยางค์อุ่น ขยับนิ้วได้คล่อง ไม่บ่นชาหรือปวดแสบร้อนใต้เฝือก\r\n---\r\n.traction = การดูแลผู้ป่วยดึงถ่วงน้ำหนัก (Traction Care)\r\nFocus: ดูแลประสิทธิภาพการดึงถ่วงน้ำหนักและป้องกันภาวะแทรกซ้อน\r\nGoal: กระดูกอยู่ในแนวแรงดึงที่ถูกต้อง (Alignment) สายดึงถ่วงทำงานมีประสิทธิภาพ ตำแหน่ง Pin site สะอาด ไม่ติดเชื้อ และไม่เกิดแผลกดทับ\r\nData: ผู้ป่วยได้รับการดึงถ่วงน้ำหนัก (Skin / Skeletal traction) บริเวณ... น้ำหนักถ่วง... กิโลกรัม\r\nAction:\r\n- ตรวจสอบเชือกดึงถ่วงน้ำหนักให้อยู่ในร่องรอก ไม่พันกัน, ลูกตุ้มน้ำหนักลอยแขวนอิสระไม่แตะพื้น\r\n- จัดท่าผู้ป่วยให้อยู่ในแนวตรงตามแนวแรงดึง (Body alignment)\r\n- ตรวจสอบผิวหนังและตำแหน่ง Pin site ทำความสะอาดด้วยเทคนิคปลอดเชื้อทุกวัน\r\nResponse: แนวการดึงถูกต้อง น้ำหนักถ่วงคงที่ Pin site แห้งสะอาด ไม่มีสิ่งคัดหลั่งซึมหรืออักเสบติดเชื้อ\r\n---\r\n.mobility = บกพร่องในการเคลื่อนไหวร่างกาย (Impaired Physical Mobility)\r\nFocus: บกพร่องในการเคลื่อนไหวร่างกายเนื่องจากกระดูกหัก/มีข้อจำกัดการลงน้ำหนัก\r\nGoal: ผู้ป่วยสามารถเคลื่อนไหว พลิกตัว และใช้อุปกรณ์ช่วยเดินได้อย่างปลอดภัย ถูกต้องตามแผนการรักษา และไม่เกิดอุบัติเหตุหกล้ม\r\nData: ผู้ป่วยเคลื่อนไหวลำบาก ช่วยเหลือตนเองบนเตียงได้บางส่วน ต้องใช้ไม้ค้ำยัน/Walker\r\nAction:\r\n- ช่วยเหลือในการทำกิจวัตรประจำวัน, ช่วยพลิกตะแคงตัวสลับข้างทุก 2 ชั่วโมง\r\n- สอนการบริหารข้อต่อและกล้ามเนื้อส่วนที่ไม่ได้บาดเจ็บ\r\n- ฝึกสอนการใช้อุปกรณ์ช่วยเดิน (Walker / Crutches) ตามระดับการลงน้ำหนักที่แพทย์กำหนด (NWB / PWB)\r\n- ประเมินความปลอดภัยขณะเคลื่อนไหว\r\nResponse: ผู้ป่วยเข้าใจและปฏิบัติตามคำแนะนำในการฝึกเดินได้อย่างถูกต้อง ปลอดภัย ไม่เกิดอุบัติเหตุ\r\n---\r\n\r\n[4. การพยาบาลอายุรกรรม (Internal Medicine Nursing)]\r\n.chf = หัวใจล้มเหลวและน้ำท่วมปอด (Heart Failure / Pulmonary Edema)\r\nFocus: ภาวะน้ำเกินและเหนื่อยหอบจากหัวใจล้มเหลว (Fluid Overload / CHF)\r\nGoal: ภาวะน้ำคั่งลดลง อาการหอบเหนื่อยทุเลา หายใจสะดวกขึ้น SpO2 ≥ 95% ไม่มีอาการบวม และปริมาณน้ำเข้า-ออกสมดุล\r\nData: ผู้ป่วยบ่นหายใจเหนื่อยหอบ นอนราบไม่ได้ (Orthopnea), หายใจเร็ว RR... /min, SpO2... %, ฟังปอดได้ยินเสียง Crepitation ชายปอดทั้ง 2 ข้าง, ขาทั้ง 2 ข้างบวมกดบุ๋ม (Pitting edema 2+), เส้นเลือดดำที่คอโป่งพอง (JVD positive)\r\nAction:\r\n- จัดท่านอนศีรษะสูง (High-Fowler\u0027s position)\r\n- ให้ออกซิเจน Mask with bag / Cannula ตามแผนการรักษา\r\n- ให้ยาขับปัสสาวะ Lasix (Furosemide)... mg IV ตามคำสั่งแพทย์\r\n- จำกัดน้ำดื่ม... ml/วัน และจำกัดอาหารเค็ม (Low salt diet)\r\n- บันทึก Intake-Output อย่างเคร่งครัด\r\n- ชั่งน้ำหนักตัวทุกเช้า\r\nResponse: ปัสสาวะออกเพิ่มขึ้น... ml หลังได้ยาขับปัสสาวะ, ผู้ป่วยหายใจเหนื่อยลดลง RR... /min, SpO2 เพิ่มขึ้นเป็น... %, ฟังปอดเสียง Crepitation ลดลง นอนพักได้\r\n---\r\n.acs = กล้ามเนื้อหัวใจขาดเลือดเฉียบพลัน แน่นหน้าอก (ACS / Myocardial Infarction)\r\nFocus: เจ็บแน่นหน้าอกเฉียบพลันจากกล้ามเนื้อหัวใจขาดเลือด (Acute Chest Pain / ACS)\r\nGoal: บรรเทาอาการเจ็บแน่นหน้าอก กล้ามเนื้อหัวใจได้รับออกซิเจนเพียงพอ สัญญาณชีพและคลื่นไฟฟ้าหัวใจคงที่ และไม่เกิดภาวะแทรกซ้อนรุนแรง\r\nData: ผู้ป่วยบอกเจ็บแน่นหน้าอกตรงกลางเหมือนมีของหนักทับ ร้าวไปกรามและแขนซ้าย Pain score = .../10, เหงื่อแตก ตัวเย็น กระสับกระส่าย, V/S: BP.../... mmHg, PR... /min\r\nAction:\r\n- ให้ผู้ป่วยนอนพักนิ่งบนเตียง (Absolute bed rest)\r\n- ให้ออกซิเจน Cannula 3-4 LPM\r\n- รายงานแพทย์ทันที\r\n- ทำ EKG 12 leads ส่งแพทย์อ่านผล\r\n- ดูแลให้ยา Isordil (Isosorbide dinitrate) 5 mg อมใต้ลิ้นทันที และให้ยาตามแผนการรักษา (Aspirin, Clopidogrel, Morphine)\r\n- เจาะเลือดส่งตรวจ Cardiac markers (Troponin-T/I, CK-MB)\r\nResponse: หลังได้รับยาและนอนพัก อาการแน่นหน้าอกทุเลาลง Pain score ลดลงเหลือ.../10, EKG ไม่พบ ST elevation เพิ่มขึ้น, สัญญาณชีพคงที่ เฝ้าระวังอาการต่อเนื่อง\r\n---\r\n.htn = ความดันโลหิตสูงวิกฤต (Hypertensive Urgency / Crisis)\r\nFocus: ความดันโลหิตสูงรุนแรงเสี่ยงต่อภาวะแทรกซ้อนทางหลอดเลือดสมองและหัวใจ\r\nGoal: ควบคุมความดันโลหิตให้อยู่ในเกณฑ์เป้าหมายตามแผนการรักษา (\u003c 140/90 mmHg หรือตามแพทย์สั่ง) และไม่เกิดภาวะแทรกซ้อนทางสมองและหัวใจ\r\nData: วัดความดันโลหิตได้สูงมาก BP = .../... mmHg (SBP \u003e 180 หรือ DBP \u003e 110), บ่นปวดศีรษะตึงบริเวณท้ายทอย ตาพร่ามัว เวียนศีรษะ คลื่นไส้\r\nAction:\r\n- ให้ผู้ป่วยนอนพักผ่อนบนเตียงในสิ่งแวดล้อมที่เงียบสงบ\r\n- ดูแลให้ยาลดความดันโลหิต... ตามแผนการรักษาของแพทย์\r\n- ประเมินอาการทางระบบประสาท (Neuro sign) ตรวจเช็คการพูด แขนขาอ่อนแรง\r\n- วัดและบันทึกสัญญาณชีพซ้ำทุก 15-30 นาที\r\nResponse: ความดันโลหิตค่อยๆ ลดลงสู่ระดับเป้าหมาย BP = .../... mmHg, อาการปวดศีรษะและตาพร่ามัวทุเลาลง ไม่มีอาการแขนขาอ่อนแรง\r\n---\r\n.copd = ปอดอุดกั้นเรื้อรัง/หอบหืดกำเริบเฉียบพลัน (COPD / Asthma Exacerbation)\r\nFocus: หายใจลำบากและแลกเปลี่ยนก๊าซบกพร่องจากหลอดลมตีบเกร็ง\r\nGoal: การระบายอากาศดีขึ้น อาการหอบเหนื่อยลดลง ขับเสมหะได้ SpO2 อยู่ในเกณฑ์ 88-92% และไม่มีภาวะคาร์บอนไดออกไซด์คั่ง\r\nData: ผู้ป่วยหายใจหอบเหนื่อย ใช้กล้ามเนื้อช่วยหายใจ (Accessory muscle use), อัตราการหายใจ RR... /min, SpO2... %, ฟังปอดได้ยินเสียง Wheezing ทั้งสองข้าง, ไอมีเสมหะเหนียว\r\nAction:\r\n- จัดท่านอนศีรษะสูงหรือนั่งโน้มตัวไปข้างหน้า (Tripod position)\r\n- ให้ออกซิเจน Low flow (Venturi mask หรือ Cannula 1-2 LPM ควบคุม SpO2 88-92%)\r\n- พ่นยาขยายหลอดลม (Berodual / Ventolin + Atrovent) ตามแผนการรักษา\r\n- ให้ยา Corticosteroid IV ตามคำสั่งแพทย์\r\n- สอนการหายใจแบบห่อปาก (Pursed-lip breathing)\r\nResponse: หายใจหอบเหนื่อยลดลง การใช้กล้ามเนื้อช่วยหายใจลดลง, SpO2 อยู่ในเกณฑ์เป้าหมาย... %, ฟังปอดเสียง Wheezing ทุเลาลง หายใจโล่งขึ้น\r\n---\r\n.pneumonia = ปอดอักเสบติดเชื้อ (Pneumonia)\r\nFocus: ติดเชื้อในระบบทางเดินหายใจและมีเสมหะคั่งค้าง\r\nGoal: ทางเดินหายใจโล่ง ขับเสมหะได้ดี ไข้ลดลง อาการหอบเหนื่อยทุเลา SpO2 ≥ 95% และผลตรวจทางห้องปฏิบัติการ/ภาพรังสีปอดดีขึ้น\r\nData: มีไข้สูง T... °C, ไอมีเสมหะข้นเหนียวสีเขียว/เหลือง, หายใจเหนื่อย หายใจเร็ว, ฟังปอดได้ยินเสียง Crepitation ชายปอด, ผล CXR พบ Infiltration บริเวณ...\r\nAction:\r\n- จัดท่านอนศีรษะสูง, เคาะปอดระบายเสมหะและสอนการไอขับเสมหะอย่างมีประสิทธิภาพ\r\n- ให้ออกซิเจนตามแผนการรักษา\r\n- ดูแลให้ยาปฏิชีวนะ (Antibiotics)... ทางหลอดเลือดดำตรงเวลาสม่ำเสมอ\r\n- เช็ดตัวลดไข้เมื่ออุณหภูมิ \u003e 38.5 °C\r\n- กระตุ้นให้ดื่มน้ำอุ่นวันละ 2,000 ml\r\nResponse: ไข้ลดลง เสมหะขับออกได้ง่ายขึ้น สีจางลงและเหนียวน้อยลง, SpO2 = ... %, อาการเหนื่อยหอบลดลง\r\n---\r\n.dka = ภาวะน้ำตาลในเลือดสูงวิกฤต (DKA / Hyperglycemia)\r\nFocus: ภาวะน้ำตาลในเลือดสูงรุนแรงและกรดคีโตนคั่งในร่างกาย (DKA / HHS)\r\nGoal: ระดับน้ำตาลในเลือดลดลงสู่เกณฑ์ปลอดภัย ภาวะกรดคีโตนในเลือดดีขึ้น สารน้ำและเกลือแร่กลับสู่สมดุล และผู้ป่วยรู้สึกตัวดี\r\nData: ผู้ป่วยซึมลง หายใจเร็วลึก (Kussmaul breathing) มีกลิ่นลมหายใจคล้ายผลไม้ (Fruity odor), ผิวหนังแห้ง ริมฝีปากแห้ง, ตรวจ DTX = ... mg/dL, Urine ketone/sugar positive, V/S: BP.../... mmHg, PR... /min\r\nAction:\r\n- รายงานแพทย์ทันที\r\n- เปิดเส้นเลือดดำให้สารน้ำ 0.9% NSS ในอัตราเร็วตามแผนการรักษาเพื่อแก้ไขภาวะขาดน้ำ\r\n- ให้ยาฉีดอินซูลิน Regular Insulin (RI) ทางหลอดเลือดดำตามแพทย์สั่ง\r\n- บันทึกสัญญาณชีพและเจาะตรวจ DTX ทุก 1 ชั่วโมง\r\n- ติดตามผลตรวจระดับเกลือแร่ (Electrolyte โดยเฉพาะ Potassium) และค่าก๊าซในเลือด (ABG)\r\n- บันทึก Intake-Output ทุกชั่วโมง\r\nResponse: ระดับน้ำตาลในเลือด DTX ค่อยๆ ลดลงสู่ระดับ... mg/dL, ภาวะขาดน้ำทุเลาลง ปัสสาวะออกดี (\u003e 0.5 ml/kg/hr), ผู้ป่วยรู้สึกตัวตื่นขึ้น หายใจเร็วลึกลดลง\r\n---\r\n.hypo = ภาวะน้ำตาลในเลือดต่ำ (Hypoglycemia)\r\nFocus: ภาวะน้ำตาลในเลือดต่ำเสี่ยงต่อการหมดสติและสมองขาดพลังงาน\r\nGoal: ระดับน้ำตาลในเลือด DTX กลับสู่เกณฑ์ปกติ (≥ 100 mg/dL) อาการใจสั่น มือสั่น เหงื่อแตก ซึมทุเลาลง และผู้ป่วยปลอดภัย\r\nData: ผู้ป่วยรู้สึกใจสั่น มือสั่น เหงื่อแตกท่วมตัว หน้าซีด อ่อนเพลีย สับสน พูดไม่ชัด, ตรวจ DTX = ... mg/dL (ต่ำกว่า 70 mg/dL)\r\nAction: ให้การพยาบาลแก้ไขตามเกณฑ์ Rule of 15 ทันที:\r\n* กรณีรู้สึกตัวดี: ให้ดื่มน้ำหวาน/น้ำผลไม้ 1 แก้ว (150-200 ml) หรือน้ำหวานเข้มข้น 1 ช้อนโต๊ะ\r\n* กรณีซึม/ไม่รู้สึกตัว/NPO: รีบรายงานแพทย์และให้ 50% Glucose 50 ml ทางหลอดเลือดดำทันที\r\nตรวจวัดระดับน้ำตาล DTX ซ้ำหลังให้การดูแล 15 นาที, ประเมินอาการทางระบบประสาทอย่างใกล้ชิด\r\nResponse: ตรวจ DTX ซ้ำได้... mg/dL (\u003e 100 mg/dL), ผู้ป่วยรู้สึกตัวดี อาการใจสั่น มือสั่น เหงื่อแตกทุเลาลง ปลอดภัยดี\r\n---\r\n.ckd = ไตวายเรื้อรัง/บวมน้ำและของเสียคั่ง (CKD / Uremia)\r\nFocus: ภาวะบวมน้ำและสารน้ำคั่งค้างเนื่องจากไตทำงานบกพร่อง (Fluid Retention in CKD)\r\nGoal: ปริมาณน้ำและของเสียในร่างกายสมดุล ไม่มีภาวะน้ำเกินหรือน้ำท่วมปอด เกลือแร่ในเลือดอยู่ในเกณฑ์ปลอดภัย และชะลอการเสื่อมของไต\r\nData: ผู้ป่วยมีประวัติโรคไตเรื้อรัง (CKD Stage...), ขาบวมกดบุ๋มทั้งสองข้าง Pitting edema 2+, ปัสสาวะออกน้อย... ml/วัน, ค่า eGFR... , Cr... , BUN... , K+...\r\nAction:\r\n- บันทึกปริมาณน้ำเข้า-ออก (Intake-Output) อย่างเข้มงวด\r\n- จำกัดปริมาณน้ำดื่มตามแพทย์สั่ง (... ml/วัน)\r\n- ให้สุขศึกษาจำกัดอาหารที่มีโพแทสเซียมสูง (กล้วย ส้ม มะเขือเทศ) โซเดียมสูง และฟอสฟอรัสสูง\r\n- ชั่งน้ำหนักตัวเวลาเดียวกันทุกเช้า\r\n- ดูแลให้ยาขับปัสสาวะ/ยาจับฟอสฟอรัสตามแผนการรักษา\r\nResponse: ผู้ป่วยและญาติปฏิบัติตามการจำกัดน้ำและอาหารได้ดี น้ำหนักตัวไม่เพิ่มขึ้น ไม่มีอาการเหนื่อยหอบ ปัสสาวะออกได้ต่อเนื่อง\r\n---\r\n.hd = การพยาบาลผู้ป่วยฟอกเลือดด้วยเครื่องไตเทียม (Hemodialysis Care)\r\nFocus: การดูแลหลอดเลือดสำหรับฟอกเลือดและเฝ้าระวังภาวะแทรกซ้อนหลังฟอกเลือด\r\nGoal: การฟอกเลือดดำเนินไปด้วยความราบรื่นและปลอดภัย เส้นฟอกเลือด (AVF/AVG) ใช้งานได้ดี มี Thrill/Bruit ชัดเจน และไม่เกิดภาวะความดันตกหลังฟอกเลือด\r\nData: ผู้ป่วยได้รับการฟอกเลือดด้วยเครื่องไตเทียม (Hemodialysis) ผ่านเส้นฟอกเลือด (AVF / AVG / Double lumen catheter)\r\nAction:\r\n- ตรวจคลำการสั่นสะเทือน (Thrill) และฟังเสียงฟู่ (Bruit) บริเวณเส้นฟอกเลือดทุกเวร\r\n- ห้ามวัดความดันโลหิต ห้ามเจาะเลือด หรือให้สารน้ำบริเวณแขนข้างที่มีเส้นฟอกเลือด\r\n- สังเกตตำแหน่งเข็มฟอกเลือดไม่มีเลือดซึมหรือบวมช้ำ, หลังฟอกเลือดตรวจวัดสัญญาณชีพเฝ้าระวังความดันโลหิตต่ำ (Post-HD Hypotension)\r\nResponse: เส้นฟอกเลือด Thrill/Bruit ชัดเจนดี แผลฟอกเลือดไม่มีเลือดซึม สัญญาณชีพหลังฟอกเลือดคงที่ ไม่มีอาการเวียนศีรษะหรือตะคริว\r\n---\r\n.ugib = เลือดออกในทางเดินอาหารส่วนบน (Upper GI Bleed)\r\nFocus: เสี่ยงต่อภาวะช็อกจากการสูญเสียเลือดในระบบทางเดินอาหาร\r\nGoal: ภาวะเลือดออกในทางเดินอาหารหยุด สัญญาณชีพคงที่ ไม่มีอาการอาเจียนเป็นเลือดหรือถ่ายดำเพิ่ม และระดับฮีโมโกลบินคงที่\r\nData: ผู้ป่วยถ่ายอุจจาระเป็นสีดำเหนียวคล้ายยางมะตอย (Melena) / อาเจียนเป็นเลือดสดหรือสีกาแฟ (Hematemesis), หน้าซีด เหงื่อแตก ตัวเย็น, V/S: BP.../... mmHg, PR... /min, ค่า Hb/Hct...\r\nAction:\r\n- ให้ผู้ป่วยนอนพักบนเตียง ยกปลายเท้าสูงเล็กน้อย\r\n- ให้ออกซิเจนตามแผนการรักษา\r\n- ใส่สายยางทางจมูกถึงกระเพาะอาหาร (NG tube) ดูแล Gastric lavage ด้วยน้ำเย็นตามคำสั่งแพทย์และบันทึกสี/ปริมาณ\r\n- เปิดเส้นเลือดดำขนาดใหญ่ให้สารน้ำและเตรียมจองเลือด (PRC)\r\n- ให้ยา Proton Pump Inhibitor (Omeprazole/Pantoprazole) IV ตามคำสั่ง\r\n- งดน้ำและอาหาร (NPO)\r\nResponse: เลือดสดจากการ Lavage จางลง, ได้รับสารน้ำและเลือดทดแทน สัญญาณชีพคงที่ BP.../... mmHg, PR... /min\r\n---\r\n.cirrhosis = ตับแข็งและภาวะท้องมาน (Cirrhosis \u0026 Ascites)\r\nFocus: ภาวะท้องมานและเสี่ยงต่อการเกิดภาวะสมองทำงานบกพร่องจากตับวาย (Hepatic Encephalopathy)\r\nGoal: ลดการคั่งของน้ำในช่องท้อง (Ascites) ไม่มีภาวะเลือดออกในทางเดินอาหาร สติสัมปชัญญะคงที่ ไม่เกิดภาวะ Hepatic encephalopathy\r\nData: ท้องมานโต ตึง แน่นอึดอัดท้อง หายใจไม่สะดวก, ตาเหลือง ตัวเหลือง (Jaundice), ประเมินระดับความรู้สึกตัว (Orientation to time, place, person)\r\nAction:\r\n- วัดขนาดรอบเอว (Abdominal girth) และชั่งน้ำหนักทุกวัน\r\n- จัดท่านอนศีรษะสูงเพื่อช่วยให้กระบังลมขยายตัวหายใจสะดวกขึ้น\r\n- จำกัดโซเดียมและน้ำดื่มตามแผนการรักษา\r\n- ดูแลให้ยาขับปัสสาวะและยาระบาย Lactulose เพื่อขับสารแอมโมเนีย\r\n- ประเมินอาการสับสน มือสั่นกระตุก (Asterixis / Flapping tremor)\r\nResponse: ผู้ป่วยรู้สึกตัวดี สื่อสารตรงประเด็น ไม่มีอาการสับสน มือไม่สั่น, รอบเอวลดลงเหลือ... cm, หายใจเหนื่อยลดลง\r\n---\r\n.stroke = โรคหลอดเลือดสมองเฉียบพลัน (Acute Stroke / CVA)\r\nFocus: การทำงานของระบบประสาทบกพร่องเนื่องจากสมองขาดเลือดหรือมีเลือดออกในสมอง\r\nGoal: ควบคุมความดันโลหิตและสัญญาณประสาทให้คงที่ ป้องกันเนื้อสมองขาดเลือดเพิ่ม ไม่เกิดภาวะสำลัก และฟื้นฟูสมรรถภาพการเคลื่อนไหว\r\nData: ผู้ป่วยมีอาการแขนขาข้าง... อ่อนแรง (Motor power grade...), ปากเบี้ยว พูดไม่ชัด กลืนลำบาก, ระดับความรู้สึกตัว GCS = ... คะแนน (E... V... M...)\r\nAction:\r\n- จัดท่านอนศีรษะสูง 30 องศา (Head up 30 degrees) แนวคอตรงไม่พับงอ\r\n- ตรวจประเมินสัญญาณทางระบบประสาท (Neuro sign) และ GCS ทุก... ชม.\r\n- เฝ้าระวังและควบคุมความดันโลหิตให้อยู่ในเกณฑ์ที่แพทย์กำหนด\r\n- ทดสอบการกลืน (Swallowing test) ก่อนให้อาหาร/น้ำเพื่อป้องกันการสำลักลงปอด (Aspiration)\r\n- พลิกตะแคงตัวและจัดวางแขนขาข้างที่อ่อนแรงในท่าที่ถูกต้อง (Functional position)\r\nResponse: สัญญาณทางระบบประสาทคงที่ GCS... คะแนน, ไม่มีอาการสำลัก, แขนขาข้างที่อ่อนแรงได้รับการจัดท่าถูกต้อง ไม่มีข้อติดแข็ง\r\n---\r\n.sepsis = ภาวะติดเชื้อในกระแสเลือด (Sepsis Hour-1 Bundle)\r\nFocus: เสี่ยงต่อภาวะช็อกจากการติดเชื้อในกระแสเลือด (Septic Shock / Hypoperfusion)\r\nGoal: สัญญาณชีพคงที่ ค่า Serum Lactate ลดลงสู่เกณฑ์ปกติ ได้รับยาปฏิชีวนะและสารน้ำครบตาม Hour-1 Bundle และป้องกันภาวะ Septic shock\r\nData: มีไข้สูง T... °C (หรือตัวเย็น T \u003c 36 °C), หายใจเร็ว RR... /min, ชีพจรเต้นเร็ว PR... /min, ความดันโลหิตเริ่มลดลง SBP... mmHg, ผลตรวจเลือดพบ WBC... , Serum Lactate... mmol/L\r\nAction: ปฏิบัติตามแนวทางการดูแลผู้ป่วย Sepsis (Hour-1 Bundle) อย่างเร่งด่วน:\r\n1. เจาะเลือดส่งตรวจ Hemoculture 2 ตำแหน่งก่อนเริ่มยาปฏิชีวนะ\r\n2. ให้ยาปฏิชีวนะทางหลอดเลือดดำ (Broad-spectrum IV Antibiotics)... ทันทีภายใน 1 ชั่วโมง\r\n3. ให้สารน้ำอย่างรวดเร็ว (Fluid resuscitation) 0.9% NSS หรือ Acetar 30 ml/kg ภายใน 3 ชั่วโมง\r\n4. ติดตามค่า Serum Lactate ซ้ำตามแผนการรักษา\r\n5. บันทึกสัญญาณชีพทุก 15-30 นาที และใส่สายสวนปัสสาวะเพื่อติดตาม Urine output ทุก 1 ชั่วโมง (เป้าหมาย \u003e 0.5 ml/kg/hr)\r\nResponse: สัญญาณชีพเริ่มคงที่หลังได้รับสารน้ำ BP = .../... mmHg (MAP \u003e 65 mmHg), ปัสสาวะออกดี... ml/hr, ได้รับยาฆ่าเชื้อตรงตามเวลา\r\n---\r\n.tb = วัณโรคปอดและการป้องกันการแพร่กระจายเชื้อ (Pulmonary TB)\r\nFocus: เสี่ยงต่อการแพร่กระจายเชื้อวัณโรคสู่ผู้อื่น (Airborne Infection)\r\nGoal: ผู้ป่วยได้รับยาต้านวัณโรคครบถ้วน อาการไอและไข้ลดลง ป้องกันการแพร่กระจายเชื้อสู่ผู้อื่น และไม่เกิดผลข้างเคียงจากยาต้านวัณโรค\r\nData: ผู้ป่วยได้รับการวินิจฉัย/สงสัยวัณโรคปอด (Pulmonary TB), ผล Sputum AFB positive, ไอเรื้อรัง มีไข้ต่ำๆ ตอนเย็น เหงื่อออกกลางคืน น้ำหนักลด\r\nAction:\r\n- จัดผู้ป่วยให้อยู่ในห้องแยกโรคความดันลบ (Negative pressure room) หรือห้องแยกเดี่ยวที่อากาศถ่ายเทสะดวก\r\n- ติดป้ายเตือนการป้องกันการติดเชื้อทางอากาศ (Airborne Precaution) หน้าห้อง\r\n- ให้ผู้ป่วยสวม Surgical mask ตลอดเวลาเมื่อต้องออกจากห้อง, บุคลากรทางการแพทย์สวมหน้ากาก N95 ทุกครั้งก่อนเข้าห้องผู้ป่วย\r\n- สอนสุขอนามัยการไอจาม (Cough etiquette) โดยใช้กระดาษชำระปิดปากและทิ้งลงในถังขยะติดเชื้อ\r\n- ดูแลให้ยารักษาวัณโรค (Anti-TB drugs) ตามแผนการรักษา\r\nResponse: ผู้ป่วยเข้าใจและปฏิบัติตามมาตรการป้องกันการแพร่เชื้อ สวมหน้ากากอนามัยถูกต้อง บุคลากรใช้อุปกรณ์ PPE ครบถ้วน\r\n---\r\n\r\n[5. ความปลอดภัยและการป้องกันภาวะแทรกซ้อน]\r\n.fall = เสี่ยงต่อการพลัดตกหกล้ม (High Risk for Falls)\r\nFocus: เสี่ยงต่อการพลัดตกหกล้ม (High Risk for Falls)\r\nGoal: ผู้ป่วยและญาติมีความตระหนักและปฏิบัติตามมาตรการป้องกันการพลัดตกหกล้ม ไม่เกิดอุบัติเหตุพลัดตกหกล้มตลอดการพักรักษาตัวในโรงพยาบาล\r\nData: ประเมิน Fall risk score = ... คะแนน (กลุ่มเสี่ยงสูง), ผู้ป่วยสูงอายุ / เคลื่อนไหวไม่คล่องตัว / ได้รับยาที่ทำให้ง่วงซึม\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินความเสี่ยงต่อการพลัดตกหกล้ม (Morse Fall Scale) ติดป้ายเตือนเสี่ยงล้มที่ข้อมือและหัวเตียง\r\n- จัดสภาพแวดล้อมรอบเตียงให้แห้ง สะอาด แสงสว่างเพียงพอ ไม่มีสายไฟหรือสิ่งกีดขวางทางเดิน\r\n- วางกริ่งเรียกพยาบาลและของใช้จำเป็นในระยะที่ผู้ป่วยเอื้อมถึงได้สะดวก\r\n- แนะนำการใช้อุปกรณ์ช่วยเดิน (Walker / ไม้เท้า) และมีเจ้าหน้าที่ช่วยประคองทุกครั้งที่ลงจากเตียง\r\n[⛅ เวรบ่าย]\r\n- ตรวจเช็คไม้กั้นเตียงยกขึ้นทั้ง 2 ข้าง และปรับระดับเตียงให้อยู่ระดับต่ำสุดพร้อมล็อกล้อเตียง\r\n- กำชับผู้ป่วยและญาติให้กดกริ่งเรียกพยาบาลทุกครั้งที่ต้องการลุกจากเตียง โดยเฉพาะเวลาไปห้องน้ำ\r\n- ตรวจสอบผู้ป่วยที่ได้รับยานอนหลับหรือยาที่มีผลต่อความดันโลหิต ให้ระวังอาการหน้ามืดเวลาเปลี่ยนท่า\r\n[🌙 เวรดึก]\r\n- ตรวจสอบไม้กั้นเตียงยกขึ้นทั้ง 2 ข้างอย่างแน่นหนา และล็อกล้อเตียงเรียบร้อย\r\n- เปิดไฟส่องสว่างนำทาง (Night light) ในห้องและทางไปห้องน้ำ ป้องกันการสะดุดล้มในความมืด\r\n- ช่วยเหลือผู้ป่วยในการขับถ่ายข้างเตียงโดยใช้ Urinal หรือ Commode chair ไม่ให้เดินไปห้องน้ำลำพัง\r\n- เดินตรวจเวรทุก 1-2 ชั่วโมง สังเกตผู้ป่วยที่กระสับกระส่ายหรือพยายามปีนไม้กั้นเตียง\r\nResponse: ผู้ป่วยและญาติเข้าใจและให้ความร่วมมือ ไม้กั้นเตียงยกขึ้นตลอดเวลา ไม่พบอุบัติเหตุพลัดตกหกล้มในเวร\r\n---\r\n.pressure = เสี่ยงต่อการเกิดแผลกดทับ (Risk for Pressure Injury)\r\nFocus: เสี่ยงต่อการเกิดแผลกดทับเนื่องจากการนอนนิ่งบนเตียงเป็นเวลานาน\r\nGoal: ผิวหนังบริเวณปุ่มกระดูกคงความสมบูรณ์ ไม่เกิดแผลกดทับรายใหม่ (Zero New Pressure Injury) และแผลเดิมได้รับการดูแลจนสมานดีขึ้น\r\nData: ประเมิน Braden Scale = ... คะแนน (กลุ่มเสี่ยงปานกลาง/สูง), ผู้ป่วยเคลื่อนไหวลำบาก นอนติดเตียง\r\nAction:\r\n- พลิกตะแคงตัวสลับซ้าย-หงาย-ขวา ทุก 2 ชั่วโมงตามตาราง\r\n- จัดหาที่นอนลมลดแรงกดทับ (Air mattress)\r\n- ดูแลผ้าปูเตียงให้สะอาด เรียบตึง และแห้งอยู่เสมอ\r\n- ใช้อุปกรณ์หนุนรองบริเวณปุ่มกระดูก (ส้นเท้า, ก้นกบ)\r\n- ทาโลชั่นบำรุงผิวหนังไม่ให้แห้งแตก\r\nResponse: ผิวหนังบริเวณก้นกบและปุ่มกระดูกต่างๆ ทั่วร่างกายเรียบเนียน ไม่มีรอยแดงหรือแผลกดทับ (Skin intact, Stage 0)\r\n---\r\n.infection = เสี่ยงต่อการติดเชื้อในระบบต่างๆ (Risk for Infection)\r\nFocus: เสี่ยงต่อการติดเชื้อเนื่องจากมีแผลผ่าตัดและอุปกรณ์คาสายในร่างกาย\r\nGoal: แผลผ่าตัดและตำแหน่งสายสวนต่างๆ สะอาด ไม่เกิดการติดเชื้อในโรงพยาบาล (Healthcare-associated infection) และสัญญาณชีพปกติ\r\nData: ผู้ป่วยมีแผลผ่าตัด, สายน้ำเกลือ (IV line), สายสวนปัสสาวะ, V/S: T... °C, PR... /min, WBC...\r\nAction:\r\n- ปฏิบัติการพยาบาลโดยยึดหลัก Aseptic technique อย่างเคร่งครัด\r\n- ล้างมือตามหลัก 5 Moments\r\n- ดูแลความสะอาดของ IV site และแผลผ่าตัด\r\n- ดูแลสายสวนปัสสาวะเป็นระบบปิด\r\n- ติดตามสัญญาณชีพและสังเกตอาการไข้ หนาวสั่น บวมแดง\r\nResponse: อุณหภูมิร่างกายปกติ ไม่มีไข้, ตำแหน่งคาสายต่างๆ แห้งสะอาด ไม่มีอาการอักเสบติดเชื้อ\r\n---\r\n.dvt = เสี่ยงต่อภาวะลิ่มเลือดอุดตันในหลอดเลือดดำส่วนลึก (Risk for DVT)\r\nFocus: เสี่ยงต่อภาวะหลอดเลือดดำส่วนลึกอุดตัน (Deep Vein Thrombosis)\r\nGoal: การไหลเวียนโลหิตในหลอดเลือดดำส่วนปลายดี ไม่มีอาการปวดบวมแดงร้อนที่น่อง และไม่เกิดภาวะลิ่มเลือดอุดตันในหลอดเลือดดำลึก (DVT / PE)\r\nData: ผู้ป่วยหลังผ่าตัดกระดูกสะโพก/ขา เคลื่อนไหวได้น้อย นอนบนเตียง\r\nAction:\r\n- สวมปลอกขาลดการคั่งของเลือด (TED stockings / IPC)\r\n- สอนและกระตุ้นให้บริหารข้อเท้า กระดกปลายเท้าขึ้น-ลง (Ankle pumping exercise) บ่อยๆ\r\n- ดูแลให้ยาป้องกันลิ่มเลือดอุดตัน (Anticoagulant) ตามคำสั่งแพทย์\r\n- สังเกตอาการปวด บวม แดง ร้อน บริเวณน่องและขา\r\nResponse: ขาทั้งสองข้างขนาดเท่ากัน ไม่มีอาการบวมแดงหรือกดเจ็บบริเวณน่อง (Homan\u0027s sign negative)\r\n---\r\n\r\n[6. สารน้ำ สารอาหาร และการขับถ่าย]\r\n.iv = การดูแลให้สารน้ำทางหลอดเลือดดำ (IV Infusion Care)\r\nFocus: ได้รับสารน้ำทางหลอดเลือดดำตามแผนการรักษา\r\nGoal: สารน้ำและยาหยดต่อเนื่องตามแผนการรักษา ตำแหน่งแทงเข็มน้ำเกลือปกติ ไม่มีอาการบวม แดง ปวด หรือรั่วซึม (Phlebitis Grade 0)\r\nData: ได้รับสารน้ำ... อัตราไหล... ml/hr ตำแหน่งเส้นเลือดดำบริเวณ...\r\nAction:\r\n- ตรวจสอบความถูกต้องของชนิดและอัตราการไหลของสารน้ำ\r\n- ตรวจประเมินตำแหน่งแทงเข็มน้ำเกลือ สังเกตอาการบวม แดง ปวด หรือน้ำเกลือซึมรั่ว (Phlebitis / Infiltration check)\r\n- บันทึก Intake-Output\r\nResponse: สารน้ำไหลสะดวกดี ไม่มีอาการปวด บวม แดง หรือเลื่อนหลุดรอบตำแหน่งแทงเข็ม\r\n---\r\n.foley = ดูแลสายสวนปัสสาวะและป้องกัน CAUTI (Foley\u0027s Catheter Care)\r\nFocus: ดูแลสายสวนปัสสาวะและป้องกันการติดเชื้อในระบบทางเดินปัสสาวะ (CAUTI Prevention)\r\nGoal: ปัสสาวะระบายไหลสะดวก ถุงและสายสวนเป็นระบบปิดสะอาด ปัสสาวะสีเหลืองใส ปริมาณ ≥ 0.5 ml/kg/hr และไม่เกิดการติดเชื้อ CAUTI\r\nData: Retained Foley\u0027s catheter No. ... ต่อถุงปัสสาวะ (Urine bag)\r\nAction:\r\n- ทำความสะอาดอวัยวะสืบพันธุ์ภายนอกและสายสวนด้วยน้ำยาฆ่าเชื้อวันละ 2 ครั้งและหลังขับถ่าย\r\n- ดูแลสายสวนไม่ให้หักพับงอ\r\n- แขวนถุงปัสสาวะให้อยู่ต่ำกว่าระดับกระเพาะปัสสาวะเสมอ\r\n- เทปัสสาวะและบันทึกปริมาณ สี ความใสทุกเวร\r\nResponse: ปัสสาวะไหลสะดวก สีเหลืองใส ไม่มีตะกอนหรือกลิ่นเหม็นผิดปกติ ปริมาณ... ml/เวร\r\n---\r\n.constipation = ภาวะท้องผูกจากการนอนนิ่งและยาแก้ปวด (Constipation)\r\nFocus: ภาวะท้องผูกเนื่องจากความพร่องในการเคลื่อนไหวและได้รับยาแก้ปวดกลุ่ม Opioids\r\nGoal: ระบบขับถ่ายทำงานมีประสิทธิภาพ ผู้ป่วยสามารถถ่ายอุจจาระได้นุ่ม ไม่ต้องออกแรงเบ่ง และไม่มีอาการแน่นอึดอัดท้อง\r\nData: ผู้ป่วยบอกไม่ได้ถ่ายอุจจาระมา... วัน, บ่นอึดอัดแน่นท้อง, ฟังเสียงลำไส้ Bowel sound... ครั้ง/นาที\r\nAction:\r\n- ประเมินแบบแผนการขับถ่าย\r\n- กระตุ้นให้ดื่มน้ำอุ่น 2,000-2,500 ml/วัน (หากไม่มีข้อห้าม)\r\n- แนะนำอาหารที่มีกากใยสูง ผัก ผลไม้, ช่วยนวดหน้าท้องตามแนวการเคลื่อนของลำไส้ใหญ่\r\n- ดูแลให้ยาระบายตามแผนการรักษาของแพทย์\r\nResponse: หลังให้การพยาบาล ผู้ป่วยสามารถถ่ายอุจจาระได้ อุจจาระนิ่ม ขับถ่ายสะดวก สบายท้องขึ้น\r\n---\r\n.nausea = คลื่นไส้ อาเจียน (Nausea \u0026 Vomiting)\r\nFocus: มีอาการคลื่นไส้ อาเจียนจากผลข้างเคียงของยาดมสลบ/ยาแก้ปวด\r\nGoal: อาการคลื่นไส้อาเจียนทุเลาลง สามารถรับประทานอาหารและสารน้ำได้ ไม่เกิดภาวะขาดน้ำ และไม่เกิดการสำลักลงปอด\r\nData: ผู้ป่วยบ่นคลื่นไส้ พะอืดพะอม อาเจียน... ครั้ง เป็นเศษอาหาร/น้ำย่อยสีเหลือง\r\nAction:\r\n- จัดท่านอนศีรษะสูงหรือนอนตะแคงเพื่อป้องกันการสำลัก\r\n- ดูแลเช็ดปากและทำความสะอาดหลังอาเจียน\r\n- ให้บ้วนปากด้วยน้ำสะอาด\r\n- ดูแลให้ยาแก้อาเจียน... ตามคำสั่งแพทย์\r\n- งดอาหารและน้ำชั่วคราวจนกว่าอาการจะดีขึ้น\r\nResponse: อาการคลื่นไส้ทุเลาลง ไม่อาเจียนเพิ่ม สีหน้าสดชื่นขึ้น ไม่มีภาวะสำลัก\r\n---\r\n\r\n[7. การรับใหม่ ส่งเวร และจำหน่าย (Admin/Shift/Discharge)]\r\n.nsadm = บันทึกแรกรับผู้ป่วยใน (IPD Admission Note)\r\nFocus: รับใหม่ผู้ป่วยใน (Admission Note)\r\nGoal: ผู้ป่วยและญาติได้รับการปฐมนิเทศ คลายความวิตกกังวล ได้รับการประเมินแรกรับครบถ้วน และปลอดภัยตลอดการพักรักษาในหอผู้ป่วย\r\nData: รับใหม่ผู้ป่วยเพศ... อายุ... ปี มาจากห้องตรวจ/ER ด้วยอาการสำคัญ..., ระดับความรู้สึกตัว: ตื่นดี รู้เรื่อง (Alert), สัญญาณชีพแรกรับ: T... °C, BP.../... mmHg, PR... /min, RR... /min, SpO2... %\r\nAction:\r\n- ปฐมนิเทศผู้ป่วยและญาติ แนะนำสถานที่ กฎระเบียบ การใช้กริ่งเรียกพยาบาล สิทธิ์การรักษา\r\n- ประเมินความเสี่ยงล้ม/แผลกดทับ/ภาวะโภชนาการ\r\n- เจาะเลือดส่งตรวจ Lab และจัดยาตามคำสั่งแพทย์แรกรับ\r\n- รายงานแพทย์เวรรับทราบ\r\nResponse: ผู้ป่วยและญาติเข้าใจดี มีความร่วมมือ ไม่มีภาวะวิตกกังวล อยู่ในความดูแลของพยาบาลประจำหอผู้ป่วย\r\n---\r\n.shift = บันทึกส่งเวรพยาบาลประจำผลัด (End of Shift Handover)\r\nFocus: สรุปรายงานอาการผู้ป่วยประจำผลัด (Shift Summary)\r\nGoal: ผู้ป่วยได้รับการดูแลพยาบาลต่อเนื่องตามแผนการรักษา สัญญาณชีพคงที่ ได้รับยาตรงเวลา และปลอดภัยในทุกเวร\r\nData: ผู้ป่วยรู้สึกตัวดี สัญญาณชีพคงที่ (V/S stable): T... °C, BP.../... mmHg, PR... /min, SpO2... %\r\nAction:\r\n- ดูแลให้ยาตามตารางการรักษา\r\n- ตรวจสอบแผลผ่าตัดแห้งดี, สายระบายทำงานปกติ ปริมาณ... ml, ปัสสาวะออก... ml สีเหลืองใส, รับประทานอาหารได้ ไม่มีอาการคลื่นไส้อาเจียน\r\n- ยกไม้กั้นเตียงและดูแลความปลอดภัยรอบเตียง\r\nResponse: อาการทั่วไปคงที่ ปวดแผลทุเลา พักผ่อนได้ ส่งมอบเวรให้ผลัดถัดไปรับทราบและดูแลต่อเนื่อง\r\n---\r\n.transfer = บันทึกส่งต่อ/ย้ายหอผู้ป่วย (Patient Transfer Note)\r\nFocus: ส่งต่อผู้ป่วยไปรับการรักษาต่อที่... (Transfer Note)\r\nGoal: การส่งย้ายผู้ป่วยไปยังหอผู้ป่วยปลายทางเป็นไปด้วยความราบรื่น รวดเร็ว ปลอดภัย และส่งมอบข้อมูลการรักษาครบถ้วน\r\nData: ผู้ป่วยมีแผนย้ายไปรับการรักษาต่อที่..., ระดับความรู้สึกตัว..., V/S ก่อนย้าย: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\r\nAction:\r\n- ตรวจสอบความพร้อมของเอกสาร Chart, ฟิล์ม X-ray, ยาประจำตัว และผล Lab ล่าสุด\r\n- ประสานงานพยาบาลหอผู้ป่วยปลายทาง\r\n- ตรวจสอบสายน้ำเกลือและสายระบายต่างๆ ให้เรียบร้อย\r\n- นำส่งผู้ป่วยพร้อมรายงานสรุปอาการและการรักษา\r\nResponse: ส่งผู้ป่วยถึงหอผู้ป่วยปลายทางปลอดภัย เจ้าหน้าที่รับมอบผู้ป่วยและเอกสารครบถ้วนเรียบร้อย\r\n---\r\n.dc = บันทึกจำหน่ายกลับบ้านตามหลัก D-METHOD (Discharge Planning D-METHOD)\r\nFocus: ให้สุขศึกษาและคำแนะนำก่อนจำหน่ายตามหลัก D-METHOD\r\nGoal: ผู้ป่วยและญาติมีความรู้ความเข้าใจเกี่ยวกับโรค การดูแลแผล การรับประทานยา และการมาตรวจตามนัดตามหลัก D-METHOD อย่างถูกต้อง\r\nData: แพทย์มีคำสั่งให้ผู้ป่วยจำหน่ายกลับบ้านได้ อาการทั่วไปคงที่ V/S stable แผลผ่าตัดแห้งดี\r\nAction: ให้คำแนะนำจำหน่ายตามหลัก D-METHOD:\r\n1. D (Disease): อธิบายพยาธิสภาพของโรคและการดำเนินโรคให้ผู้ป่วยและญาติเข้าใจ\r\n2. M (Medicine): แนะนำชื่อยา ขนาด วิธีรับประทาน และอาการข้างเคียงที่ต้องระวัง\r\n3. E (Environment): การจัดสภาพแวดล้อมที่บ้านให้ปลอดภัย ห้องน้ำมีราวจับ ป้องกันการลื่นล้ม\r\n4. T (Treatment): การดูแลรักษาแผลผ่าตัด ระวังอย่าให้เปียกน้ำ การบริหารร่างกาย และข้อจำกัดการลงน้ำหนัก\r\n5. H (Health): การดูแลสุขภาพ โภชนาการ การพักผ่อน การสังเกตอาการผิดปกติ\r\n6. O (Outpatient): มอบใบนัดตรวจติดตามอาการ วันที่... เวลา... น. ณ แผนก...\r\n7. D (Diet): อาหารที่ควรรับประทาน (โปรตีนสูงช่วยสมานแผล) และอาหารที่ควรงดเว้น\r\nResponse: ผู้ป่วยและญาติเข้าใจคำแนะนำทั้งหมด สามารถทวนซ้ำได้ถูกต้อง ได้รับยากลับบ้านและใบนัดครบถ้วน เดินทางกลับบ้านปลอดภัย\r\n---\r\n.dama = ปฏิเสธการรักษาและขอกลับบ้าน (Discharge Against Medical Advice)\r\nFocus: ผู้ป่วย/ญาติปฏิเสธการรักษาและประสงค์ขอกลับบ้าน (DAMA)\r\nGoal: ผู้ป่วยและญาติรับทราบข้อมูลเกี่ยวกับพยาธิสภาพ ความเสี่ยง และอันตรายจากการปฏิเสธการรักษาครบถ้วน และยินยอมลงนามในเอกสารตามระเบียบ\r\nData: ผู้ป่วยและญาติแสดงความจำนงขอยุติการรักษาและขอกลับบ้านด้วยเหตุผล...\r\nAction:\r\n- แพทย์และพยาบาลได้อธิบายถึงพยาธิสภาพของโรค แผนการรักษา และผลเสีย/อันตรายที่อาจเกิดขึ้นถึงแก่ชีวิตหากไม่ได้รับการรักษาต่อเนื่อง แต่ผู้ป่วยและญาติยังคงยืนยันขอกลับบ้าน\r\n- ให้ผู้ป่วย/ญาติลงลายมือชื่อในเอกสารปฏิเสธการรักษา (DAMA form) ไว้เป็นหลักฐาน\r\n- ถอดสายน้ำเกลือและอุปกรณ์ทางการแพทย์\r\n- มอบยากลับบ้านและเอกสารที่เกี่ยวข้อง\r\nResponse: ผู้ป่วยและญาติลงนามรับทราบความเสี่ยงเรียบร้อย และเดินทางออกจากโรงพยาบาลด้วยความสมัครใจ\r\n---\r\n\r\n[8. สัญลักษณ์และคีย์ลัดย่อด่วน]\r\n.vs = สัญญาณชีพ (Vital Signs)\r\nT: ... °C, BP: .../... mmHg, PR: ... /min, RR: ... /min, SpO2: ... %\r\n---\r\n.order = รับคำสั่งแพทย์ทางโทรศัพท์ (Telephone Order)\r\nรับคำสั่งการรักษาทางโทรศัพท์จาก นพ./พญ. ... เมื่อเวลา... น. \r\nคำสั่งการรักษา: ...\r\nพยาบาลได้ทำการทวนสอบซ้ำ (Read back) ครบถ้วนถูกต้อง แพทย์ยืนยันคำสั่งเรียบร้อย\r\n---\r\n.dt = วันที่และเวลาปัจจุบัน\r\n{NOW}\r\n---\r\n.d = วันที่ปัจจุบัน\r\n{DATE}\r\n---\r\n.t = เวลาปัจจุบัน\r\n{TIME}\r\n---\r\n\r\n[9. ศัลยกรรมข้อเข่าเสื่อม Knee Arthroplasty (TKA / UKA / Rehab)]\r\n.tka = ผ่าตัดเปลี่ยนข้อเข่าเทียม (Total Knee Arthroplasty: TKA)\r\nFocus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อเข่าเทียม (Post-Op TKA)\r\nGoal: การไหลเวียนโลหิตและเส้นประสาทปลายเท้าปกติ (CMS Intact) ควบคุมความปวดได้ดี สายระบายทำงานมีประสิทธิภาพ และไม่เกิดภาวะข้อเข่างอติดหรือ DVT\r\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Total Knee Arthroplasty (TKA) เข่าข้าง... แผลผ่าตัดปิด pressure dressing แนบสนิทดี, มีสายระบาย (Redivac/Hemovac) ต่อลงขวดสุญญากาศ มีเลือดออกสะสม... ml ลักษณะ serosanguinous, CMS check ปลายเท้า: ปลายเท้าอุ่น capillary refill \u003c 2 วินาที, คลำชีพจร Dorsalis pedis pulse ได้ชัดเจน, กระดิกนิ้วเท้าและข้อเท้าได้ ไม่บวมตึง, Pain score = .../10\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินแผลผ่าตัด ทำแผล (Dressing) ด้วย Normal Saline และเทคนิคปลอดเชื้อ\r\n- จัดวางขาบนเครื่องช่วยงอเข่าอัตโนมัติ (CPM) มุมงอเริ่มต้น... องศา นาน 1 ชม. ตามคำสั่งแพทย์\r\n- ฝึกสอนและกระตุ้นการบริหารกล้ามเนื้อ Quadriceps setting และ Ankle pumping exercise\r\n- ช่วยเหลือและฝึกสอนผู้ป่วยลงจากเตียงและฝึกเดินด้วยอุปกรณ์ช่วยเดิน (Walker)\r\n- ให้ยาบรรเทาปวดและยาปฏิชีวนะมื้อเช้า-เที่ยงตามแผนการรักษา\r\n[⛅ เวรบ่าย]\r\n- ตรวจประเมินการไหลเวียนโลหิตและประสาทรับรู้ส่วนปลาย (CMS check) ปลายเท้าข้างที่ผ่าตัด\r\n- ประเมินระดับความปวดหลังการฝึกกายภาพ และดูแลให้ยาแก้ปวดตามคำสั่งการรักษา\r\n- ประคบเย็น (Cold pack) รอบข้อเข่า 20-30 นาที เพื่อลดอาการบวมและปวดตึง\r\n- ตรวจสอบสายระบายแผลผ่าตัด (Redivac drain) ให้คงสภาพสุญญากาศ บันทึกปริมาณและลักษณะเลือด\r\n- จัดท่านอนหงาย หนุนหมอนรองใต้ข้อเท้าให้เข่าเหยียดตรง (ห้ามหนุนใต้ข้อพับเข่า)\r\n[🌙 เวรดึก]\r\n- ตรวจเช็คการจัดท่านอน เหยียดข้อเข่าตรง ป้องกันภาวะข้อเข่างอติด (Knee flexion contracture)\r\n- จัดสิ่งแวดล้อมให้เงียบสงบ แสงสว่างเหมาะสม และยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อความปลอดภัย\r\n- ดูแลจัดสายระบายไม่ให้ดึงรั้งหรือหักพับงอ และสังเกตสารคัดหลั่งรอบแผล\r\n- บันทึกและสรุปยอด Intake-Output และปริมาณเลือดจากสายระบายสะสมรอบ 24 ชั่วโมง\r\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจประเมิน CMS ปลายเท้า และอาการปวดก่อนส่งต่อเวรเช้า\r\nResponse: สัญญาณชีพคงที่, CMS ปลายเท้าปกติ ปลายเท้าอุ่น ชีพจรเต้นชัดเจน ขยับนิ้วเท้าได้ดี, แผลผ่าตัดไม่มี active bleeding, สายระบายออกลดลง, ผู้ป่วยสามารถทำ Ankle pumping ได้ถูกต้อง, Pain score ลดลงเหลือ.../10\r\n---\r\n.uka = ผ่าตัดเปลี่ยนข้อเข่าเทียมเฉพาะส่วน (Unicompartmental Knee Arthroplasty: UKA)\r\nFocus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อเข่าเทียมเฉพาะส่วน (Post-Op UKA)\r\nGoal: แผลผ่าตัดเรียบร้อยดี บวมตึงน้อย ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี ควบคุมความปวดได้ และเริ่มฝึกเดินลงน้ำหนักได้อย่างปลอดภัย\r\nData: รับย้ายหลังผ่าตัด UKA เข่าข้าง... แผลผ่าตัดขนาดเล็กปิดก๊อซแนบสนิท ไม่มีเลือดสดซึม, ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี, Pain score = .../10\r\nAction: \r\n1. ตรวจวัดสัญญาณชีพและประเมิน CMS check ปลายเท้าทุก 2 ชม.\r\n2. จัดท่าเหยียดข้อเข่าตรง หนุนหมอนใต้ข้อเท้า และประคบเย็นรอบข้อเข่าเพื่อลดบวม\r\n3. ดูแลให้ยาแก้ปวดและสารน้ำทางหลอดเลือดดำตามแผน\r\n4. กระตุ้นให้ทำ Ankle pumping และ Straight leg raising exercise\r\n5. วางแผนร่วมกับนักกายภาพบำบัดในการฝึกยืนและลงน้ำหนัก (Weight bearing) ด้วย Walker ตามคำสั่งแพทย์\r\nResponse: แผลผ่าตัดแห้งดี บวมช้ำน้อย, CMS check ปกติ, ผู้ป่วยสามารถงอและเหยียดเข่าได้ตามเกณฑ์, ปวดลดลง ลุกยืนลงน้ำหนักได้มั่นคง\r\n---\r\n.tkarehab = การฟื้นฟูสภาพและกายภาพบำบัดข้อเข่า (TKA Rehabilitation \u0026 CPM)\r\nFocus: ฟื้นฟูสมรรถภาพกล้ามเนื้อและการเคลื่อนไหวข้อเข่า (Impaired Physical Mobility / Knee Rehabilitation)\r\nGoal: ผู้ป่วยสามารถงอและเหยียดข้อเข่าได้ตามเป้าหมาย (Extension 0°, Flexion ≥ 90°) กล้ามเนื้อต้นขาแข็งแรงขึ้น และใช้อุปกรณ์ช่วยเดินได้ถูกต้อง\r\nData: ผู้ป่วยหลังผ่าตัด TKA วันที่... ข้อเข่ายังมีอาการตึงตัว งอเข่าได้... องศา กล้ามเนื้อต้นขายังล้า\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ดูแลให้ยาแก้ปวดก่อนเริ่มฝึกกายภาพ 30 นาทีเพื่อให้บริหารข้อเข่าได้อย่างเต็มที่\r\n- จัดผู้ป่วยลงเครื่องช่วยงอเข่าอัตโนมัติ (CPM) มุมงอเริ่มต้น... องศา นาน 1-2 ชม. ตามคำสั่งแพทย์\r\n- ฝึกสอนและกระตุ้นการบริหารกล้ามเนื้อ: Quad setting, Terminal knee extension, และ Heel slide\r\n- ฝึกสอนการเดินโดยใช้อุปกรณ์ช่วยเดิน (Walker) และการก้าวเดินที่ถูกต้อง\r\n- ประคบเย็นรอบข้อเข่า 20-30 นาทีทันทีหลังฝึกเสร็จ\r\n[⛅ เวรบ่าย]\r\n- ประเมินอาการบวม แดง ร้อน และระดับความปวดรอบข้อเข่าหลังการฝึกช่วงเช้า\r\n- จัดผู้ป่วยฝึก CPM รอบบ่ายตามคำสั่งแพทย์ (กรณีมีคำสั่งวันละ 2 ครั้ง)\r\n- กระตุ้นให้ทำ Ankle pumping exercise บ่อยๆ เพื่อป้องกัน DVT\r\n- จัดท่านอนเหยียดเข่าตรง หนุนหมอนใต้ข้อเท้า (ห้ามหนุนใต้ข้อพับเข่า)\r\n[🌙 เวรดึก]\r\n- ตรวจเช็คท่านอนให้ข้อเข่าเหยียดตรง ป้องกันการงอข้อเข่าค้างขณะหลับ (Knee flexion contracture)\r\n- ประคบเย็นเสริมกรณีข้อเข่ายังมีอาการบวมตึง\r\n- จัดสิ่งแวดล้อมให้ผู้ป่วยได้นอนหลับพักผ่อนเต็มที่เพื่อฟื้นฟูกล้ามเนื้อ\r\nResponse: ผู้ป่วยสามารถงอข้อเข่าได้เพิ่มขึ้นเป็น... องศา, ทนต่อการทำกายภาพได้ดี ไม่มีอาการเจ็บปวดรุนแรง, กล้ามเนื้อต้นขามีกำลังดีขึ้น สามารถใช้ Walker เดินได้อย่างปลอดภัย\r\n---\r\n.arthro = ส่องกล้องตรวจและผ่าตัดข้อเข่า (Knee Arthroscopy / Meniscectomy / ACL)\r\nFocus: การพยาบาลหลังผ่าตัดส่องกล้องข้อเข่า (Post-Op Knee Arthroscopy)\r\nGoal: อาการบวมและปวดในข้อเข่าลดลง แผลส่องกล้องแห้งสะอาด ไม่มีการติดเชื้อในข้อ และฟื้นฟูการเคลื่อนไหวข้อเข่าได้เร็ว\r\nData: รับย้ายผู้ป่วยหลังทำ Knee Arthroscopy เข่าข้าง... แผลรอยเจาะส่องกล้องปิดก๊อซและพันผ้ายืด (Elastic bandage) แนบกระชับดี\r\nAction: \r\n1. ประเมิน CMS check ปลายเท้า (สีผิว ความอุ่น การเคลื่อนไหวนิ้วเท้า ชีพจรส่วนปลาย)\r\n2. หนุนขาสูงกว่าระดับหัวใจ และประคบเย็นรอบข้อเข่า 24-48 ชม. แรก เพื่อลดอาการบวม\r\n3. ตรวจสอบผ้าพันแผลไม่ให้รัดแน่นหรือหลวมจนเกินไป\r\n4. สอนการบริหาร Ankle pump และ Quad setting\r\n5. แนะนำการลงน้ำหนักตามคำสั่งแพทย์ (PWB / FWB / NWB)\r\nResponse: ปลายเท้าอุ่น ขยับนิ้วเท้าได้ดี ไม่มีอาการชาหรือบวมคล้ำ, แผลไม่มี bleeding ซึมทะลุผ้าพันแผล, ปวดทุเลาลง\r\n---\r\n\r\n[10. ศัลยกรรมข้อสะโพก Hip Arthroplasty (THA / BHA / Bipolar)]\r\n.tha = ผ่าตัดเปลี่ยนข้อสะโพกเทียม (Total Hip Arthroplasty: THA)\r\nFocus: การพยาบาลหลังผ่าตัดเปลี่ยนข้อสะโพกเทียม และป้องกันข้อสะโพกหลุด (Post-Op THA \u0026 Dislocation Prevention)\r\nGoal: ข้อสะโพกเทียมอยู่ในตำแหน่งที่ถูกต้อง ไม่เกิดภาวะข้อสะโพกหลุด (No Dislocation) CMS ปลายเท้าปกติ และฟื้นฟูการเดินได้อย่างปลอดภัย\r\nData: รับย้ายผู้ป่วยหลังผ่าตัด Total Hip Arthroplasty (THA) สะโพกข้าง... แผลผ่าตัดด้านข้างสะโพกปิดแน่นสนิท, สายระบาย Redivac มีเลือดออกสะสม... ml, ปลายเท้าอุ่น เคลื่อนไหวและรับความรู้สึกได้ปกติ\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินแผลผ่าตัด ทำแผลด้านข้างสะโพกด้วยเทคนิคปลอดเชื้อ\r\n- ตรวจสอบการวางหมอนสามเหลี่ยม (Abduction pillow) ระหว่างขาทั้งสองข้างให้ถูกต้อง\r\n- ช่วยเหลือผู้ป่วยฝึกยืนและลงน้ำหนักเดินด้วย Walker ตามคำสั่งแพทย์ (PWB / FWB)\r\n- กระตุ้นให้ทำ Ankle pumping exercise อย่างต่อเนื่องเพื่อส่งเสริมการไหลเวียนเลือดดำ\r\n- เน้นย้ำข้อห้าม: ห้ามงอสะโพกเกิน 90 องศา, ห้ามไขว่ห้างหรือหนีบขา, ห้ามบิดปลายเท้าเข้าใน\r\n[⛅ เวรบ่าย]\r\n- ตรวจประเมิน CMS check ปลายเท้า และเฝ้าระวังภาวะข้อสะโพกหลุด (ขาไม่สั้นเต่อ ไม่บิดหมุน)\r\n- ดูแลให้ยาแก้ปวดและยาป้องกันลิ่มเลือดอุดตัน (Anticoagulant) ตามแผนการรักษา\r\n- ตรวจสอบสายระบายสุญญากาศ บันทึกปริมาณเลือด ระวังสายดึงรั้ง\r\n- แนะนำการใช้เบาะเสริมความสูงบนชักโครก (Raised toilet seat) เวลาขับถ่าย\r\n[🌙 เวรดึก]\r\n- จัดท่านอนหงายและตรวจเช็คหมอน Abduction pillow อยู่ในตำแหน่งถูกต้องตลอดเวลาที่นอนหลับ\r\n- กำชับการพลิกตัวตะแคงต้องพลิกแบบ Log-roll โดยมีหมอนหนุนคั่นระหว่างขาทั้งสองข้างเสมอ\r\n- สรุปยอด Intake-Output และปริมาณเลือดจากสายระบายสะสม 24 ชม.\r\n- วัดสัญญาณชีพรอบ 06:00 น. ตรวจเช็คแนวข้อสะโพกและ CMS ปลายเท้าก่อนส่งเวรเช้า\r\nResponse: ขาสองข้างกางในแนวตรงด้วย Abduction pillow ไม่มีข้อสะโพกบิดหมุนผิดรูป, สัญญาณชีพคงที่, CMS check ปกติ ขยับนิ้วเท้าได้ดี, ปริมาณเลือดจากสายระบายค่อยๆ ลดลง, Pain score.../10\r\n---\r\n.bha = ผ่าตัดเปลี่ยนข้อสะโพกเทียมสองแกน (Bipolar Hemiarthroplasty: BHA)\r\nFocus: การพยาบาลผู้สูงอายุหลังผ่าตัด Bipolar Hemiarthroplasty จากกระดูกสะโพกหัก\r\nGoal: ป้องกันภาวะแทรกซ้อนจากการผ่าตัดข้อสะโพก ป้องกันข้อหลุด ควบคุมความปวดได้ดี และเริ่มฝึกยืนเดินด้วย Walker ได้อย่างมั่นคง\r\nData: ผู้ป่วยสูงอายุ รับย้ายหลังผ่าตัด Bipolar Hemiarthroplasty สะโพกข้าง... (Dx: Fracture Neck of Femur), รู้สึกตัวดี ถามตอบรู้เรื่อง แผลผ่าตัดปิด gauze แนบสนิท มี Redivac drain... ml\r\nAction: \r\n1. จัดท่านอนกางขาสะโพกด้วยหมอน Abduction pillow ป้องกันข้อสะโพกเทียมหลุด\r\n2. ประเมินภาวะสับสนเฉียบพลันในผู้สูงอายุ (Delirium assessment) จัดสภาพแวดล้อมให้เงียบสงบ มีแสงสว่างเพียงพอ\r\n3. ป้องกันภาวะแทรกซ้อนจากการนอนติดเตียง:\r\n   - พลิกตัวตะแคงตัวประคองทุก 2 ชม. พร้อมหนุนหมอนรองข้อเข่าและส้นเท้า ป้องกันแผลกดทับ\r\n   - กระตุ้นการหายใจลึกๆ และไออย่างมีประสิทธิภาพ (Deep breathing \u0026 Coughing) หรือเป่า Incentive spirometer ทุกชั่วโมง ป้องกันภาวะปอดแฟบ (Atelectasis)\r\n4. ตรวจสอบแผลผ่าตัด สายระบาย และ CMS check ปลายเท้า\r\n5. ดูแลให้สารน้ำ ยาแก้ปวด และยากระตุ้นการขับถ่ายเพื่อป้องกันท้องผูก\r\nResponse: รู้สึกตัวตื่นดี ไม่มีอาการสับสนเพ้อ, ข้อสะโพกอยู่ในแนวตรง ไม่บิดหมุน, แผลแห้งดี ไม่มีเลือดสดซึม, ปอดเสียงใส ไม่มีเสมหะคั่งค้าง\r\n---\r\n.hipcare = ข้อควรระวังและป้องกันข้อสะโพกเทียมเคลื่อนหลุด (Hip Dislocation Prevention Precautions)\r\nFocus: ให้สุขศึกษาและแนวทางปฏิบัติเพื่อป้องกันข้อสะโพกเทียมหลุด (Post-Hip Surgery Precautions)\r\nGoal: ผู้ป่วยและญาติเข้าใจและปฏิบัติตามข้อห้ามเพื่อป้องกันข้อสะโพกหลุด (Hip Precautions) ได้ถูกต้อง 100% ตลอดเวลา\r\nData: ผู้ป่วยหลังผ่าตัดเปลี่ยนข้อสะโพกเทียม (THA/BHA) อยู่ในระยะฟื้นฟูสภาพ เตรียมพร้อมกลับบ้าน\r\nAction: \r\n1. เน้นย้ำกฎเหล็ก 3 ข้อ: 1) ห้ามงอสะโพกเกิน 90 องศา 2) ห้ามไขว่ห้างหรือหนีบขา 3) ห้ามบิดปลายเท้าเข้าด้านใน\r\n2. ท่านอน: นอนหงายหนุนหมอนข้างคั่นระหว่างขาเสมอ หากนอนตะแคงให้ตะแคงข้างปกติและหนุนหมอนหนาคั่นระหว่างขาทั้งสองข้าง\r\n3. ท่านั่ง: นั่งเก้าอี้ที่มีพนักพิงสูงและมีที่วางแขน ไม่นั่งเก้าอี้เตี้ย โซฟานุ่มจมตัว หรือนั่งยองๆ บนพื้น\r\n4. การขับถ่าย: ใช้ชักโครกที่มีเบาะเสริมความสูง ไม่นั่งส้วมซึม\r\n5. การหยิบของ: ใช้ไม้ยาวหนีบของ (Reacher) ห้ามก้มตัวลงเก็บของที่พื้น\r\n6. การสวมใส่เสื้อผ้า: ให้ญาติช่วยสวมกางเกงและถุงเท้า หรือใช้อุปกรณ์ช่วยสวม\r\n7. การสังเกตอาการผิดปกติ: ปวดสะโพกรุนแรงฉับพลัน ขาสั้นลงกว่าอีกข้าง หรือปลายเท้าบิดออกนอก ให้รีบมาโรงพยาบาลทันที\r\nResponse: ผู้ป่วยและญาติเข้าใจข้อห้ามและแนวทางปฏิบัติ สามารถสาธิตวิธีการลุก-นั่งและการนอนที่ถูกต้องได้ ปลอดภัยจากภาวะข้อสะโพกหลุด\r\n---\r\n\r\n[11. ศัลยกรรมกระดูกสันหลัง Spine Surgery Nursing (DAR)]\r\n.laminectomy = ผ่าตัดกระดูกสันหลังตัดกระดูกลามินา (Laminectomy / Decompression)\r\nFocus: การพยาบาลหลังผ่าตัดกระดูกสันหลัง (Post-Op Laminectomy)\r\nGoal: การทำงานของเส้นประสาทและไขสันหลังปกติ (Motor \u0026 Sensory Intact) อาการชาและปวดร้าวลดลง แผลผ่าตัดแห้งดี และไม่มี CSF leak\r\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Laminectomy ระดับ... แผลผ่าตัดกลางหลังปิดแน่นสนิท, มีสายระบายเลือด (Hemovac/Redivac) ออก... ml, Motor power ขาสองข้าง: ขวา grade... ซ้าย grade..., Sensation: รับความรู้สึกได้ดี ไม่มีอาการชาเพิ่มขึ้น\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินระบบประสาทส่วนล่าง (Motor power \u0026 Sensation ขาทั้ง 2 ข้าง)\r\n- ทำแผลผ่าตัดกลางหลังด้วยเทคนิคปลอดเชื้อ ตรวจสอบไม่มีน้ำใส CSF leakage\r\n- ฝึกสอนการพลิกตัวแบบท่อนซุง (Log-rolling technique) โดยเจ้าหน้าที่ 2-3 คน\r\n- ดูแลสวมเสื้อพยุงหลัง (TLSO / L-S support) ให้กระชับก่อนเริ่มฝึกนั่งและยืน\r\n[⛅ เวรบ่าย]\r\n- ตรวจเช็คสายระบายแผลผ่าตัด สังเกตสีและปริมาณ หากมีน้ำใสสีเหลืองฟางข้าวให้สงสัย CSF leak\r\n- ประเมินระดับความรู้สึกตัว อาการปวดศีรษะ และอาการปวดแผลผ่าตัด ให้ยาแก้ปวดตามแผน\r\n- ประเมินการขับถ่ายปัสสาวะ เฝ้าระวังภาวะปัสสาวะคั่งค้าง (Urinary retention)\r\n- แนะนำข้อห้าม BLT: ห้ามก้มตัว (No Bending), ห้ามยกของหนัก (No Lifting), ห้ามบิดเอี้ยวตัว (No Twisting)\r\n[🌙 เวรดึก]\r\n- จัดท่านอนหงายราบหรือศีรษะสูงไม่เกิน 30 องศา หนุนหมอนใต้ข้อพับเข่าเล็กน้อยเพื่อผ่อนคลายกล้ามเนื้อหลัง\r\n- ช่วยพลิกตัวแบบ Log-rolling ทุก 2 ชั่วโมงเพื่อป้องกันแผลกดทับ\r\n- จัดสิ่งแวดล้อมให้เงียบสงบ ยกไม้กั้นเตียงขึ้น 2 ข้างเพื่อความปลอดภัย\r\n- สรุปยอด Intake-Output และยอดเลือดจากสายระบายสะสมรอบ 24 ชั่วโมง\r\nResponse: Motor power ขาทั้งสองข้างคงที่ ขยับข้อเท้าและนิ้วเท้าได้ดี, พลิกตัวแบบ Log-roll ลำตัวตรงดี, แผลผ่าตัดไม่มี CSF leakage, ปัสสาวะออกสะดวก ไม่คั่งค้าง, Pain score ลดลง\r\n---\r\n.discectomy = ผ่าตัดหมอนรองกระดูกทับเส้นประสาท (Microdiscectomy)\r\nFocus: การพยาบาลหลังผ่าตัดหมอนรองกระดูกสันหลัง (Post-Op Microdiscectomy)\r\nGoal: ลดการกดทับของเส้นประสาท อาการปวดหลังและปวดร้าวลงขาบรรเทาลง ควบคุมการขับถ่ายได้ปกติ และเคลื่อนไหวร่างกายได้ถูกสุขลักษณะ\r\nData: รับย้ายผู้ป่วยหลังผ่าตัด Microdiscectomy ระดับ L...-L... แผลผ่าตัดขนาดเล็กปิดก๊อซแน่นสนิท, อาการปวดร้าวชาลงขาเดิมทุเลาลง\r\nAction: \r\n1. ประเมิน Neuro signs ขาสองข้าง: Straight leg raising, ขยับนิ้วเท้า และกำลังกล้ามเนื้อ EHL/Gastroc\r\n2. พลิกตัวตะแคงด้วยเทคนิค Log-rolling\r\n3. แนะนำการลุกจากเตียง: ตะแคงตัวทั้งตัว ห้อยขาสองข้างลงข้างเตียงพร้อมใช้แขนสองข้างยันตัวลุกขึ้นนั่งตรงๆ ห้ามบิดเอี้ยวหลัง\r\n4. แนะนำข้อควรระวัง: หลีกเลี่ยงการนั่งนานเกิน 30-45 นาที ไม่ยกของหนัก\r\nResponse: ผู้ป่วยลุกนั่งและยืนเดินได้ตามขั้นตอน ลำตัวตรง ไม่บิดเอี้ยว, อาการปวดร้าวลงขาเดิมลดลงชัดเจน ขยับนิ้วเท้าได้แรงดี\r\n---\r\n.plif = ผ่าตัดเชื่อมข้อกระดูกสันหลังและใส่เหล็กดาม (PLIF / TLIF Spinal Fusion)\r\nFocus: การพยาบาลหลังผ่าตัดเชื่อมข้อกระดูกสันหลังและดามเหล็ก (Post-Op PLIF / TLIF)\r\nGoal: แนวกระดูกสันหลังมั่นคง การยึดตรึงข้อกระดูกอยู่ในตำแหน่งที่ถูกต้อง ระบบประสาทส่วนปลายปกติ และสามารถพลิกตัวแบบ Log rolling ได้ดี\r\nData: รับย้ายหลังผ่าตัด Posterior Lumbar Interbody Fusion (PLIF/TLIF) ระดับ... แผลผ่าตัดปิด gauze แนบสนิท, สายระบาย... ml, ขาสองข้างขยับได้ Motor grade...\r\nAction: \r\n1. ประเมินสัญญาณชีพ และ Neuro signs ขาทั้งสองข้างอย่างใกล้ชิด\r\n2. พลิกตัวแบบ Log-rolling ทุก 2 ชม. ป้องกันแผลกดทับและลดการดึงรั้งของแนวกระดูกสันหลังที่เชื่อมข้อ\r\n3. ดูแลสายระบายสุญญากาศให้อยู่ในระบบปิด\r\n4. แนะนำข้อห้ามการเคลื่อนไหว: **ห้ามก้มตัว ห้ามยกของหนัก ห้ามบิดเอี้ยวตัว (No Bending, No Lifting, No Twisting: BLT restrictions)**\r\n5. เมื่อเริ่มฝึกนั่งหรือยืนเดิน: ดูแลสวมเสื้อพยุงหลังชนิดแข็ง (TLSO หรือ L-S Support) ให้กระชับพอดีตัวก่อนลุกขึ้นนั่งทุกครั้ง\r\n6. ดูแลให้ยาแก้ปวดและยาลดการเกร็งกล้ามเนื้อ (Muscle relaxant) ตามแผนการรักษา\r\nResponse: กระดูกสันหลังอยู่ในแนวตรงมั่นคงดี, สวมเสื้อพยุงหลังได้ถูกต้องก่อนเคลื่อนไหว, Neurovascular ขาปกติ ไม่มีอาการกล้ามเนื้ออ่อนแรงเฉียบพลัน, แผลแห้งดี\r\n---\r\n.acdf = ผ่าตัดกระดูกสันหลังส่วนคอทางด้านหน้า (Anterior Cervical Discectomy \u0026 Fusion: ACDF)\r\nFocus: การพยาบาลหลังผ่าตัดกระดูกคอ และเฝ้าระวังทางเดินหายใจอุดกั้น (Post-Op ACDF)\r\nGoal: ทางเดินหายใจโล่ง ไม่มีอาการแน่นคอหรือหายใจลำบากจาก Hematoma กลืนอาหารได้สะดวก ระบบประสาทแขนขาทั้ง 4 ข้างปกติ\r\nData: รับย้ายหลังผ่าตัด ACDF ระดับ C...-C... แผลผ่าตัดบริเวณลำคอด้านหน้าปิดเรียบร้อย, หายใจสม่ำเสมอ ไม่มีเสียง Stridor, พูดมีเสียง ไม่มีเสียงแหบ, กลืนน้ำลายได้\r\nAction: \r\n1. **เฝ้าระวังภาวะทางเดินหายใจอุดกั้นจากก้อนเลือดคั่งที่คอ (Neck Hematoma \u0026 Airway Obstruction)**:\r\n   - ตรวจประเมินอัตราและลักษณะการหายใจอย่างใกล้ชิด สังเกตอาการหายใจเหนื่อย หายใจมีเสียงฮึด (Stridor)\r\n   - สังเกตและคลำบริเวณลำคอด้านหน้ารอบแผลผ่าตัด เฝ้าระวังอาการบวมตึง คอหนาขึ้น หรือหลอดลมถูกดันเบี้ยว (Tracheal deviation)\r\n   - เตรียมชุด Emergency Tracheostomy set และอุปกรณ์กู้ชีพไว้ข้างเตียงเสมอ\r\n2. สังเกตอาการกลืนลำบาก (Dysphagia) และอาการเสียงแหบ (Hoarseness) จากการบาดเจ็บของ Recurrent laryngeal nerve\r\n3. จัดท่านอนศีรษะสูง 30-45 องศา (Semi-Fowler\u0027s position) เพื่อลดอาการบวมบริเวณคอ\r\n4. ดูแลให้ผู้ป่วยสวมปลอกคอพยุง (Philadelphia collar / Hard collar) ตลอดเวลาตามคำสั่งแพทย์ ห้ามก้มหรือหงายคอ\r\n5. ประเมินกำลังกล้ามเนื้อแขนและมือ (Grip strength, Motor power แขนทั้งสองข้าง)\r\nResponse: ทางเดินหายใจโล่ง หายใจสะดวก ไม่มีเสียง Stridor, ลำคอไม่บวมตึง หลอดลมอยู่ตรงกึ่งกลาง, พูดชัดเจนไม่มีเสียงแหบ, กลืนน้ำได้ไม่สำลัก, กำลังกล้ามเนื้อแขนและมือแข็งแรงปกติ\r\n---\r\n.csfleak = เฝ้าระวังและดูแลภาวะน้ำหล่อเลี้ยงสมองและไขสันหลังรั่ว (CSF Leakage)\r\nFocus: มีภาวะน้ำไขสันหลังรั่วซึมจากแผลผ่าตัดกระดูกสันหลัง (Cerebrospinal Fluid Leakage)\r\nGoal: ปริมาณน้ำไขสันหลังรั่วหยุด แผลผ่าตัดแห้งสนิท อาการปวดศีรษะทุเลาลง และไม่เกิดภาวะเยื่อหุ้มสมองอักเสบ (Meningitis)\r\nData: ผู้ป่วยบ่นปวดศีรษะตุ๊บๆ รุนแรงเวลาลุกนั่ง แต่อาการทุเลาลงเมื่อนอนราบ (Spinal headache), บริเวณแผลผ่าตัดมีน้ำเหลืองใส (Clear watery/yellowish discharge) ซึมเปื้อนผ้าปิดแผล\r\nAction: \r\n1. รายงานแพทย์เจ้าของไข้ทันทีที่พบอาการสงสัย CSF leak\r\n2. จัดให้ผู้ป่วย **นอนราบไม่หนุนหมอน (Flat bed rest)** ตลอด 24-48 ชม. เพื่อลดแรงดันน้ำไขสันหลังและเปิดโอกาสให้เยื่อหุ้มดูราประสานตัว\r\n3. สังเกตลักษณะและปริมาณน้ำที่ซึมจากแผล (Halo sign / Ring test), เปลี่ยนผ้าก๊อซด้านนอกด้วยเทคนิคปลอดเชื้อ\r\n4. เฝ้าระวังอาการแสดงของการติดเชื้อเยื่อหุ้มสมอง (Meningitis): ไข้สูง คอแข็ง (Stiff neck), สับสน, กลัวแสง (Photophobia)\r\n5. ดูแลให้สารน้ำทางหลอดเลือดดำและยาแก้ปวดตามคำสั่งแพทย์อย่างเคร่งครัด\r\nResponse: ผู้ป่วยให้ความร่วมมือนอนราบบนเตียง, อาการปวดศีรษะทุเลาลง, น้ำไขสันหลังที่ซึมแผลลดลง, ไม่มีไข้ ไม่มีอาการคอแข็ง\r\n---\r\n.spinerehab = การฟื้นฟูสภาพกระดูกสันหลังและการสวมเสื้อพยุง (TLSO / L-S Support \u0026 BLT)\r\nFocus: ฝึกทักษะการเคลื่อนไหวร่างกายอย่างปลอดภัยหลังผ่าตัดกระดูกสันหลัง\r\nGoal: ผู้ป่วยสามารถทรงตัว ใส่กายอุปกรณ์เสริมพยุงหลัง (LS support / TLSO) และฝึกยืนเดินได้อย่างถูกต้อง ปลอดภัย ไม่ปวดหลังเพิ่ม\r\nData: ผู้ป่วยหลังผ่าตัดกระดูกสันหลัง แพทย์มีคำสั่งให้เริ่มลุกนั่งและเดินโดยใช้อุปกรณ์พยุงหลัง\r\nAction: \r\n1. แนะนำการสวมเสื้อเกราะพยุงหลัง (TLSO / L-S Support): สวมขณะนอนราบบนเตียง โดยการกลิ้งตัวตะแคงสวมเสื้อพยุงและดึงแถบตีนตุ๊กแกให้กระชับพอดีตัวก่อนลุกขึ้นนั่งทุกครั้ง\r\n2. ฝึกทักษะการลุกนั่งข้างเตียง: ตะแคงตัวแบบท่อนซุง หย่อนขาสองข้างลงพร้อมใช้มือยันตัวลุกขึ้นพร้อมกัน\r\n3. ย้ำเตือนข้อจำกัด BLT: ห้ามก้มตัว (No Bending), ห้ามยกของหนักเกิน 2-3 กก. (No Lifting), ห้ามเอี้ยวหรือบิดลำตัว (No Twisting) อย่างน้อย 6-12 สัปดาห์\r\n4. ส่งเสริมการเดินออกกำลังกายสม่ำเสมอ หลีกเลี่ยงการนั่งเก้าอี้นานเกิน 30-45 นาที\r\nResponse: ผู้ป่วยสามารถสวมเสื้อพยุงหลังได้ถูกต้อง ลุกนั่งและยืนเดินได้ทรงตัวมั่นคง ปฏิบัติตามหลัก BLT ได้ถูกต้อง\r\n---\r\n\r\n[12. การพยาบาลกระดูกหักและการบาดเจ็บ Trauma \u0026 Fracture Care]\r\n.orif = ผ่าตัดจัดกระดูกและยึดตรึงด้วยโลหะภายใน (ORIF: Fractures)\r\nFocus: การพยาบาลหลังผ่าตัดดามกระดูกหัก (Post-Op ORIF)\r\nGoal: กระดูกที่ยึดตรึงอยู่ในแนวที่ถูกต้อง แผลผ่าตัดสะอาด แห้งดี ปลายรยางค์อุ่น CMS ปกติ และไม่เกิดภาวะแทรกซ้อนจากการผ่าตัด\r\nData: รับย้ายผู้ป่วยหลังทำผ่าตัด Open Reduction and Internal Fixation (ORIF) บริเวณ... ขอบแผลผ่าตัดปิดเรียบร้อย ดามเฝือกชั่วคราว (Slab) ไว้, มีอาการปวดและบวมตึงบริเวณที่ผ่าตัด Pain score = .../10\r\nAction: \r\n1. **เฝ้าระวังภาวะความดันในช่องกล้ามเนื้อสูง (Compartment Syndrome Monitoring 5 Ps)**:\r\n   - ตรวจประเมิน Pain (ปวดรุนแรงไม่สัมพันธ์กับแผล), Pallor (ผิวซีดเย็น), Pulselessness (ชีพจรส่วนปลายเบา/คลำไม่ได้), Paresthesia (มีอาการชา/เหน็บ), Paralysis (ขยับนิ้วไม่ได้) ทุก 1-2 ชม.\r\n2. จัดวางอวัยวะที่ผ่าตัดให้อยู่ในระดับสูงกว่าหัวใจ (Elevation) โดยใช้หมอนรองรับ เพื่อช่วยลดอาการบวมคั่งของหลอดเลือดดำ\r\n3. ประคบเย็นบริเวณรอบๆ แผลผ่าตัด ครั้งละ 20 นาที\r\n4. ตรวจสอบความแน่นตึงของผ้าพันแผล (Elastic bandage) หากตึงแน่นเกินไปจนกดการไหลเวียนเลือด ให้คลายออกและพันใหม่พอดี\r\n5. ดูแลให้ยาแก้ปวดและยาปฏิชีวนะตามแผนการรักษา\r\nResponse: ไม่พบอาการแสดงของ Compartment syndrome, ปลายแขน/ปลายเท้าอุ่นดี ชีพจรส่วนปลายเต้นสม่ำเสมอ, ขยับนิ้วได้ ไม่ชา, อาการบวมลดลง, Pain score ลดลงเหลือ.../10\r\n---\r\n.exfix = การพยาบาลผู้ป่วยใส่โครงยึดกระดูกภายนอก (External Fixation \u0026 Pin Site Care)\r\nFocus: การดูแลผู้ป่วยใส่โครงดามกระดูกภายนอกและป้องกันการติดเชื้อ (External Fixation Care)\r\nGoal: อุปกรณ์ตรึงกระดูกภายนอกมั่นคงแข็งแรง ตำแหน่ง Pin site สะอาด ไม่มีการติดเชื้อ CMS ส่วนปลายปกติ และบริหารกล้ามเนื้อได้ถูกต้อง\r\nData: ผู้ป่วยได้รับการผ่าตัดใส่เครื่องดามกระดูกภายนอก (External Fixator) บริเวณ... มีเหล็กแทงผ่านผิวหนังยึดกับกระดูก แผล Pin site ปิดก๊อซสะอาด\r\nAction: \r\n1. ตรวจประเมิน CMS check ปลายรยางค์ส่วนที่ใส่เครื่องมือดามกระดูก\r\n2. ทำความสะอาดบริเวณรอบเหล็กด้ามดึง (Pin site care) วันละ 1-2 ครั้ง โดยใช้ไม้พันสำลีชุบ Normal Saline เช็ดวนออกจากโคนเหล็ก ห้ามเช็ดย้อนกลับไปมา\r\n3. สังเกตอาการแสดงของการติดเชื้อ: ผิวหนังรอบเหล็กบวมแดง ร้อน กดเจ็บ หรือมีหนอง/discharge ไหลซึม\r\n4. ตรวจสอบความมั่นคงของน็อตและโครงยึด ห้ามหมุนหรือปรับแต่งน็อตเอง\r\n5. ยกอวัยวะสูงเพื่อลดอาการบวม และระวังไม่ให้โครงเหล็กกระแทกกับสิ่งกีดขวาง\r\nResponse: แผล Pin sites สะอาด แห้งดี ไม่พบอาการอักเสบติดเชื้อ, โครงยึดตรึงแน่นหนา, CMS check ส่วนปลายปกติ ไม่บวมตึง\r\n---\r\n.amputation = การดูแลผู้ป่วยผ่าตัดตัดแขน/ขา (Amputation \u0026 Phantom Limb Pain)\r\nFocus: การพยาบาลหลังผ่าตัดตัดรยางค์และจัดการอาการปวดแขนขาเทียม (Post-Amputation Care)\r\nGoal: แผลตอกลับสมานตัวดี ควบคุมความปวด Phantom limb pain ได้ ป้องกันภาวะข้อพับติด (Contracture) และพร้อมสำหรับการใส่ขาเทียม\r\nData: รับย้ายผู้ป่วยหลังผ่าตัด Amputation (AKA / BKA) ข้าง... ตอขา (Stump) ปิด elastic bandage แนบสนิท, ผู้ป่วยบ่นปวดแปลบเหมือนยังมีขาอยู่ (Phantom limb sensation / pain)\r\nAction: \r\n1. เฝ้าระวังภาวะเลือดออกเฉียบพลัน: วางสายยางรัดห้ามเลือด (Tourniquet) ไว้ที่หัวเตียงตลอดเวลา สังเกตเลือดซึมที่ผ้าปิดแผล\r\n2. จัดท่าตอขา: ช่วง 24 ชม. แรก หนุนหมอนยกตอขาสูงเพื่อลดบวม หลังจาก 24 ชม. ให้นอนราบและกระตุ้นให้นอนคว่ำ (Prone position) วันละ 2-3 ครั้ง ครั้งละ 20-30 นาที เพื่อป้องกันข้อสะโพกงอติด (Hip flexion contracture)\r\n3. อธิบายให้เข้าใจว่าอาการปวดแปลบ Phantom limb pain เป็นปฏิกิริยาปกติของเส้นประสาทที่ถูกตัด และจะค่อยๆ ลดลง\r\n4. ดูแลให้ยาแก้ปวดกลุ่มประสาท (Gabapentin / Pregabalin) ตามคำสั่งแพทย์\r\n5. สอนการพันผ้ายืดตอขาแบบรูปเลข 8 (Figure of 8 bandaging) เพื่อเตรียมตอขาให้เรียวพร้อมใส่ขาเทียมในอนาคต\r\nResponse: แผลตอขาไม่มี active bleeding, ผู้ป่วยคลายความวิตกกังวลเรื่อง Phantom sensation, เข้าใจและให้ความร่วมมือในการนอนคว่ำ, ปวดลดลง\r\n---\r\n\r\n[13. ศัลยกรรมและหัตถการเฉพาะทาง Specialized Surgery]\r\n.appendectomy = ผ่าตัดไส้ติ่งอักเสบ (Post-Op Appendectomy)\r\nFocus: การพยาบาลหลังผ่าตัดไส้ติ่งอักเสบ (Post-Op Appendectomy)\r\nGoal: ฟื้นตัวหลังผ่าตัดไส้ติ่งได้ดี แผลผ่าตัดสะอาด ลำไส้เริ่มกลับมาทำงาน (Bowel sound ปกติ) ผายลมได้ และไม่มีภาวะเยื่อบุช่องท้องอักเสบ\r\nData: รับย้ายผู้ป่วยหลังผ่าตัด Appendectomy (Open / Laparoscopic), แผลผ่าตัดปิดก๊อซแนบสนิท, ท้องนุ่ม ฟังเสียงลำไส้เคลื่อนไหว (Bowel sounds) ได้... ครั้ง/นาที, Pain score = .../10\r\nAction: \r\n1. ประเมินสัญญาณชีพ อาการปวดแผล และอาการแน่นตึงท้อง\r\n2. จัดท่านอนศีรษะสูงเล็กน้อย (Low Fowler\u0027s) งอเข่าเล็กน้อยเพื่อผ่อนคลายกล้ามเนื้อหน้าท้องและลดการตึงของแผล\r\n3. ประเมินการกลับมาทำงานของลำไส้ (Bowel sound, การผายลม)\r\n4. เมื่อผายลมแล้ว เริ่มให้จิบน้ำ และเริ่มอาหารเหลว/อาหารอ่อนตามลำดับคำสั่งแพทย์\r\n5. กระตุ้นให้ลุกขยับตัวและเดินเร็วหลังผ่าตัด (Early ambulation) เพื่อป้องกันลำไส้ติดกันและกระตุ้นการเคลื่อนไหวของทางเดินอาหาร\r\nResponse: สัญญาณชีพคงที่, ผู้ป่วยผายลมได้ ท้องไม่อืด, เริ่มจิบน้ำได้ไม่คลื่นไส้อาเจียน, สามารถลุกเดินข้างเตียงได้, แผลผ่าตัดแห้งดี\r\n---\r\n.lapchole = ผ่าตัดถุงน้ำดีส่องกล้อง (Post-Op Laparoscopic Cholecystectomy)\r\nFocus: การพยาบาลหลังผ่าตัดถุงน้ำดีผ่านกล้อง (Post-Op Lap Chole)\r\nGoal: แผลเจาะส่องกล้องแห้งสะอาด ไม่มีอาการแน่นอึดอัดท้องจากก๊าซ CO2 ไม่มีภาวะน้ำดีรั่ว และสามารถเริ่มรับประทานอาหารไขมันต่ำได้ดี\r\nData: รับย้ายหลังทำ Laparoscopic Cholecystectomy, มีแผลส่องกล้อง 3-4 รอยบริเวณหน้าท้อง ปิดแผลกันน้ำเรียบร้อย, ผู้ป่วยบ่นแน่นท้องและมีอาการปวดร้าวไปที่สะบักไหล่ขวา (Referred shoulder pain from CO2 gas)\r\nAction: \r\n1. ประเมินสัญญาณชีพ และแผลผ่าตัดหน้าท้อง\r\n2. อธิบายให้ผู้ป่วยเข้าใจว่าอาการปวดไหล่เกิดจากก๊าซคาร์บอนไดออกไซด์ที่ใช้ขยายช่องท้องระหว่างผ่าตัดระคายเคืองกะบังลม ซึ่งจะค่อยๆ สลายตัวไปเองใน 24-48 ชม.\r\n3. จัดท่านอนศีรษะสูงและแนะนำให้เปลี่ยนอิริยาบถบ่อยๆ, ช่วยพยุงลุกเดินเพื่อช่วยให้ก๊าซดูดซึมและระบายออกได้เร็วขึ้น\r\n4. ดูแลให้ยาแก้ปวดและยาขับลมตามแผน\r\n5. สังเกตอาการแทรกซ้อน: ตัวเหลือง ตาเหลือง (Jaundice) หรือปวดท้องรุนแรงผิดปกติ (Bile leak)\r\nResponse: ผู้ป่วยคลายความกังวล, ลุกเดินได้ดีขึ้น อาการปวดสะบักไหล่ทุเลาลง, ท้องไม่อืด แผลผ่าตัดแห้งดี ไม่มีเลือดหรือน้ำดีซึม\r\n---\r\n.mastectomy = ผ่าตัดเต้านม (Post-Op Modified Radical Mastectomy: MRM)\r\nFocus: การพยาบาลหลังผ่าตัดเต้านมและป้องกันภาวะบวมน้ำเหลือง (Post-Op MRM \u0026 Lymphedema Prevention)\r\nGoal: แผลผ่าตัดและแผ่นผิวหนังแนบสนิทดี สายระบายทำงานมีประสิทธิภาพ แขนข้างที่ผ่าตัดไม่บวม (No Lymphedema) และบริหารข้อไหล่ได้ตามแผน\r\nData: รับย้ายหลังผ่าตัด MRM เต้านมข้าง... แผลผ่าตัดยาวที่ทรวงอกปิดแนบสนิท, มีสายระบาย JP drain ต่อขวดสุญญากาศ ออก... ml\r\nAction: \r\n1. **ป้องกันภาวะแขนบวมน้ำเหลือง (Lymphedema Prevention) ข้างที่ผ่าตัด**:\r\n   - แขวนป้ายเตือน \"ห้ามวัดความดันโลหิต ห้ามเจาะเลือด ห้ามฉีดยา และห้ามให้น้ำเกลือที่แขนข้างผ่าตัดเด็ดขาด\"\r\n   - จัดวางแขนข้างผ่าตัดหนุนบนหมอนให้อยู่ในระดับสูงกว่าหัวใจเล็กน้อยขณะนอน\r\n2. ดูแลสายระบายแผลให้อยู่ในภาวะสุญญากาศ บันทึกปริมาณและสีของสารคัดหลั่ง\r\n3. เริ่มบริหารแขนและมือแบบเบาๆ: กำมือคลายมือ (Ball squeezing), งอและเหยียดข้อศอก ใน 24 ชม. แรก\r\n4. ให้กำลังใจและประเมินความพร้อมทางด้านจิตใจในการปรับตัวต่อภาพลักษณ์ที่เปลี่ยนไป\r\nResponse: แขนข้างผ่าตัดไม่บวม, แผลไม่มีเลือดออกผิดปกติ, สายระบายคงสภาพสุญญากาศ, ผู้ป่วยสามารถบริหารมืองอศอกได้ดี\r\n---\r\n\r\n\r\n# ==============================================================================\r\n[14. ภาวะเกลือแร่ในเลือดผิดปกติ (Electrolyte Imbalances)]\r\n# ==============================================================================\r\n.hypok = ภาวะโพแทสเซียมในเลือดต่ำ (Hypokalemia, K \u003c 3.5 mEq/L)\r\nFocus: ภาวะโพแทสเซียมในเลือดต่ำ (Hypokalemia, K \u003c 3.5 mEq/L)\r\nGoal: ระดับ Serum K+ กลับสู่เกณฑ์ปกติ (3.5 - 5.0 mEq/L) คลื่นไฟฟ้าหัวใจปกติ กล้ามเนื้อมีแรงดีขึ้น และไม่เกิดภาวะหัวใจเต้นผิดจังหวะ\r\nData:\r\n- ผล Serum K+ ล่าสุด ... mEq/L (ค่าปกติ 3.5 - 5.0 mEq/L)\r\n- ผู้ป่วยมีอาการอ่อนแรง กล้ามเนื้อแขนขาไม่มีแรง ตะคริว ชาปลายมือปลายเท้า ท้องอืด แน่นท้อง ท้องผูก (Paralytic ileus)\r\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเต้นเบาหรือไม่สม่ำเสมอ)\r\n- EKG Monitor: พบ Flat/Inverted T wave, ST depression, Prominent U wave, เฝ้าระวัง Ventricular Arrhythmias\r\nAction:\r\n- รายงานแพทย์ทราบผลแล็บวิกฤต (Critical Lab Value) K+ ... mEq/L ทันที\r\n- ให้การรักษาตามแผน:\r\n  * กรณีรับประทานได้: ให้ KCl Elixir ... ml หรือ Kalimate / Add-K ตามแผนการรักษา แนะนำรับประทานหลังอาหารทันที\r\n  * กรณีให้ทางหลอดเลือดดำ: ให้ KCl ... mEq in IV fluid ... ml drip ใน ... ชม. (ใช้อัตราไม่เกิน 10 - 20 mEq/hr ผ่าน Infusion pump เสมอ ห้าม IV Push หรือ Bolus เด็ดขาด!)\r\n- ติดตาม EKG Monitor ต่อเนื่อง สังเกตอาการทางระบบประสาทและกล้ามเนื้อ\r\n- ตรวจสอบบริเวณแทงสายน้ำเกลือ เฝ้าระวังอาการปวดแสบร้อนตามแนวหลอดเลือด (Phlebitis / Vein irritation)\r\n- ชะลอหรือหลีกเลี่ยงยาขับปัสสาวะกลุ่มขับโพแทสเซียม (เช่น Furosemide) ชั่วคราวตามดุลยพินิจแพทย์\r\nResponse:\r\n- ผู้ป่วยไม่มีอาการชาหรือกล้ามเนื้อกระตุก แรงกล้ามเนื้อดีขึ้น ชีพจรเต้นสม่ำเสมอ\r\n- ไม่มีภาวะหัวใจเต้นผิดจังหวะ ไม่มีอาการปวดแสบบริเวณให้สายน้ำเกลือ\r\n- เจาะเลือดตรวจซ้ำ Serum K+ หลังให้ยาครบตามแผน ผล K+ ซ้ำได้ ... mEq/L\r\n---\r\n.hyperk = ภาวะโพแทสเซียมในเลือดสูง (Hyperkalemia, K \u003e 5.0 - 5.5 mEq/L)\r\nFocus: ภาวะโพแทสเซียมในเลือดสูงวิกฤต (Hyperkalemia, K \u003e 5.0 - 5.5 mEq/L)\r\nGoal: ระดับ Serum K+ ลดลงสู่เกณฑ์ปลอดภัย (\u003c 5.0 mEq/L) ป้องกันภาวะหัวใจเต้นผิดจังหวะที่อันตรายถึงชีวิต และ EKG กลับสู่ภาวะปกติ\r\nData:\r\n- ผล Serum K+ ล่าสุด ... mEq/L (ค่าวิกฤต \u003e 5.5 - 6.0 mEq/L)\r\n- ผู้ป่วยมีอาการกล้ามเนื้ออ่อนแรง ชาตามปลายมือปลายเท้า คลื่นไส้ ใจสั่น ชีพจรเต้นช้าหรือไม่สม่ำเสมอ\r\n- EKG Monitor: พบ Tall peaked T wave, Prolonged PR interval, Flattened P wave, Widened QRS complex, เสี่ยงต่อ Sinus arrest หรือ Ventricular Fibrillation (VF)\r\nAction:\r\n- รายงานแพทย์ทันที และเตรียมอุปกรณ์ช่วยชีวิต / รถ Emergency Cart พร้อม Defibrillator\r\n- ให้การรักษาฉุกเฉินตามแผนแพทย์:\r\n  * ป้องกันกล้ามเนื้อหัวใจ: 10% Calcium Gluconate 10 ml IV push ช้าๆ ใน 3-5 นาที (EKG monitor ขณะให้)\r\n  * ดึงโพแทสเซียมเข้าสู่เซลล์: Regular Insulin (RI) 10 units + 50% Glucose 50 ml IV push หรือ 10% D/W 500 ml + RI ... units IV drip ใน ... ชม.\r\n  * ยาพ่นขยายหลอดลม: Salbutamol (Ventolin) 10-20 mg nebulizer\r\n  * ขับโพแทสเซียมออกจากร่างกาย: Sodium Polystyrene Sulfonate (Kalimate / Kayexalate) 15-30 g Oral / Retention enema หรือ Furosemide (Lasix) ... mg IV\r\n  * เตรียมการฟอกเลือดฉุกเฉิน (Hemodialysis) หากค่า K+ สูงรุนแรงและดื้อต่อยา\r\n- งดอาหารและผลไม้ที่มีโพแทสเซียมสูง (กล้วย ส้ม มะเขือเทศ ฝรั่ง น้ำมะพร้าว)\r\n- บันทึกสัญญาณชีพและ EKG Monitor ทุก 15-30 นาที จนกว่าจะพ้นภาวะวิกฤต\r\nResponse:\r\n- คลื่นไฟฟ้าหัวใจ Tall peaked T wave ลดลง ไม่พบ Widened QRS complex หรือหัวใจเต้นผิดจังหวะ\r\n- ผู้ป่วยรู้สึกตัวดี อาการชาและอ่อนแรงทุเลาลง สัญญาณชีพคงที่\r\n- ติดตามเจาะเลือดตรวจซ้ำ Serum K+ หลังการรักษา ผล K+ ลดลงเหลือ ... mEq/L\r\n---\r\n.hypona = ภาวะโซเดียมในเลือดต่ำ (Hyponatremia, Na \u003c 135 mEq/L)\r\nFocus: ภาวะโซเดียมในเลือดต่ำ (Hyponatremia, Na \u003c 135 mEq/L)\r\nGoal: ระดับ Serum Na+ ค่อยๆ เพิ่มขึ้นสู่เกณฑ์ปลอดภัยอย่างระมัดระวัง สติสัมปชัญญะดีขึ้น ไม่มีอาการชักหรือสมองบวม\r\nData:\r\n- ผล Serum Na+ ล่าสุด ... mEq/L (ระดับต่ำปานกลาง 125-130 mEq/L, ต่ำรุนแรง \u003c 120 mEq/L)\r\n- ผู้ป่วยมีอาการปวดศีรษะ สับสน ซึม อ่อนเพลีย คลื่นไส้อาเจียน กล้ามเนื้อกระตุก (Cerebral edema)\r\n- ประเมิน Glasgow Coma Scale (GCS): E... V... M... คะแนนรวม ... คะแนน\r\n- ประเมินภาวะสารน้ำในร่างกาย (Hypovolemic / Euvolemic / Hypervolemic)\r\nAction:\r\n- รายงานแพทย์ทราบผลแล็บวิกฤต Na+ ... mEq/L ทันที\r\n- ปฏิบัติตามแผนการรักษาอย่างเคร่งครัด:\r\n  * กรณีมีอาการทางระบบประสาทรุนแรง (ชัก/ซึม): ให้ 3% NaCl ... ml IV drip ผ่าน Infusion pump ตามอัตราที่แพทย์สั่งอย่างเคร่งครัด\r\n  * กรณี SIADH / Euvolemic: จำกัดน้ำดื่ม (Fluid restriction) 800 - 1,000 ml/วัน\r\n  * กรณี Hypovolemic: ให้ 0.9% NSS IV drip ทดแทน\r\n- **ข้อควรระวังสำคัญ:** ควบคุมอัตราการเพิ่มของ Na+ ไม่เกิน 8 - 10 mEq/L ใน 24 ชม. เพื่อป้องกันภาวะก้านสมองเสื่อมถาวร (Osmotic Demyelination Syndrome: ODS)\r\n- เฝ้าระวังภาวะชัก: ยกไม้กั้นเตียงทั้งสองข้าง เตรียมออกซิเจนและอุปกรณ์ดูดเสมหะพร้อมข้างเตียง\r\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) ทุก 8 ชม. ชั่งน้ำหนักตัวทุกวัน\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวดีขึ้น ถามตอบรู้เรื่อง สับสนลดลง ไม่มีอาการชักเกร็งหรือคลื่นไส้\r\n- สัญญาณชีพคงที่ ไม่มีภาวะสารน้ำเกิน ปัสสาวะออก \u003e 0.5 ml/kg/hr\r\n- ติดตามระดับ Serum Electrolytes ตามแผนแพทย์ ระดับ Na+ ค่อยๆ ปรับขึ้นสู่เกณฑ์ปลอดภัย\r\n---\r\n.hyperna = ภาวะโซเดียมในเลือดสูง (Hypernatremia, Na \u003e 145 mEq/L)\r\nFocus: ภาวะโซเดียมในเลือดสูง (Hypernatremia, Na \u003e 145 mEq/L)\r\nGoal: ระดับ Serum Na+ ค่อยๆ ลดลงสู่เกณฑ์ปกติ ภาวะขาดน้ำในเซลล์สมองได้รับการแก้ไข ผู้ป่วยรู้สึกตัวดี และสารน้ำในร่างกายสมดุล\r\nData:\r\n- ผล Serum Na+ ล่าสุด ... mEq/L (ค่าปกติ 135 - 145 mEq/L)\r\n- ผู้ป่วยมีอาการกระหายน้ำอย่างรุนแรง ริมฝีปากแห้ง ผิวหนังแห้ง ยืดหยุ่นลดลง (Poor skin turgor)\r\n- อาการทางระบบประสาท: กระสับกระส่าย สับสน ซึม กล้ามเนื้อกระตุก หรือชัก\r\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm, หายใจเร็ว, ปัสสาวะเข้มปริมาณลดลง\r\nAction:\r\n- รายงานแพทย์ทราบค่าระดับโซเดียมสูงผิดปกติ\r\n- คำนวณ Free Water Deficit ร่วมกับแพทย์ และให้น้ำทดแทนอย่างระมัดระวัง:\r\n  * ให้ดื่มน้ำสะอาดบ่อยๆ กรณีผู้ป่วยกลืนได้ปกติ\r\n  * ให้น้ำทางสายยาง NG tube ... ml ทุก ... ชม.\r\n  * กรณีให้ทางหลอดเลือดดำ: ให้สารน้ำไฮโปโทนิก (เช่น 0.45% NaCl หรือ 5% D/W) ทางหลอดเลือดดำตามอัตราที่แพทย์กำหนด\r\n- **ข้อควรระวังสำคัญ:** อัตราการลดลงของ Na+ ต้องไม่เกิน 10 - 12 mEq/L ใน 24 ชม. (ลดไม่เกิน 0.5 mEq/L/hr) เพื่อป้องกันภาวะสมองบวมน้ำเฉียบพลัน (Cerebral edema)\r\n- บันทึกสัญญาณชีพและประเมินระดับความรู้สึกตัว (Neuro signs) ทุก 2-4 ชม.\r\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) อย่างเคร่งครัด\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวดีขึ้น ความกระหายน้ำลดลง เยื่อบุช่องปากชุ่มชื้นขึ้น\r\n- ไม่มีอาการกระตุกหรือชัก สัญญาณชีพคงที่ ปัสสาวะออกเพียงพอ\r\n- ผล Serum Na+ ตรวจติดตามค่อยๆ ลดลงอย่างปลอดภัยตามเป้าหมายการรักษา\r\n---\r\n.hypoca = ภาวะแคลเซียมในเลือดต่ำ (Hypocalcemia, Ca \u003c 8.5 mg/dL)\r\nFocus: ภาวะแคลเซียมในเลือดต่ำ (Hypocalcemia, Total Ca \u003c 8.5 mg/dL)\r\nGoal: ระดับ Serum Ca2+ กลับสู่เกณฑ์ปกติ อาการชา มือจีบเกร็ง กล้ามเนื้อกระตุก (Tetany) ทุเลาลง และคลื่นไฟฟ้าหัวใจปกติ\r\nData:\r\n- ผล Total Calcium ... mg/dL (หรือ Ionized Ca ... mmol/L, ค่าปกติ 1.15 - 1.30 mmol/L)\r\n- ผู้ป่วยมีอาการชาและเหน็บเสียวรอบปาก ปลายมือ ปลายเท้า กล้ามเนื้อกระตุก ปวดเกร็งกล้ามเนื้อ (Cramps)\r\n- ตรวจพบ Chvostek\u0027s sign ให้ผลบวก (เคาะหน้าหูมุมขากรรไกรแล้วมุมปากกระตุก)\r\n- ตรวจพบ Trousseau\u0027s sign ให้ผลบวก (วัดความดันโลหิตค้างไว้แล้วมือหงิกเกร็ง Carpopedal spasm)\r\n- EKG Monitor: พบ Prolonged QT interval, เสี่ยงต่อ Torsades de Pointes\r\nAction:\r\n- รายงานแพทย์ทันที และเตรียม 10% Calcium Gluconate 10 ml\r\n- ให้การรักษาตามแผน:\r\n  * กรณีฉุกเฉิน/มีอาการเกร็ง: ให้ 10% Calcium Gluconate 10 ml IV push ช้าๆ นานอย่างน้อย 10 นาที (หรือผสมใน 5% D/W 100 ml drip ใน 20-30 นาที)\r\n  * เฝ้าระวังอัตราการเต้นของหัวใจอย่างใกล้ชิดขณะฉีด (เสี่ยงต่อ Bradycardia / Arrhythmia)\r\n  * กรณีให้ต่อเนื่อง: ให้ Calcium Gluconate ... amp in IV fluid drip ผ่าน Infusion pump\r\n  * ยารับประทาน: ให้ Calcium carbonate ... mg + Vitamin D (Calcitriol) ตามแผนการรักษา\r\n- ตรวจสอบระดับ Serum Albumin และ Magnesium (หาก Mg ต่ำต้องแก้ไขควบคู่กันจึงจะหาย)\r\n- ดูแลความปลอดภัย ป้องกันอุบัติเหตุจากการหงิกเกร็งหรือชัก\r\nResponse:\r\n- อาการชาและหงิกเกร็งมือเท้าทุเลาลง Chvostek\u0027s sign และ Trousseau\u0027s sign ให้ผลลบ\r\n- คลื่นไฟฟ้าหัวใจ QT interval ปกติ ไม่มีภาวะหัวใจเต้นช้าหรือผิดจังหวะ\r\n- ผลตรวจติดตามระดับแคลเซียมในเลือดกลับสู่เกณฑ์ปกติ\r\n---\r\n.hyperca = ภาวะแคลเซียมในเลือดสูง (Hypercalcemia, Ca \u003e 10.5 mg/dL)\r\nFocus: ภาวะแคลเซียมในเลือดสูง (Hypercalcemia, Total Ca \u003e 10.5 mg/dL)\r\nGoal: ระดับ Serum Ca2+ ลดลงสู่เกณฑ์ปลอดภัย ผู้ป่วยได้รับสารน้ำเพียงพอ ขับแคลเซียมออกทางปัสสาวะได้ดี และไม่มีอาการซึมหรือหัวใจเต้นผิดจังหวะ\r\nData:\r\n- ผล Total Calcium ... mg/dL (ระดับวิกฤต \u003e 12 - 14 mg/dL)\r\n- ผู้ป่วยมีอาการอ่อนเพลีย เบื่ออาหาร คลื่นไส้ อาเจียน ท้องผูก ปวดท้อง ปัสสาวะบ่อย กระหายน้ำมาก\r\n- อาการทางระบบประสาท: สับสน ซึม ตอบสนองช้า หลงลืม Reflex ลดลง\r\n- EKG Monitor: พบ Shortened QT interval, Widened T wave, Bradycardia หรือ Heart block\r\nAction:\r\n- รายงานแพทย์ทราบผลแล็บวิกฤตทันที\r\n- ให้การพยาบาลตามแผนการรักษา:\r\n  * ขยายปริมาตรสารน้ำในหลอดเลือด: ให้ 0.9% NSS IV drip ในอัตรา 200 - 300 ml/hr ตามสภาพหัวใจและไต เพื่อเร่งการขับแคลเซียมออกทางไต\r\n  * ยาขับปัสสาวะ: ให้ Furosemide (Lasix) ... mg IV ตามแผน (ให้หลังจากได้รับสารน้ำอย่างเพียงพอแล้วเท่านั้น ห้ามใช้ Thiazide เด็ดขาด)\r\n  * ยาลดการสลายกระดูก: ให้ Calcitonin / Bisphosphonates (Zoledronic acid / Pamidronate) ตามแผนแพทย์\r\n- บันทึกสัญญาณชีพ ระดับความรู้สึกตัว และ EKG Monitor อย่างใกล้ชิด\r\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) ทุก 2-4 ชม. ป้องกันภาวะขาดน้ำหรือสารน้ำเกิน\r\n- แนะนำการเคลื่อนไหวร่างกายเท่าที่ทำได้ (Mobilization) เพื่อลดการสลายแคลเซียมออกจากกระดูก\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวตื่นดีขึ้น อาการคลื่นไส้และท้องผูกทุเลาลง\r\n- ปัสสาวะออกดี (\u003e 100-150 ml/hr) ไม่มีอาการหอบเหนื่อยหรือบวมจากสารน้ำเกิน\r\n- คลื่นไฟฟ้าหัวใจ QT interval ปกติ ระดับแคลเซียมตรวจซ้ำลดลงสู่เกณฑ์ปลอดภัย\r\n---\r\n.hypomg = ภาวะแมกนีเซียมในเลือดต่ำ (Hypomagnesemia, Mg \u003c 1.7 mg/dL)\r\nFocus: ภาวะแมกนีเซียมในเลือดต่ำ (Hypomagnesemia, Mg \u003c 1.7 mg/dL)\r\nGoal: ระดับ Serum Mg2+ กลับสู่เกณฑ์ปกติ (1.8 - 2.4 mg/dL) อาการกล้ามเนื้อกระตุกและใจสั่นทุเลาลง การตอบสนอง Reflex ปกติ\r\nData:\r\n- ผล Serum Mg2+ ล่าสุด ... mg/dL (ค่าปกติ 1.7 - 2.2 mg/dL)\r\n- ผู้ป่วยมีอาการกล้ามเนื้อกระตุก สั่น (Tremor) กล้ามเนื้อเกร็ง ไวต่อสิ่งกระตุ้น รีเฟล็กซ์ไวเกิน (Hyperreflexia, DTRs 3-4+)\r\n- มักพบร่วมกับภาวะ Hypokalemia และ Hypocalcemia ที่ดื้อต่อการรักษา\r\n- EKG Monitor: พบ Prolonged QT, Prolonged PR, ST depression, T wave inversion, เสี่ยงต่อ Torsades de Pointes และ VT/VF\r\nAction:\r\n- รายงานแพทย์ทราบผลตรวจแมกนีเซียมต่ำ\r\n- ให้การรักษาตามแผน:\r\n  * ภาวะวิกฤต/หัวใจเต้นผิดจังหวะ: ให้ 50% Magnesium sulfate (MgSO4) 2 g (4 ml) ผสมใน 5% D/W 100 ml IV drip ใน 15-30 นาที ผ่าน Infusion pump\r\n  * ภาวะไม่เร่งด่วน: ให้ 50% MgSO4 ... g ผสมใน IV fluid 1,000 ml drip ใน 8-12 ชม.\r\n  * ยารับประทาน: ให้ Magnesium oxide / Mag-F tab ตามแผน\r\n- ติดตาม EKG Monitor ต่อเนื่องขณะให้ยา\r\n- ตรวจ Deep Tendon Reflexes (DTRs), อัตราการหายใจ (RR) และปริมาณปัสสาวะก่อนและระหว่างให้ MgSO4 เสมอ (ป้องกันภาวะ Hypermagnesemia เป็นพิษ)\r\n- จัดสภาพแวดล้อมให้เงียบสงบ ลดสิ่งกระตุ้นเพื่อป้องกันอาการชักเกร็ง\r\nResponse:\r\n- กล้ามเนื้อไม่อ่อนแรงหรือกระตุกสั่น รีเฟล็กซ์ DTRs ปกติ (2+)\r\n- คลื่นไฟฟ้าหัวใจปกติ ไม่มี Ventricular Arrhythmia หรือ Torsades de Pointes\r\n- ผลตรวจติดตาม Serum Mg2+ กลับสู่ระดับปกติ\r\n---\r\n.hypermg = ภาวะแมกนีเซียมในเลือดสูง (Hypermagnesemia, Mg \u003e 2.5 mg/dL)\r\nFocus: ภาวะแมกนีเซียมในเลือดสูง (Hypermagnesemia, Mg \u003e 2.5 mg/dL)\r\nGoal: ระดับ Serum Mg2+ ลดลงสู่เกณฑ์ปกติ การหายใจและสัญญาณชีพคงที่ Reflex กลับมาปกติ และขับแมกนีเซียมออกได้ดี\r\nData:\r\n- ผล Serum Mg2+ ล่าสุด ... mg/dL (ระดับวิกฤต \u003e 4.0 - 5.0 mg/dL)\r\n- ผู้ป่วยมีอาการหน้าแดง ร้อนวูบวาบ คลื่นไส้ อาเจียน กล้ามเนื้ออ่อนแรง ง่วงซึม ตอบสนองช้า\r\n- ตรวจ Deep Tendon Reflexes (DTRs): ลดลงหรือไม่พบ (Hyporeflexia / Absent DTRs, 0 - 1+)\r\n- สัญญาณชีพ: BP ตก (Hypotension), ชีพจรเต้นช้า (Bradycardia), อัตราการหายใจช้า (\u003c 10-12 ครั้ง/นาที)\r\n- EKG Monitor: Prolonged PR, Widened QRS, Tall T wave, เสี่ยงต่อ Complete Heart Block หรือ Cardiac arrest\r\nAction:\r\n- รายงานแพทย์ทันที และหยุดยาทุกชนิดที่มีส่วนผสมของแมกนีเซียม (ยาลดกรด, ยาระบาย M.O.M., ยาบำรุง)\r\n- ให้ยาต้านฤทธิ์ฉุกเฉินตามแผน: ให้ 10% Calcium Gluconate 10 ml IV push ช้าๆ ใน 5-10 นาที เพื่อต้านพิษของแมกนีเซียมต่อกล้ามเนื้อหัวใจ\r\n- ส่งเสริมการขับถ่ายแมกนีเซียม: ให้ 0.9% NSS IV drip ร่วมกับ Furosemide (Lasix) ... mg IV ตามแผน\r\n- ให้ออกซิเจนและเตรียมเครื่องช่วยหายใจ / รถกู้ชีพฉุกเฉินให้พร้อม\r\n- เตรียมผู้ป่วยเพื่อฟอกเลือดฉุกเฉิน (Hemodialysis) กรณีผู้ป่วยไตวายหรือระดับ Mg สูงวิกฤตรุนแรง\r\n- ประเมิน DTRs, อัตราการหายใจ และระดับความรู้สึกตัวทุก 15-30 นาที\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวดีขึ้น รีเฟล็กซ์ DTRs กลับมาปกติ (2+)\r\n- หายใจสม่ำเสมอ อัตราการหายใจ \u003e 16 ครั้ง/นาที ความดันโลหิตและชีพจรคงที่\r\n- ผลตรวจ Serum Mg2+ ลดลงสู่เกณฑ์ปลอดภัย\r\n---\r\n.hypop = ภาวะฟอสเฟตในเลือดต่ำ (Hypophosphatemia, PO4 \u003c 2.5 mg/dL)\r\nFocus: ภาวะฟอสเฟตในเลือดต่ำ (Hypophosphatemia, Serum Phosphate \u003c 2.5 mg/dL)\r\nGoal: ระดับ Serum Phosphate กลับสู่เกณฑ์ปกติ (2.5 - 4.5 mg/dL) กล้ามเนื้อหายใจและกล้ามเนื้อลายมีแรงดีขึ้น ไม่อ่อนเพลีย\r\nData:\r\n- ผล Serum Phosphorus/Phosphate ล่าสุด ... mg/dL (ค่าวิกฤต \u003c 1.0 - 1.5 mg/dL)\r\n- ผู้ป่วยมีอาการกล้ามเนื้ออ่อนแรง หายใจเหนื่อย หย่าเครื่องช่วยหายใจไม่สำเร็จ (Difficulty weaning from ventilator)\r\n- มีอาการสับสน อ่อนเพลียอย่างมาก ชัก อาการกล้ามเนื้อสลาย (Rhabdomyolysis) ปวดกล้ามเนื้อ ปัสสาวะสีโค้ก\r\n- มักพบในผู้ป่วยทุพโภชนาการที่ได้รับสารอาหารเร็วเกินไป (Refeeding Syndrome), ผู้ป่วย DKA หลังได้ Insulin, หรือพิษสุราเรื้อรัง\r\nAction:\r\n- รายงานแพทย์ทราบค่าฟอสเฟตในเลือดต่ำ\r\n- ให้การพยาบาลตามแผนการรักษา:\r\n  * กรณีให้ทางหลอดเลือดดำ: ให้ Sodium Phosphate หรือ Potassium Phosphate ... mmol in IV fluid ... ml drip ช้าๆ ใน 4-6 ชม. (ใช้อัตราไม่เกิน 7-10 mmol/hr เฝ้าระวังระดับแคลเซียมในเลือดลดต่ำลง)\r\n  * กรณีรับประทานได้: เสริมฟอสเฟตทางปาก เช่น นม ไข่แดง ถั่ว ปลา หรือยาฟอสเฟตตามแพทย์สั่ง\r\n- ประเมินกำลังกล้ามเนื้อ อัตราและลักษณะการหายใจอย่างใกล้ชิด\r\n- ติดตามระดับ Serum Phosphate, Calcium, Potassium และ Magnesium ควบคู่กันเสมอ\r\n- เฝ้าระวังสีและปริมาณปัสสาวะ ตรวจติดตามค่า CK หากสงสัยภาวะกล้ามเนื้อสลาย\r\nResponse:\r\n- กำลังกล้ามเนื้อดีขึ้น หายใจสม่ำเสมอ หายใจด้วยตนเองได้ดีขึ้น\r\n- ปัสสาวะออกปกติ ไม่มีสีเข้มผิดปกติ\r\n- ผลตรวจติดตาม Serum Phosphate เพิ่มขึ้นสู่ระดับปกติอย่างปลอดภัย\r\n---\r\n.hyperp = ภาวะฟอสเฟตในเลือดสูง (Hyperphosphatemia, PO4 \u003e 4.5 mg/dL)\r\nFocus: ภาวะฟอสเฟตในเลือดสูง (Hyperphosphatemia, Serum Phosphate \u003e 4.5 mg/dL)\r\nGoal: ระดับ Serum Phosphate ลดลงสู่เกณฑ์ปลอดภัย ป้องกันการจับตัวของผลึกแคลเซียมฟอสเฟตในเนื้อเยื่อ และไตขับฟอสเฟตได้ดีขึ้น\r\nData:\r\n- ผล Serum Phosphorus/Phosphate ล่าสุด ... mg/dL (ค่าปกติ 2.5 - 4.5 mg/dL)\r\n- ผู้ป่วยมีอาการคันตามผิวหนัง มีอาการของภาวะแคลเซียมต่ำร่วมด้วย (กล้ามเนื้อกระตุก มือหงิกเกร็ง ชารอบปาก)\r\n- มีประวัติโรคไตเรื้อรัง (CKD/ESRD), ภาวะเนื้อเยื่อสลาย (Tumor Lysis Syndrome / Rhabdomyolysis)\r\n- เสี่ยงต่อการเกิดผลึกแคลเซียมฟอสเฟตตกตะกอนตามเนื้อเยื่อ หลอดเลือด และไต (Metastatic Calcification)\r\nAction:\r\n- รายงานแพทย์ทราบผลแล็บ\r\n- ให้การรักษาและการพยาบาลตามแผน:\r\n  * ให้ยาจับฟอสเฟตในทางเดินอาหาร (Phosphate Binders) เช่น Calcium carbonate, Calcium acetate หรือ Sevelamer ตามแผนการรักษา (แนะนำผู้ป่วยรับประทานพร้อมอาหารหรือเคี้ยวพร้อมมื้ออาหารทันทีเพื่อให้ยาจับกับฟอสเฟตในอาหาร)\r\n  * งดอาหารที่มีฟอสเฟตสูง: ผลิตภัณฑ์จากนม เนย ชีส ถั่ว ข้าวโอ๊ต ช็อกโกแลต น้ำอัดลมสีเข้ม\r\n  * ให้น้ำเกลือ 0.9% NSS IV drip และยาขับปัสสาวะเพื่อเร่งการขับถ่ายทางไต (ในผู้ป่วยที่การทำงานของไตยังดี)\r\n  * เตรียมการฟอกเลือด (Hemodialysis) ตามแผนการรักษาในผู้ป่วยไตวายเรื้อรัง\r\n- ดูแลผิวหนัง ทาโลชั่นบรรเทาอาการคัน และตัดเล็บให้สั้นเพื่อป้องกันแผลติดเชื้อจากการเกา\r\nResponse:\r\n- ผู้ป่วยไม่มีอาการชาเกร็ง อาการคันตามผิวหนังลดลง\r\n- ปฏิบัติตัวและควบคุมอาหารที่มีฟอสเฟตสูงได้อย่างถูกต้อง รับประทานยาพร้อมมื้ออาหารตามคำแนะนำ\r\n- ผลตรวจ Serum Phosphate และ Calcium ค่อยๆ ลดลงสู่ระดับเป้าหมาย\r\n---\r\n\r\n\r\n# ==============================================================================\r\n[15. ผลแล็บและค่าเลือดผิดปกติ (Critical Labs \u0026 Abnormal Blood Values)]\r\n# ==============================================================================\r\n.anemia = ภาวะโลหิตจางรุนแรง / ซีดวิกฤต (Severe Anemia, Hb \u003c 7-8 g/dL)\r\nFocus: ภาวะโลหิตจางรุนแรง / ภาวะซีดวิกฤต (Severe Anemia, Hb \u003c 7-8 g/dL)\r\nGoal: ระดับ Hb/Hct เพิ่มขึ้นสู่เกณฑ์เป้าหมาย อาการซีด เหนื่อย เพลีย วิงเวียนศีรษะทุเลาลง เนื้อเยื่อได้รับออกซิเจนเพียงพอ และสัญญาณชีพคงที่\r\nData:\r\n- ผล CBC: Hb ... g/dL, Hct ... %, RBC indices ปกติ/ผิดปกติ\r\n- ผู้ป่วยมีอาการหน้ามืด วิงเวียนศีรษะ เหนื่อยง่าย อ่อนเพลีย ใจสั่นเวลาขยับตัว ตาพร่ามัว ซีดตามเยื่อบุตา ริมฝีปาก และฝ่ามือ\r\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเร็ว Tachycardia), SpO2 ... %\r\n- ประเมินแหล่งเลือดออก: แผลผ่าตัด, เลือดออกในทางเดินอาหาร (Melena / Hematemesis), หรือปัสสาวะปนเลือด\r\nAction:\r\n- รายงานแพทย์ทราบผลค่าเลือดวิกฤตทันที\r\n- ดูแลให้นอนพักบนเตียง (Bed rest) ช่วยเหลือการทำกิจวัตรประจำวัน ยกไม้กั้นเตียงป้องกันพลัดตกหกล้ม\r\n- ให้ออกซิเจนแคนนูลา 3-5 LPM ตามแผนการรักษาเพื่อเพิ่มการนำส่งออกซิเจนสู่เนื้อเยื่อ\r\n- เตรียมการให้เลือดตามแผนแพทย์:\r\n  * เจาะเลือดส่งตรวจ Blood Grouping, Rh และ Crossmatch ทันที\r\n  * ตรวจสอบเลือด Packed Red Cells (PRC) ... unit ร่วมกับพยาบาล 2 ท่าน (ตรวจสอบชื่อ-สกุล, HN, Unit no., Blood group, วันหมดอายุ)\r\n  * วัดสัญญาณชีพก่อนให้เลือด, ที่ 15 นาทีแรก, และทุก 1 ชม. จนให้เสร็จ\r\n  * ให้เลือดผ่านสาย Transfusion set ที่มีตัวกรอง เฝ้าระวังปฏิกิริยาแพ้เลือด (ไข้ หนาวสั่น แน่นหน้าอก ผื่นขึ้น BP ตก)\r\n- ติดตามบันทึกสัญญาณชีพและอาการเหนื่อยอย่างใกล้ชิด\r\nResponse:\r\n- ผู้ป่วยไม่มีอาการหน้ามืด เหนื่อยเพลียลดลง ริมฝีปากและเล็บมีสีชมพูขึ้น\r\n- ไม่มีภาวะแทรกซ้อนจากการให้เลือด สัญญาณชีพคงที่ ไม่มีไข้หรือผื่น\r\n- ตรวจติดตามค่า Hct ซ้ำหลังให้เลือด 4-6 ชม. ค่า Hct เพิ่มขึ้นเป็น ... %\r\n---\r\n.thrombocyto = ภาวะเกล็ดเลือดต่ำวิกฤต (Severe Thrombocytopenia, Plt \u003c 20,000 - 50,000 /uL)\r\nFocus: ภาวะเกล็ดเลือดต่ำวิกฤต เสี่ยงต่อภาวะเลือดออกรุนแรง (Severe Thrombocytopenia)\r\nGoal: ระดับเกล็ดเลือดอยู่ในเกณฑ์ปลอดภัย ไม่เกิดภาวะเลือดออกผิดปกติในอวัยวะสำคัญ (Zero Major Bleeding) และไม่มีจุดเลือดออกเพิ่ม\r\nData:\r\n- ผล Platelet Count ล่าสุด ... /uL (ค่าวิกฤต \u003c 20,000 - 50,000 /uL)\r\n- สำรวจร่างกายพบ: จุดเลือดออกใต้ผิวหนัง (Petechiae), จ้ำเลือด (Purpura/Ecchymosis), เลือดออกตามไรฟัน, เลือดกำเดาไหล\r\n- เฝ้าระวังเลือดออกในอวัยวะสำคัญ: ปวดศีรษะรุนแรง อาเจียนพุ่ง (Intracranial hemorrhage), ถ่ายดำ ถ่ายเป็นเลือด ปัสสาวะเป็นเลือด\r\nAction:\r\n- รายงานแพทย์ทราบผลเกล็ดเลือดต่ำวิกฤต\r\n- ปฏิบัติตามมาตรการป้องกันเลือดออก (Bleeding Precautions) อย่างเคร่งครัด:\r\n  * **ห้ามฉีดยาเข้ากล้ามเนื้อ (No IM Injection)** เด็ดขาด และหลีกเลี่ยงการเจาะเลือดซ้ำซ้อน\r\n  * หากจำเป็นต้องเจาะเลือด ให้กดแผลห้ามเลือดแน่นๆ นานอย่างน้อย 5-10 นาที\r\n  * แนะนำผู้ป่วยใช้แปรงสีฟันขนอ่อนนุ่ม ห้ามแคะจมูก ห้ามเบ่งถ่ายอุจจาระแรงๆ\r\n  * ยกไม้กั้นเตียงทั้งสองข้าง ระวังการกระแทกหรือพลัดตกหกล้ม\r\n  * หลีกเลี่ยงยาที่มีผลต่อการทำงานของเกล็ดเลือด เช่น Aspirin, NSAIDs, Anticoagulants\r\n- ให้สารประกอบเกล็ดเลือด (Platelet Concentrate / Single Donor Platelet) ... units ตามแผนแพทย์ โดยให้ทันทีผ่านสายให้เลือดด้วยความนุ่มนวล\r\n- บันทึกสัญญาณชีพและตรวจระบบประสาท (Pupils, GCS) ทุก 2-4 ชม.\r\nResponse:\r\n- ไม่มีจุดเลือดออกใหม่ตามผิวหนัง ไม่มีเลือดออกตามไรฟันหรือเลือดกำเดา\r\n- รู้สึกตัวดี สัญญาณชีพคงที่ ไม่มีอาการปวดศีรษะหรือความดันในกะโหลกศีรษะสูง\r\n- ผลตรวจ Platelet count หลังให้เกล็ดเลือดเพิ่มขึ้นเป็น ... /uL\r\n---\r\n.pancytopenia = ภาวะเม็ดเลือดต่ำทุกชนิด (Pancytopenia: Anemia + Leukopenia + Thrombocytopenia)\r\nFocus: ภาวะเม็ดเลือดต่ำทุกชนิด (Pancytopenia: เม็ดเลือดแดง เม็ดเลือดขาว และเกล็ดเลือดต่ำพร้อมกัน)\r\nGoal: ป้องกันการติดเชื้อในกระแสเลือด ป้องกันภาวะเลือดออกง่าย และแก้ไขภาวะซีดอย่างมีประสิทธิภาพ\r\nData:\r\n- ผล CBC: Hb ... g/dL, WBC ... /uL, ANC ... /uL, Platelet ... /uL\r\n- มีอาการอ่อนเพลีย เหนื่อย ซีด (Anemia) เสี่ยงต่อการติดเชื้อง่าย (Neutropenia) และมีจ้ำเลือด/เลือดออกง่าย (Thrombocytopenia)\r\n- ประเมินสัญญาณชีพ: T ... °C, BP ... mmHg, PR ... bpm, RR ... /min\r\nAction:\r\n- รายงานแพทย์และเฝ้าระวัง 3 ภาวะหลักพร้อมกัน:\r\n  1. **ด้านการติดเชื้อ (Infection Protection):** แนะนำผู้ป่วยสวมหน้ากากอนามัย ล้างมือบ่อยๆ แยกห้องพัก ดูแลความสะอาดของร่างกายและสิ่งแวดล้อม รับประทานอาหารปรุงสุกสะอาด\r\n  2. **ด้านภาวะซีด (Anemia Care):** ดูแลให้นอนพักบนเตียง ลดกิจกรรมที่เหนื่อยล้า ให้ออกซิเจนตามแผนการรักษา\r\n  3. **ด้านการป้องกันเลือดออก (Bleeding Precautions):** หลีกเลี่ยงการฉีดยาเข้ากล้าม ใช้แปรงสีฟันขนนุ่ม ระวังอุบัติเหตุหกล้ม\r\n- ให้ยาปฏิชีวนะ ยาเพิ่มเม็ดเลือดขาว (G-CSF) เลือด PRC หรือเกล็ดเลือดตามแผนแพทย์อย่างเคร่งครัด\r\n- วัดสัญญาณชีพและอุณหภูมิกายทุก 4 ชม. หากมีไข้ (T ≥ 38.0 °C) ให้รายงานแพทย์และส่ง Hemoculture ทันที\r\nResponse:\r\n- ผู้ป่วยไม่มีไข้ ไม่มีจุดเลือดออกใหม่ ปากและเยื่อบุสะอาด\r\n- รู้สึกตัวดี อาการอ่อนเพลียลดลง สัญญาณชีพคงที่\r\n- ปฏิบัติตัวตามมาตรการป้องกันการติดเชื้อและเลือดออกได้อย่างถูกต้อง\r\n---\r\n.leukocytosis = ภาวะเม็ดเลือดขาวสูงผิดปกติ / ติดเชื้อรุนแรง (Leukocytosis, WBC \u003e 15,000 /uL)\r\nFocus: ภาวะเม็ดเลือดขาวสูงผิดปกติ บ่งชี้การติดเชื้อรุนแรงในร่างกาย (Leukocytosis / Severe Infection)\r\nGoal: ค้นหาและกำจัดแหล่งติดเชื้อ ระดับเม็ดเลือดขาวลดลงสู่เกณฑ์ปกติ สัญญาณชีพคงที่ และไข้ลดลง\r\nData:\r\n- ผล CBC: WBC ... /uL (ค่าปกติ 4,000 - 10,000 /uL), Neutrophil ... %, Band form ... % (Shift to the left)\r\n- อาการแสดง: มีไข้ หนาวสั่น เหงื่อออก ชีพจรเต้นเร็ว หายใจเร็ว ปวดเมื่อยตามตัว\r\n- ค้นหาจุดติดเชื้อ: แผลผ่าตัดมีอาการปวด บวม แดง ร้อน มีหนอง, ไอมีเสมหะสีเหลืองเขียว, ปัสสาวะแสบขัดขุ่น, หรือสายสวนต่างๆ\r\n- สัญญาณชีพ: T ... °C, PR ... bpm, RR ... /min, BP ... mmHg\r\nAction:\r\n- รายงานแพทย์ทราบผลค่าเม็ดเลือดขาวสูงและอาการแสดงของการติดเชื้อ\r\n- ปฏิบัติตาม Sepsis Protocol:\r\n  * ส่งตรวจเพาะเชื้อ (Hemoculture 2 ข้าง, Sputum, Urine culture) ก่อนเริ่มยาปฏิชีวนะ\r\n  * ให้ยาปฏิชีวนะทางหลอดเลือดดำ (IV Antibiotics) ภายใน 1 ชม. แรกตามแผนการรักษาอย่างเคร่งครัด\r\n  * ให้ยาลดไข้ Paracetamol ... mg ทางปาก/IV และเช็ดตัวลดไข้ (Tepid sponge)\r\n- ดูแลทำความสะอาดแผลผ่าตัดด้วยเทคนิคปลอดเชื้อ (Aseptic technique)\r\n- ติดตามอุณหภูมิกายและสัญญาณชีพทุก 2-4 ชม. ประเมินภาวะช็อกจากการติดเชื้อ (Septic Shock)\r\nResponse:\r\n- ไข้ลดลง อุณหภูมิกาย \u003c 37.5 °C ชีพจรและการหายใจช้าลงสู่เกณฑ์ปกติ\r\n- แผลผ่าตัดแห้งดี ไม่มีหนองซึม\r\n- ผลตรวจติดตาม WBC ตรวจซ้ำลดลงสู่ระดับปกติ\r\n---\r\n.neutropenia = ภาวะเม็ดเลือดขาวต่ำวิกฤต / เสี่ยงติดเชื้อรุนแรง (Febrile / Severe Neutropenia, ANC \u003c 500-1,000)\r\nFocus: ภาวะเม็ดเลือดขาวต่ำวิกฤต เสี่ยงต่อการติดเชื้อรุนแรงถึงแก่ชีวิต (Severe Neutropenia, ANC \u003c 500-1,000)\r\nGoal: ป้องกันการติดเชื้อแบคทีเรียและเชื้อราอย่างเข้มงวด (Infection-free) เม็ดเลือดขาวชนิด Neutrophil ฟื้นตัว และไม่เกิดภาวะ Sepsis\r\nData:\r\n- ผล Absolute Neutrophil Count (ANC) ล่าสุด ... /uL (ภาวะวิกฤต ANC \u003c 500 /uL เสี่ยงติดเชื้อขั้นรุนแรง)\r\n- อุณหภูมิกาย: T ... °C (หาก T ≥ 38.0°C หรือ ≥ 38.3°C ถือเป็นภาวะฉุกเฉิน Febrile Neutropenia)\r\n- สังเกตอาการติดเชื้อที่อาจไม่มีหนองชัดเจน: เจ็บคอ แผลในปาก ปวดทวารหนัก เจ็บบริเวณสายสวนหลอดเลือด หนาวสั่น ซึม\r\nAction:\r\n- ดำเนินการตามมาตรการป้องกันการติดเชื้อเข้มงวด (Neutropenic Precautions):\r\n  * จัดให้อยู่ในห้องแยกเดี่ยว (Private Room) แนะนำผู้เข้าพบสวมหน้ากากอนามัยและล้างมือทุกครั้ง\r\n  * หลีกเลี่ยงอาหารดิบ ผักสด ผลไม้เปลือกบาง รับประทานเฉพาะอาหารปรุงสุกใหม่ สะอาด\r\n  * แนะนำบ้วนปากด้วยน้ำเกลือ 0.9% NSS ทุกครั้งหลังอาหาร หลีกเลี่ยงน้ำยาบ้วนปากที่มีแอลกอฮอล์\r\n  * **ห้ามวัดอุณหภูมิทางทวารหนัก และห้ามเหน็บยา/สวนอุจจาระ (No per rectum)** เพื่อป้องกันเยื่อบุฉีกขาด\r\n- กรณีมีไข้ (Febrile Neutropenia): ส่งเพาะเชื้อ Hemoculture 2 จุดทันที และให้ยาปฏิชีวนะ Broad-spectrum IV Antibiotics ภายใน 1 ชม.\r\n- ให้ยาเพิ่มเม็ดเลือดขาว Granulocyte Colony-Stimulating Factor (G-CSF / Filgrastim) ฉีดใต้ผิวหนังตามแผนแพทย์\r\n- วัดสัญญาณชีพและประเมินอาการติดเชื้อทุก 2-4 ชม.\r\nResponse:\r\n- ผู้ป่วยไม่มีไข้ ไม่มีอาการหนาวสั่น เยื่อบุช่องปากสะอาด ไม่มีแผลอักเสบ\r\n- สัญญาณชีพคงที่ ไม่มีอาการติดเชื้อในกระแสเลือด\r\n- ผลตรวจติดตาม ANC ค่อยๆ เพิ่มขึ้นสูงกว่า 1,000 /uL\r\n---\r\n.coagulopathy = ภาวะการแข็งตัวของเลือดผิดปกติ (Coagulopathy, Prolonged PT/INR, PTT)\r\nFocus: ภาวะการแข็งตัวของเลือดผิดปกติ เสี่ยงต่อภาวะเลือดออกไม่หยุด (Coagulopathy)\r\nGoal: การแข็งตัวของเลือดกลับสู่เกณฑ์ปลอดภัย ค่า PT/INR/PTT ดีขึ้น ไม่มีเลือดออกในอวัยวะสำคัญ และหยุดเลือดได้อย่างรวดเร็ว\r\nData:\r\n- ผล Coagulogram ล่าสุด: PT ... sec, INR ... (ปกติ 0.8-1.2, วิกฤต \u003e 2.5-3.0), aPTT ... sec (ปกติ 25-35 sec)\r\n- ผู้ป่วยมีประวัติใช้ยาต้านการแข็งตัวของเลือด (Warfarin / Heparin / DOACs), โรคตับแข็ง, หรือภาวะ DIC\r\n- สำรวจร่างกาย: เลือดออกตามแผลผ่าตัดไม่ยอมหยุด, เลือดออกตามรอยเจาะเข็ม, จ้ำเลือดขนาดใหญ่, เลือดออกในทางเดินอาหาร\r\nAction:\r\n- รายงานแพทย์ทราบผลค่าการแข็งตัวของเลือดที่ผิดปกติทันที\r\n- ปฏิบัติตามแผนการรักษาเพื่อแก้ไขการแข็งตัวของเลือด:\r\n  * กรณีได้รับ Warfarin เกินขนาด: ให้ Vitamin K1 (Phytomenadione) ... mg IV slow push หรือ Oral ตามแผน\r\n  * กรณีได้รับ Heparin เกินขนาด: ให้ Protamine sulfate ตามสัดส่วนขนาดยาและเวลาที่แพทย์กำหนด\r\n  * กรณีเลือดออกเฉียบพลัน: ให้ Fresh Frozen Plasma (FFP) ... units IV drip เพื่อทดแทน Clotting factors\r\n  * หยุดยาต้านการแข็งตัวของเลือดทุกชนิดชั่วคราวตามคำสั่งแพทย์\r\n- ใช้สำลีหรือผ้าก๊อซกดแผลห้ามเลือดนานกว่าปกติ (อย่างน้อย 10-15 นาที)\r\n- เฝ้าระวังเลือดออกในอวัยวะสำคัญ: บันทึกระดับความรู้สึกตัว (Neuro signs), สัญญาณชีพ และตรวจสีปัสสาวะ/อุจจาระ\r\nResponse:\r\n- เลือดบริเวณแผลผ่าตัดและรอยเข็มหยุดสนิท ไม่มีจ้ำเลือดหรือเลือดออกเพิ่ม\r\n- ผู้ป่วยรู้สึกตัวดี สัญญาณชีพคงที่ Hct ไม่ลดลง\r\n- ผลตรวจซ้ำ PT/INR และ aPTT ลดลงสู่เกณฑ์ที่ปลอดภัยตามเป้าหมาย\r\n---\r\n.metacid = ภาวะเลือดเป็นกรดเมแทบอลิก (Metabolic Acidosis, pH \u003c 7.35, HCO3 \u003c 22)\r\nFocus: ภาวะเลือดเป็นกรดเมแทบอลิก (Metabolic Acidosis, pH \u003c 7.35, HCO3 \u003c 22 mEq/L)\r\nGoal: ภาวะกรดเมตาบอลิกได้รับการแก้ไข ค่า pH และ HCO3- ในเลือดกลับสู่เกณฑ์ปกติ การหายใจลึกเหนื่อยลดลง และสัญญาณชีพคงที่\r\nData:\r\n- ผล Arterial Blood Gas (ABG): pH ... (ปกติ 7.35-7.45), HCO3 ... mEq/L (ปกติ 22-26), PaCO2 ... mmHg, Base Excess ...\r\n- อาการแสดง: หายใจลึกเร็ว (Kussmaul breathing เพื่อขับ CO2 ชดเชย), อ่อนเพลีย สับสน ซึม คลื่นไส้\r\n- สัญญาณชีพ: BP ตก (Hypotension), ชีพจรเร็ว, ปลายมือปลายเท้าเย็น\r\n- สาเหตุที่พบบ่อย: DKA (น้ำตาลสูง), Lactic Acidosis (Sepsis/Shock), ไตวายรุนแรง (Uremia), หรือท้องเสียรุนแรง\r\nAction:\r\n- รายงานแพทย์ทราบผลตรวจก๊าซในเลือดทันที\r\n- ดูแลรักษาตามสาเหตุของภาวะกรดเกิน:\r\n  * กรณีติดเชื้อ/ช็อก (Lactic acidosis): ให้สารน้ำ 0.9% NSS / Acetar IV resuscitation อย่างเต็มที่ ร่วมกับยาปฏิชีวนะ\r\n  * กรณี DKA: ให้ Regular Insulin IV drip ร่วมกับสารน้ำทดแทนตาม DKA Protocol\r\n  * กรณีเป็นกรดรุนแรง (pH \u003c 7.1-7.2 หรือ HCO3 \u003c 10): ให้ 7.5% Sodium Bicarbonate ... ml ผสมในสารน้ำ IV drip ตามแผนแพทย์อย่างระมัดระวัง\r\n- ให้ออกซิเจนแคนนูลาหรือ Mask with bag ตามความเหมาะสม\r\n- ติดตามเฝ้าระวังระดับ Serum K+ (ภาวะเลือดเป็นกรดทำให้ K+ ออกนอกเซลล์ เมื่อกรดลดลง K+ จะลดลงตาม)\r\n- ตรวจบันทึกสัญญาณชีพ, สภาพการหายใจ และประเมินระดับความรู้สึกตัวทุก 1-2 ชม.\r\nResponse:\r\n- การหายใจลึกเร็วลดลง สภาพการหายใจสม่ำเสมอขึ้น\r\n- ผู้ป่วยรู้สึกตัวดีขึ้น ความดันโลหิตและสัญญาณชีพกลับสู่เกณฑ์ปกติ\r\n- ผลตรวจติดตาม ABG: ค่า pH และ HCO3 ปรับตัวดีขึ้นสู่ระดับปลอดภัย\r\n---\r\n.metalk = ภาวะเลือดเป็นด่างเมแทบอลิก (Metabolic Alkalosis, pH \u003e 7.45, HCO3 \u003e 26)\r\nFocus: ภาวะเลือดเป็นด่างเมแทบอลิก (Metabolic Alkalosis, pH \u003e 7.45, HCO3 \u003e 26 mEq/L)\r\nGoal: ภาวะด่างเมตาบอลิกดีขึ้น การหายใจและเกลือแร่กลับสู่สมดุล อาการชาและกล้ามเนื้อกระตุกเกร็งทุเลาลง\r\nData:\r\n- ผล Arterial Blood Gas (ABG): pH ... (ค่าปกติ 7.35 - 7.45), HCO3 ... mEq/L (ค่าปกติ 22 - 26 mEq/L)\r\n- อาการแสดง: การหายใจช้าและตื้น (Hypoventilation เพื่อกัก CO2 ชดเชย), ชาปลายมือปลายเท้า, กล้ามเนื้อกระตุกเกร็ง (Tetany)\r\n- มักพบร่วมกับภาวะ Hypokalemia และ Hypochloremia จากการอาเจียนรุนแรง, การดูดระบายน้ำย่อยทาง NG tube มากเกินไป, หรือการได้ยาขับปัสสาวะ\r\nAction:\r\n- รายงานแพทย์ทราบผลค่าเลือด\r\n- ให้การพยาบาลตามแผนการรักษา:\r\n  * ให้สารน้ำ 0.9% NSS IV drip เพื่อชดเชยปริมาตรและคลอไรด์ (Chloride-responsive alkalosis)\r\n  * ตรวจและแก้ไขภาวะโพแทสเซียมต่ำ: เสริม Potassium Chloride (KCl) ตามแผนการรักษา\r\n  * กรณีคาสาย NG tube ดูดน้ำย่อย: ปรับลดความถี่หรือหยุดการดูดระบายชั่วคราวตามคำสั่งแพทย์\r\n- สังเกตลักษณะการหายใจและตรวจวัดความอิ่มตัวของออกซิเจน (SpO2) อย่างใกล้ชิด (ป้องกันภาวะ Hypoxemia จากการหายใจช้า)\r\n- บันทึกสัญญาณชีพ ปริมาณน้ำเข้า-ออก (I/O) และอาการทางระบบประสาทกล้ามเนื้อ\r\nResponse:\r\n- อาการชาและกล้ามเนื้อกระตุกทุเลาลง การหายใจสม่ำเสมอ SpO2 \u003e 95%\r\n- สัญญาณชีพคงที่ ระดับเกลือแร่ K+ และ Cl- ตรวจซ้ำกลับสู่เกณฑ์ปกติ\r\n- ผล ABG ค่าความเป็นกรดด่าง (pH) กลับคืนสู่สภาวะสมดุล\r\n---\r\n.respacid = ภาวะเลือดเป็นกรดจากการหายใจล้มเหลว (Respiratory Acidosis / CO2 Retention)\r\nFocus: ภาวะเลือดเป็นกรดจากการหายใจ ระบายคาร์บอนไดออกไซด์ไม่เพียงพอ (Respiratory Acidosis, PaCO2 \u003e 45 mmHg)\r\nGoal: ปรับปรุงการระบายอากาศให้มีประสิทธิภาพ ขจัดก๊าซคาร์บอนไดออกไซด์ส่วนเกิน ระดับ PaCO2 และ pH ในเลือดกลับสู่เกณฑ์ปกติ\r\nData:\r\n- ผล Arterial Blood Gas (ABG): pH ... (\u003c 7.35), PaCO2 ... mmHg (ปกติ 35-45 mmHg), HCO3 ... mEq/L\r\n- ผู้ป่วยมีอาการหายใจตื้น หายใจลำบาก หอบเหนื่อย อกบุ๋ม หรือกดการหายใจ ซึม ง่วงหลับ ปวดศีรษะ สับสน (CO2 Narcosis)\r\n- ตรวจพบ Asterixis (มือสั่นกระตุกเมื่อเหยียดแขนกระดกข้อมือ)\r\n- ประวัติโรคปอดอุดกั้นเรื้อรัง (COPD), หอบหืดรุนแรง (Severe Asthma), ได้รับยากดประสาท/มอร์ฟีน, หรือกล้ามเนื้อหายใจอ่อนแรง\r\nAction:\r\n- รายงานแพทย์ทันที และจัดท่านอนศีรษะสูง 45 - 90 องศา (High Fowler\u0027s position) เพื่อขยายทรวงอก\r\n- เคลียร์ทางเดินหายใจให้โล่ง ดูดเสมหะ (Suction) หากมีเสมหะคั่งค้าง\r\n- ให้การรักษาด้านระบบหายใจตามแผนแพทย์:\r\n  * ผู้ป่วย COPD: ให้ออกซิเจนความเข้มข้นต่ำอย่างระมัดระวัง (Venturi mask หรือ Low-flow nasal cannula 1-2 LPM) เป้าหมาย SpO2 88-92%\r\n  * พ่นยาขยายหลอดลม (Bronchodilator nebulizer) ตามคำสั่งแพทย์\r\n  * กรณีได้รับยาแก้ปวดกลุ่ม Opioids เกินขนาด: เตรียมยาต้าน Naloxone (Narcan) ... mg IV ตามแผน\r\n  * เตรียมอุปกรณ์ช่วยหายใจแรงดันบวก (BiPAP) หรือเตรียมท่อช่วยหายใจ (Endotracheal tube) หากผู้ป่วยซึมลงหรือไม่สามารถหายใจเองได้\r\n- บันทึกสัญญาณชีพ ความลึก-อัตราการหายใจ และ SpO2 อย่างต่อเนื่อง\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวตื่นดีขึ้น หายใจเหนื่อยลดลง ไม่มีอาการง่วงซึมหรือสับสน\r\n- อัตราการหายใจสม่ำเสมอ SpO2 อยู่ในเกณฑ์เป้าหมาย\r\n- ผลตรวจซ้ำ ABG ค่า PaCO2 ลดลง และค่า pH ปรับตัวดีขึ้น\r\n---\r\n.aki = ภาวะไตวายเฉียบพลัน (Acute Kidney Injury: Cr สูง / ปัสสาวะออกน้อย Oliguria)\r\nFocus: ภาวะไตวายเฉียบพลัน (Acute Kidney Injury: AKI)\r\nGoal: ชะลอและฟื้นฟูการทำงานของไต ค่า BUN/Cr ลดลง ปริมาณปัสสาวะออกอย่างน้อย 0.5 ml/kg/hr และเกลือแร่ในเลือดสมดุล\r\nData:\r\n- ผลการทำงานของไต: Serum Creatinine (Cr) เพิ่มขึ้นเป็น ... mg/dL (เดิม ... mg/dL), BUN ... mg/dL, eGFR ... ml/min\r\n- ปริมาณปัสสาวะ: ปัสสาวะออกน้อย (Oliguria \u003c 0.5 ml/kg/hr ต่อเนื่อง 6 ชม.) ปริมาณปัสสาวะรวมใน 24 ชม. ได้ ... ml\r\n- อาการแสดง: มีอาการบวมตามหนังตา ขาและข้อเท้าบวมทั้งสองข้าง น้ำหนักตัวเพิ่มขึ้น อ่อนเพลีย คลื่นไส้ เบื่ออาหาร หายใจหอบเหนื่อย\r\n- ฟังปอดได้ยินเสียง Crepitation หรือ Wheezing (สงสัยภาวะน้ำท่วมปอด / Pulmonary edema)\r\nAction:\r\n- รายงานแพทย์ทราบค่าไตที่เพิ่มขึ้นและปริมาณปัสสาวะออกน้อย\r\n- หาสาเหตุและให้การพยาบาลตามแผน:\r\n  * กรณี Pre-renal (ขาดน้ำ/ความดันตก): ให้สารน้ำ IV resuscitation ตามแผน และติดตาม CVP หรือความดันโลหิต\r\n  * กรณี Post-renal (อุดกั้นทางเดินปัสสาวะ): ตรวจสอบสายสวนปัสสาวะว่าพับหักงอหรือตันหรือไม่ ล้างสายสวนหรือรายงานแพทย์พิจารณาใส่สายสวนใหม่\r\n  * กรณีได้รับยาที่มีพิษต่อไต (Nephrotoxic drugs): แจ้งแพทย์และเภสัชกรเพื่อชะลอหรือปรับขนาดยา (เช่น NSAIDs, Aminoglycosides, Vancomycin, Colistin)\r\n- บันทึกปริมาณน้ำเข้า-ออก (I/O) อย่างเคร่งครัดทุก 1-2 ชม.\r\n- ชั่งน้ำหนักตัวทุกเช้าก่อนอาหาร\r\n- ติดตามระดับเกลือแร่ในเลือดอย่างใกล้ชิด โดยเฉพาะภาวะโพแทสเซียมสูง (Hyperkalemia) และเลือดเป็นกรด\r\nResponse:\r\n- ปริมาณปัสสาวะออกเพิ่มขึ้น (\u003e 0.5 ml/kg/hr) อาการบวมลดลง\r\n- ผู้ป่วยไม่มีอาการหอบเหนื่อย ไม่มีเสียงผิดปกติในปอด สัญญาณชีพคงที่\r\n- ผลตรวจติดตามค่า BUN และ Creatinine ทรงตัวและค่อยๆ ลดลงสู่เกณฑ์ปกติ\r\n---\r\n.hyperbili = ภาวะบิลิรูบินในเลือดสูง / ดีซ่าน (Hyperbilirubinemia / Jaundice)\r\nFocus: ภาวะบิลิรูบินในเลือดสูงและภาวะดีซ่าน (Hyperbilirubinemia / Clinical Jaundice)\r\nGoal: ภาวะตัวเหลืองตาเหลืองลดลง ระดับบิลิรูบินในเลือดลดลง ขจัดสารพิษได้ดี และไม่เกิดภาวะแทรกซ้อนทางระบบประสาท\r\nData:\r\n- ผล LFTs: Total Bilirubin ... mg/dL (ปกติ 0.2 - 1.2 mg/dL), Direct Bilirubin ... mg/dL\r\n- สภาพร่างกาย: ตัวเหลือง ตาเหลือง (Icteric sclerae), ปัสสาวะสีเข้มเหมือนน้ำชา, อุจจาระสีซีด (Clay-colored stool)\r\n- มีอาการคันตามผิวหนัง (Pruritus), แน่นอึดอัดใต้ชายโครงขวา, เบื่ออาหาร, คลื่นไส้\r\n- สาเหตุ: นิ่วอุดกั้นท่อน้ำดี (Choledocholithiasis), ตับอักเสบ, เม็ดเลือดแดงแตก (Hemolysis), หรือเนื้องอกทางเดินน้ำดี\r\nAction:\r\n- รายงานแพทย์ทราบค่าผลแล็บและประเมินภาวะการติดเชื้อในท่อน้ำดี (Cholangitis: ไข้ หนาวสั่น ปวดท้อง ดีซ่าน)\r\n- ให้การพยาบาลตามแผนการรักษา:\r\n  * กรณีสงสัยท่อน้ำดีอุดกั้น: งดน้ำงดอาหาร (NPO) ส่งตรวจ Ultrasound หรือเตรียมตรวจส่องกล้อง ERCP\r\n  * ให้สารน้ำทางหลอดเลือดดำและยาปฏิชีวนะตามแผนการรักษา\r\n  * ให้ยาแก้คัน (Antihistamines / Cholestyramine) ตามคำสั่งแพทย์\r\n- ดูแลสุขอนามัยของผิวหนัง: เช็ดตัวด้วยน้ำสะอาด หลีกเลี่ยงน้ำอุ่นจัด ทาโลชั่นให้ความชุ่มชื้น ตัดเล็บสั้นเพื่อป้องกันแผลติดเชื้อจากการเกา\r\n- สังเกตและบันทึกสีของอุจจาระและปัสสาวะทุกครั้ง\r\nResponse:\r\n- ผู้ป่วยมีอาการคันผิวหนังลดลง ไม่มีไข้หนาวสั่นหรือปวดท้องรุนแรง\r\n- ตัวเหลืองตาเหลืองค่อยๆ จางลง สีปัสสาวะจางลง\r\n- ผลตรวจติดตามระดับ Bilirubin ในเลือดลดลงอย่างต่อเนื่อง\r\n---\r\n.hepatitis = ภาวะตับอักเสบเฉียบพลัน / เอนไซม์ตับสูงรุนแรง (Acute Liver Injury / Transaminitis)\r\nFocus: ภาวะตับอักเสบเฉียบพลันและเอนไซม์ตับสูงรุนแรง (Acute Liver Injury / Transaminitis)\r\nGoal: ระดับเอนไซม์ตับ (AST/ALT) ลดลง เซลล์ตับได้รับการฟื้นฟู ไม่มีภาวะเลือดออกผิดปกติ และไม่มีภาวะตับวายเฉียบพลัน\r\nData:\r\n- ผลเอนไซม์ตับ: AST (SGOT) ... U/L, ALT (SGPT) ... U/L (สูงกว่าค่าปกติหลายเท่าตัว หรือ \u003e 500 - 1,000 U/L), ALP ... U/L\r\n- ผู้ป่วยมีอาการอ่อนเพลียอย่างมาก เบื่ออาหาร คลื่นไส้ อาเจียน แน่นอึดอัดบริเวณใต้ชายโครงขวา ปัสสาวะสีเข้ม\r\n- ประเมินประวัติการใช้ยา สมุนไพร แอลกอฮอล์ หรือการติดเชื้อไวรัสตับอักเสบ\r\n- เฝ้าระวังภาวะตับวายเฉียบพลัน (Hepatic Failure): สับสน ซึม พูดจาวกวน มือสั่น Flapping tremor (Asterixis)\r\nAction:\r\n- รายงานแพทย์ทันที และหยุดยาทุกชนิดที่มีผลต่อตับ (Hepatotoxic drugs เช่น Paracetamol, ยาต้านวัณโรค, ยากันชัก)\r\n- ให้การรักษาตามแผน:\r\n  * กรณีได้รับ Paracetamol เกินขนาด: ให้ N-acetylcysteine (NAC) ทางหลอดเลือดดำตาม Protocol\r\n  * ให้น้ำเกลือสารน้ำทดแทนทางหลอดเลือดดำอย่างเพียงพอ\r\n  * แนะนำผู้ป่วยนอนพักผ่อนอย่างเต็มที่ (Bed rest) เพื่อเพิ่มเลือดไปเลี้ยงตับ\r\n- ตรวจสอบค่าการแข็งตัวของเลือด (PT/INR) เสมอ (PT เป็นตัวบ่งชี้การสังเคราะห์โปรตีนของตับที่สำคัญที่สุด)\r\n- บันทึกสัญญาณชีพและตรวจประเมินระดับความรู้สึกตัว (Neuro signs / GCS) ทุก 4 ชม. เฝ้าระวัง Hepatic Encephalopathy\r\n- แนะนำอาหารคาร์โบไฮเดรตสูง ย่อยง่าย ลดอาหารไขมันสูง\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวดี ไม่มีอาการสับสน มือไม่สั่น (No flapping tremor)\r\n- อาการคลื่นไส้ แน่นชายโครงขวาลดลง รับประทานอาหารได้ดีขึ้น\r\n- ผลตรวจติดตามค่า AST, ALT และ PT/INR มีแนวโน้มลดลงสู่เกณฑ์ปลอดภัย\r\n---\r\n.hypogly = ภาวะน้ำตาลในเลือดต่ำวิกฤต (Severe Hypoglycemia, DTX \u003c 70 mg/dL)\r\nFocus: ภาวะน้ำตาลในเลือดต่ำวิกฤต (Severe Hypoglycemia, DTX/Blood Glucose \u003c 70 mg/dL)\r\nGoal: ระดับน้ำตาลในเลือด DTX กลับสู่เกณฑ์ปกติ (≥ 100 mg/dL) อาการใจสั่น มือสั่น เหงื่อแตก ซึมทุเลาลง และผู้ป่วยปลอดภัย\r\nData:\r\n- ผลตรวจระดับน้ำตาลปลายนิ้ว (DTX) ล่าสุด ... mg/dL (ค่าวิกฤต \u003c 50-70 mg/dL)\r\n- อาการแสดงจากระบบประสาทอัตโนมัติ: ใจสั่น เหงื่อแตก ตัวเย็น มือสั่น กระสับกระส่าย รู้สึกหิวมาก หน้าซีด ชีพจรเต้นเร็ว\r\n- อาการแสดงจากสมองขาดน้ำตาล (Neuroglycopenic): ปวดศีรษะ เวียนศีรษะ มึนงง สับสน เดินเซ พูดไม่ชัด ซึมลง ชักเกร็ง หรือหมดสติ\r\nAction:\r\n- ให้การช่วยเหลือทันทีตาม Rule of 15 / Hypoglycemia Protocol:\r\n  * **กรณีผู้ป่วยรู้สึกตัวดีและกลืนได้:** ให้รับประทานคาร์โบไฮเดรตเชิงเดี่ยว 15 กรัมทันที (เช่น น้ำส้ม 1 กล่อง / น้ำหวาน 1 แก้ว หรือลูกอม 3-4 เม็ด)\r\n  * **กรณีผู้ป่วยซึม หมดสติ ชัก หรือ NPO:** ให้ 50% Glucose 25 - 50 ml (1-2 หลอด) ทางหลอดเลือดดำทันที (IV Push ช้าๆ)\r\n  * หากไม่มีเส้นเลือดดำ ให้ฉีด Glucagon 1 mg เข้ากล้ามเนื้อ (IM) ตามแผนแพทย์\r\n- ตรวจวัดระดับน้ำตาลในเลือดซ้ำ (Re-check DTX) หลังให้การรักษาครบ 15 นาที\r\n  * หาก DTX ยัง \u003c 70 mg/dL ให้ซ้ำตามขั้นตอนเดิมอีกครั้ง\r\n  * หาก DTX ≥ 70 mg/dL ให้ผู้ป่วยรับประทานอาหารมื้อหลักหรืออาหารว่าง (เช่น ขนมปัง นม) เพื่อรักษาระดับน้ำตาลให้คงที่\r\n- หาสาเหตุ: รับประทานอาหารน้อยกว่าปกติ ออกกำลังกายหักโหม หรือได้รับยาเบาหวาน/อินซูลินเกินขนาด\r\nResponse:\r\n- ผู้ป่วยรู้สึกตัวตื่นดี อาการใจสั่น เหงื่อแตก และมือสั่นหายไป\r\n- สัญญาณชีพคงที่ ไม่มีอาการชักเกร็ง\r\n- ผลตรวจ DTX ซ้ำหลังการรักษา 15 นาที ได้ ... mg/dL (เป้าหมาย \u003e 80-100 mg/dL)\r\n---\r\n.hypergly = ภาวะน้ำตาลในเลือดสูงวิกฤต (Severe Hyperglycemia / DKA / HHS, DTX \u003e 300 - 500 mg/dL)\r\nFocus: ภาวะน้ำตาลในเลือดสูงวิกฤต (Severe Hyperglycemia / DKA / HHS, DTX \u003e 300 - 500 mg/dL)\r\nGoal: ระดับน้ำตาลในเลือด DTX ค่อยๆ ลดลงสู่เกณฑ์เป้าหมาย ป้องกันภาวะเลือดเป็นกรด DKA / HHS และภาวะขาดน้ำได้รับการแก้ไข\r\nData:\r\n- ผลตรวจระดับน้ำตาลในเลือด: DTX ... mg/dL (ค่าสูงเกินเกณฑ์หรืออ่านค่า Hi \u003e 500 mg/dL)\r\n- อาการแสดง: กระหายน้ำมาก ปัสสาวะบ่อย ปริมาณมาก ผิวหนังและเยื่อบุแห้ง ตาโหล อ่อนเพลีย น้ำหนักลด\r\n- อาการภาวะ DKA: หายใจหอบลึกเร็ว (Kussmaul breathing) ลมหายใจมีกลิ่นผลไม้ (Fruity breath / Acetone odor) ปวดท้อง คลื่นไส้อาเจียน ซึมลง\r\n- ผลตรวจปัสสาวะ: ตรวจพบ Urine Ketone และ Urine Sugar ให้ผลบวก\r\n- สัญญาณชีพ: BP ... mmHg, PR ... bpm (ชีพจรเร็ว), หายใจเร็ว, อุณหภูมิกาย ... °C\r\nAction:\r\n- รายงานแพทย์ทันที และปฏิบัติตาม DKA/HHS Protocol:\r\n  * ให้สารน้ำชดเชยภาวะขาดน้ำ: ให้ 0.9% NSS 1,000 ml IV drip ใน 1 ชม. แรก และปรับอัตราตามแผนการรักษาอย่างเคร่งครัด\r\n  * ให้ยาอินซูลินลดน้ำตาล: Regular Insulin (RI) 100 units in 0.9% NSS 100 ml (1:1) IV drip ผ่าน Infusion pump ตามอัตราที่แพทย์สั่ง (เป้าหมายลดน้ำตาล 50-75 mg/dL/hr)\r\n  * ตรวจติดตาม DTX ทุก 1 ชม. เพื่อปรับขนาดยาอินซูลิน\r\n  * ส่งตรวจเลือดประเมิน Electrolytes, ABG, BUN, Cr และ Serum Ketone\r\n  * **ข้อควรระวังสำคัญ:** ตรวจระดับ Serum K+ เสมอ หาก K \u003c 3.3 mEq/L ให้ระงับอินซูลินชั่วคราวและเติม K+ ก่อน เพื่อป้องกัน Hypokalemic cardiac arrest\r\n- บันทึกสัญญาณชีพและปริมาณน้ำเข้า-ออก (I/O) ทุก 1-2 ชม.\r\nResponse:\r\n- ระดับน้ำตาลในเลือดค่อยๆ ลดลงอย่างคงที่ตามเป้าหมาย (ลดลง 50-75 mg/dL/hr) ไม่เกิดภาวะน้ำตาลตกเฉียบพลัน\r\n- ผู้ป่วยรู้สึกตัวดีขึ้น ริมฝีปากชุ่มชื้นขึ้น อาการหายใจหอบเหนื่อยลดลง\r\n- สัญญาณชีพคงที่ ปัสสาวะออกดี (\u003e 0.5-1 ml/kg/hr) ผลตรวจกรดด่างและเกลือแร่ปรับตัวดีขึ้น\r\n---\r\n\r\n[16. การพยาบาลผู้ป่วยระยะสุดท้ายและการดูแลแบบประคับประคอง (Palliative \u0026 End-of-Life Care)]\r\n.palliative = การดูแลแบบประคับประคองระยะสุดท้าย (Palliative \u0026 Comfort Care)\r\nFocus: การดูแลแบบประคับประคองเพื่อความสุขสบายและลดความทุกข์ทรมาน (Palliative Comfort Care)\r\nGoal: ผู้ป่วยได้รับการดูแลเพื่อความสุขสบายสูงสุด (Maximum Comfort) บรรเทาอาการทุกข์ทรมานทั้งทางกาย จิตใจ สังคม และจิตวิญญาณ\r\nData: ผู้ป่วยระยะท้าย (Terminal stage/End-stage disease), อ่อนเพลียมาก รับประทานอาหารและยาทางปากได้ลดลง/ไม่ได้, มีอาการไม่สุขสบาย/หายใจเหนื่อย/ปวด, ผู้ป่วยและครอบครัวมีความวิตกกังวล, สัญญาณชีพ: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\r\nAction:\r\n- ให้การพยาบาลโดยยึดหลักความสุขสบายของผู้ป่วยเป็นศูนย์กลาง (Comfort-oriented care)\r\n- จัดท่านอนศีรษะสูง 30-45 องศา หรือนอนตะแคงเพื่อช่วยให้หายใจโล่งขึ้น\r\n- ดูแลสุขอนามัยในช่องปาก (Oral care) ใช้สำลีชุบน้ำสะอาดแตะริมฝีปากและทาลิปมันบำรุงริมฝีปากไม่ให้แห้งแตก\r\n- ดูแลให้ยาบรรเทาปวดและยาระงับอาการไม่สุขสบายตามแผนการรักษาแบบประคับประคอง\r\n- สื่อสารด้วยความเคารพ อ่อนโยน และเปิดโอกาสให้สมาชิกในครอบครัวได้อยู่เคียงข้าง ได้พูดคุย สัมผัส และมีส่วนร่วมในการดูแล\r\n- ประสานงานทีมประคับประคอง (Palliative Care Team) และอำนวยความสะดวกในการประกอบพิธีกรรมทางศาสนาตามความเชื่อของผู้ป่วย\r\nResponse: ผู้ป่วยนอนหลับพักได้ สีหน้าผ่อนคลาย ไม่มีอาการทุรนทุรายหรือกระสับกระส่าย, ครอบครัวเข้าใจแนวทางการดูแล มีความสงบทางจิตใจและมีความพึงพอใจต่อการดูแล\r\n---\r\n.terminalpain = การจัดการความปวดระยะสุดท้าย (Terminal Pain Management)\r\nFocus: จัดการความปวดรุนแรงในผู้ป่วยระยะสุดท้าย (Terminal Pain / Palliative Pain)\r\nGoal: ผู้ป่วยได้รับการระงับความปวดอย่างมีประสิทธิภาพและต่อเนื่อง สีหน้าผ่อนคลาย พักผ่อนได้สงบ และไม่มีอาการทุรนทุราย\r\nData: ผู้ป่วยบ่นปวด/แสดงสีหน้าเจ็บปวด คิ้วขมวด ร้องคราง หายใจเกร็ง ดิ้นกระสับกระส่าย, ประเมินระดับความปวด Pain score = .../10 (หรือ PAINAD / BPS = ... คะแนน), สัญญาณชีพ: BP.../... mmHg, PR... /min\r\nAction:\r\n- ประเมินอาการปวดอย่างสม่ำเสมอทั้งทางภาษาพูดและภาษากาย\r\n- ดูแลให้ยาแก้ปวดกลุ่ม Opioids (Morphine / Fentanyl) ทางหลอดเลือดดำ/แผ่นแปะ/ใต้ลิ้น ตามแผนการรักษาของแพทย์อย่างตรงเวลาสม่ำเสมอ (Around-the-clock)\r\n- ให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough pain dose) ทันทีเมื่อมีอาการปวดกำเริบ\r\n- เฝ้าระวังผลข้างเคียงของยา (อาการง่วงซึม คลื่นไส้ ท้องผูก)\r\n- จัดท่านอนในท่าที่ผ่อนคลาย หนุนหมอนรองรับบริเวณที่ปวด\r\n- ดูแลสิ่งแวดล้อมให้เงียบสงบ เปิดเพลงเบาๆ ช่วยผ่อนคลาย\r\nResponse: อาการปวดทุเลาลง ระดับความปวดลดลงเหลือ \u003c 3/10 (PAINAD/BPS ลดลง), สีหน้าผ่อนคลาย คลายเกร็ง สามารถนอนหลับพักผ่อนได้อย่างสงบ\r\n---\r\n.deathrattle = ภาวะหายใจมีเสียงครืดคราดระยะใกล้เสียชีวิต (Death Rattle / Terminal Secretions)\r\nFocus: หายใจมีเสียงครืดคราดจากเสมหะคั่งค้างในทางเดินหายใจส่วนบน (Death Rattle)\r\nGoal: เสียงครืดคราดในลำคอลดลง ทางเดินหายใจส่วนบนโล่งขึ้น ผู้ป่วยหายใจได้อย่างสงบ และครอบครัวคลายความตื่นตระหนก\r\nData: ผู้ป่วยระยะใกล้เสียชีวิต (Actively dying) หายใจมีเสียงดังครืดคราดในลำคอ (Terminal respiratory secretions) จากกล้ามเนื้อกลืนและไออ่อนแรง, ญาติแสดงความตกใจและกังวลว่าผู้ป่วยจะสำลักหรือทรมาน\r\nAction:\r\n- จัดท่านอนตะแคงกึ่งคว่ำหรือยกศีรษะสูงเล็กน้อย เพื่อให้สารคัดหลั่งและน้ำลายไหลระบายออกทางมุมปากได้ตามแรงโน้มถ่วง\r\n- หลีกเลี่ยงการดูดเสมหะลึกเพราะจะกระตุ้นให้ผู้ป่วยระคายเคือง ไอกระสับกระส่าย และทรมานยิ่งขึ้น ใช้ผ้าสะอาดชุบน้ำเช็ดทำความสะอาดช่องปากและมุมปากอย่างนุ่มนวล\r\n- ดูแลให้ยาต้านสารคัดหลั่ง (Anticholinergics เช่น Buscopan / Atropine / Scopolamine) ตามแผนการรักษาของแพทย์เพื่อลดการสร้างสารคัดหลั่งใหม่\r\n- อธิบายให้ครอบครัวเข้าใจด้วยความนุ่มนวลว่าเสียงนี้เกิดจากการระบายน้ำลายตามธรรมชาติและผู้ป่วยไม่ได้รู้สึกเจ็บปวดหรือทรมาน\r\nResponse: เสียงหายใจครืดคราดลดลง ไม่มีสารคัดหลั่งไหลย้อนสำลัก, ญาติคลายความวิตกกังวลและเข้าใจสภาวะตามธรรมชาติของผู้ป่วย\r\n---\r\n.terminaldyspnea = ภาวะหายใจลำบากและหิวอากาศระยะสุดท้าย (Terminal Dyspnea \u0026 Air Hunger)\r\nFocus: ภาวะหายใจลำบากและหิวอากาศในผู้ป่วยระยะสุดท้าย (Terminal Dyspnea \u0026 Air Hunger)\r\nGoal: อาการหอบเหนื่อยและหิวอากาศทุเลาลง ผู้ป่วยหายใจผ่อนคลายและสุขสบายขึ้น ไม่ทุรนทุราย\r\nData: ผู้ป่วยมีอาการหายใจหอบเหนื่อย อ้าปากหายใจ ใช้กล้ามเนื้อหน้าอกและคอช่วยหายใจ (Accessory muscle use), มีอาการหิวอากาศ (Air hunger), หายใจเร็ว RR... /min, SpO2... %\r\nAction:\r\n- จัดท่านอนศีรษะสูง 45-60 องศา (High-Fowler\u0027s position) เพื่อให้กระบังลมหย่อนตัวขยายปอดได้ดีขึ้น\r\n- ใช้พัดลมตั้งโต๊ะเปิดเป่าลมเย็นเบาๆ ผ่านบริเวณใบหน้าและจมูกผู้ป่วย (Facial cooling fan) เพื่อกระตุ้น Trigeminal nerve ช่วยลดความรู้สึกหอบเหนื่อย\r\n- ให้ออกซิเจน Cannula อัตราต่ำ 2-3 LPM เพื่อเพิ่มความสุขสบาย\r\n- ดูแลให้ยา Morphine ขนาดต่ำทางหลอดเลือดดำ/ใต้ลิ้นตามคำสั่งแพทย์ เพื่อลดความไวของศูนย์ควบคุมการหายใจและคลายความวิตกกังวล\r\n- พูดคุยปลอบประโลม จับมือให้ความมั่นใจแก่ผู้ป่วย\r\nResponse: ผู้ป่วยหายใจช้าลงและลึกขึ้น อาการหอบเกร็งและหิวอากาศทุเลาลง, อัตราการหายใจลดลงเหลือ RR... /min, สีหน้าสงบขึ้น สามารถนอนพักได้\r\n---\r\n.deliriumpalliative = ภาวะเพ้อสับสนกระสับกระส่ายระยะสุดท้าย (Terminal Agitation \u0026 Delirium)\r\nFocus: ภาวะกระสับกระส่าย สับสน และเพ้อในผู้ป่วยระยะสุดท้าย (Terminal Restlessness \u0026 Delirium)\r\nGoal: ผู้ป่วยสงบลง อาการกระสับกระส่ายและสับสนลดลง ปลอดภัยจากอุบัติเหตุ และครอบครัวได้รับการประคับประคองจิตใจ\r\nData: ผู้ป่วยมีอาการกระสับกระส่าย ดึงสายน้ำเกลือ/อุปกรณ์ พยายามลุกจากเตียง พูดจาเพ้อสับสน ไม่รับรู้วันเวลาสถานที่ (Disoriented), สีหน้าหวาดกลัวหรือวิตกกังวล\r\nAction:\r\n- ตรวจประเมินค้นหาสาเหตุทางกายที่แก้ไขได้ (เช่น ภาวะปัสสาวะคั่ง, ท้องผูกแน่นท้อง, ปวดรุนแรง, หรือขาดออกซิเจน)\r\n- ปรับสิ่งแวดล้อมให้เงียบสงบ ลดแสงไฟจ้าและเสียงดังรบกวน\r\n- ให้ญาติที่คุ้นเคยคอยอยู่ดูแลเคียงข้างและพูดคุยบอกความจริงอย่างนุ่มนวล\r\n- ดูแลให้ยา Haloperidol หรือ Midazolam ตามแผนการรักษาของแพทย์เพื่อระงับความทรมาน (Palliative sedation for refractory distress)\r\n- ป้องกันอุบัติเหตุตกเตียงโดยยกไม้กั้นเตียงและบุผ้านวมกันกระแทก หลีกเลี่ยงการผูกมัดร่างกาย\r\nResponse: ผู้ป่วยสงบลง หายตื่นกลัว สามารถนอนหลับพักผ่อนได้อย่างปลอดภัย ไม่เกิดอุบัติเหตุพลัดตกหกล้ม\r\n---\r\n.postmortem = การดูแลผู้ป่วยและครอบครัวหลังเสียชีวิต (Post-Mortem Care \u0026 Bereavement)\r\nFocus: การพยาบาลดูแลร่างผู้เสียชีวิตและการประคับประคองจิตใจครอบครัว (Post-Mortem Care)\r\nGoal: การดูแลร่างผู้เสียชีวิตเป็นไปด้วยความเคารพ สมเกียรติ ปฏิบัติถูกต้องตามแนวทาง และครอบครัวได้รับการดูแลด้านจิตใจอย่างอบอุ่น\r\nData: แพทย์ตรวจวินิจฉัยและลงบันทึกผู้ป่วยถึงแก่กรรมเวลา... น., สัญญาณชีพหยุดเต้น ไม่มีชีพจร ไม่มีเสียงหายใจ ม่านตาขยายทั้งสองข้างไม่ตอบสนองต่อแสง\r\nAction:\r\n- ปิดม่านรอบเตียงเพื่อความเป็นส่วนตัว\r\n- ปลดอุปกรณ์การแพทย์และสายระบายต่างๆ ออกอย่างนุ่มนวล (ยกเว้นกรณีชันสูตรพลิกศพ)\r\n- ทำความสะอาดร่างกายผู้เสียชีวิต จัดท่านอนหงาย หนุนหมอน 1 ใบใต้ศีรษะเพื่อป้องกันเลือดคั่งที่ใบหน้า\r\n- ปิดตาและหุบปาก\r\n- สวมเสื้อผ้าสะอาดและห่อร่างตามแนวปฏิบัติของโรงพยาบาล\r\n- ผูกป้ายระบุตัวตน (Mortuary tag) ที่ข้อมือและข้อเท้า\r\n- ให้เวลาครอบครัวได้อยู่ร่วมอำลาและประกอบพิธีกรรมทางศาสนา\r\n- กล่าวแสดงความเสียใจและประคับประคองด้านจิตใจ\r\n- แนะนำขั้นตอนการติดต่อรับศพและเอกสารใบมรณบัตร\r\nResponse: การทำความสะอาดและจัดเตรียมร่างผู้เสียชีวิตเรียบร้อย สมเกียรติ, ญาติได้รับข้อมูลขั้นตอนการติดต่อและเอกสารครบถ้วน ครอบครัวมีความซาบซึ้งต่อการดูแล\r\n---\r\n\r\n[17. การพยาบาลระบบประสาทและสมอง (Neurological \u0026 Neurosurgical Nursing)]\r\n.icp = ภาวะความดันในกะโหลกศีรษะสูง (Increased Intracranial Pressure - IICP)\r\nFocus: เสี่ยงต่อภาวะความดันในกะโหลกศีรษะสูงและสมองเคลื่อน (Increased ICP / Brain Herniation)\r\nGoal: ป้องกันและลดความดันในกะโหลกศีรษะ ระดับความรู้สึกตัวคงที่ สัญญาณชีพคงที่ รูม่านตาตอบสนองต่อแสงดี และไม่เกิดภาวะสมองเคลื่อน (Herniation)\r\nData: ผู้ป่วยมีอาการปวดศีรษะรุนแรง อาเจียนพุ่ง (Projectile vomiting), ซึมลง GCS ลดลง... คะแนน, รูม่านตาขยายไม่เท่ากัน (Pupils unequal / sluggish), สัญญาณชีพพบ Cushing\u0027s triad (ความดันโลหิตสูงขึ้นโดยเฉพาะ Systolic, ชีพจรเต้นช้า Bradycardia, หายใจผิดปกติ)\r\nAction:\r\n- จัดท่านอนศีรษะสูง 30 องศา คอตรงในแนวระนาบ (Neutral alignment) ห้ามพับงอคอหรือบิดเอียงเพื่อช่วยการระบายเลือดดำจากสมอง\r\n- ดูแลให้ยาลดบวมสมอง (Mannitol 20% หรือ 3% NaCl) หยดทางหลอดเลือดดำตามแผนการรักษาอย่างเคร่งครัด\r\n- หลีกเลี่ยงกิจกรรมที่เพิ่มความดันในกะโหลกศีรษะ (ห้ามดูดเสมหะนานเกิน 10-15 วินาที, ระวังอย่าให้ผู้ป่วยไอ จาม หรือเบ่งอุจจาระ)\r\n- ให้ออกซิเจนควบคุม PaCO2 35-40 mmHg\r\n- ตรวจประเมิน Neuro sign และ GCS ทุก 1 ชั่วโมง\r\n- รายงานแพทย์ทันทีเมื่อพบความผิดปกติ\r\nResponse: ระดับความรู้สึกตัวคงที่ GCS... คะแนน, รูม่านตาขนาด... mm ตอบสนองต่อแสงดีทั้ง 2 ข้าง, ไม่มีอาการอาเจียนพุ่ง สัญญาณชีพคงที่\r\n---\r\n.seizure = การพยาบาลขณะชักและหลังชัก (Seizure Care \u0026 Status Epilepticus)\r\nFocus: ป้องกันอันตรายและภาวะขาดออกซิเจนขณะและหลังมีอาการชักเกร็ง (Active Seizure Management)\r\nGoal: ผู้ป่วยปลอดภัยขณะชัก ทางเดินหายใจโล่ง ไม่เกิดการสำลักหรือบาดเจ็บ อาการชักสงบลง และฟื้นตัวหลังชักได้ดี\r\nData: ผู้ป่วยมีอาการชักเกร็ง/กระตุก (Tonic-clonic seizure), กัดฟัน ตาค้าง น้ำลายฟูมปาก, ไม่รู้สึกตัว, ระยะเวลาชักนาน... นาที\r\nAction: \r\n- ขณะชัก: ป้องกันอันตรายโดยเคลียร์สิ่งของรอบตัว จัดท่านอนตะแคงหน้าเพื่อป้องกันการสำลักน้ำลาย ห้ามผูกมัดผู้ป่วย และห้ามนำสิ่งของใดๆ งัดหรือใส่ในปากเด็ดขาด, ให้ออกซิเจน Mask with bag / Cannula, ดูแลให้ยากันชักฉุกเฉิน (Diazepam / Midazolam / Keppra / Dilantin) ทางหลอดเลือดดำตามคำสั่งแพทย์, สังเกตและจับเวลาลักษณะการชัก\r\n- หลังชัก (Post-ictal): ดูดเสมหะในช่องปากอย่างนุ่มนวล, ตรวจวัดสัญญาณชีพ, เจาะ DTX ตรวจหาน้ำตาลต่ำ, ประเมิน GCS และ Neuro sign\r\nResponse: อาการชักหยุดลงเวลา... น. รวมเวลาชัก... นาที, ทางเดินหายใจโล่ง SpO2 = ... %, หลังชักผู้ป่วยค่อยๆ รู้สึกตัวตื่น ไม่พบการบาดเจ็บของร่างกาย\r\n---\r\n.gcsdrop = ภาวะการเปลี่ยนแปลงระดับความรู้สึกตัว (Altered Level of Consciousness / GCS Drop)\r\nFocus: ระดับความรู้สึกตัวลดลงเฉียบพลัน เสี่ยงต่อภาวะสมองขาดเลือดหรือมีพยาธิสภาพลุกลาม\r\nGoal: ตรวจพบและรายงานสาเหตุของการเปลี่ยนแปลงระดับความรู้สึกตัวได้อย่างรวดเร็ว ได้รับการแก้ไขทันท่วงที และป้องกันเนื้อสมองขาดออกซิเจน\r\nData: ผู้ป่วยมีอาการซึมลง ไม่ตอบสนองต่อเสียงเรียกเหมือนเดิม, ค่า GCS ลดลงจากเดิม \u003e 2 คะแนน (E... V... M...), รูม่านตา...\r\nAction:\r\n- รายงานแพทย์ทันที\r\n- ตรวจวัดสัญญาณชีพฉุกเฉินและเจาะตรวจ DTX ทันทีเพื่อแยกภาวะ Hypoglycemia\r\n- จัดท่านอนศีรษะสูง 30 องศา\r\n- ดูแลทางเดินหายใจให้โล่ง ให้ออกซิเจนเสริม\r\n- ตรวจประเมิน Motor power แขนขาทั้ง 4 ข้าง\r\n- เตรียมความพร้อมส่งตรวจเอกซเรย์คอมพิวเตอร์สมอง (CT Brain Urgent) ตามคำสั่งแพทย์\r\nResponse: แพทย์ตรวจประเมินผู้ป่วย, DTX = ... mg/dL, ส่งทำ CT Brain เวลา... น. ปลอดภัยดี ไม่เกิดภาวะทางเดินหายใจอุดกั้น\r\n---\r\n.tbi = การบาดเจ็บที่ศีรษะและสมอง (Traumatic Brain Injury / Head Injury)\r\nFocus: เสี่ยงต่อภาวะแทรกซ้อนจากการบาดเจ็บที่กะโหลกศีรษะและเนื้อสมอง (Traumatic Brain Injury Care)\r\nGoal: สัญญาณทางระบบประสาทคงที่หรือดีขึ้น ป้องกันการบาดเจ็บซ้ำของเนื้อสมอง (Secondary Brain Injury) และไม่พบสัญญาณ CSF leak\r\nData: ผู้ป่วยได้รับอุบัติเหตุกระทบกระแทกที่ศีรษะ, มีแผลแตก/บวมโนบริเวณ..., มีอาการปวดศีรษะ คลื่นไส้ จำเหตุการณ์ไม่ได้ (Amnesia), GCS = ... คะแนน\r\nAction:\r\n- ตรวจประเมินและบันทึก Neuro sign, GCS, และ Pupil ทุก 1 ชั่วโมง\r\n- สังเกตสัญญาณน้ำไขสันหลังรั่ว (CSF Leakage) เช่น มีน้ำใสหรือเลือดปนน้ำใสออกจากจมูก (Rhinorrhea) หรือหู (Otorrhea) ตรวจ Halo sign\r\n- สังเกต Battle\u0027s sign (รอยช้ำหลังหู) และ Raccoon eyes\r\n- จัดท่านอนศีรษะสูง 30 องศา\r\n- ดูแลให้ยาแก้ปวดที่ไม่มีผลกดประสาทตามคำสั่งแพทย์\r\nResponse: GCS คงที่... คะแนน, รูม่านตาตอบสนองต่อแสงดี, ไม่พบ CSF leakage หรืออาการชักเกร็ง\r\n---\r\n.sci = การบาดเจ็บกระดูกสันหลังและไขสันหลัง (Spinal Cord Injury / Neuro Care)\r\nFocus: ป้องกันการบาดเจ็บของไขสันหลังเพิ่มขึ้นและเฝ้าระวัง Neurogenic / Spinal Shock\r\nGoal: ป้องกันการบาดเจ็บของไขสันหลังเพิ่มขึ้น สัญญาณชีพคงที่ ป้องกันภาวะช็อกทางระบบประสาท และป้องกันแผลกดทับ\r\nData: ผู้ป่วยมีภาวะกระดูกสันหลังหัก/บาดเจ็บไขสันหลัง (Spinal cord injury ระดับ...), แขนขาอ่อนแรง ขยับไม่ได้ ชาตั้งแต่ระดับ... ลงไป (Sensory level), ปัสสาวะ/อุจจาระไม่ออก\r\nAction:\r\n- ดามคอด้วย Hard collar ตลอดเวลา\r\n- จัดท่าและพลิกตัวแบบท่อนซุง (Log rolling) โดยมีผู้ช่วยอย่างน้อย 3-4 คน เพื่อให้แนวกระดูกสันหลังตรงตลอดเวลา\r\n- ตรวจวัดสัญญาณชีพเฝ้าระวังภาวะ Neurogenic shock (BP ต่ำร่วมกับชีพจรช้า)\r\n- สังเกตอาการ Autonomic dysreflexia (เหงื่อแตก ความดันสูง ปวดศีรษะรุนแรง)\r\n- ใส่สายสวนปัสสาวะและดูแลการขับถ่าย\r\n- ดูแลใส่ถุงน่องลมหรือ TED hose ป้องกัน DVT\r\nResponse: ผู้ป่วยได้รับการพลิกตัวแบบ Log roll ถูกต้อง, สัญญาณชีพคงที่ BP.../... mmHg, PR... /min, Sensory level คงที่ ไม่พบลำดับการบาดเจ็บเลื่อนสูงขึ้น\r\n---\r\n.delirium = ภาวะสับสนเฉียบพลันในหอผู้ป่วย (Hospital / Ward Delirium Management)\r\nFocus: ภาวะสับสนเฉียบพลัน ขาดสมาธิ และอารมณ์แปรปรวน (Acute Delirium in Ward)\r\nGoal: ผู้ป่วยกลับมารู้จักบุคคล เวลา สถานที่ (Reoriented) อาการสับสนกระสับกระส่ายลดลง วงจรการหลับ-ตื่นปกติ และปลอดภัย\r\nData: ผู้ป่วยมีอาการสับสนเฉียบพลัน (CAM positive), หวาดระแวง เอะอะโวยวาย เห็นภาพหลอน (Hallucination), ดึงสายน้ำเกลือและพยายามก้าวลงจากเตียง, สมาธิสั้น พฤติกรรมแปรปรวนสลับไปมาระหว่างวัน\r\nAction:\r\n- ประเมินค้นหาสาเหตุทางกาย (Infection, Hypoxia, Electrolyte imbalance, Urinary retention, Pain)\r\n- จัดสิ่งแวดล้อมให้ปลอดภัย มีนาฬิกาและปฏิทินในห้อง เปิดม่านให้แสงสว่างเวลากลางวันและปิดไฟหรี่เวลากลางคืนเพื่อคงวงจรหลับ-ตื่น (Circadian rhythm)\r\n- พูดคุยบอกวัน เวลา สถานที่ซ้ำๆ (Reorientation)\r\n- กระตุ้นให้ญาติที่คุ้นเคยอยู่ดูแล\r\n- หลีกเลี่ยงการผูกมัดผู้ป่วย (Physical restraint) โดยไม่จำเป็น\r\n- จัดยาตามแผนการรักษา\r\nResponse: ผู้ป่วยสงบลง สามารถนอนหลับพักผ่อนได้เวลากลางคืน, ไม่เกิดอุบัติเหตุพลัดตกหกล้ม สายน้ำเกลือไม่เลื่อนหลุด\r\n---\r\n\r\n[18. การพยาบาลผู้ป่วยใส่เครื่องช่วยหายใจและดูแลทางเดินหายใจ (Ventilator \u0026 Airway Care)]\r\n.vent = การพยาบาลผู้ป่วยใช้เครื่องช่วยหายใจ (Mechanical Ventilator \u0026 VAP Bundle)\r\nFocus: ดูแลประสิทธิภาพการระบายอากาศและป้องกันปอดอักเสบจากการใช้เครื่องช่วยหายใจ (VAP Prevention Bundle)\r\nGoal: ผู้ป่วยหายใจสัมพันธ์กับเครื่องช่วยหายใจ การแลกเปลี่ยนก๊าซมีประสิทธิภาพ SpO2 ≥ 95% และไม่เกิดปอดอักเสบจากการใช้เครื่องช่วยหายใจ (Zero VAP)\r\nData: ผู้ป่วยใส่ท่อช่วยหายใจ (ETT No... ลึก... cm ที่มุมปาก) ต่อเครื่องช่วยหายใจ Mode... , FiO2... , TV... , RR... , PEEP... , V/S: BP.../... mmHg, SpO2... %\r\nAction: ปฏิบัติตามแนวทาง VAP Prevention Bundle อย่างเคร่งครัด:\r\n1. จัดท่านอนศีรษะสูง 30-45 องศา (Semi-Fowler\u0027s position) ตลอดเวลา\r\n2. ทำความสะอาดช่องปากและฟัน (Oral care) ด้วย 0.12% Chlorhexidine วันละ 2-4 ครั้ง\r\n3. ตรวจวัดความดันลมในกระเปาะท่อช่วยหายใจ (Cuff pressure) ให้อยู่ระหว่าง 20-30 cmH2O ทุกเวรเพื่อป้องกันลมรั่วและเนื้อเยื่อขาดเลือด\r\n4. เทน้ำขังในสายเครื่องช่วยหายใจ (Ventilator circuit condensate) ทิ้งลงภาชนะรองรับ ห้ามเทไหลย้อนกลับ\r\n5. ประเมินความพร้อมในการหย่าเครื่องช่วยหายใจ (Daily sedation vacation \u0026 weaning assessment)\r\nResponse: ผู้ป่วยหายใจสัมพันธ์กับเครื่องช่วยหายใจดี ไม่ต้านเครื่อง (Synchronized), SpO2 = ... %, ปอดขยายตัวเท่ากันทั้ง 2 ข้าง, ไม่มีสัญญาณการติดเชื้อ VAP\r\n---\r\n.suction = การดูดเสมหะผ่านท่อช่วยหายใจ (Endotracheal Suctioning Care)\r\nFocus: กำจัดเสมหะและดูแลทางเดินหายใจให้โล่ง (Ineffective Airway Clearance)\r\nGoal: ทางเดินหายใจโล่ง เสียงเสมหะในปอดลดลง การระบายอากาศดีขึ้น และไม่เกิดภาวะพร่องออกซิเจนขณะดูดเสมหะ\r\nData: ผู้ป่วยหายใจเสียงเสมหะครืดคราดในท่อช่วยหายใจ, กราฟเครื่องช่วยหายใจพบรอยหยัก (Sawtooth pattern) หรือ Peak airway pressure สูงขึ้น, SpO2 ลดลงเหลือ... %\r\nAction:\r\n- ให้ออกซิเจนเข้มข้น 100% (Hyperoxygenation) นาน 30-60 วินาทีก่อนดูดเสมหะ\r\n- ใช้สายดูดเสมหะขนาดเหมาะสม (ไม่เกิน 1/2 ของขนาด ETT) ด้วยเทคนิคปลอดเชื้อ (Aseptic technique / Closed suction system), สอดสายดูดเสมหะลึกพอดี ดูดเสมหะพร้อมหมุนสายขึ้นมาภายในเวลาไม่เกิน 10-15 วินาที\r\n- สังเกตสี ปริมาณ และลักษณะของเสมหะ\r\n- ให้ออกซิเจน 100% ซ้ำหลังดูดเสมหะจนค่า SpO2 กลับสู่เกณฑ์ปกติ\r\nResponse: ดูดเสมหะได้... ml ลักษณะเหนียว สีขาวขุ่น/เหลือง, ทางเดินหายใจโล่งขึ้น หายใจสัมพันธ์กับเครื่อง, Peak pressure ลดลงสู่เกณฑ์ปกติ, SpO2 เพิ่มขึ้นเป็น... %\r\n---\r\n.ettcare = การดูแลท่อช่วยหายใจและเปลี่ยนพลาสเตอร์ (ETT Care \u0026 Tape Repositioning)\r\nFocus: ป้องกันท่อช่วยหายใจเลื่อนหลุดและป้องกันแผลกดทับที่ริมฝีปาก (ETT Dislodgement \u0026 Pressure Injury)\r\nGoal: ท่อช่วยหายใจอยู่ในตำแหน่งที่ถูกต้อง ไม่เลื่อนหลุด ผิวหนังรอบปากและริมฝีปากปกติ ไม่เกิดแผลกดทับ\r\nData: ผู้ป่วยใส่ท่อช่วยหายใจ Endotracheal tube เบอร์... ตำแหน่งเดิมอยู่ที่ขีด... cm ที่มุมปาก... , พลาสเตอร์ยึดท่อเริ่มเปียกชื้น/หลุดลอก\r\nAction:\r\n- ตรวจวัดระดับความลึกของท่อช่วยหายใจที่ขีดมุมปากก่อนทำหัตถการ\r\n- จับยึดท่อช่วยหายใจให้แน่นตลอดเวลาขณะแกะพลาสเตอร์เดิมออก\r\n- ทำความสะอาดผิวหนังรอบปากและเช็ดคราบกาว\r\n- ตรวจสอบสภาพผิวหนังและริมฝีปาก\r\n- ย้ายตำแหน่งท่อช่วยหายใจสลับไปมุมปากอีกข้างเพื่อป้องกันแผลกดทับ\r\n- ติดพลาสเตอร์ยึดท่อ (ETT Taping) ให้แน่นหนาและมั่นคง\r\n- ฟังเสียงลมเข้าปอดซ้ำทั้ง 2 ข้างว่าเท่ากัน (Equal breath sounds)\r\nResponse: ท่อช่วยหายใจยึดติดแน่นที่มุมปากข้าง... ขีดความลึก... cm เท่าเดิม, ฟังปอดลมเข้าเท่ากันทั้งสองข้าง ไม่มีลมรั่วรอบ Cuff\r\n---\r\n.tracheo = การดูแลท่อเจาะคอและแผลเจาะคอ (Tracheostomy Tube \u0026 Stoma Care)\r\nFocus: ป้องกันการอุดกั้นของท่อเจาะคอและป้องกันการติดเชื้อรอบแผลเจาะคอ (Tracheostomy Care)\r\nGoal: ทางเดินหายใจโล่ง ท่อเจาะคอไม่อุดกั้น แผลรอบ Stoma สะอาด แห้งดี และไม่เกิดการติดเชื้อ\r\nData: ผู้ป่วยมีท่อหลอดลมคอ (Tracheostomy tube No... มี Cuff / ไม่มี Cuff), แผลรอบท่อเจาะคอมีเสมหะและสิ่งคัดหลั่งซึมเปื้อนผ้าก๊อซรองแผล\r\nAction:\r\n- ประเมินทางเดินหายใจและดูดเสมหะในท่อเจาะคอให้โล่ง\r\n- ถอด Inner cannula ออกมาล้างทำความสะอาดด้วย Normal Saline และต้มฆ่าเชื้อ/เปลี่ยนอันใหม่ (กรณีเป็นท่อโลหะหรือท่อถอดล้างได้)\r\n- ทำความสะอาดผิวหนังรอบ Stoma ด้วยเทคนิคปลอดเชื้อ\r\n- ปิดแผลด้วยผ้าก๊อซผ่ากึ่งกลาง (Tracheostomy gauze)\r\n- เปลี่ยนเชือกผูกท่อเจาะคอให้กระชับพอสอดนิ้วมือได้ 1-2 นิ้วเพื่อป้องกันการรัดแน่นหรือหลุด\r\nResponse: ท่อเจาะคอสะอาด ทางเดินหายใจโล่ง หายใจสะดวก, แผลรอบท่อเจาะคอแห้งสะอาด ไม่มีรอยแดงหรือหนอง, เชือกผูกท่อแน่นหนาพอดี\r\n---\r\n.wean = การฝึกหย่าเครื่องช่วยหายใจ (Ventilator Weaning \u0026 Spontaneous Breathing Trial)\r\nFocus: ประเมินความพร้อมและฝึกหย่าเครื่องช่วยหายใจ (Ventilator Weaning \u0026 SBT)\r\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจ ทนต่อการทดสอบหายใจด้วยตนเอง (SBT) ได้สำเร็จ สัญญาณชีพคงที่ และพร้อมถอดท่อช่วยหายใจ\r\nData: ผู้ป่วยรู้สึกตัวดี พยาธิสภาพของปอดดีขึ้น, ค่าก๊าซในเลือด (ABG) ปกติ, ตั้งเครื่องช่วยหายใจ Mode Weaning (PSV / CPAP / T-Piece) FiO2 \u003c 0.4, PEEP \u003c 5 cmH2O\r\nAction:\r\n- อธิบายขั้นตอนการฝึกหายใจให้ผู้ป่วยเข้าใจและคลายความวิตกกังวล\r\n- จัดท่านอนศีรษะสูง 45-60 องศา\r\n- เริ่มทดสอบการหายใจด้วยตนเอง (Spontaneous Breathing Trial: SBT) เป็นเวลา 30-120 นาที\r\n- เฝ้าสังเกตสัญญาณเตือนที่ต้องหยุด Weaning: อัตราการหายใจ RR \u003e 35 หรือ \u003c 8 ครั้ง/นาที, SpO2 \u003c 90%, HR \u003e 140 หรือเปลี่ยนแปลง \u003e 20%, BP \u003e 180 หรือ \u003c 90 mmHg, กระสับกระส่าย เหงื่อแตก ใช้กล้ามเนื้อช่วยหายใจ\r\nResponse: ผู้ป่วยทนต่อการฝึกหายใจได้ดี (Tolerated SBT) นาน... นาที, อัตราการหายใจคงที่ RR... /min, SpO2... %, สัญญาณชีพคงที่ สีหน้าผ่อนคลาย พร้อมสำหรับการพิจารณาถอดท่อช่วยหายใจ\r\n---\r\n.extubate = การพยาบาลหลังถอดท่อช่วยหายใจ (Post-Extubation Care \u0026 Stridor Monitoring)\r\nFocus: เฝ้าระวังภาวะทางเดินหายใจอุดกั้นและทางเดินหายใจบวมหลังถอดท่อช่วยหายใจ (Post-Extubation Stridor)\r\nGoal: ถอดท่อช่วยหายใจสำเร็จอย่างปลอดภัย ทางเดินหายใจเปิดโล่ง ไม่มีเสียง Stridor หายใจสะดวก และไม่ต้องใส่ท่อช่วยหายใจซ้ำ (Re-intubation)\r\nData: แพทย์ทำการถอดท่อช่วยหายใจ (Extubation) หลังผ่านการประเมิน Cuff leak test, ผู้ป่วยตื่นดี สามารถไอขับเสมหะได้เอง\r\nAction:\r\n- ดูดเสมหะในช่องปากและท่อช่วยหายใจให้สะอาดก่อนถอดท่อ\r\n- ปลดลมออกจาก Cuff และถอดท่อออกอย่างนุ่มนวลขณะผู้ป่วยหายใจเข้าลึก\r\n- ให้ออกซิเจน Mask with bag / Cannula ทันทีหลังถอดท่อ\r\n- จัดท่านอนศีรษะสูง\r\n- ตรวจประเมินเสียงหายใจเฝ้าระวังภาวะกล่องเสียงบวม (Laryngeal edema / Stridor)\r\n- สังเกตการหายใจเข้ามีเสียงหวีด (Inspiratory stridor) หรือการดึงรั้งของทรวงอก\r\n- แนะนำงดน้ำและอาหาร (NPO) อย่างน้อย 2-4 ชั่วโมงเพื่อประเมินความปลอดภัย\r\nResponse: ผู้ป่วยหายใจด้วยตนเองได้ดี ไม่มีเสียง Stridor หรือเสียงแหบ, SpO2 = ... %, ไอขับเสมหะได้ดี ไม่มีอาการเหนื่อยหอบ\r\n---\r\n\r\n[19. การช่วยชีวิตและการพยาบาลผู้ป่วยวิกฤต (Critical Care \u0026 Life Support)]\r\n.cpr = การช่วยฟื้นคืนชีพขั้นสูงและการดูแลหลังฟื้นคืนชีพ (CPR \u0026 Post-Cardiac Arrest Care / ROSC)\r\nFocus: การช่วยฟื้นคืนชีพขั้นสูงและการดูแลเพื่อฟื้นฟูหลังหัวใจกลับมาเต้น (Cardiopulmonary Resuscitation \u0026 ROSC)\r\nGoal: ได้รับการกู้ชีพขั้นสูงอย่างรวดเร็วและมีประสิทธิภาพ หัวใจกลับมาเต้น (ROSC) สัญญาณชีพและการไหลเวียนโลหิตฟื้นตัว และสมองได้รับออกซิเจนเพียงพอ\r\nData: ผู้ป่วยหมดสติ คลำชีพจร Carotid ไม่ได้ ไม่หายใจ (Cardiac Arrest) เวลา... น., EKG Monitor พบ Rhythm: ... (VF / pVT / Asystole / PEA)\r\nAction:\r\n- กดปุ่มเรียก Code Blue ฉุกเฉินทันที\r\n- เริ่มกดหน้าอกทันที (Quality CPR: อัตราเร็ว 100-120 ครั้ง/นาที, ลึก 5-6 ซม., ปล่อยคืนสุด ไม่หยุดกดเกิน 10 วินาที)\r\n- เปิดทางเดินหายใจและช่วยหายใจด้วย Ambu bag with O2 100%\r\n- นำ Defibrillator มาติดขั้ว Pad\r\n- ให้การกระตุกหัวใจด้วยไฟฟ้า (Defibrillation) ... Joules (กรณี Shockable rhythm)\r\n- ให้ยาช่วยชีวิตฉุกเฉิน (Adrenaline 1 mg IV ทุก 3-5 นาที, Cordarone/Amiodarone) ตาม ACLS Guidelines\r\n- ใส่ท่อช่วยหายใจสำเร็จ ETT No... ลึก... cm\r\n- คลำพบชีพจรกลับมาเต้น (ROSC) เวลา... น. รวมเวลากดหน้าอก... นาที\r\nResponse: ได้รับการกู้ชีพสำเร็จ (ROSC), สัญญาณชีพหลัง ROSC: BP.../... mmHg, PR... /min, SpO2... %, ดูแลให้ยา Vasoactive inotropes ทางหลอดเลือดดำเพื่อควบคุมความดันโลหิต, ติดตามผล ABG และ EKG 12 leads, เตรียมส่งต่อหอผู้ป่วยวิกฤต (ICU)\r\n---\r\n.transfusion = การให้เลือดและส่วนประกอบของเลือด (Blood Transfusion \u0026 Reaction Monitoring)\r\nFocus: ป้องกันภาวะแทรกซ้อนและเฝ้าระวังปฏิกิริยาจากการได้รับเลือด (Blood Transfusion Safety)\r\nGoal: ได้รับเลือดและส่วนประกอบของเลือดอย่างปลอดภัย ถูกต้องตามหลัก Double Check สัญญาณชีพคงที่ และไม่เกิดปฏิกิริยาจากการให้เลือด\r\nData: มีแผนการรักษาให้เลือด (PRC / FFP / Platelets / Cryoprecipitate) จำนวน... ยูนิต, ค่า Hb/Hct ก่อนให้เลือด...\r\nAction: ปฏิบัติตามแนวทางการให้เลือดปลอดภัย (Double Check Verification):\r\n1. ตรวจสอบชื่อ-นามสกุล, HN, หมายเลขยูนิตเลือด, หมู่เลือด (ABO \u0026 Rh), และวันหมดอายุ ร่วมกับพยาบาลวิชาชีพคนที่สองอย่างละเอียด\r\n2. ตรวจวัดสัญญาณชีพก่อนเริ่มให้เลือด (Baseline V/S)\r\n3. ให้เลือดผ่านชุดให้เลือดที่มีตัวกรอง (Blood administration set) ด้วยอัตราช้า 2 ml/min ในช่วง 15 นาทีแรก\r\n4. ตรวจวัดสัญญาณชีพที่ 15 นาทีหลังเริ่มให้เลือด และทุก 30-60 นาทีจนให้เลือดหมด\r\n5. เฝ้าระวังอาการแพ้เลือด (Transfusion reaction): ไข้ หนาวสั่น แน่นหน้าอก หายใจลำบาก ผื่นคัน ลมพิษ ความดันโลหิตตก ปวดหลัง หากพบอาการให้หยุดให้เลือดทันทีและรายงานแพทย์\r\n6. ให้เลือดหมดภายในเวลาไม่เกิน 4 ชั่วโมงต่อ 1 ยูนิต\r\nResponse: ให้เลือดหมดเวลา... น. รวมเวลาให้... ชม., สัญญาณชีพคงที่ ไม่มีไข้ ไม่มีอาการหนาวสั่นหรือผื่นคัน ปลอดภัยดี\r\n---\r\n.cvcline = การดูแลสายสวนหลอดเลือดดำส่วนกลาง (Central Venous Catheter - CVC / CLABSI Bundle)\r\nFocus: ป้องกันการติดเชื้อในกระแสเลือดจากการคาสายสวนหลอดเลือดดำส่วนกลาง (CLABSI Prevention Bundle)\r\nGoal: สายสวนหลอดเลือดดำส่วนกลางทำงานมีประสิทธิภาพ ให้ยาและสารน้ำได้ต่อเนื่อง แผลแห้งสะอาด และไม่เกิดการติดเชื้อ CLABSI\r\nData: ผู้ป่วยคาสายสวนหลอดเลือดดำส่วนกลาง (CVC / PICC / Perm cath) บริเวณ (Subclavian / Internal Jugular / Femoral) ข้าง...\r\nAction:\r\n- ตรวจประเมินตำแหน่งรอยเจาะและสภาพแผล CVC ทุกเวร\r\n- ทำความสะอาดผิวหนังรอบรอยเจาะด้วย 2% Chlorhexidine in 70% Alcohol ด้วยเทคนิคปลอดเชื้อ (Aseptic technique)\r\n- ปิดแผลด้วยแผ่นฟิล์มใสปลอดเชื้อ (Transparent dressing)\r\n- ขัดถูทำความสะอาดจุกเกลียว (Hub scrubbing) ด้วยแอลกอฮอล์นานอย่างน้อย 15 วินาทีก่อนให้ยาหรือต่อสายน้ำเกลือ\r\n- ตรวจสอบการไหลย้อนของเลือด (Blood return) และล้างสาย (Flush) ด้วย Normal Saline หลังให้ยาทุกครั้ง\r\n- ประเมินความจำเป็นในการคาสายทุกวันเพื่อพิจารณาถอดออกโดยเร็ว\r\nResponse: แผลรอบรอยเจาะสาย CVC สะอาด แห้งดี ไม่มีอาการบวมแดง ร้อน หรือมีหนอง, สายระบายเปิดโล่งดี ไม่มีเลือดคั่งค้าง\r\n---\r\n.aline = การดูแลสายวัดความดันในหลอดเลือดแดง (Arterial Line \u0026 Continuous ABP Care)\r\nFocus: เฝ้าระวังการไหลเวียนโลหิตส่วนปลายและป้องกันการติดเชื้อจากการคาสายหลอดเลือดแดง (Arterial Line Care)\r\nGoal: คลื่นความดันโลหิตคมชัด วัดค่าต่อเนื่องได้แม่นยำ การไหลเวียนโลหิตส่วนปลายมือ/เท้าปกติ และไม่มีภาวะเลือดออกหรือการติดเชื้อ\r\nData: มีการคาสายสวนหลอดเลือดแดง (Arterial line) บริเวณ Radial / Femoral artery ข้าง... เพื่อติดตามความดันโลหิตแบบต่อเนื่อง (Continuous ABP Monitoring) และเจาะตรวจก๊าซในเลือด\r\nAction:\r\n- ตรวจสอบระดับตัวแปลงสัญญาณ (Transducer) ให้อยู่ระดับหัวใจ (Phlebostatic axis) และทำการ Zero calibration ทุกเวร\r\n- ตรวจสอบระบบ Flush bag ความดัน 300 mmHg\r\n- ตรวจประเมินการไหลเวียนโลหิตส่วนปลายมือ/เท้า (Capillary refill, สีผิว, ความอุ่น, ชีพจร) ทุก 1-2 ชั่วโมง\r\n- ตรวจสอบข้อต่อทุกจุดให้แน่นหนาป้องกันการหลุดและตกเลือดรวดเร็ว\r\n- เจาะเก็บเลือดตรวจ ABG ด้วยเทคนิคปลอดเชื้อ\r\nResponse: คลื่นสัญญาณความดัน (Arterial waveform) คมชัดดี วัดค่า BP/MAP ได้แม่นยำ, ปลายมือข้างที่ใส่สายอุ่น สีชมพู CRT \u003c 2 วินาที ไม่พบภาวะแทรกซ้อน\r\n---\r\n.chesttube = การดูแลท่อระบายทรวงอก (Chest Tube \u0026 Underwater Seal Drainage Care)\r\nFocus: ดูแลประสิทธิภาพการระบายลมและของเหลวจากช่องเยื่อหุ้มปอดและเฝ้าระวังลมรั่ว (Chest Tube / ICD Care)\r\nGoal: ปอดขยายตัวเต็มที่ สารคัดหลั่งและลมในช่องเยื่อหุ้มปอดระบายได้มีประสิทธิภาพ ระบบขวดระบายน้ำทำงานสมบูรณ์ และไม่มีลมรั่ว\r\nData: ผู้ป่วยใส่ท่อระบายทรวงอก (Intercostal Drainage: ICD) ข้าง... ต่อเข้าขวดระบายน้ำระบบ Water-seal / Suction... cmH2O, มีสารคัดหลั่ง/ลมระบายออก\r\nAction:\r\n- ตรวจสอบระดับน้ำในขวด Water-seal ให้ท่วมปลายหลอดแก้ว 2 ซม.\r\n- สังเกตการกระเพื่อมของน้ำในหลอดแก้วสัมพันธ์กับการหายใจ (Fluctuation / Tidaling)\r\n- สังเกตฟองอากาศปุดในขวด (Air leak)\r\n- วางขวดระบายให้อยู่ต่ำกว่าระดับทรวงอกผู้ป่วยเสมอ (อย่างน้อย 2-3 ฟุต) และตั้งตรงไม่ล้ม\r\n- ตรวจสอบสายยางไม่หักพับงอ ไม่ดึงรั้ง และห้ามบีบรูดสาย (Stripping) โดยไม่จำเป็น\r\n- ตรวจสอบรอยต่อทุกจุดให้แนบสนิท\r\n- ทำแผลรอบท่อระบายด้วยเทคนิคปลอดเชื้อ\r\nResponse: ระดับน้ำในขวดระบายกระเพื่อมตามการหายใจดี, สารคัดหลั่งระบายได้... ml สี serosanguinous, ปอดขยายตัวดีขึ้น เสียงหายใจเข้าเท่ากันทั้งสองข้าง\r\n---\r\n.hadrug = การบริหารยาความเสี่ยงสูงทางหลอดเลือดดำ (High Alert Drug \u0026 Vasoactive Inotropes)\r\nFocus: ความปลอดภัยในการบริหารยากลุ่มความเสี่ยงสูงและยากระตุ้นความดันโลหิต (High Alert Drugs: HAD)\r\nGoal: ผู้ป่วยได้รับยาความเสี่ยงสูงอย่างถูกต้อง ปลอดภัย ผ่านเครื่อง Infusion pump สัญญาณชีพและค่า MAP อยู่ในเกณฑ์เป้าหมาย และไม่เกิดภาวะเนื้อเยื่อตาย\r\nData: ผู้ป่วยได้รับยาที่มีความเสี่ยงสูง / ยากระตุ้นหัวใจและความดันโลหิต (Norepinephrine / Dopamine / Nicardipine / Amiodarone / Insulin drip / Heparin) อัตราเร็ว... ml/hr (Dose... mcg/kg/min)\r\nAction: ปฏิบัติตามแนวทางการใช้ยาความเสี่ยงสูง (High Alert Drug Safety):\r\n1. ตรวจสอบความถูกต้องแบบ Double Check (ตัวยา ขนาดยา ความเข้มข้น อัตราหยด และชื่อผู้ป่วย)\r\n2. ให้ยาผ่านเครื่องควบคุมสารน้ำ (Infusion pump) เสมอ และติดป้ายเตือนยาความเสี่ยงสูงชัดเจนที่ขวดและสายน้ำเกลือ\r\n3. ให้ยาผ่านเส้นเลือดดำขนาดใหญ่หรือสาย CVC เพื่อป้องกันการรั่วออกนอกหลอดเลือด (Extravasation) ซึ่งทำให้เนื้อเยื่อตาย\r\n4. ตรวจวัดสัญญาณชีพและประเมินระดับความดันโลหิต/ชีพจรทุก 15-30 นาทีขณะปรับขนาดยา (Titration) เพื่อให้ได้ค่า MAP ตามเป้าหมาย (\u003e 65 mmHg)\r\n5. สังเกตอาการข้างเคียง เช่น หัวใจเต้นผิดจังหวะ ปลายมือปลายเท้าเขียวคล้ำ\r\nResponse: ยาหยดสม่ำเสมอผ่านเครื่อง Infusion pump, ความดันโลหิตอยู่ในเกณฑ์เป้าหมาย MAP = ... mmHg, บริเวณรอยแทงเข็มไม่มีอาการบวมแดงหรือยารั่วซึม\r\n---\r\n\r\n[20. การพยาบาลผู้ป่วยมะเร็งกระดูกและรังสีรักษา (Bone Cancer \u0026 Radiotherapy)]\r\n.boneca = การพยาบาลผู้ป่วยมะเร็งกระดูกและการแพร่กระจายมายังกระดูก (Bone Cancer \u0026 Bone Metastasis Care)\r\nFocus: การพยาบาลผู้ป่วยมะเร็งกระดูกและการแพร่กระจายมายังกระดูก\r\nGoal: ผู้ป่วยได้รับการดูแลแบบองค์รวม ควบคุมอาการปวดได้ดี ป้องกันภาวะแทรกซ้อนจากการทำลายกระดูก เสริมสร้างความปลอดภัย และได้รับการประคับประคองจิตใจ\r\nData: ผู้ป่วยได้รับการวินิจฉัยว่าเป็นมะเร็งกระดูก (Primary bone tumor / Metastatic bone disease จาก...), บ่นปวดตื้อลึกในกระดูกบริเวณ... ปวดมากขึ้นเวลากลางคืนหรือเมื่อลงน้ำหนัก, มีก้อนบวม/กดเจ็บ, เคลื่อนไหวร่างกายลำบาก\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินอาการปวด อาการบวม และความสามารถในการทำกิจวัตรประจำวัน\r\n- ช่วยเหลือในการทำความสะอาดร่างกายและเปลี่ยนท่านอนอย่างนุ่มนวล หลีกเลี่ยงการดึงรั้งรยางค์ที่มีรอยโรค\r\n- ส่งเสริมการรับประทานอาหารที่มีโปรตีนสูงและแคลอรี่เพียงพอ\r\n- ติดตามผลภาพถ่ายทางรังสี (X-ray / Bone scan / CT / MRI) และผลตรวจเลือด\r\n[⛅ เวรบ่าย]\r\n- ดูแลให้ยาบรรเทาปวดตามแผนการรักษาอย่างตรงเวลา ประเมินระดับความปวดทั้งขณะพักและเคลื่อนไหว\r\n- สังเกตอาการข้างเคียงของยาแก้ปวดกลุ่ม Opioids (คลื่นไส้ อาเจียน ท้องผูก ง่วงซึม)\r\n- จัดท่าทางให้อยู่ในท่าที่สุขสบายและใช้อุปกรณ์หนุนรองรับน้ำหนักกระดูก\r\n- ให้กำลังใจและเปิดโอกาสให้ผู้ป่วยและครอบครัวระบายความกังวล\r\n[🌙 เวรดึก]\r\n- ดูแลสิ่งแวดล้อมให้เงียบสงบ เอื้อต่อการนอนหลับพักผ่อน\r\n- ให้ยาแก้ปวดก่อนนอนเพื่อป้องกันอาการปวดกระดูกรบกวนการนอนหลับ\r\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างเพื่อป้องกันการพลัดตกหกล้ม\r\n- เฝ้าระวังอาการปวดรุนแรงเฉียบพลันหรืออาการผิดปกติทางระบบประสาทรอบดึก\r\nResponse: ผู้ป่วยสุขสบายขึ้น บ่นปวดกระดูกลดลง Pain score ≤ 3/10 เคลื่อนไหวเปลี่ยนท่าได้อย่างปลอดภัย ไม่มีอุบัติเหตุพลัดตกหกล้ม สีหน้าผ่อนคลายและนอนหลับพักผ่อนได้\r\n---\r\n.pathofx = เสี่ยงต่อภาวะกระดูกหักจากพยาธิสภาพของโรค (Risk for Pathological Fracture)\r\nFocus: เสี่ยงต่อภาวะกระดูกหักจากพยาธิสภาพของมะเร็งทำลายเนื้อกระดูก (Risk for Pathological Fracture)\r\nGoal: ผู้ป่วยไม่เกิดภาวะกระดูกหักจากพยาธิสภาพ (Pathological fracture) ไม่มีอุบัติเหตุพลัดตกหกล้ม เคลื่อนย้ายตัวถูกต้อง และใช้อุปกรณ์พยุงกายอย่างปลอดภัย\r\nData: ภาพถ่ายรังสีพบรอยโรคกระดูกถูกทำลายแบบ Lytic lesion / Blastic lesion บริเวณ... เสี่ยงต่อกระดูกหักง่ายแม้รับแรงกระแทกเพียงเล็กน้อย (Pathological fracture risk), ผู้ป่วยรู้สึกเสียวแปลบและปวดเสียวเมื่อลงน้ำหนัก\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ติดป้ายเตือน \"ระวังกระดูกหักง่าย (Fall \u0026 Fracture Precaution)\" ที่หัวเตียงและหน้าชาร์ต\r\n- แนะนำและดูแลการจำกัดการลงน้ำหนัก (Non-weight bearing / Partial weight bearing) ตามแผนการรักษาของแพทย์ออร์โธปิดิกส์\r\n- สอนและดูแลการใช้อุปกรณ์ช่วยเดิน (Walker / Crutches) หรืออุปกรณ์ประคองกระดูก (Brace / Splint)\r\n- แนะนำผู้ป่วยหลีกเลี่ยงการบิดหมุนตัว การก้มยกของหนัก หรือการออกแรงกระแทกกระดูก\r\n[⛅ เวรบ่าย]\r\n- ช่วยเหลือในการเคลื่อนย้ายตัวและเปลี่ยนท่าอย่างถูกวิธีโดยมีผู้ช่วยเหลืออย่างน้อย 1-2 คน (Log-roll technique เมื่อมีรอยโรคที่กระดูกสันหลัง)\r\n- จัดวางของใช้จำเป็นให้อยู่ใกล้มือผู้ป่วยเพื่อป้องกันการเอื้อมหรือก้มตัว\r\n- ดูแลทางเดินในห้องให้โล่ง ไม่มีสิ่งกีดขวาง และพื้นแห้งสนิท\r\n- สังเกตอาการปวดเฉียบพลัน ผิดรูป หรือได้ยินเสียงกรอบแกรบ (Crepitus)\r\n[🌙 เวรดึก]\r\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้าง ล็อกล้อเตียงให้แน่นสนิทตลอดเวลา\r\n- จัดวางกระโถนปัสสาวะไว้ข้างเตียงและกำชับให้กดกริ่งเรียกพยาบาลทุกครั้งที่ต้องการลุกจากเตียง\r\n- ตรวจตราความปลอดภัยรอบดึกอย่างสม่ำเสมอ\r\n- เฝ้าระวังไม่ให้ผู้ป่วยลุกเดินเองตามลำพัง\r\nResponse: ไม่เกิดอุบัติเหตุพลัดตกหกล้ม ไม่เกิดภาวะกระดูกหักจากพยาธิสภาพ เคลื่อนย้ายตัวได้อย่างนุ่มนวลและปลอดภัย ใช้อุปกรณ์ช่วยพยุงได้ถูกต้อง\r\n---\r\n.hypercamal = ภาวะแคลเซียมในเลือดสูงฉุกเฉินจากมะเร็งกระดูก (Hypercalcemia of Malignancy: HCM)\r\nFocus: ภาวะระดับแคลเซียมในเลือดสูงฉุกเฉินจากการแพร่กระจายของมะเร็งทำลายกระดูก (Hypercalcemia of Malignancy: HCM)\r\nGoal: ระดับซีรั่มแคลเซียมลดลงสู่เกณฑ์ปกติ (Total Ca 8.5-10.5 mg/dL, Corrected Ca ปกติ) ได้รับสารน้ำและยาอย่างปลอดภัย สัญญาณชีพคงที่ รู้สึกตัวดี และไม่เกิดภาวะหัวใจเต้นผิดจังหวะ\r\nData: ผลตรวจ Total Calcium = ... mg/dL, Corrected Calcium = ... mg/dL (สูงกว่า 10.5 mg/dL), ผู้ป่วยมีอาการอ่อนเพลีย ซึม สับสน เบื่ออาหาร คลื่นไส้อาเจียน ท้องผูก ดื่มน้ำบ่อย ปัสสาวะมาก (Polyuria) หรือปัสสาวะออกน้อย กล้ามเนื้ออ่อนแรง\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินระดับความรู้สึกตัว (GCS), สัญญาณชีพ และอาการแสดงของภาวะแคลเซียมสูง (คลื่นไส้ ท้องผูก สับสน กล้ามเนื้ออ่อนแรง)\r\n- ดูแลให้สารน้ำ 0.9% NSS ทางหลอดเลือดดำในอัตราเร็วตามแผนการรักษา (Vigorous hydration 200-300 ml/hr) เพื่อขับแคลเซียมออกทางไต\r\n- ตรวจสอบผลตรวจเลือดระดับ Electrolyte, BUN, Cr และ Corrected Calcium\r\n- บันทึกปริมาณน้ำเข้า-ออก (Intake/Output) อย่างเคร่งครัด\r\n[⛅ เวรบ่าย]\r\n- ดูแลให้ยาขับปัสสาวะ Furosemide (Lasix) ทางหลอดเลือดดำตามแผน เพื่อช่วยขับแคลเซียมหลังให้สารน้ำเพียงพอ (หลีกเลี่ยง Thiazide diuretics)\r\n- ดูแลให้ยากลุ่มยับยั้งการทำลายกระดูก (Bisphosphonates เช่น Zoledronic acid หรือ Pamidronate) ทางหลอดเลือดดำตามแผนการรักษา โดยผสมสารน้ำและหยดช้าๆ ไม่น้อยกว่า 15-30 นาที\r\n- ตรวจติดตามคลื่นไฟฟ้าหัวใจ (EKG) เฝ้าระวัง QT interval สั้นลง หรือ Bradycardia\r\n[🌙 เวรดึก]\r\n- ตรวจวัดสัญญาณชีพและประเมินภาวะน้ำเกิน (Fluid overload: หายใจหอบเหนื่อย, ฟังปอดพบ Crepitation, SpO2 ลดลง) จากการได้รับสารน้ำปริมาณมาก\r\n- สรุปยอดปัสสาวะสะสม หากออก \u003c 0.5 ml/kg/hr ให้รายงานแพทย์\r\n- เฝ้าระวังอาการชักหรือสับสนเพ้อ (Delirium) รอบดึก และยกไม้กั้นเตียงขึ้นเพื่อความปลอดภัย\r\nResponse: ปัสสาวะออกดีสะสม... ml/เวร ไม่มีภาวะน้ำคั่งหรือหอบเหนื่อย, ผล Corrected Calcium ลดลงเหลือ... mg/dL, ผู้ป่วยรู้สึกตัวดีขึ้น อาการคลื่นไส้อ่อนเพลียทุเลาลง สัญญาณชีพและคลื่นไฟฟ้าหัวใจปกติ\r\n---\r\n.radiotherapy = การดูแลผู้ป่วยก่อน-ระหว่าง-หลังส่งฉายแสง (Radiation Therapy Management \u0026 Transport Care)\r\nFocus: การเตรียมความพร้อมและดูแลผู้ป่วยระหว่างเข้ารับการฉายรังสีรักษา (Radiation Therapy Nursing Care)\r\nGoal: ผู้ป่วยมีความพร้อมทั้งร่างกายและจิตใจ ได้รับการฉายรังสีครบถ้วนตามแผนการรักษา ปลอดภัยระหว่างการเคลื่อนย้ายส่งต่อ และไม่เกิดภาวะแทรกซ้อนเฉียบพลัน\r\nData: ผู้ป่วยมีแผนเข้ารับการฉายรังสีรักษา (External Beam Radiation Therapy: EBRT) บริเวณ... ครั้งที่... จากแผนทั้งหมด... ครั้ง, V/S ก่อนไป: BP.../... mmHg, PR... /min, RR... /min, SpO2... %\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจสอบใบนัดและแผนการฉายรังสีรักษา (RT appointment \u0026 treatment sheet)\r\n- ประเมินความพร้อมของผู้ป่วย สัญญาณชีพ และระดับความรู้สึกตัว\r\n- จัดเตรียมยาแก้ปวดให้ผู้ป่วยรับประทานก่อนไปฉายแสง 30-45 นาที เพื่อให้ผู้ป่วยสามารถนอนราบนิ่งบนเตียงฉายแสงได้อย่างสุขสบาย\r\n- ตรวจสอบรอยมาร์กหมึกตำแหน่งฉายรังสี ห้ามขัดถูหรือลบเลือน\r\n- ประสานงานศูนย์รังสีรักษาและเวรเปลเพื่อนำส่งด้วยเตียงนอนหรือรถนั่งอย่างปลอดภัย\r\n[⛅ เวรบ่าย]\r\n- รับย้ายผู้ป่วยกลับจากห้องฉายรังสีรักษา ตรวจวัดสัญญาณชีพทันทีแรกรับกลับ\r\n- ประเมินอาการเหนื่อย อ่อนเพลีย วิงเวียน หรือคลื่นไส้หลังฉายแสง\r\n- จัดท่านอนพักผ่อนในสิ่งแวดล้อมที่เงียบสงบ\r\n- ดูแลให้จิบน้ำอุ่นหรือรับประทานอาหารว่างเบาๆ หากไม่มีอาการคลื่นไส้อาเจียน\r\n- บันทึกผลการฉายแสงและอาการตอบสนองลงในเวชระเบียน\r\n[🌙 เวรดึก]\r\n- ตรวจประเมินสัญญาณชีพรอบดึกและติดตามอาการข้างเคียงสะสม\r\n- ส่งเสริมการนอนหลับพักผ่อนเพื่อฟื้นฟูร่างกายจากการได้รับรังสี\r\n- ให้คำแนะนำผู้ป่วยและญาติเกี่ยวกับการปฏิบัติตัวและแผนการฉายแสงในวันถัดไป\r\n- เตรียมเอกสารส่งต่อเวรเช้าให้พร้อม\r\nResponse: ผู้ป่วยได้รับการฉายรังสีรักษาตามแผนเรียบร้อยดี การส่งต่อปลอดภัย สัญญาณชีพคงที่ ไม่มีอาการวิงเวียนหรือคลื่นไส้อาเจียนรุนแรง สามารถนอนพักผ่อนได้ดี\r\n---\r\n.radskin = การดูแลผิวหนังบริเวณฉายแสงและป้องกันรังสีอักเสบ (Radiation Dermatitis \u0026 Skin Care)\r\nFocus: ป้องกันและดูแลภาวะผิวหนังอักเสบ บวมแดง และลอกหลุดจากรังสีรักษา (Radiation Dermatitis Care)\r\nGoal: ผิวหนังบริเวณที่ฉายรังสีสะอาด ชุ่มชื้น ไม่เกิดแผลฉีกขาด ลอกหลุดเป็นแผลเปียก (Moist desquamation) หรือติดเชื้อแทรกซ้อน เส้นมาร์กตำแหน่งฉายรังสีคมชัด\r\nData: ผิวหนังบริเวณที่ฉายรังสี (Radiation field) มีอาการแห้ง แดง คัน (Erythema) คล้ำขึ้น หรือมีสะเก็ดแห้งลอก (Dry desquamation), ผู้ป่วยบ่นแสบร้อนคันบริเวณรอยฉายแสง\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินสภาพผิวหนังบริเวณที่ฉายรังสี: สีผิว ความยืดหยุ่น รอยแดง อาการบวม หรือตุ่มน้ำพอง ตามเกณฑ์ RTOG/CTCAE\r\n- ทำความสะอาดผิวหนังด้วยน้ำเปล่าหรือสบู่อ่อนโยน (pH balance) ซับเบาๆ ด้วยผ้าขนหนูนุ่ม ห้ามถูแรง\r\n- ระมัดระวังไม่ให้รอยเส้นหมึกระบุพิกัดฉายรังสีลบเลือน หากเส้นจางให้แจ้งนักรังสีการแพทย์แต้มใหม่ ห้ามเขียนทับเอง\r\n[⛅ เวรบ่าย]\r\n- ทาโลชั่นหรือครีมบำรุงผิวที่ไม่มีน้ำหอม/โลหะผสม (เช่น Urea cream, Aloe vera gel) ตามที่แพทย์รังสีรักษาแนะนำ หลังการฉายแสงเสร็จสิ้น (ห้ามทาก่อนเข้าห้องฉายรังสีภายใน 2-4 ชม.)\r\n- แนะนำผู้ป่วยสวมใส่เสื้อผ้าเนื้อนุ่ม หลวมสบาย ไม่รัดแน่นหรือเสียดสีผิวหนัง\r\n- กำชับห้ามเกา ห้ามแกะสะเก็ด ห้ามประคบร้อนหรือเย็น และห้ามติดพลาสเตอร์เหนียวบริเวณรอยฉายรังสีเด็ดขาด\r\n- แนะนำหลีกเลี่ยงการถูกแสงแดดโดยตรง\r\n[🌙 เวรดึก]\r\n- ตรวจสอบผิวหนังก่อนนอนและจัดเสื้อผ้าผ้าปูที่นอนให้เรียบตึงไม่ระคายเคือง\r\n- ดูแลให้ยาแก้แพ้หรือยาแก้คันตามแผนการรักษาหากมีอาการคันรบกวนการนอนหลับ\r\n- สังเกตสัญญาณการติดเชื้อแทรกซ้อน (บวม ร้อน เจ็บ หรือมีน้ำเหลืองซึมเปื้อน) เพื่อรายงานแพทย์\r\nResponse: ผิวหนังบริเวณฉายแสงสะอาด ไม่มีรอยถลอกลอกเปียกหรือแผลติดเชื้อ เส้นมาร์กตำแหน่งรังสีชัดเจน อาการแสบคันลดลง ผู้ป่วยเข้าใจและปฏิบัติตามคำแนะนำในการดูแลผิวหนังได้ถูกต้อง\r\n---\r\n.painflare = การจัดการอาการปวดกระดูกจากมะเร็งและปวดกำเริบหลังฉายแสง (Bone Cancer Pain \u0026 Radiation Pain Flare)\r\nFocus: การจัดการอาการปวดกระดูกจากมะเร็งและอาการปวดกำเริบชั่วคราวหลังฉายรังสี (Bone Cancer Pain \u0026 Radiation Pain Flare)\r\nGoal: ระดับความปวดลดลงอยู่ในเกณฑ์ที่ทนได้ Pain score ≤ 3/10 ควบคุมอาการปวดกำเริบฉับพลัน (Breakthrough pain / Pain flare) ได้รวดเร็ว และไม่มีภาวะกดการหายใจจากยากลุ่มอนุพันธ์ฝิ่น\r\nData: ผู้ป่วยบ่นปวดกระดูกบริเวณที่ฉายแสงเพิ่มขึ้นอย่างเฉียบพลันหลังการฉายรังสี 1-3 วันแรก (Radiation pain flare) Pain score = .../10, หน้าตานิ่ว กระสับกระส่าย ขยับตัวลำบาก, V/S: BP.../... mmHg, PR... /min\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินลักษณะ ตำแหน่ง ความถี่ และระดับความปวดกระดูก (Pain score 0-10) แยกแยะระหว่างปวดเดิมกับปวดกำเริบจากรังสี (Pain flare)\r\n- ดูแลให้ยาแก้ปวดตามรอบเวลา (Around-the-clock analgesics) เช่น ยากลุ่มสเตียรอยด์ (Dexamethasone) เพื่อลดอาการบวมอักเสบ และยาแก้ปวดกลุ่ม Opioids ร่วมกับ Paracetamol ตามแผน\r\n- ประเมินความปวดซ้ำหลังให้ยา 30-60 นาที\r\n[⛅ เวรบ่าย]\r\n- ดูแลให้ยาแก้ปวดเสริมเฉพาะหน้า (Breakthrough dose / Rescue dose) ทันทีเมื่อผู้ป่วยมีอาการปวดกำเริบฉับพลัน\r\n- จัดท่านอนประคองส่วนที่ปวดด้วยหมอนนุ่ม ผ่อนคลายกล้ามเนื้อ หลีกเลี่ยงการเคลื่อนไหวที่ทำให้กระดูกรับแรงบิดเค้น\r\n- สังเกตอาการข้างเคียงของยากลุ่ม Opioids (อัตราการหายใจ, ระดับความง่วงซึม Sedation score, อาการคลื่นไส้)\r\n[🌙 เวรดึก]\r\n- ดูแลให้ยาแก้ปวดก่อนนอนเพื่อส่งเสริมการนอนหลับพักผ่อนต่อเนื่องตลอดคืน\r\n- เฝ้าระวังภาวะกดการหายใจ (Respiratory depression: RR \u003c 10 ครั้ง/นาที) ตรวจวัด RR สม่ำเสมอ\r\n- จัดสิ่งแวดล้อมห้องพักให้เงียบสงบลดสิ่งเร้า\r\n- เตรียมพร้อมยาแก้พิษ Naloxone ไว้กรณีเกิด Opioid toxicity\r\nResponse: อาการปวดกระดูกกำเริบทุเลาลง Pain score ลดลงเหลือ.../10, ผู้ป่วยสีหน้าผ่อนคลาย ขยับตัวได้ดีขึ้น อัตราการหายใจปกติ (RR... /min) ไม่มีง่วงซึมผิดปกติ สามารถนอนหลับพักผ่อนได้\r\n---\r\n.mscc = ภาวะกดทับไขสันหลังจากมะเร็งกระดูกลุกลามฉุกเฉิน (Malignant Spinal Cord Compression: MSCC)\r\nFocus: ภาวะฉุกเฉินทางมะเร็งวิทยา: มะเร็งกระดูกสันหลังลุกลามกดทับไขสันหลัง (Malignant Spinal Cord Compression: MSCC)\r\nGoal: ตรวจพบสัญญาณเตือนทางระบบประสาทได้รวดเร็ว ได้รับการรักษาฉุกเฉินทันท่วงที (High-dose Dexamethasone \u0026 Emergency Radiotherapy/Surgery) ป้องกันความพิการอัมพาตถาวร และการทำงานของระบบประสาทฟื้นตัว\r\nData: ผู้ป่วยมะเร็งกระดูกสันหลังมีอาการปวดหลังรุนแรงร้าวไปตามรากประสาท (Radicular pain) ร่วมกับมีอาการขาอ่อนแรง ขยับขาได้ลดลง (Motor weakness Grade.../5), มีอาการชาหรือสูญเสียความรู้สึกตั้งแต่ระดับ... ลงไป (Sensory level loss), หรือมีปัญหาการกลั้นปัสสาวะ/อุจจาระไม่ได้ (Autonomic dysfunction / Urinary retention)\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ตรวจประเมินระบบประสาทอย่างละเอียดทุก 2-4 ชั่วโมง: กำลังกล้ามเนื้อขา (Motor power), การรับความรู้สึก (Sensory level), และอาการชา\r\n- รายงานแพทย์ทันทีเมื่อพบสัญญาณเตือนของ MSCC เพื่อส่งตรวจ MRI Spine ฉุกเฉิน\r\n- ดูแลให้ยา Dexamethasone ขนาดสูง (High-dose IV Dexamethasone 10-16 mg IV stat then 4 mg IV q 6 hr) ตามคำสั่งแพทย์เพื่อลดอาการบวมกดทับไขสันหลัง\r\n- ป้องกันภาวะแทรกซ้อนของสเตียรอยด์ (ให้ยาป้องกันแผลในกระเพาะอาหาร PPI, ติดตามค่าน้ำตาลในเลือด DTX)\r\n[⛅ เวรบ่าย]\r\n- จัดท่าผู้ป่วยนอนราบบนที่นอนแข็ง ไม่งอพับหลัง ใช้เทคนิคการพลิกตัวแบบท่อนซุง (Log-roll turning technique) โดยมีเจ้าหน้าที่อย่างน้อย 3 คน\r\n- ตรวจสอบการคาสายสวนปัสสาวะ (Foley catheter) บันทึกปริมาณปัสสาวะเพื่อเฝ้าระวังกระเพาะปัสสาวะคั่งค้าง\r\n- ประสานงานเตรียมส่งผู้ป่วยเข้ารับการฉายรังสีรักษาฉุกเฉิน (Emergency Radiotherapy) หรือห้องผ่าตัดกระดูกสันหลัง (Emergency Decompression)\r\n[🌙 เวรดึก]\r\n- ตรวจประเมินกำลังกล้ามเนื้อขาและระดับความรู้สึกซ้ำรอบดึก หากอาการอ่อนแรงแย่ลงให้รายงานแพทย์เวรทันที\r\n- พลิกตัวเปลี่ยนท่านอนอย่างนุ่มนวลทุก 2 ชั่วโมงเพื่อป้องกันแผลกดทับ\r\n- ยกไม้กั้นเตียงขึ้นทั้ง 2 ข้างและดูแลความปลอดภัยรอบด้าน\r\n- ให้กำลังใจผู้ป่วยและครอบครัวเพื่อลดความวิตกกังวล\r\nResponse: ได้รับยา High-dose Dexamethasone และประสานงานส่งฉายรังสีรักษาฉุกเฉินเรียบร้อย, กำลังกล้ามเนื้อขาคงที่ Motor power Grade.../5 ไม่พบการลุกลามเพิ่มขึ้น, อาการปวดหลังทุเลาลง และคาสายสวนปัสสาวะระบายได้สะดวก\r\n---\r\n.radfatigue = ภาวะอ่อนเพลีย เบื่ออาหาร และไขกระดูกกดจากการฉายแสง (Radiation-Induced Fatigue, Anorexia \u0026 Myelosuppression)\r\nFocus: ภาวะอ่อนเพลียสะสม เบื่ออาหาร และไขกระดูกถูกกดจากการฉายรังสีรักษา (Radiation Fatigue \u0026 Bone Marrow Suppression)\r\nGoal: ผู้ป่วยมีระดับพลังงานเพิ่มขึ้น ทำกิจวัตรประจำวันได้ตามความสามารถ ได้รับสารอาหารและน้ำเพียงพอ น้ำหนักตัวคงที่ และไม่เกิดการติดเชื้อหรือภาวะเลือดออกจากเม็ดเลือดต่ำ\r\nData: ผู้ป่วยมีอาการอ่อนเพลีย เหนื่อยล้าสะสม (Fatigue score.../10), เบื่ออาหาร ทานได้น้อย คลื่นไส้ น้ำหนักตัวลดลง, ผลตรวจ CBC: Hb... g/dL, Hct... %, WBC... /uL, ANC... /uL, Platelet... /uL\r\nAction:\r\n[☀️ เวรเช้า]\r\n- ประเมินระดับความเหนื่อยล้าอ่อนเพลีย (Fatigue score 0-10) และวางแผนจัดตารางกิจกรรมให้สอดคล้องกับช่วงเวลาที่มีพลังงาน\r\n- จัดอาหารมื้อเล็กๆ แต่บ่อยครั้ง (Small frequent meals) เน้นโปรตีนสูงและพลังงานสูง\r\n- ตรวจสอบผลตรวจความสมบูรณ์ของเม็ดเลือด (CBC) สังเกตภาวะซีด (Anemia), เม็ดเลือดขาวต่ำ (Neutropenia), และเกล็ดเลือดต่ำ (Thrombocytopenia)\r\n- ดูแลความสะอาดของร่างกายและช่องปากด้วยแปรงขนนุ่ม\r\n[⛅ เวรบ่าย]\r\n- ส่งเสริมให้ผู้ป่วยได้งีบหลับพักผ่อนระหว่างวัน (ไม่เกิน 30-45 นาที เพื่อไม่ให้รบกวนการนอนกลางคืน)\r\n- แนะนำการออกกำลังกายเบาๆ เช่น การยืดเหยียดกล้ามเนื้อบนเตียง หรือนั่งเก้าอี้ขยับเท้า เพื่อลดความเมื่อยล้าสะสม\r\n- ดูแลให้สารน้ำ วิตามิน หรืออาหารเสริมทางการแพทย์ตามแผนการรักษา\r\n- สังเกตจุดจ้ำเลือด (Petechiae) หรือเลือดออกตามไรฟัน\r\n[🌙 เวรดึก]\r\n- เฝ้าระวังอาการไข้สูง หนาวสั่น (Neutropenic fever: T ≥ 38.0 °C) หากพบให้รายงานแพทย์และปฏิบัติตามแนวทางการดูแลผู้ป่วยติดเชื้อทันที\r\n- จัดสิ่งแวดล้อมห้องพักให้เงียบสงบ มืดพอเหมาะ ส่งเสริมการนอนหลับพักผ่อนเต็มที่ในเวลากลางคืน\r\n- ดูแลความปลอดภัยรอบเตียง ป้องกันการพลัดตกหกล้มจากความอ่อนเพลีย\r\nResponse: ผู้ป่วยรับประทานอาหารได้มากขึ้น... มื้อ, รู้สึกสดชื่นขึ้น Fatigue score ลดลงเหลือ.../10, สัญญาณชีพคงที่ ไม่มีไข้ (T... °C) ไม่มีจุดเลือดออกผิดปกติ สามารถนอนหลับพักผ่อนได้เต็มที่\r\n---\r\n"}', now(), 'Desktop Admin') ON CONFLICT (bed_number) DO UPDATE SET content = EXCLUDED.content, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by;
